final class AppState: ObservableObject {
    typealias PropertyShadowWriteOverride = (Property) async throws -> Void
    typealias PropertyRemoteInsertOverride = (Property) async throws -> Void
    typealias SessionShadowWriteOverride = (Property, Session, SessionMetadata) async throws -> Void
    typealias ShotMetadataWriteOverride = (UUID, UUID, SupabaseShotRichMetadataPayload, Bool) async throws -> Void
    typealias SessionSnapshotStorageUploadOverride = (SessionSnapshotStorageObject) async throws -> Void
    typealias SessionSnapshotRowInsertOverride = (SessionSnapshotUploadRow) async throws -> Void
    typealias SessionSnapshotRowsFetchOverride = (UUID?, UUID?, UUID?) async throws -> [SessionSnapshotUploadRow]
    typealias SessionSnapshotStorageDownloadOverride = (String, String) async throws -> Data
    typealias SessionSnapshotMediaDownloadOverride = (String, String) async throws -> Data
    typealias CanonicalReadRemoteSnapshotFetchOverride = (UUID, UUID?, UUID?) async throws -> CanonicalReadRemoteSnapshot

    enum SessionSnapshotKind: String, Codable, CaseIterable, Equatable {
        case draft
        case completed
        case export
        case delivery
        case manual
    }

    enum SessionSnapshotUploadOutcome: String, Equatable {
        case disabled
        case unavailable
        case succeeded
        case failed
        case orphanRisk
    }

    struct SessionSnapshotUploadResult: Equatable {
        let outcome: SessionSnapshotUploadOutcome
        let snapshotID: UUID?
        let sessionID: UUID?
        let propertyID: UUID?
        let storagePath: String?
        let message: String?
    }

    struct SessionSnapshotAuthPreflightRemoteParentStatus: Equatable {
        var propertyExists: Bool = false
        var sessionExists: Bool = false
        var propertyOrgID: UUID?
        var sessionOrgID: UUID?
        var sessionPropertyIDMatches: Bool = false
        var orgIDsMatch: Bool = false
        var errorMessage: String?

        var confirmedCanonicalOrgID: UUID? {
            guard propertyExists,
                  sessionExists,
                  sessionPropertyIDMatches,
                  let propertyOrgID,
                  let sessionOrgID,
                  propertyOrgID == sessionOrgID else {
                return nil
            }
            return propertyOrgID
        }

        var hasConfirmedRemoteParent: Bool {
            confirmedCanonicalOrgID != nil
        }
    }

    struct SessionSnapshotAuthPreflightResult: Equatable {
        var checkedAt: Date
        var appAuthUserID: String?
        var clientAuthUserID: String?
        var usersMatch: Bool
        var payloadOrgID: UUID?
        var payloadPropertyID: UUID?
        var payloadSessionID: UUID?
        var remoteParentStatus: SessionSnapshotAuthPreflightRemoteParentStatus
        var isReady: Bool
        var failureMessage: String?
    }

    struct SessionSnapshotLocalOrgRepairResult: Equatable {
        var repaired: Bool
        var propertyID: UUID?
        var sessionID: UUID?
        var previousLocalOrgID: UUID?
        var canonicalOrgID: UUID?
        var message: String
    }

    struct LocalOrgDriftAuditSample: Equatable {
        var subject: String
        var propertyID: UUID
        var sessionID: UUID?
        var localOrgID: UUID?
        var canonicalOrgID: UUID
        var detail: String

        var diagnosticsLine: String {
            [
                "subject=\(subject)",
                "property_id=\(propertyID.uuidString)",
                "session_id=\(sessionID?.uuidString ?? "none")",
                "local_org_id=\(localOrgID?.uuidString ?? "none")",
                "canonical_org_id=\(canonicalOrgID.uuidString)",
                "detail=\(detail)"
            ].joined(separator: " ")
        }
    }

    struct LocalOrgDriftAuditResult: Equatable {
        var checkedAt: Date
        var totalPropertiesChecked: Int
        var totalSessionsChecked: Int
        var propertyMismatchCount: Int
        var sessionMismatchCount: Int
        var unableToConfirmCount: Int
        var confirmedMismatches: [LocalOrgDriftAuditSample] = []
        var samples: [LocalOrgDriftAuditSample]

        var totalMismatchCount: Int {
            propertyMismatchCount + sessionMismatchCount
        }
    }

    struct LocalOrgDriftRepairResult: Equatable {
        var repairedAt: Date
        var attemptedCount: Int
        var repairedPropertyCount: Int
        var repairedSessionCount: Int
        var skippedCount: Int
        var failureCount: Int
        var samples: [LocalOrgDriftAuditSample]
    }

    struct ManualSessionSnapshotUploadTarget: Equatable {
        enum Source: String, Equatable {
            case activeSession = "active_session"
            case mostRecentLocalSession = "most_recent_local_session"
        }

        let source: Source
        let propertyID: UUID
        let propertyName: String
        let sessionID: UUID
        let sessionStatus: Session.Status
        let sessionStartedAt: Date
    }

    struct ManualSessionSnapshotUploadTargetResolution: Equatable {
        let target: ManualSessionSnapshotUploadTarget?
        let selectedPropertyID: UUID?
        let sessionsFoundForPropertyCount: Int
        let localSessionIndexAvailable: Bool
        let reason: String
    }

    struct ManualSessionSnapshotTestSessionResult: Equatable {
        let sessionID: UUID?
        let propertyID: UUID?
        let created: Bool
        let message: String
    }

    struct SessionSnapshotStorageObject: Equatable {
        let bucket: String
        let path: String
        let payloadData: Data
        let contentType: String
        let payloadSHA256: String
    }

    struct SessionSnapshotUploadManifest: Codable, Equatable {
        let media: [SessionSnapshotMediaManifestItem]
    }

    struct SessionSnapshotUploadRow: Codable, Equatable, Identifiable {
        let id: UUID
        let orgID: UUID
        let propertyID: UUID
        let sessionID: UUID
        let snapshotKind: String
        let snapshotSchemaVersion: Int
        let sessionMetadataSchemaVersion: Int?
        let trigger: String
        let sessionStatus: String
        let isSealed: Bool
        let exportedAt: Date?
        let firstDeliveredAt: Date?
        let reExportExpiresAt: Date?
        let payloadStorageBucket: String
        let payloadStoragePath: String
        let payloadByteSize: Int
        let rawSessionJSONSHA256: String
        let snapshotPayloadSHA256: String
        let manifest: SessionSnapshotUploadManifest
        let shotCount: Int
        let issueCount: Int
        let guidedCount: Int
        let mediaManifestCount: Int
        let missingLocalOriginalsCount: Int
        let supabaseStorageMetadataCount: Int
        let createdBy: UUID?
        let updatedBy: UUID?
        let createdAt: Date?

        enum CodingKeys: String, CodingKey {
            case id
            case orgID = "org_id"
            case propertyID = "property_id"
            case sessionID = "session_id"
            case snapshotKind = "snapshot_kind"
            case snapshotSchemaVersion = "snapshot_schema_version"
            case sessionMetadataSchemaVersion = "session_metadata_schema_version"
            case trigger
            case sessionStatus = "session_status"
            case isSealed = "is_sealed"
            case exportedAt = "exported_at"
            case firstDeliveredAt = "first_delivered_at"
            case reExportExpiresAt = "re_export_expires_at"
            case payloadStorageBucket = "payload_storage_bucket"
            case payloadStoragePath = "payload_storage_path"
            case payloadByteSize = "payload_byte_size"
            case rawSessionJSONSHA256 = "raw_session_json_sha256"
            case snapshotPayloadSHA256 = "snapshot_payload_sha256"
            case manifest
            case shotCount = "shot_count"
            case issueCount = "issue_count"
            case guidedCount = "guided_count"
            case mediaManifestCount = "media_manifest_count"
            case missingLocalOriginalsCount = "missing_local_originals_count"
            case supabaseStorageMetadataCount = "supabase_storage_metadata_count"
            case createdBy = "created_by"
            case updatedBy = "updated_by"
            case createdAt = "created_at"
        }
    }

    struct SessionSnapshotReadbackResult: Equatable {
        var checkedAt: Date
        var snapshotID: UUID?
        var propertyID: UUID?
        var sessionID: UUID?
        var storagePathPresent: Bool
        var rowFound: Bool
        var payloadReadable: Bool
        var checksumVerified: Bool
        var byteSizeMatches: Bool
        var countsValid: Bool
        var rowObjectConsistent: Bool
        var payloadByteSize: Int?
        var snapshotCreatedAt: Date?
        var failureReason: String?

        var status: String {
            if rowFound && payloadReadable && checksumVerified && byteSizeMatches && countsValid && rowObjectConsistent {
                return "verified"
            }
            if !rowFound { return "row_missing" }
            if !payloadReadable { return "payload_unreadable" }
            if !checksumVerified { return "checksum_mismatch" }
            if !byteSizeMatches { return "byte_size_mismatch" }
            if !countsValid { return "count_mismatch" }
            return "row_object_mismatch"
        }
    }

