    private func fetchCanonicalReadRemoteSnapshotIfAvailable(
        activeOrganizationID: UUID?,
        propertyID: UUID,
        sessionID: UUID?
    ) async -> CanonicalReadRemoteSnapshot? {
        if let canonicalReadRemoteSnapshotFetchOverride {
            do {
                return try await canonicalReadRemoteSnapshotFetchOverride(activeOrganizationID ?? UUID(), propertyID, sessionID)
            } catch {
                recordDiagnosticsError(error)
                return nil
            }
        }
        guard backendFeatureFlags.supabaseEnabled,
              isOrganizationContextReady,
              let activeOrganizationID,
              let client = supabaseClient else {
            return nil
        }

        let orgValue = activeOrganizationID.uuidString.lowercased()
        let propertyValue = propertyID.uuidString.lowercased()
        let sessionValue = sessionID?.uuidString.lowercased()

        async let observations: [CanonicalReadRemoteObservationRecord]? = {
            guard let sessionValue else { return [] }
            do {
                return try await client
                    .from("observations")
                    .select("id, session_id, deleted_at")
                    .eq("org_id", value: orgValue)
                    .eq("session_id", value: sessionValue)
                    .limit(5_000)
                    .execute()
                    .value as [CanonicalReadRemoteObservationRecord]
            } catch {
                return nil
            }
        }()

        do {
            async let properties: [CanonicalReadRemotePropertyRecord] = client
                .from("properties")
                .select("id, org_id, updated_at, revision, deleted_at")
                .eq("org_id", value: orgValue)
                .eq("id", value: propertyValue)
                .limit(2)
                .execute()
                .value

            async let sessions: [CanonicalReadRemoteSessionRecord] = {
                var query = client
                    .from("sessions")
                    .select("id, org_id, property_id, status, updated_at, revision, deleted_at")
                    .eq("org_id", value: orgValue)
                    .eq("property_id", value: propertyValue)
                if let sessionValue {
                    query = query.eq("id", value: sessionValue)
                }
                return try await query
                    .limit(25)
                    .execute()
                    .value as [CanonicalReadRemoteSessionRecord]
            }()

            async let shots: [CanonicalReadRemoteShotRecord] = {
                guard let sessionValue else { return [] }
                return try await client
                    .from("shots")
                    .select("id, session_id, deleted_at")
                    .eq("org_id", value: orgValue)
                    .eq("session_id", value: sessionValue)
                    .limit(5_000)
                    .execute()
                    .value as [CanonicalReadRemoteShotRecord]
            }()

            return try await CanonicalReadRemoteSnapshot(
                properties: properties.map {
                    CanonicalReadRemotePropertyRow(
                        id: $0.id,
                        orgID: $0.orgID,
                        updatedAt: $0.updatedAt,
                        revision: $0.revision,
                        deletedAt: $0.deletedAt
                    )
                },
                sessions: sessions.map {
                    CanonicalReadRemoteSessionRow(
                        id: $0.id,
                        orgID: $0.orgID,
                        propertyID: $0.propertyID,
                        status: $0.status,
                        updatedAt: $0.updatedAt,
                        revision: $0.revision,
                        deletedAt: $0.deletedAt
                    )
                },
                shots: shots.map {
                    CanonicalReadRemoteShotRow(
                        id: $0.id,
                        sessionID: $0.sessionID,
                        deletedAt: $0.deletedAt
                    )
                },
                observations: observations?.map {
                    CanonicalReadRemoteObservationRow(
                        id: $0.id,
                        sessionID: $0.sessionID,
                        deletedAt: $0.deletedAt
                    )
                }
            )
        } catch {
            recordDiagnosticsError(error)
            return nil
        }
    }

    private func makeMediaRecoveryInspectionSummary(
        inspectedAt: Date,
        activeOrganizationID: UUID?,
        local: LocalDivergenceSnapshot,
        remote: RemoteDivergenceSnapshot?,
        divergenceAuditSummary: DivergenceAuditSummary?,
        previousSnapshotOrgID: UUID? = nil
    ) -> MediaRecoveryInspectionSummary {
        let localPropertiesByID = dictionaryByNormalizedID(local.properties, id: \.id)
        let localSessionsByID = dictionaryByNormalizedID(local.sessions, id: \.id)
        let remotePropertiesByID = dictionaryByNormalizedID(remote?.properties ?? [], id: \.id)
        let remoteSessionsByID = dictionaryByNormalizedID(remote?.sessions ?? [], id: \.id)
        let remoteShotsByID = dictionaryByNormalizedID(remote?.shots ?? [], id: \.id)
        let remotePropertyIDs = Set(remotePropertiesByID.keys)
        let remoteSessionIDs = Set(remoteSessionsByID.keys)
        print(
            "[MediaRecovery] event=inspect_scope " +
            "activeOrgID=\(activeOrganizationID?.uuidString ?? "nil") " +
            "previousSnapshotOrgID=\(previousSnapshotOrgID?.uuidString ?? "nil")"
        )
        if let previousSnapshotOrgID,
           previousSnapshotOrgID != activeOrganizationID {
            print(
                "[MediaRecovery] event=inspect_skipped_stale_snapshot " +
                "activeOrgID=\(activeOrganizationID?.uuidString ?? "nil") " +
                "snapshotOrgID=\(previousSnapshotOrgID.uuidString)"
            )
        }
        let divergenceCandidateReasons: [String: Set<String>]
        if let divergenceAuditSummary,
           divergenceAuditSummary.activeOrganizationID != activeOrganizationID {
            print(
                "[MediaRecovery] event=inspect_skipped_stale_snapshot " +
                "activeOrgID=\(activeOrganizationID?.uuidString ?? "nil") " +
                "snapshotOrgID=\(divergenceAuditSummary.activeOrganizationID?.uuidString ?? "nil")"
            )
            divergenceCandidateReasons = [:]
        } else {
            divergenceCandidateReasons = mediaRecoveryDivergenceCandidateReasons(divergenceAuditSummary)
        }

        var candidateReasonsByShotID: [String: Set<String>] = [:]
        for localShot in local.shots {
            let shot = localShot.shot
            let shotKey = divergenceKey(shot.shotID)
            let propertyKey = divergenceKey(localShot.propertyID)
            let sessionKey = divergenceKey(localShot.sessionID)
            guard localMediaRecoveryShotBelongsToActiveScope(
                localShot,
                activeOrganizationID: activeOrganizationID,
                localPropertiesByID: localPropertiesByID,
                remotePropertyIDs: remotePropertyIDs,
                remoteSessionIDs: remoteSessionIDs
            ) else {
                continue
            }
            if shot.uploadState != "uploaded",
               shot.uploadAttempts >= maximumSupabaseMediaUploadAttempts {
                candidateReasonsByShotID[shotKey, default: []].insert("retry_capped_media")
            }
            if let reasons = divergenceCandidateReasons[shotKey],
               remotePropertyIDs.contains(propertyKey) || remoteSessionIDs.contains(sessionKey) {
                candidateReasonsByShotID[shotKey, default: []].formUnion(reasons)
            }
        }

        let candidates = local.shots.compactMap { localShot -> MediaRecoveryCandidate? in
            let shot = localShot.shot
            let shotKey = divergenceKey(shot.shotID)
            guard let sourceReasons = candidateReasonsByShotID[shotKey],
                  !sourceReasons.isEmpty else {
                return nil
            }

            let property = localPropertiesByID[divergenceKey(localShot.propertyID)]
            let session = localSessionsByID[divergenceKey(localShot.sessionID)]
            let remoteProperty = remotePropertiesByID[divergenceKey(localShot.propertyID)]
            let remoteSession = remoteSessionsByID[divergenceKey(localShot.sessionID)]
            let remoteShot = remoteShotsByID[shotKey]
            let fileExists = localMediaFileExists(
                propertyID: localShot.propertyID,
                sessionID: localShot.sessionID,
                shot: shot
            )
            let propertyOrgID = property?.orgId
            let sessionOrgID = localShot.metadataOrgID
            let staleLocalOrg = isStaleLocalMediaRecoveryOrg(
                activeOrganizationID: activeOrganizationID,
                propertyOrgID: propertyOrgID,
                sessionOrgID: sessionOrgID
            )
            let reconciledOrgID = mediaRecoveryReconciledOrganizationID(
                activeOrganizationID: activeOrganizationID,
                localPropertyID: localShot.propertyID,
                localSessionID: localShot.sessionID,
                remoteProperty: remoteProperty,
                remoteSession: remoteSession
            )
            let remotePreflightAvailable = remote != nil
            let remoteStoragePathPresent = remoteShot.map { normalizedSupabaseText($0.storagePath) != nil }
            let classification = Self.mediaRecoveryClassification(
                fileExists: fileExists,
                staleLocalOrg: staleLocalOrg,
                remotePreflightAvailable: remotePreflightAvailable,
                remotePropertyExists: remotePreflightAvailable ? remoteProperty != nil : nil,
                remoteSessionExists: remotePreflightAvailable ? remoteSession != nil : nil,
                remoteShotExists: remotePreflightAvailable ? remoteShot != nil : nil,
                remoteStoragePathPresent: remoteStoragePathPresent,
                remoteUploadState: remoteShot?.uploadState
            )

            return MediaRecoveryCandidate(
                id: shot.shotID,
                shotID: shot.shotID,
                sessionID: localShot.sessionID,
                propertyID: localShot.propertyID,
                propertyName: normalizedSupabaseText(property?.name) ?? "Unknown Property",
                sessionStatus: session?.status.rawValue ?? "unknown",
                sessionStartedAt: session?.startedAt,
                sessionIsSealed: session?.isSealed ?? false,
                shotIsFlagged: shot.isFlagged,
                uploadState: shot.uploadState,
                uploadAttempts: shot.uploadAttempts,
                lastUploadError: shot.lastUploadError.map(Self.sanitizedDiagnosticsErrorMessage),
                fileExists: fileExists,
                localFilename: Self.safeDiagnosticsFilename(
                    originalFilename: shot.originalFilename,
                    originalRelativePath: shot.originalRelativePath
                ),
                activeOrganizationID: activeOrganizationID,
                reconciledOrganizationID: reconciledOrgID,
                propertyOrgID: propertyOrgID,
                sessionOrgID: sessionOrgID,
                staleLocalOrg: staleLocalOrg,
                remotePreflightAvailable: remotePreflightAvailable,
                remotePropertyExists: remotePreflightAvailable ? remoteProperty != nil : nil,
                remoteSessionExists: remotePreflightAvailable ? remoteSession != nil : nil,
                remoteShotExists: remotePreflightAvailable ? remoteShot != nil : nil,
                remoteStoragePathPresent: remoteStoragePathPresent,
                classification: classification,
                importanceHint: Self.mediaRecoveryImportanceHint(
                    sessionStatus: session?.status.rawValue,
                    sessionIsSealed: session?.isSealed ?? false,
                    shotIsFlagged: shot.isFlagged
                ),
                sourceReasons: sourceReasons.sorted()
            )
        }
        .sorted {
            if $0.classification.rawValue != $1.classification.rawValue {
                return $0.classification.rawValue < $1.classification.rawValue
            }
            if $0.propertyName != $1.propertyName {
                return $0.propertyName < $1.propertyName
            }
            return $0.shotID.uuidString < $1.shotID.uuidString
        }

        return MediaRecoveryInspectionSummary(
            inspectedAt: inspectedAt,
            activeOrganizationID: activeOrganizationID,
            remotePreflightAvailable: remote != nil,
            candidates: candidates
        )
    }

    private func mediaRecoveryRetryPreflight(
        propertyID: UUID,
        sessionID: UUID,
        shotID: UUID
    ) async -> MediaRecoveryRetryPreflight {
        guard let activeOrganizationID else {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Active organization is unavailable.",
                resolvedOrganizationID: nil,
                metadata: nil,
                shot: nil
            )
        }
        guard canAccessOrganization(activeOrganizationID) else {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Active organization is not accessible.",
                resolvedOrganizationID: nil,
                metadata: nil,
                shot: nil
            )
        }
        guard let metadata = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: sessionID),
              let shot = metadata.shots.first(where: { $0.shotID == shotID }) else {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Local session metadata or shot is unavailable.",
                resolvedOrganizationID: activeOrganizationID,
                metadata: nil,
                shot: nil
            )
        }
        guard resolveMediaRecoveryFileURL(propertyID: propertyID, sessionID: sessionID, shot: shot) != nil else {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Local media file is missing.",
                resolvedOrganizationID: activeOrganizationID,
                metadata: metadata,
                shot: shot
            )
        }

        guard let remote = await fetchRemoteDivergenceSnapshotIfAvailable(activeOrganizationID: activeOrganizationID) else {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Remote preflight is unavailable.",
                resolvedOrganizationID: activeOrganizationID,
                metadata: metadata,
                shot: shot
            )
        }

        let remotePropertiesByID = dictionaryByNormalizedID(remote.properties, id: \.id)
        let remoteSessionsByID = dictionaryByNormalizedID(remote.sessions, id: \.id)
        let remoteShotsByID = dictionaryByNormalizedID(remote.shots, id: \.id)
        let propertyKey = divergenceKey(propertyID)
        let sessionKey = divergenceKey(sessionID)
        let shotKey = divergenceKey(shotID)

        guard remotePropertiesByID[propertyKey]?.orgID == activeOrganizationID else {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Remote property was not found under the active organization.",
                resolvedOrganizationID: activeOrganizationID,
                metadata: metadata,
                shot: shot
            )
        }

        if let remoteShot = remoteShotsByID[shotKey],
           normalizedSupabaseText(remoteShot.uploadState)?.lowercased() == "uploaded",
           normalizedSupabaseText(remoteShot.storagePath) != nil {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Remote shot already appears complete.",
                resolvedOrganizationID: activeOrganizationID,
                metadata: metadata,
                shot: shot
            )
        }

        if let remoteSession = remoteSessionsByID[sessionKey],
           remoteSession.orgID != activeOrganizationID || remoteSession.propertyID != propertyID {
            return MediaRecoveryRetryPreflight(
                isAllowed: false,
                message: "Remote session belongs to a different property or organization.",
                resolvedOrganizationID: activeOrganizationID,
                metadata: metadata,
                shot: shot
            )
        }

        return MediaRecoveryRetryPreflight(
            isAllowed: true,
            message: remoteSessionsByID[sessionKey] == nil
                ? "Remote property exists; session will be safely ensured under the active organization."
                : "Remote property and session preflight passed.",
            resolvedOrganizationID: activeOrganizationID,
            metadata: metadata,
            shot: shot
        )
    }

    private func performMediaRecoveryRetryUpload(
        propertyID: UUID,
        sessionID: UUID,
        shotID: UUID,
        orgID: UUID,
        metadata: SessionMetadata,
        shot: ShotMetadata
    ) async throws {
#if DEBUG
        if let mediaRecoveryUploadOverride {
            try await mediaRecoveryUploadOverride(orgID, propertyID, sessionID, shotID)
            try? localStore.updateShotStorageMetadata(propertyID: propertyID, sessionID: sessionID, shotID: shotID) { shot in
                shot.storageBucket = self.supabaseOperationalMediaBucket
                shot.storagePath = self.operationalMediaStoragePath(
                    sessionID: sessionID,
                    shotID: shotID,
                    originalFilename: shot.originalFilename
                )
                shot.uploadState = "uploaded"
                shot.uploadAttempts += 1
                shot.lastUploadError = nil
                shot.updatedAt = Date()
            }
            return
        }
#endif
        guard let client = supabaseClient else {
            throw NSError(domain: "ScoutCapture.MediaRecovery", code: 1, userInfo: [
                NSLocalizedDescriptionKey: "Supabase client is unavailable."
            ])
        }
        guard let localFileURL = resolveMediaRecoveryFileURL(
            propertyID: propertyID,
            sessionID: sessionID,
            shot: shot
        ) else {
            throw NSError(domain: "ScoutCapture.MediaRecovery", code: 2, userInfo: [
                NSLocalizedDescriptionKey: "Local media file is missing."
            ])
        }

        let fileData = try Data(contentsOf: localFileURL, options: [.mappedIfSafe])
        let checksum = sha256Hex(for: fileData)
        let byteSize = fileData.count
        let storagePath = operationalMediaStoragePath(
            sessionID: sessionID,
            shotID: shotID,
            originalFilename: shot.originalFilename
        )

        try await ensureSupabaseSessionPrerequisites(
            propertyID: propertyID,
            sessionID: sessionID,
            metadata: metadata,
            orgID: orgID
        )
        try await persistShotRichMetadataToSupabase(
            orgID: orgID,
            propertyID: propertyID,
            sessionID: sessionID,
            metadata: metadata,
            shot: shot,
            allowInsert: true
        )
        _ = try await client.storage.from(supabaseOperationalMediaBucket).upload(
            storagePath,
            fileURL: localFileURL,
            options: FileOptions(
                cacheControl: "31536000",
                contentType: contentType(for: localFileURL),
                upsert: true
            )
        )
        try await persistShotStorageMetadataToSupabase(
            orgID: orgID,
            propertyID: propertyID,
            sessionID: sessionID,
            shotID: shotID,
            storageBucket: supabaseOperationalMediaBucket,
            storagePath: storagePath,
            checksumSHA256: checksum,
            byteSize: byteSize,
            uploadState: "uploaded",
            uploadAttempts: shot.uploadAttempts + 1,
            lastUploadError: nil
        )

        let verified = try await fetchShotFinalizeReadinessRecord(
            client: client,
            shotID: shotID,
            sessionID: sessionID,
            activeOrganizationID: orgID
        )
        guard normalizedSupabaseText(verified?.storageBucket) == supabaseOperationalMediaBucket,
              normalizedSupabaseText(verified?.storagePath) == storagePath,
              normalizedSupabaseText(verified?.uploadState)?.lowercased() == "uploaded" else {
            throw NSError(domain: "ScoutCapture.MediaRecovery", code: 3, userInfo: [
                NSLocalizedDescriptionKey: "Remote upload verification failed."
            ])
        }

        try? localStore.updateShotStorageMetadata(propertyID: propertyID, sessionID: sessionID, shotID: shotID) { shot in
            shot.storageBucket = self.supabaseOperationalMediaBucket
            shot.storagePath = storagePath
            shot.checksumSHA256 = checksum
            shot.byteSize = byteSize
            shot.uploadState = "uploaded"
            shot.lastUploadError = nil
            shot.updatedAt = Date()
        }
    }

    private func resolveMediaRecoveryFileURL(
        propertyID: UUID,
        sessionID: UUID,
        shot: ShotMetadata
    ) -> URL? {
        let relativePath = shot.originalRelativePath.trimmingCharacters(in: .whitespacesAndNewlines)
        if let resolved = localStore.resolveSessionRelativeFileURL(
            propertyID: propertyID,
            sessionID: sessionID,
            relativePath: relativePath
        ), FileManager.default.fileExists(atPath: resolved.path) {
            return resolved
        }
        if !relativePath.isEmpty {
            let fallback = localStore
                .sessionFolderURL(propertyID: propertyID, sessionID: sessionID)
                .appendingPathComponent(relativePath, isDirectory: false)
            if FileManager.default.fileExists(atPath: fallback.path) {
                return fallback
            }
        }
        guard let filename = Self.safeDiagnosticsFilename(
            originalFilename: shot.originalFilename,
            originalRelativePath: shot.originalRelativePath
        ) else {
            return nil
        }
        let originalsFallback = localStore
            .originalsFolderURL(propertyID: propertyID, sessionID: sessionID)
            .appendingPathComponent(filename, isDirectory: false)
        return FileManager.default.fileExists(atPath: originalsFallback.path) ? originalsFallback : nil
    }

    private func localMediaRecoveryShotBelongsToActiveScope(
        _ localShot: LocalDivergenceShot,
        activeOrganizationID: UUID?,
        localPropertiesByID: [String: Property],
        remotePropertyIDs: Set<String>,
        remoteSessionIDs: Set<String>
    ) -> Bool {
        guard let activeOrganizationID else { return false }
        let propertyKey = divergenceKey(localShot.propertyID)
        let sessionKey = divergenceKey(localShot.sessionID)
        if localPropertiesByID[propertyKey]?.orgId == activeOrganizationID {
            return true
        }
        if localShot.metadataOrgID == activeOrganizationID {
            return true
        }
        return remotePropertyIDs.contains(propertyKey) || remoteSessionIDs.contains(sessionKey)
    }

    private func mediaRecoveryReconciledOrganizationID(
        activeOrganizationID: UUID?,
        localPropertyID: UUID,
        localSessionID: UUID,
        remoteProperty: DivergenceRemotePropertyRecord?,
        remoteSession: DivergenceRemoteSessionRecord?
    ) -> UUID? {
        guard let activeOrganizationID else { return nil }
        if remoteProperty?.id == localPropertyID,
           remoteProperty?.orgID == activeOrganizationID {
            return activeOrganizationID
        }
        if remoteSession?.id == localSessionID,
           remoteSession?.orgID == activeOrganizationID {
            return activeOrganizationID
        }
        return nil
    }

    private func mediaRecoveryDivergenceCandidateReasons(
        _ divergenceAuditSummary: DivergenceAuditSummary?
    ) -> [String: Set<String>] {
        guard let divergenceAuditSummary else { return [:] }
        var reasonsByShotID: [String: Set<String>] = [:]
        for item in divergenceAuditSummary.items {
            guard let shotID = item.shotID else { continue }
            let shotKey = divergenceKey(shotID)
            switch item.category {
            case .localOnlyShot:
                reasonsByShotID[shotKey, default: []].insert("divergence_local_only_shot")
            case .mediaDrift:
                if item.reason.localizedCaseInsensitiveContains("retry-capped") {
                    reasonsByShotID[shotKey, default: []].insert("divergence_retry_capped_media_drift")
                }
            default:
                continue
            }
        }
        return reasonsByShotID
    }

    private func localMediaFileExists(
        propertyID: UUID,
        sessionID: UUID,
        shot: ShotMetadata
    ) -> Bool {
        let relativePath = shot.originalRelativePath.trimmingCharacters(in: .whitespacesAndNewlines)
        if let resolved = localStore.resolveSessionRelativeFileURL(
            propertyID: propertyID,
            sessionID: sessionID,
            relativePath: relativePath
        ) {
            return FileManager.default.fileExists(atPath: resolved.path)
        }
        if !relativePath.isEmpty {
            let fallback = localStore
                .sessionFolderURL(propertyID: propertyID, sessionID: sessionID)
                .appendingPathComponent(relativePath, isDirectory: false)
            if FileManager.default.fileExists(atPath: fallback.path) {
                return true
            }
        }
        let filename = Self.safeDiagnosticsFilename(
            originalFilename: shot.originalFilename,
            originalRelativePath: shot.originalRelativePath
        )
        guard let filename else { return false }
        let originalsFallback = localStore
            .originalsFolderURL(propertyID: propertyID, sessionID: sessionID)
            .appendingPathComponent(filename, isDirectory: false)
        return FileManager.default.fileExists(atPath: originalsFallback.path)
    }

    private func isStaleLocalMediaRecoveryOrg(
        activeOrganizationID: UUID?,
        propertyOrgID: UUID?,
        sessionOrgID: UUID?
    ) -> Bool {
        guard let activeOrganizationID else { return false }
        if let propertyOrgID, propertyOrgID != activeOrganizationID {
            return true
        }
        if let sessionOrgID, sessionOrgID != activeOrganizationID {
            return true
        }
        return false
    }

    nonisolated static func mediaRecoveryClassification(
        fileExists: Bool,
        staleLocalOrg: Bool,
        remotePreflightAvailable: Bool,
        remotePropertyExists: Bool?,
        remoteSessionExists: Bool?,
        remoteShotExists: Bool?,
        remoteStoragePathPresent: Bool?,
        remoteUploadState: String?
    ) -> MediaRecoveryClassification {
        guard fileExists else { return .missingLocalFile }

        let normalizedRemoteUploadState = remoteUploadState?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        if remoteShotExists == true,
           remoteStoragePathPresent == true,
           normalizedRemoteUploadState == "uploaded" {
            return .alreadyRemoteComplete
        }

        if staleLocalOrg {
            return .needsOrgReconciliation
        }

        guard remotePreflightAvailable else {
            return .needsManualReview
        }

        if remotePropertyExists == false || remoteSessionExists == false {
            return .missingRemoteParent
        }

        if remotePropertyExists == true, remoteSessionExists == true {
            return .retryable
        }

        return .needsManualReview
    }

    nonisolated static func mediaRecoveryImportanceHint(
        sessionStatus: String?,
        sessionIsSealed: Bool,
        shotIsFlagged: Bool
    ) -> String {
        if shotIsFlagged {
            return "Flagged shot; likely needs review."
        }
        let normalizedStatus = sessionStatus?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        if sessionIsSealed || normalizedStatus == "completed" {
            return "Completed or sealed session; likely important."
        }
        if normalizedStatus == "draft" {
            return "Draft session; manual review before any future repair."
        }
        return "Manual review before any future repair."
    }

    nonisolated static func mediaRecoverySnapshotText(_ summary: MediaRecoveryInspectionSummary) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Media Recovery Candidates")
        lines.append("Inspected: \(summary.inspectedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(summary.activeOrganizationID?.uuidString ?? "none")")
        lines.append("Remote Preflight Available: \(summary.remotePreflightAvailable ? "yes" : "no")")
        lines.append("")
        lines.append("Summary")
        lines.append("Candidates Found: \(summary.candidatesFound)")
        lines.append("File Exists: \(summary.fileExistsCount)")
        lines.append("Retryable: \(summary.retryableCount)")
        lines.append("Needs Org Reconciliation: \(summary.needsOrgReconciliationCount)")
        lines.append("Missing Remote Parent: \(summary.missingRemoteParentCount)")
        lines.append("Already Remote Complete: \(summary.alreadyRemoteCompleteCount)")
        lines.append("Missing Local File: \(summary.missingLocalFileCount)")
        lines.append("Needs Manual Review: \(summary.manualReviewCount)")
        lines.append("")
        lines.append("Notes")
        lines.append("Retry-capped does not mean lost; it means automatic backfill stopped before another upload attempt.")
        lines.append("If the local file exists, recovery may be possible after remote parent and org checks pass.")
        lines.append("Draft or test sessions may be intentionally left alone after manual review.")
        lines.append("")
        lines.append("Candidates")
        for candidate in summary.candidates {
            lines.append([
                candidate.classification.rawValue,
                candidate.importanceHint,
                "property=\(candidate.propertyID.uuidString)",
                "session=\(candidate.sessionID.uuidString)",
                "shot=\(candidate.shotID.uuidString)",
                "fileExists=\(candidate.fileExists ? "yes" : "no")",
                "sessionStatus=\(candidate.sessionStatus)",
                "attempts=\(candidate.uploadAttempts)",
                "sources=\(candidate.sourceReasons.joined(separator: ","))",
                "error=\(diagnosticsPreviewText(candidate.lastUploadError, maxLength: 240) ?? "none")"
            ].joined(separator: " | "))
        }
        return lines.joined(separator: "\n")
    }

    private func makeDivergenceAuditSummary(
        ranAt: Date,
        activeOrganizationID: UUID?,
        local: LocalDivergenceSnapshot,
        remote: RemoteDivergenceSnapshot?
    ) -> DivergenceAuditSummary {
        let localPropertiesByID = dictionaryByNormalizedID(local.properties, id: \.id)
        let localSessionsByID = dictionaryByNormalizedID(local.sessions, id: \.id)
        let remotePropertiesByID = dictionaryByNormalizedID(remote?.properties ?? [], id: \.id)
        let remoteSessionsByID = dictionaryByNormalizedID(remote?.sessions ?? [], id: \.id)
        let remoteShotsByID = dictionaryByNormalizedID(remote?.shots ?? [], id: \.id)
        let remotePropertyIDs = Set(remotePropertiesByID.keys)
        let remoteSessionIDs = Set(remoteSessionsByID.keys)
        let remoteShotIDs = Set(remoteShotsByID.keys)
        let scopedLocalProperties = local.properties.filter { property in
            localPropertyBelongsToAuditScope(
                property,
                activeOrganizationID: activeOrganizationID,
                remotePropertyIDs: remotePropertyIDs
            )
        }
        let scopedLocalPropertyIDs = Set(scopedLocalProperties.map { divergenceKey($0.id) })
        let scopedLocalSessions = local.sessions.filter { session in
            localSessionBelongsToAuditScope(
                session,
                scopedLocalPropertyIDs: scopedLocalPropertyIDs,
                remoteSessionIDs: remoteSessionIDs
            )
        }
        let scopedLocalSessionIDs = Set(scopedLocalSessions.map { divergenceKey($0.id) })
        let scopedLocalShots = local.shots.filter { shot in
            localShotBelongsToAuditScope(
                shot,
                activeOrganizationID: activeOrganizationID,
                scopedLocalPropertyIDs: scopedLocalPropertyIDs,
                scopedLocalSessionIDs: scopedLocalSessionIDs,
                remoteShotIDs: remoteShotIDs
            )
        }
        let localOnlyShotIDs = Set(scopedLocalShots.compactMap { shot -> String? in
            let shotKey = divergenceKey(shot.shot.shotID)
            return remote != nil && !remoteShotIDs.contains(shotKey) ? shotKey : nil
        })

        var items: [DivergenceAuditItem] = []
        var presenceCounts = DivergencePresenceCounts()

        if remote == nil {
            items.append(
                DivergenceAuditItem(
                    category: .remoteUnavailable,
                    entityType: "remote",
                    entityID: nil,
                    orgID: activeOrganizationID,
                    reason: "Remote audit scope was unavailable; local-only and remote-only comparisons were skipped."
                )
            )
        }

        for property in local.properties.sorted(by: { $0.id.uuidString < $1.id.uuidString }) {
            let propertyKey = divergenceKey(property.id)
            if let activeOrganizationID,
               property.orgId != activeOrganizationID,
               remotePropertiesByID[propertyKey] == nil {
                items.append(
                    DivergenceAuditItem(
                        category: .staleOrgMismatch,
                        entityType: "property",
                        entityID: property.id,
                        propertyID: property.id,
                        orgID: property.orgId,
                        reason: "Local property org does not match the active organization."
                    )
                )
            }
            if property.captureProfile == nil {
                items.append(
                    DivergenceAuditItem(
                        category: .legacyCaptureProfile,
                        entityType: "property",
                        entityID: property.id,
                        propertyID: property.id,
                        orgID: property.orgId,
                        reason: "Local property capture_profile is a legacy null metadata state."
                    )
                )
            }
        }

        for session in local.sessions.sorted(by: { $0.id.uuidString < $1.id.uuidString }) {
            let propertyKey = divergenceKey(session.propertyID)
            let propertyOrgID = localPropertiesByID[propertyKey]?.orgId
            if localPropertiesByID[propertyKey] == nil {
                items.append(
                    DivergenceAuditItem(
                        category: .missingParent,
                        entityType: "session",
                        entityID: session.id,
                        propertyID: session.propertyID,
                        sessionID: session.id,
                        orgID: propertyOrgID,
                        reason: "Local session references a missing local property."
                    )
                )
            }
            if session.captureProfile == nil {
                items.append(
                    DivergenceAuditItem(
                        category: .legacyCaptureProfile,
                        entityType: "session",
                        entityID: session.id,
                        propertyID: session.propertyID,
                        sessionID: session.id,
                        orgID: propertyOrgID,
                        reason: "Local session capture_profile is a legacy null metadata state."
                    )
                )
            }
        }

        var sessionMetadataProfileFindingIDs = Set<UUID>()
        for localShot in local.shots.sorted(by: { $0.shot.shotID.uuidString < $1.shot.shotID.uuidString }) {
            let shot = localShot.shot
            let shotKey = divergenceKey(shot.shotID)
            if let activeOrganizationID,
               let metadataOrgID = localShot.metadataOrgID,
               metadataOrgID != activeOrganizationID,
               remoteShotsByID[shotKey] == nil,
               !scopedLocalPropertyIDs.contains(divergenceKey(localShot.propertyID)),
               !scopedLocalSessionIDs.contains(divergenceKey(localShot.sessionID)) {
                items.append(
                    DivergenceAuditItem(
                        category: .staleOrgMismatch,
                        entityType: "shot",
                        entityID: shot.shotID,
                        propertyID: localShot.propertyID,
                        sessionID: localShot.sessionID,
                        shotID: shot.shotID,
                        orgID: metadataOrgID,
                        reason: "Local shot metadata org does not match the active organization."
                    )
                )
            }
            if localPropertiesByID[divergenceKey(shot.propertyID)] == nil,
               !localOnlyShotIDs.contains(shotKey) {
                items.append(
                    DivergenceAuditItem(
                        category: .missingParent,
                        entityType: "shot",
                        entityID: shot.shotID,
                        propertyID: shot.propertyID,
                        sessionID: shot.sessionID,
                        shotID: shot.shotID,
                        orgID: localShot.metadataOrgID,
                        reason: "Local shot references a missing local property."
                    )
                )
            }
            if localSessionsByID[divergenceKey(shot.sessionID)] == nil,
               !localOnlyShotIDs.contains(shotKey) {
                items.append(
                    DivergenceAuditItem(
                        category: .missingParent,
                        entityType: "shot",
                        entityID: shot.shotID,
                        propertyID: shot.propertyID,
                        sessionID: shot.sessionID,
                        shotID: shot.shotID,
                        orgID: localShot.metadataOrgID,
                        reason: "Local shot references a missing local session."
                    )
                )
            }
            appendLocalMediaDriftItems(for: localShot, to: &items)
            if CaptureProfile(storedValue: localShot.metadataCaptureProfile) == nil,
               sessionMetadataProfileFindingIDs.insert(localShot.sessionID).inserted {
                items.append(
                    DivergenceAuditItem(
                        category: .legacyCaptureProfile,
                        entityType: "session_metadata",
                        entityID: localShot.sessionID,
                        propertyID: localShot.propertyID,
                        sessionID: localShot.sessionID,
                        orgID: localShot.metadataOrgID,
                        reason: "Local session metadata capture_profile is a legacy null or unknown metadata state."
                    )
                )
            }
        }

        if let remote {
            presenceCounts = appendLocalRemotePresenceItems(
                localProperties: scopedLocalProperties,
                localSessions: scopedLocalSessions,
                localShots: scopedLocalShots,
                remotePropertiesByID: remotePropertiesByID,
                remoteSessionsByID: remoteSessionsByID,
                remoteShotsByID: remoteShotsByID,
                activeOrganizationID: activeOrganizationID,
                to: &items
            )
            appendRemoteParentAndMediaItems(
                remote: remote,
                remotePropertiesByID: remotePropertiesByID,
                remoteSessionsByID: remoteSessionsByID,
                to: &items
            )
            appendCaptureProfileMismatchItems(
                localPropertiesByID: localPropertiesByID,
                localSessionsByID: localSessionsByID,
                remotePropertiesByID: remotePropertiesByID,
                remoteSessionsByID: remoteSessionsByID,
                to: &items
            )
            appendDeletedHiddenMismatchItems(
                localPropertiesByID: localPropertiesByID,
                localSessionsByID: localSessionsByID,
                remotePropertiesByID: remotePropertiesByID,
                remoteSessionsByID: remoteSessionsByID,
                to: &items
            )
        }

        let sortedItems = items.sorted {
            if $0.category.rawValue != $1.category.rawValue {
                return $0.category.rawValue < $1.category.rawValue
            }
            return ($0.entityID?.uuidString ?? "") < ($1.entityID?.uuidString ?? "")
        }

        return DivergenceAuditSummary(
            ranAt: ranAt,
            activeOrganizationID: activeOrganizationID,
            remoteScopeAvailable: remote != nil,
            localPropertyCount: local.properties.count,
            remotePropertyCount: remote?.properties.count ?? 0,
            localSessionCount: local.sessions.count,
            remoteSessionCount: remote?.sessions.count ?? 0,
            localShotCount: local.shots.count,
            remoteShotCount: remote?.shots.count ?? 0,
            matchedPropertyCount: presenceCounts.matchedProperties,
            matchedSessionCount: presenceCounts.matchedSessions,
            matchedShotCount: presenceCounts.matchedShots,
            localOnlyPropertyCount: presenceCounts.localOnlyProperties,
            remoteOnlyPropertyCount: presenceCounts.remoteOnlyProperties,
            localOnlySessionCount: presenceCounts.localOnlySessions,
            remoteOnlySessionCount: presenceCounts.remoteOnlySessions,
            localOnlyShotCount: presenceCounts.localOnlyShots,
            remoteOnlyShotCount: presenceCounts.remoteOnlyShots,
            staleOrgReconciledPropertyCount: presenceCounts.staleOrgReconciledProperties,
            staleOrgReconciledShotCount: presenceCounts.staleOrgReconciledShots,
            items: sortedItems
        )
    }

    private func localPropertyBelongsToAuditScope(
        _ property: Property,
        activeOrganizationID: UUID?,
        remotePropertyIDs: Set<String>
    ) -> Bool {
        guard let activeOrganizationID else { return true }
        return property.orgId == activeOrganizationID ||
            remotePropertyIDs.contains(divergenceKey(property.id))
    }

    private func localSessionBelongsToAuditScope(
        _ session: Session,
        scopedLocalPropertyIDs: Set<String>,
        remoteSessionIDs: Set<String>
    ) -> Bool {
        scopedLocalPropertyIDs.contains(divergenceKey(session.propertyID)) ||
            remoteSessionIDs.contains(divergenceKey(session.id))
    }

    private func localShotBelongsToAuditScope(
        _ shot: LocalDivergenceShot,
        activeOrganizationID: UUID?,
        scopedLocalPropertyIDs: Set<String>,
        scopedLocalSessionIDs: Set<String>,
        remoteShotIDs: Set<String>
    ) -> Bool {
        remoteShotIDs.contains(divergenceKey(shot.shot.shotID)) ||
            scopedLocalPropertyIDs.contains(divergenceKey(shot.propertyID)) ||
            scopedLocalSessionIDs.contains(divergenceKey(shot.sessionID)) ||
            (activeOrganizationID != nil && shot.metadataOrgID == activeOrganizationID)
    }

    @discardableResult
    private func appendLocalRemotePresenceItems(
        localProperties: [Property],
        localSessions: [Session],
        localShots: [LocalDivergenceShot],
        remotePropertiesByID: [String: DivergenceRemotePropertyRecord],
        remoteSessionsByID: [String: DivergenceRemoteSessionRecord],
        remoteShotsByID: [String: DivergenceRemoteShotRecord],
        activeOrganizationID: UUID?,
        to items: inout [DivergenceAuditItem]
    ) -> DivergencePresenceCounts {
        let localPropertyIDs = Set(localProperties.map { divergenceKey($0.id) })
        let localSessionIDs = Set(localSessions.map { divergenceKey($0.id) })
        let localShotIDs = Set(localShots.map { divergenceKey($0.shot.shotID) })
        var counts = DivergencePresenceCounts()
        counts.matchedProperties = localPropertyIDs.intersection(remotePropertiesByID.keys).count
        counts.matchedSessions = localSessionIDs.intersection(remoteSessionsByID.keys).count
        counts.matchedShots = localShotIDs.intersection(remoteShotsByID.keys).count
        counts.staleOrgReconciledProperties = localProperties.filter { property in
            guard let activeOrganizationID else { return false }
            return property.orgId != activeOrganizationID &&
                remotePropertiesByID[divergenceKey(property.id)] != nil
        }.count
        counts.staleOrgReconciledShots = localShots.filter { shot in
            guard let activeOrganizationID else { return false }
            return shot.metadataOrgID != nil &&
                shot.metadataOrgID != activeOrganizationID &&
                remoteShotsByID[divergenceKey(shot.shot.shotID)] != nil
        }.count

        if let activeOrganizationID {
            for property in localProperties
                where property.orgId != activeOrganizationID &&
                    remotePropertiesByID[divergenceKey(property.id)] != nil {
                items.append(
                    DivergenceAuditItem(
                        category: .legacyOrgReconciliation,
                        entityType: "property",
                        entityID: property.id,
                        propertyID: property.id,
                        orgID: property.orgId,
                        reason: "Local historical org metadata differs, but remote active-org ownership reconciled this property for audit."
                    )
                )
            }
            for localShot in localShots
                where localShot.metadataOrgID != nil &&
                    localShot.metadataOrgID != activeOrganizationID &&
                    remoteShotsByID[divergenceKey(localShot.shot.shotID)] != nil {
                items.append(
                    DivergenceAuditItem(
                        category: .legacyOrgReconciliation,
                        entityType: "shot",
                        entityID: localShot.shot.shotID,
                        propertyID: localShot.propertyID,
                        sessionID: localShot.sessionID,
                        shotID: localShot.shot.shotID,
                        orgID: localShot.metadataOrgID,
                        reason: "Local shot historical org metadata differs, but remote active-org ownership reconciled this shot for audit."
                    )
                )
            }
        }

        for property in localProperties where remotePropertiesByID[divergenceKey(property.id)] == nil {
            counts.localOnlyProperties += 1
            items.append(
                DivergenceAuditItem(
                    category: .localOnlyProperty,
                    entityType: "property",
                    entityID: property.id,
                    propertyID: property.id,
                    orgID: property.orgId,
                    reason: "Local active-org property is missing from remote active-org query."
                )
            )
        }
        for remoteProperty in remotePropertiesByID.values where !localPropertyIDs.contains(divergenceKey(remoteProperty.id)) {
            counts.remoteOnlyProperties += 1
            items.append(
                DivergenceAuditItem(
                    category: .remoteOnlyProperty,
                    entityType: "property",
                    entityID: remoteProperty.id,
                    propertyID: remoteProperty.id,
                    orgID: remoteProperty.orgID,
                    reason: "Remote active-org property is missing from local cache."
                )
            )
        }

        for session in localSessions where remoteSessionsByID[divergenceKey(session.id)] == nil {
            counts.localOnlySessions += 1
            items.append(
                DivergenceAuditItem(
                    category: .localOnlySession,
                    entityType: "session",
                    entityID: session.id,
                    propertyID: session.propertyID,
                    sessionID: session.id,
                    orgID: activeOrganizationID,
                    reason: "Local active-org session is missing from remote active-org query."
                )
            )
        }
        for remoteSession in remoteSessionsByID.values where !localSessionIDs.contains(divergenceKey(remoteSession.id)) {
            counts.remoteOnlySessions += 1
            items.append(
                DivergenceAuditItem(
                    category: .remoteOnlySession,
                    entityType: "session",
                    entityID: remoteSession.id,
                    propertyID: remoteSession.propertyID,
                    sessionID: remoteSession.id,
                    orgID: remoteSession.orgID,
                    reason: "Remote active-org session is missing from local cache."
                )
            )
        }

        for localShot in localShots where remoteShotsByID[divergenceKey(localShot.shot.shotID)] == nil {
            counts.localOnlyShots += 1
            items.append(
                DivergenceAuditItem(
                    category: .localOnlyShot,
                    entityType: "shot",
                    entityID: localShot.shot.shotID,
                    propertyID: localShot.propertyID,
                    sessionID: localShot.sessionID,
                    shotID: localShot.shot.shotID,
                    orgID: localShot.metadataOrgID ?? activeOrganizationID,
                    reason: "Local active-org shot is missing from remote active-org query."
                )
            )
        }
        for remoteShot in remoteShotsByID.values where !localShotIDs.contains(divergenceKey(remoteShot.id)) {
            counts.remoteOnlyShots += 1
            items.append(
                DivergenceAuditItem(
                    category: .remoteOnlyShot,
                    entityType: "shot",
                    entityID: remoteShot.id,
                    propertyID: remoteShot.propertyID,
                    sessionID: remoteShot.sessionID,
                    shotID: remoteShot.id,
                    orgID: remoteShot.orgID,
                    reason: "Remote active-org shot is missing from local metadata."
                )
            )
        }
        return counts
    }

    private func appendRemoteParentAndMediaItems(
        remote: RemoteDivergenceSnapshot,
        remotePropertiesByID: [String: DivergenceRemotePropertyRecord],
        remoteSessionsByID: [String: DivergenceRemoteSessionRecord],
        to items: inout [DivergenceAuditItem]
    ) {
        for session in remote.sessions where remotePropertiesByID[divergenceKey(session.propertyID)] == nil {
            items.append(
                DivergenceAuditItem(
                    category: .missingParent,
                    entityType: "session",
                    entityID: session.id,
                    propertyID: session.propertyID,
                    sessionID: session.id,
                    orgID: session.orgID,
                    reason: "Remote session references a missing remote property in the active-org audit scope."
                )
            )
        }

        for shot in remote.shots {
            if let propertyID = shot.propertyID, remotePropertiesByID[divergenceKey(propertyID)] == nil {
                items.append(
                    DivergenceAuditItem(
                        category: .missingParent,
                        entityType: "shot",
                        entityID: shot.id,
                        propertyID: propertyID,
                        sessionID: shot.sessionID,
                        shotID: shot.id,
                        orgID: shot.orgID,
                        reason: "Remote shot references a missing remote property in the active-org audit scope."
                    )
                )
            }
            if let sessionID = shot.sessionID, remoteSessionsByID[divergenceKey(sessionID)] == nil {
                items.append(
                    DivergenceAuditItem(
                        category: .missingParent,
                        entityType: "shot",
                        entityID: shot.id,
                        propertyID: shot.propertyID,
                        sessionID: sessionID,
                        shotID: shot.id,
                        orgID: shot.orgID,
                        reason: "Remote shot references a missing remote session in the active-org audit scope."
                    )
                )
            }
            if shot.propertyID == nil {
                if let sessionID = shot.sessionID,
                   let remoteSession = remoteSessionsByID[divergenceKey(sessionID)],
                   remotePropertiesByID[divergenceKey(remoteSession.propertyID)] != nil {
                    items.append(
                        DivergenceAuditItem(
                            category: .legacyRemoteSchema,
                            entityType: "shot",
                            entityID: shot.id,
                            propertyID: remoteSession.propertyID,
                            sessionID: sessionID,
                            shotID: shot.id,
                            orgID: shot.orgID,
                            reason: "Remote shot has a legacy null property_id, but its session resolves to an active-org property."
                        )
                    )
                } else {
                    items.append(
                        DivergenceAuditItem(
                            category: .missingParent,
                            entityType: "shot",
                            entityID: shot.id,
                            sessionID: shot.sessionID,
                            shotID: shot.id,
                            orgID: shot.orgID,
                            reason: "Remote shot has a null property_id with unresolved active-org lineage."
                        )
                    )
                }
            }
            if shot.sessionID == nil {
                items.append(
                    DivergenceAuditItem(
                        category: .missingParent,
                        entityType: "shot",
                        entityID: shot.id,
                        propertyID: shot.propertyID,
                        shotID: shot.id,
                        orgID: shot.orgID,
                        reason: "Remote shot has a null session_id."
                    )
                )
            }
            appendRemoteMediaDriftItems(for: shot, to: &items)
        }
    }

    private func appendLocalMediaDriftItems(
        for localShot: LocalDivergenceShot,
        to items: inout [DivergenceAuditItem]
    ) {
        let shot = localShot.shot
        let uploadState = shot.uploadState.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let hasStoragePath = normalizedSupabaseText(shot.storagePath) != nil
        let reason: String?
        if uploadState == "pending", hasStoragePath {
            reason = "Local upload_state is pending but storage path exists."
        } else if uploadState == "uploaded", !hasStoragePath {
            reason = "Local upload_state is uploaded but storage path is missing."
        } else if uploadState != "uploaded", shot.uploadAttempts >= maximumSupabaseMediaUploadAttempts {
            reason = "Local media upload is retry-capped."
        } else {
            reason = nil
        }
        guard let reason else { return }
        items.append(
            DivergenceAuditItem(
                category: .mediaDrift,
                entityType: "shot",
                entityID: shot.shotID,
                propertyID: localShot.propertyID,
                sessionID: localShot.sessionID,
                shotID: shot.shotID,
                orgID: localShot.metadataOrgID,
                reason: reason
            )
        )
    }

    private func appendRemoteMediaDriftItems(
        for shot: DivergenceRemoteShotRecord,
        to items: inout [DivergenceAuditItem]
    ) {
        let uploadState = normalizedSupabaseText(shot.uploadState)?.lowercased()
        let hasStoragePath = normalizedSupabaseText(shot.storagePath) != nil
        let reason: String?
        if uploadState == "pending", hasStoragePath {
            reason = "Remote upload_state is pending but storage path exists."
        } else if uploadState == "uploaded", !hasStoragePath {
            reason = "Remote upload_state is uploaded but storage path is missing."
        } else if uploadState != "uploaded",
                  (shot.uploadAttempts ?? 0) >= maximumSupabaseMediaUploadAttempts {
            reason = "Remote media upload is retry-capped."
        } else {
            reason = nil
        }
        guard let reason else { return }
        items.append(
            DivergenceAuditItem(
                category: .mediaDrift,
                entityType: "shot",
                entityID: shot.id,
                propertyID: shot.propertyID,
                sessionID: shot.sessionID,
                shotID: shot.id,
                orgID: shot.orgID,
                reason: reason
            )
        )
    }

    private func appendCaptureProfileMismatchItems(
        localPropertiesByID: [String: Property],
        localSessionsByID: [String: Session],
        remotePropertiesByID: [String: DivergenceRemotePropertyRecord],
        remoteSessionsByID: [String: DivergenceRemoteSessionRecord],
        to items: inout [DivergenceAuditItem]
    ) {
        for (propertyKey, remoteProperty) in remotePropertiesByID {
            guard let localProperty = localPropertiesByID[propertyKey] else { continue }
            let localProfile = localProperty.captureProfile?.rawValue
            let remoteProfile = normalizedSupabaseText(remoteProperty.captureProfile)
            guard localProfile != nil || remoteProfile == nil else { continue }
            if localProfile != remoteProfile {
                items.append(
                    DivergenceAuditItem(
                        category: .captureProfile,
                        entityType: "property",
                        entityID: remoteProperty.id,
                        propertyID: remoteProperty.id,
                        orgID: remoteProperty.orgID,
                        reason: "Local property capture_profile does not match remote capture_profile."
                    )
                )
            }
        }
        for (sessionKey, remoteSession) in remoteSessionsByID {
            guard let localSession = localSessionsByID[sessionKey] else { continue }
            let localProfile = localSession.captureProfile?.rawValue
            let remoteProfile = normalizedSupabaseText(remoteSession.captureProfile)
            guard localProfile != nil || remoteProfile == nil else { continue }
            if localProfile != remoteProfile {
                items.append(
                    DivergenceAuditItem(
                        category: .captureProfile,
                        entityType: "session",
                        entityID: remoteSession.id,
                        propertyID: remoteSession.propertyID,
                        sessionID: remoteSession.id,
                        orgID: remoteSession.orgID,
                        reason: "Local session capture_profile does not match remote capture_profile."
                    )
                )
            }
        }
    }

    private func appendDeletedHiddenMismatchItems(
        localPropertiesByID: [String: Property],
        localSessionsByID: [String: Session],
        remotePropertiesByID: [String: DivergenceRemotePropertyRecord],
        remoteSessionsByID: [String: DivergenceRemoteSessionRecord],
        to items: inout [DivergenceAuditItem]
    ) {
        for (propertyKey, remoteProperty) in remotePropertiesByID {
            guard let localProperty = localPropertiesByID[propertyKey] else { continue }
            if (localProperty.deletedAt == nil) != (remoteProperty.deletedAt == nil) ||
                localProperty.isArchived != (remoteProperty.isArchived ?? false) {
                items.append(
                    DivergenceAuditItem(
                        category: .deletedHiddenMismatch,
                        entityType: "property",
                        entityID: remoteProperty.id,
                        propertyID: remoteProperty.id,
                        orgID: remoteProperty.orgID,
                        reason: "Local property deleted/archived state does not match remote state."
                    )
                )
            }
        }
        for (sessionKey, remoteSession) in remoteSessionsByID {
            guard let localSession = localSessionsByID[sessionKey] else { continue }
            if (localSession.deletedAt == nil) != (remoteSession.deletedAt == nil) {
                items.append(
                    DivergenceAuditItem(
                        category: .deletedHiddenMismatch,
                        entityType: "session",
                        entityID: remoteSession.id,
                        propertyID: remoteSession.propertyID,
                        sessionID: remoteSession.id,
                        orgID: remoteSession.orgID,
                        reason: "Local session deleted state does not match remote state."
                    )
                )
            }
        }
    }

    private func makeSyncDebtInspectionReport(
        ranAt: Date,
        activeOrganizationID: UUID?,
        local: LocalDivergenceSnapshot,
        remote: RemoteDivergenceSnapshot?,
        divergenceAuditSummary: DivergenceAuditSummary
    ) -> SyncDebtInspectionReport {
        let failedQueueItems = ((try? localStore.fetchQueuedMutations()) ?? [])
            .filter { $0.status == .failed }
            .sorted {
                let lhsDate = $0.lastAttemptAt ?? $0.updatedAt
                let rhsDate = $1.lastAttemptAt ?? $1.updatedAt
                if lhsDate != rhsDate { return lhsDate < rhsDate }
                return $0.id.uuidString < $1.id.uuidString
            }
            .map(makeQueueDebtInspectionItem)

        let remotePropertiesByID = dictionaryByNormalizedID(remote?.properties ?? [], id: \.id)
        let remoteSessionsByID = dictionaryByNormalizedID(remote?.sessions ?? [], id: \.id)
        let remoteShotsByID = dictionaryByNormalizedID(remote?.shots ?? [], id: \.id)
        let localPropertiesByID = dictionaryByNormalizedID(local.properties, id: \.id)
        let localSessionsByID = dictionaryByNormalizedID(local.sessions, id: \.id)
        let sessionCursor = activeOrganizationID.flatMap { readSyncCursor(entity: "sessions", orgID: $0) }

        let divergenceItems = divergenceAuditSummary.items.map { item in
            makeDivergenceDebtInspectionItem(
                item,
                localPropertiesByID: localPropertiesByID,
                localSessionsByID: localSessionsByID,
                remotePropertiesByID: remotePropertiesByID,
                remoteSessionsByID: remoteSessionsByID,
                remoteShotsByID: remoteShotsByID,
                sessionCursor: sessionCursor
            )
        }

        return SyncDebtInspectionReport(
            ranAt: ranAt,
            activeOrganizationID: activeOrganizationID,
            failedQueueItems: failedQueueItems,
            divergenceItems: divergenceItems,
            groupedHistoricalFindings: divergenceAuditSummary.groupedHistoricalFindings
        )
    }

    private func makeRemoteOnlySessionDetailReport(
        inspectedAt: Date,
        activeOrganizationID: UUID?,
        local: LocalDivergenceSnapshot,
        remote: RemoteOnlySessionDetailRemoteSnapshot
    ) -> RemoteOnlySessionDetailReport {
        let localPropertiesByID = dictionaryByNormalizedID(local.properties, id: \.id)
        let localSessionsByID = dictionaryByNormalizedID(local.sessions, id: \.id)
        let remotePropertiesByID = dictionaryByNormalizedID(remote.properties, id: \.id)
        let shotsBySessionID = Dictionary(grouping: remote.shots) { shot in
            shot.sessionID.map(divergenceKey) ?? ""
        }
        let observationsBySessionID = Dictionary(grouping: remote.observations ?? []) { observation in
            observation.sessionID.map(divergenceKey) ?? ""
        }
        let sessionCursor = activeOrganizationID.flatMap { readSyncCursor(entity: "sessions", orgID: $0) }
        let fileManager = FileManager.default

        let items = remote.sessions
            .filter { localSessionsByID[divergenceKey($0.id)] == nil }
            .sorted {
                if ($0.updatedAt ?? .distantPast) != ($1.updatedAt ?? .distantPast) {
                    return ($0.updatedAt ?? .distantPast) > ($1.updatedAt ?? .distantPast)
                }
                return $0.id.uuidString < $1.id.uuidString
            }
            .map { remoteSession -> RemoteOnlySessionDetailItem in
                let sessionKey = divergenceKey(remoteSession.id)
                let propertyKey = divergenceKey(remoteSession.propertyID)
                let localProperty = localPropertiesByID[propertyKey]
                let localSession = localSessionsByID[sessionKey]
                let sessionFolder = localStore.sessionFolderURL(
                    propertyID: remoteSession.propertyID,
                    sessionID: remoteSession.id
                )
                let sessionJSON = localStore.sessionJSONURL(
                    propertyID: remoteSession.propertyID,
                    sessionID: remoteSession.id
                )
                let originalsFolder = localStore.originalsFolderURL(
                    propertyID: remoteSession.propertyID,
                    sessionID: remoteSession.id
                )
                let sessionShots = shotsBySessionID[sessionKey] ?? []
                let activeSessionShots = sessionShots.filter { $0.deletedAt == nil }
                let shotsWithStorage = activeSessionShots.filter { normalizedSupabaseText($0.storagePath) != nil }
                let remoteObservationCount = remote.observations == nil
                    ? nil
                    : (observationsBySessionID[sessionKey] ?? []).filter { $0.deletedAt == nil }.count
                let normalizedStatus = remoteSession.status.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                let appearsDeleted = remoteSession.deletedAt != nil
                let appearsStale = sessionCursor.flatMap { cursor -> Bool? in
                    guard let updatedAt = remoteSession.updatedAt else { return nil }
                    return updatedAt <= cursor
                } ?? false
                let appearsDraft = normalizedStatus == Session.Status.draft.rawValue
                let appearsCompleted = normalizedStatus == Session.Status.completed.rawValue
                let classification = remoteOnlySessionDetailClassification(
                    remoteSession: remoteSession,
                    localPropertyExists: localProperty != nil,
                    localSessionExists: localSession != nil,
                    remotePropertyExists: remotePropertiesByID[propertyKey] != nil,
                    remoteShotCount: activeSessionShots.count,
                    remoteObservationCount: remoteObservationCount,
                    remoteShotsWithStoragePathCount: shotsWithStorage.count,
                    remoteShotsMissingStoragePathCount: max(0, activeSessionShots.count - shotsWithStorage.count),
                    sessionCursor: sessionCursor
                )
                let labels = remoteOnlySessionDetailLabels(
                    classification: classification.value,
                    localSessionExists: localSession != nil,
                    localPropertyExists: localProperty != nil,
                    appearsDeleted: appearsDeleted,
                    appearsStale: appearsStale,
                    appearsDraft: appearsDraft,
                    appearsCompleted: appearsCompleted,
                    remoteShotCount: activeSessionShots.count,
                    remoteShotsWithStoragePathCount: shotsWithStorage.count
                )

                return RemoteOnlySessionDetailItem(
                    id: remoteSession.id,
                    sessionID: remoteSession.id,
                    propertyID: remoteSession.propertyID,
                    orgID: remoteSession.orgID,
                    remoteStatus: normalizedStatus.isEmpty ? "unknown" : normalizedStatus,
                    startedAt: remoteSession.startedAt,
                    completedAt: remoteSession.completedAt,
                    updatedAt: remoteSession.updatedAt,
                    deletedAt: remoteSession.deletedAt,
                    captureProfile: normalizedSupabaseText(remoteSession.captureProfile),
                    parentPropertyExistsLocally: localProperty != nil,
                    localPropertyName: localProperty?.name,
                    localSessionRowExists: localSession != nil,
                    localSessionFolderExists: fileManager.fileExists(atPath: sessionFolder.path),
                    localSessionJSONExists: fileManager.fileExists(atPath: sessionJSON.path),
                    localOriginalsFolderExists: fileManager.fileExists(atPath: originalsFolder.path),
                    remoteShotCount: activeSessionShots.count,
                    remoteIssueObservationCount: remoteObservationCount,
                    remoteShotsWithStoragePathCount: shotsWithStorage.count,
                    remoteShotsMissingStoragePathCount: max(0, activeSessionShots.count - shotsWithStorage.count),
                    appearsDeleted: appearsDeleted,
                    appearsStale: appearsStale,
                    appearsDraft: appearsDraft,
                    appearsCompleted: appearsCompleted,
                    classification: classification.value,
                    classificationReason: classification.reason,
                    labels: labels
                )
            }

        return RemoteOnlySessionDetailReport(
            inspectedAt: inspectedAt,
            activeOrganizationID: activeOrganizationID,
            remoteScopeAvailable: true,
            unavailableReason: nil,
            items: items
        )
    }

    private func remoteOnlySessionDetailClassification(
        remoteSession: RemoteOnlySessionDetailSessionRecord,
        localPropertyExists: Bool,
        localSessionExists: Bool,
        remotePropertyExists: Bool,
        remoteShotCount: Int,
        remoteObservationCount: Int?,
        remoteShotsWithStoragePathCount: Int,
        remoteShotsMissingStoragePathCount: Int,
        sessionCursor: Date?
    ) -> (value: DivergenceDebtClassification, reason: String) {
        if remoteSession.deletedAt != nil {
            return (.historicalRemoteOnly, "Remote session is deleted remotely and absent locally.")
        }
        if let sessionCursor,
           let updatedAt = remoteSession.updatedAt,
           updatedAt <= sessionCursor {
            return (.historicalRemoteOnly, "Remote session updated_at is not newer than the local session sync cursor.")
        }
        let normalizedStatus = remoteSession.status.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let remoteObservationScopeIsEmpty = remoteObservationCount == nil || remoteObservationCount == 0
        if normalizedStatus == Session.Status.draft.rawValue,
           remoteSession.completedAt == nil,
           localPropertyExists,
           !localSessionExists,
           remoteShotCount == 0,
           remoteObservationScopeIsEmpty,
           remoteShotsWithStoragePathCount == 0,
           remoteShotsMissingStoragePathCount == 0 {
            return (.emptyRemoteDraftShell, "Remote draft has no completion timestamp, no local session row, no remote shots, no storage paths, and no queryable observations; hydration is not recommended.")
        }
        if localPropertyExists {
            return (.missingLocalHydration, "Remote session belongs to a local property but is absent from local session cache.")
        }
        if !remotePropertyExists {
            return (.trueParityDebt, "Remote session references a property missing from the remote active-org snapshot.")
        }
        return (.manualReview, "Remote session parent is not available locally; shell hydration is not suggested.")
    }

    private func remoteOnlySessionDetailLabels(
        classification: DivergenceDebtClassification,
        localSessionExists: Bool,
        localPropertyExists: Bool,
        appearsDeleted: Bool,
        appearsStale: Bool,
        appearsDraft: Bool,
        appearsCompleted: Bool,
        remoteShotCount: Int,
        remoteShotsWithStoragePathCount: Int
    ) -> [RemoteOnlySessionDetailLabel] {
        var labels: [RemoteOnlySessionDetailLabel] = []
        if appearsDeleted {
            labels.append(.historicalDeleted)
        }
        if appearsStale {
            labels.append(.historicalStale)
        }
        if appearsDraft {
            labels.append(.cautionDraftIncomplete)
        }
        if appearsCompleted && remoteShotCount == 0 {
            labels.append(.completedNoRemoteShots)
        }
        if appearsCompleted && remoteShotCount > 0 && remoteShotsWithStoragePathCount > 0 && localPropertyExists {
            labels.append(.possibleHydrationCandidate)
        }
        if classification == .emptyRemoteDraftShell {
            labels.append(.notRecommendedForHydration)
        }
        if !localPropertyExists {
            labels.append(.parentMissingLocally)
        }
        if localSessionExists {
            labels.append(.localShellPresent)
        }
        return labels
    }

    private func makeQueueDebtInspectionItem(_ item: LocalStore.QueuedMutation) -> QueueDebtInspectionItem {
        let payloadSummary = queueDebtPayloadSummary(for: item)
        let lastErrorMessage = item.lastError.map(Self.sanitizedDiagnosticsErrorMessage)
        let category = item.lastError
            .map { Self.diagnosticErrorCategory(for: NSError(domain: "ScoutCapture.QueueDebt", code: 0, userInfo: [NSLocalizedDescriptionKey: $0])) }
            ?? .unknown
        let classification = queueDebtClassification(
            operation: item.operation,
            lastErrorCategory: category,
            lastErrorMessage: lastErrorMessage,
            payloadSummary: payloadSummary
        )
        return QueueDebtInspectionItem(
            id: item.id,
            entityType: item.entityType,
            entityID: item.entityID,
            operation: item.operation,
            orgID: item.organizationID,
            propertyID: item.propertyID,
            sessionID: item.sessionID,
            idempotencyKey: item.idempotencyKey,
            attemptCount: item.attemptCount,
            createdAt: item.createdAt,
            lastAttemptAt: item.lastAttemptAt,
            nextAttemptAt: item.nextAttemptAt,
            lastErrorCategory: category,
            lastErrorMessage: lastErrorMessage,
            payloadSummary: payloadSummary,
            updatedBy: payloadSummary.updatedBy,
            classification: classification,
            acknowledgedAt: item.acknowledgedAt,
            acknowledgedReason: item.acknowledgedReason.map(Self.sanitizedDiagnosticsErrorMessage),
            acknowledgedClassification: item.acknowledgedClassification,
            acknowledgementSource: item.acknowledgementSource
        )
    }

    private func queueDebtPayloadSummary(for item: LocalStore.QueuedMutation) -> QueueDebtPayloadSummary {
        switch item.operation {
        case "upsert_property":
            do {
                let payload = try JSONDecoder().decode(QueuedPropertyMutationPayload.self, from: item.payloadData)
                return QueueDebtPayloadSummary(
                    payloadKind: "property",
                    payloadOrgID: payload.property.orgID,
                    payloadPropertyID: payload.property.id,
                    payloadSessionID: nil,
                    propertyName: normalizedSupabaseText(payload.property.name),
                    sessionStatus: nil,
                    sessionStartedAt: nil,
                    updatedBy: payload.property.updatedBy,
                    decodeError: nil
                )
            } catch {
                return failedQueueDebtPayloadSummary(kind: "property", error: error)
            }
        case "upsert_session":
            do {
                let payload = try JSONDecoder().decode(QueuedSessionMutationPayload.self, from: item.payloadData)
                return QueueDebtPayloadSummary(
                    payloadKind: "session",
                    payloadOrgID: payload.session.orgID,
                    payloadPropertyID: payload.session.propertyID,
                    payloadSessionID: payload.session.id,
                    propertyName: normalizedSupabaseText(payload.property.name),
                    sessionStatus: normalizedSupabaseText(payload.session.status),
                    sessionStartedAt: normalizedSupabaseText(payload.session.startedAt),
                    updatedBy: payload.session.updatedBy ?? payload.property.updatedBy,
                    decodeError: nil
                )
            } catch {
                return failedQueueDebtPayloadSummary(kind: "session", error: error)
            }
        default:
            return QueueDebtPayloadSummary(
                payloadKind: "unsupported",
                payloadOrgID: nil,
                payloadPropertyID: nil,
                payloadSessionID: nil,
                propertyName: nil,
                sessionStatus: nil,
                sessionStartedAt: nil,
                updatedBy: nil,
                decodeError: "Unsupported queued operation: \(item.operation)"
            )
        }
    }

    private func failedQueueDebtPayloadSummary(kind: String, error: Error) -> QueueDebtPayloadSummary {
        QueueDebtPayloadSummary(
            payloadKind: kind,
            payloadOrgID: nil,
            payloadPropertyID: nil,
            payloadSessionID: nil,
            propertyName: nil,
            sessionStatus: nil,
            sessionStartedAt: nil,
            updatedBy: nil,
            decodeError: Self.sanitizedDiagnosticsErrorMessage(error.localizedDescription)
        )
    }

    private func queueDebtClassification(
        operation: String,
        lastErrorCategory: DiagnosticErrorCategory,
        lastErrorMessage: String?,
        payloadSummary: QueueDebtPayloadSummary
    ) -> QueueDebtClassification {
        let normalizedError = (lastErrorMessage ?? "").lowercased()
        let isRLSFailure = lastErrorCategory == .authOrRLS ||
            normalizedError.contains("row-level security") ||
            normalizedError.contains("row level security") ||
            normalizedError.contains("rls")
        if operation == "upsert_property", isRLSFailure {
            return .staleRLSPropertyUpsert
        }
        if operation == "upsert_session", isRLSFailure {
            return .staleRLSSessionParentProperty
        }
        if lastErrorCategory == .network {
            return .retryCandidate
        }
        if payloadSummary.decodeError != nil {
            return .unknown
        }
        return .manualReview
    }

    private func validateHistoricalQueueDebtAcknowledgement(
        item: LocalStore.QueuedMutation,
        inspectionItem: QueueDebtInspectionItem
    ) throws {
        guard item.status == .failed else {
            throw QueueDebtAcknowledgementError.notFailed
        }
        guard item.operation == "upsert_property" || item.operation == "upsert_session" else {
            throw QueueDebtAcknowledgementError.unsupportedOperation(item.operation)
        }
        guard inspectionItem.classification == .staleRLSPropertyUpsert ||
                inspectionItem.classification == .staleRLSSessionParentProperty else {
            throw QueueDebtAcknowledgementError.ineligibleClassification(inspectionItem.classification.rawValue)
        }
        let normalizedError = (item.lastError ?? "").lowercased()
        guard normalizedError.contains("row-level security") ||
                normalizedError.contains("row level security") ||
                normalizedError.contains("rls") else {
            throw QueueDebtAcknowledgementError.missingRLSError
        }
        guard inspectionItem.payloadSummary.decodeError == nil else {
            throw QueueDebtAcknowledgementError.payloadMismatch(inspectionItem.payloadSummary.decodeError ?? "decode failed")
        }

        switch item.operation {
        case "upsert_property":
            let payload = try decodedPropertyDebtPayload(for: item)
            guard inspectionItem.payloadSummary.payloadPropertyID == item.entityID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("property payload ID does not match queue entity ID")
            }
            guard payload.property.id == item.entityID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("decoded property ID does not match queue entity ID")
            }
            guard item.propertyID == nil || inspectionItem.payloadSummary.payloadPropertyID == item.propertyID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("property payload ID does not match queue property ID")
            }
            guard item.propertyID == nil || payload.property.id == item.propertyID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("decoded property ID does not match queue property ID")
            }
            guard inspectionItem.payloadSummary.payloadOrgID == item.organizationID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("property payload org ID does not match queue org ID")
            }
            guard payload.property.orgID == item.organizationID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("decoded property org ID does not match queue org ID")
            }
        case "upsert_session":
            let payload = try decodedSessionDebtPayload(for: item)
            let queueSessionID = item.sessionID ?? item.entityID
            guard inspectionItem.payloadSummary.payloadSessionID == queueSessionID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("session payload ID does not match queue session ID")
            }
            guard payload.session.id == queueSessionID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("decoded session ID does not match queue session ID")
            }
            guard inspectionItem.payloadSummary.payloadPropertyID == item.propertyID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("session payload property ID does not match queue property ID")
            }
            guard payload.session.propertyID == item.propertyID,
                  payload.property.id == item.propertyID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("decoded session parent property ID does not match queue property ID")
            }
            guard inspectionItem.payloadSummary.payloadOrgID == item.organizationID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("session payload org ID does not match queue org ID")
            }
            guard payload.session.orgID == item.organizationID,
                  payload.property.orgID == item.organizationID else {
                throw QueueDebtAcknowledgementError.payloadMismatch("decoded session org ID does not match queue org ID")
            }
        default:
            throw QueueDebtAcknowledgementError.unsupportedOperation(item.operation)
        }
    }

    private func decodedPropertyDebtPayload(for item: LocalStore.QueuedMutation) throws -> QueuedPropertyMutationPayload {
        do {
            return try JSONDecoder().decode(QueuedPropertyMutationPayload.self, from: item.payloadData)
        } catch {
            throw QueueDebtAcknowledgementError.payloadMismatch(Self.sanitizedDiagnosticsErrorMessage(error.localizedDescription))
        }
    }

    private func decodedSessionDebtPayload(for item: LocalStore.QueuedMutation) throws -> QueuedSessionMutationPayload {
        do {
            return try JSONDecoder().decode(QueuedSessionMutationPayload.self, from: item.payloadData)
        } catch {
            throw QueueDebtAcknowledgementError.payloadMismatch(Self.sanitizedDiagnosticsErrorMessage(error.localizedDescription))
        }
    }

    private func makeDivergenceDebtInspectionItem(
        _ item: DivergenceAuditItem,
        localPropertiesByID: [String: Property],
        localSessionsByID: [String: Session],
        remotePropertiesByID: [String: DivergenceRemotePropertyRecord],
        remoteSessionsByID: [String: DivergenceRemoteSessionRecord],
        remoteShotsByID: [String: DivergenceRemoteShotRecord],
        sessionCursor: Date?
    ) -> DivergenceDebtInspectionItem {
        let classification = divergenceDebtClassification(
            for: item,
            localPropertiesByID: localPropertiesByID,
            localSessionsByID: localSessionsByID,
            remotePropertiesByID: remotePropertiesByID,
            remoteSessionsByID: remoteSessionsByID,
            remoteShotsByID: remoteShotsByID,
            sessionCursor: sessionCursor
        )
        return DivergenceDebtInspectionItem(
            id: item.id,
            category: item.category,
            entityType: item.entityType,
            entityID: item.entityID,
            propertyID: item.propertyID,
            sessionID: item.sessionID,
            shotID: item.shotID,
            orgID: item.orgID,
            reason: Self.sanitizedDiagnosticsErrorMessage(item.reason),
            classification: classification.value,
            classificationReason: classification.reason
        )
    }

    private func divergenceDebtClassification(
        for item: DivergenceAuditItem,
        localPropertiesByID: [String: Property],
        localSessionsByID: [String: Session],
        remotePropertiesByID: [String: DivergenceRemotePropertyRecord],
        remoteSessionsByID: [String: DivergenceRemoteSessionRecord],
        remoteShotsByID: [String: DivergenceRemoteShotRecord],
        sessionCursor: Date?
    ) -> (value: DivergenceDebtClassification, reason: String) {
        switch item.category {
        case .legacyCaptureProfile, .legacyRemoteSchema, .legacyOrgReconciliation, .staleOrgMismatch, .captureProfile:
            return (.informationalHistorical, "Historical or informational finding; not promoted to actionable debt.")
        case .remoteOnlySession:
            guard let sessionID = item.sessionID ?? item.entityID,
                  let remoteSession = remoteSessionsByID[divergenceKey(sessionID)] else {
                return (.manualReview, "Remote-only session details were unavailable in the read-only snapshot.")
            }
            if remoteSession.deletedAt != nil {
                return (.historicalRemoteOnly, "Remote session is deleted remotely and absent locally.")
            }
            if let cursor = sessionCursor,
               let updatedAt = remoteSession.updatedAt,
               updatedAt <= cursor {
                return (.historicalRemoteOnly, "Remote session updated_at is not newer than the local session sync cursor.")
            }
            if localPropertiesByID[divergenceKey(remoteSession.propertyID)] != nil {
                return (.missingLocalHydration, "Remote session belongs to a local property but is absent from local session cache.")
            }
            if remotePropertiesByID[divergenceKey(remoteSession.propertyID)] == nil {
                return (.trueParityDebt, "Remote session references a property missing from the remote active-org snapshot.")
            }
            return (.manualReview, "Remote session is absent locally but lacks enough cursor/local-parent context.")
        case .remoteOnlyShot:
            guard let shotID = item.shotID ?? item.entityID,
                  let remoteShot = remoteShotsByID[divergenceKey(shotID)] else {
                return (.manualReview, "Remote-only shot details were unavailable in the read-only snapshot.")
            }
            if remoteShotLooksLikeKnownLegacyArtifact(remoteShot) {
                return (.knownLegacyArtifact, "Remote shot has retired/superseded lifecycle markers.")
            }
            if let propertyID = remoteShot.propertyID,
               remotePropertiesByID[divergenceKey(propertyID)] == nil {
                return (.trueParityDebt, "Remote shot references a property missing from the remote active-org snapshot.")
            }
            if let sessionID = remoteShot.sessionID,
               remoteSessionsByID[divergenceKey(sessionID)] == nil {
                return (.trueParityDebt, "Remote shot references a session missing from the remote active-org snapshot.")
            }
            return (.manualReview, "Remote shot is absent locally without legacy lifecycle markers.")
        case .missingParent, .deletedHiddenMismatch, .localOnlyProperty, .remoteOnlyProperty,
             .localOnlySession, .localOnlyShot, .mediaDrift, .remoteUnavailable:
            return (.manualReview, "Finding remains actionable or recoverable and needs explicit review.")
        }
    }

    private func remoteShotLooksLikeKnownLegacyArtifact(_ shot: DivergenceRemoteShotRecord) -> Bool {
        let lifecycle = normalizedSupabaseText(shot.lifecycleState)?.lowercased()
        let replacementReason = normalizedSupabaseText(shot.replacementReason)?.lowercased()
        return lifecycle == "retired" ||
            lifecycle == "superseded" ||
            shot.supersededByShotID != nil ||
            replacementReason?.contains("superseded") == true ||
            replacementReason?.contains("retake") == true
    }

    private func dictionaryByNormalizedID<Value>(
        _ values: [Value],
        id: (Value) -> UUID
    ) -> [String: Value] {
        values.reduce(into: [:]) { result, value in
            let key = divergenceKey(id(value))
            if result[key] == nil {
                result[key] = value
            }
        }
    }

    private func divergenceKey(_ id: UUID) -> String {
        id.uuidString.lowercased()
    }

    private nonisolated static func safeDiagnosticsFilename(
        originalFilename: String,
        originalRelativePath: String
    ) -> String? {
        let filename = URL(fileURLWithPath: originalFilename).lastPathComponent
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if !filename.isEmpty {
            return filename
        }
        let relativeFilename = URL(fileURLWithPath: originalRelativePath).lastPathComponent
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return relativeFilename.isEmpty ? nil : relativeFilename
    }

    private enum ShadowWriteDiagnosticsEntity {
        case property
        case session
        case shotMetadata
        case captureProfile
    }

    private func recordShadowWriteDiagnostics(
        entity: ShadowWriteDiagnosticsEntity,
        succeeded: Bool,
        error: Error? = nil
    ) {
        if let error {
            recordDiagnosticsError(error)
        }
        mutateLocalDiagnostics { diagnostics in
            switch entity {
            case .property:
                if succeeded { diagnostics.shadowWrites.property.successCount += 1 }
                else { diagnostics.shadowWrites.property.failureCount += 1 }
            case .session:
                if succeeded { diagnostics.shadowWrites.session.successCount += 1 }
                else { diagnostics.shadowWrites.session.failureCount += 1 }
            case .shotMetadata:
                if succeeded { diagnostics.shadowWrites.shotMetadata.successCount += 1 }
                else { diagnostics.shadowWrites.shotMetadata.failureCount += 1 }
            case .captureProfile:
                if succeeded { diagnostics.shadowWrites.captureProfile.successCount += 1 }
                else { diagnostics.shadowWrites.captureProfile.failureCount += 1 }
            }
        }
    }

    private func recordCaptureProfileMaintenanceDiagnostics(_ result: CaptureProfileMaintenanceBackfillResult) {
        mutateLocalDiagnostics { diagnostics in
            diagnostics.captureProfileMaintenance = result
        }
    }

    nonisolated static func diagnosticErrorCategory(for error: Error) -> DiagnosticErrorCategory {
        let nsError = error as NSError
        let domain = nsError.domain.lowercased()
        let message = error.localizedDescription.lowercased()
        let combined = "\(domain) \(message)"

        if combined.contains("rls") ||
            combined.contains("row level security") ||
            combined.contains("permission denied") ||
            combined.contains("unauthorized") ||
            combined.contains("forbidden") ||
            combined.contains("jwt") ||
            combined.contains("auth") {
            return .authOrRLS
        }
        if combined.contains("duplicate") ||
            combined.contains("already exists") ||
            combined.contains("unique constraint") ||
            combined.contains("23505") {
            return .duplicate
        }
        if combined.contains("conflict") ||
            combined.contains("409") ||
            combined.contains("stale") {
            return .conflict
        }
        if domain.contains("url") ||
            domain.contains("network") ||
            combined.contains("network") ||
            combined.contains("timed out") ||
            combined.contains("offline") ||
            combined.contains("connection lost") ||
            combined.contains("cannot connect") {
            return .network
        }
        if domain.contains("cocoa") ||
            domain.contains("localstore") ||
            combined.contains("file") ||
            combined.contains("no such file") ||
            combined.contains("permission") {
            return .localIO
        }
        return .unknown
    }

    private nonisolated static func sanitizedDiagnosticsErrorMessage(_ message: String) -> String {
        let rawTokens = message.split(separator: " ").map(String.init)
        let redactedPathTokens = rawTokens.enumerated()
            .map { index, token -> String in
                let lower = token.lowercased()
                let previousLower = index > 0 ? rawTokens[index - 1].lowercased() : ""
                if token.hasPrefix("/") || token.hasPrefix("file:") {
                    return "[path]"
                }
                if lower.hasPrefix("data:image") ||
                    lower.hasPrefix("data:video") ||
                    lower.hasPrefix("data:application/octet-stream") {
                    return "[media]"
                }
                if lower.hasPrefix("http://") || lower.hasPrefix("https://") {
                    return "[url]"
                }
                if previousLower == "token" || previousLower == "bearer" || previousLower == "jwt" {
                    return "[redacted]"
                }
                if lower.hasPrefix("token=") ||
                    lower.hasPrefix("access_token=") ||
                    lower.hasPrefix("authorization=") ||
                    lower.hasPrefix("signedurl=") ||
                    lower.contains("token=") ||
                    lower.contains("access_token=") ||
                    lower.contains("signature=") {
                    return "[redacted]"
                }
                return token
            }
            .joined(separator: " ")
        let maxLength = 240
        guard redactedPathTokens.count > maxLength else { return redactedPathTokens }
        return String(redactedPathTokens.prefix(maxLength))
    }

    nonisolated static func diagnosticsPreviewText(_ value: String?, maxLength: Int = 96) -> String? {
        guard let value else { return nil }
        let sanitized = sanitizedDiagnosticsErrorMessage(value)
            .replacingOccurrences(of: "\n", with: " ")
            .replacingOccurrences(of: "\t", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !sanitized.isEmpty else { return nil }
        guard sanitized.count > maxLength else { return sanitized }
        return String(sanitized.prefix(max(0, maxLength))) + "..."
    }

    private nonisolated static func trimmedNonEmpty(_ value: String?) -> String? {
        guard let value else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    func inspectCompletenessGates(inspectedAt: Date = Date()) -> CompletenessGatesReport {
        makeCompletenessGatesReport(inspectedAt: inspectedAt)
    }

    func inspectExportSealPreflight(inspectedAt: Date = Date()) -> ExportSealPreflightReport {
        Self.makeExportSealPreflightReport(from: inspectCompletenessGates(inspectedAt: inspectedAt))
    }

    func inspectSessionSnapshotPreview(
        inspectedAt: Date = Date(),
        trigger: String = "preview"
    ) -> SessionSnapshotPreviewReport {
        let properties = (try? localStore.fetchProperties()) ?? []
        var rows: [SessionSnapshotPreviewRow] = []
        var checksumPassCount = 0
        var checksumFailCount = 0
        var missingOrUnreadableCount = 0

        for property in properties {
            let sessions = (try? localStore.fetchSessionsForCacheBuild(propertyID: property.id)) ?? []
            for session in sessions {
                do {
                    let envelope = try makeSessionSnapshotEnvelope(
                        propertyID: property.id,
                        session: session,
                        generatedAt: inspectedAt,
                        trigger: trigger
                    )
                    checksumPassCount += 1
                    rows.append(
                        SessionSnapshotPreviewRow(
                            id: session.id,
                            propertyID: property.id,
                            localPropertyName: property.name,
                            sessionID: session.id,
                            status: envelope.status,
                            isPreviewable: true,
                            failureReason: nil,
                            envelope: envelope
                        )
                    )
                } catch {
                    missingOrUnreadableCount += 1
                    if case SessionSnapshotPreviewError.checksumGenerationFailed = error {
                        checksumFailCount += 1
                    }
                    rows.append(
                        SessionSnapshotPreviewRow(
                            id: session.id,
                            propertyID: property.id,
                            localPropertyName: property.name,
                            sessionID: session.id,
                            status: session.status,
                            isPreviewable: false,
                            failureReason: Self.sessionSnapshotPreviewReason(for: error),
                            envelope: nil
                        )
                    )
                }
            }
        }

        let envelopes = rows.compactMap(\.envelope)
        return SessionSnapshotPreviewReport(
            inspectedAt: inspectedAt,
            activeOrganizationID: activeOrganizationID,
            sessionsInspected: rows.count,
            previewableSessions: envelopes.count,
            missingOrUnreadableSessionJSONCount: missingOrUnreadableCount,
            checksumGenerationPassCount: checksumPassCount,
            checksumGenerationFailCount: checksumFailCount,
            totalShotCount: envelopes.reduce(0) { $0 + $1.shotCount },
            totalIssueCount: envelopes.reduce(0) { $0 + $1.issueCount },
            totalGuidedCount: envelopes.reduce(0) { $0 + $1.guidedCount },
            totalMediaManifestCount: envelopes.reduce(0) { $0 + $1.mediaManifestCount },
            totalMissingLocalOriginalsCount: envelopes.reduce(0) { $0 + $1.missingLocalOriginalsCount },
            totalSupabaseStorageMetadataCount: envelopes.reduce(0) { $0 + $1.supabaseStorageMetadataCount },
            rows: rows.sorted { lhs, rhs in
                if lhs.propertyID != rhs.propertyID { return lhs.propertyID.uuidString < rhs.propertyID.uuidString }
                return lhs.sessionID.uuidString < rhs.sessionID.uuidString
            }
        )
    }

    private enum SessionSnapshotPreviewError: Error {
        case sessionJSONMissingOrUnreadable
        case sessionJSONIDMismatch
        case checksumGenerationFailed
    }

    private struct SessionSnapshotPayloadForChecksum: Codable {
        let snapshotSchemaVersion: Int
        let sessionMetadataSchemaVersion: Int?
        let trigger: String
        let generatedAt: Date
        let appVersion: String?
        let sourceDeviceID: String?
        let orgID: UUID?
        let propertyID: UUID
        let sessionID: UUID
        let status: Session.Status
        let isSealed: Bool
        let exportedAt: Date?
        let firstDeliveredAt: Date?
        let reExportExpiresAt: Date?
        let shotCount: Int
        let issueCount: Int
        let guidedCount: Int
        let mediaManifestCount: Int
        let missingLocalOriginalsCount: Int
        let supabaseStorageMetadataCount: Int
        let rawSessionJSON: String
        let rawSessionJSONSHA256: String
        let rawSessionJSONByteCount: Int
        let mediaManifest: [SessionSnapshotMediaManifestItem]
    }

    private struct SessionSnapshotBuildResult {
        let envelope: SessionSnapshotEnvelope
        let payloadData: Data
    }

    private func makeSessionSnapshotEnvelope(
        propertyID: UUID,
        session: Session,
        generatedAt: Date,
        trigger: String
    ) throws -> SessionSnapshotEnvelope {
        try makeSessionSnapshotBuildResult(
            propertyID: propertyID,
            session: session,
            generatedAt: generatedAt,
            trigger: trigger
        ).envelope
    }

    private func makeSessionSnapshotBuildResult(
        propertyID: UUID,
        session: Session,
        generatedAt: Date,
        trigger: String
    ) throws -> SessionSnapshotBuildResult {
        let sessionJSONURL = localStore.sessionJSONURL(propertyID: propertyID, sessionID: session.id)
        guard FileManager.default.fileExists(atPath: sessionJSONURL.path),
              let rawData = try? Data(contentsOf: sessionJSONURL) else {
            throw SessionSnapshotPreviewError.sessionJSONMissingOrUnreadable
        }

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        guard let rawMetadata = try? decoder.decode(SessionMetadata.self, from: rawData),
              let metadata = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: session.id) else {
            throw SessionSnapshotPreviewError.sessionJSONMissingOrUnreadable
        }
        guard rawMetadata.propertyID == propertyID, rawMetadata.sessionID == session.id else {
            throw SessionSnapshotPreviewError.sessionJSONIDMismatch
        }

        let rawSessionJSON = String(data: rawData, encoding: .utf8) ?? rawData.base64EncodedString()
        let rawChecksum = Self.sessionSnapshotSHA256Hex(for: rawData)
        let manifest = metadata.shots.map { shot in
            Self.makeSessionSnapshotMediaManifestItem(
                for: shot,
                propertyID: propertyID,
                sessionID: session.id,
                localStore: localStore
            )
        }
        let missingOriginals = manifest.filter { !$0.localOriginalExists }.count
        let storageMetadataCount = manifest.filter { $0.storageBucketPresent && $0.storagePathPresent }.count
        let payload = SessionSnapshotPayloadForChecksum(
            snapshotSchemaVersion: 1,
            sessionMetadataSchemaVersion: metadata.schemaVersion,
            trigger: trigger,
            generatedAt: generatedAt,
            appVersion: Self.trimmedNonEmpty(metadata.appVersion),
            sourceDeviceID: currentDeviceIdentifier(),
            orgID: metadata.orgID,
            propertyID: propertyID,
            sessionID: session.id,
            status: metadata.status,
            isSealed: metadata.isSealed,
            exportedAt: metadata.exportedAt,
            firstDeliveredAt: metadata.firstDeliveredAt,
            reExportExpiresAt: metadata.reExportExpiresAt,
            shotCount: metadata.shots.count,
            issueCount: metadata.issues.count,
            guidedCount: metadata.guidedShots.count,
            mediaManifestCount: manifest.count,
            missingLocalOriginalsCount: missingOriginals,
            supabaseStorageMetadataCount: storageMetadataCount,
            rawSessionJSON: rawSessionJSON,
            rawSessionJSONSHA256: rawChecksum,
            rawSessionJSONByteCount: rawData.count,
            mediaManifest: manifest
        )

        let payloadData: Data
        do {
            let encoder = JSONEncoder()
            encoder.dateEncodingStrategy = .iso8601
            encoder.outputFormatting = [.sortedKeys]
            payloadData = try encoder.encode(payload)
        } catch {
            throw SessionSnapshotPreviewError.checksumGenerationFailed
        }

        let envelope = SessionSnapshotEnvelope(
            id: session.id,
            snapshotSchemaVersion: payload.snapshotSchemaVersion,
            sessionMetadataSchemaVersion: payload.sessionMetadataSchemaVersion,
            trigger: trigger,
            generatedAt: generatedAt,
            appVersion: payload.appVersion,
            sourceDeviceID: payload.sourceDeviceID,
            orgID: payload.orgID,
            propertyID: payload.propertyID,
            sessionID: payload.sessionID,
            status: payload.status,
            isSealed: payload.isSealed,
            exportedAt: payload.exportedAt,
            firstDeliveredAt: payload.firstDeliveredAt,
            reExportExpiresAt: payload.reExportExpiresAt,
            shotCount: payload.shotCount,
            issueCount: payload.issueCount,
            guidedCount: payload.guidedCount,
            mediaManifestCount: payload.mediaManifestCount,
            missingLocalOriginalsCount: payload.missingLocalOriginalsCount,
            supabaseStorageMetadataCount: payload.supabaseStorageMetadataCount,
            rawSessionJSON: rawSessionJSON,
            rawSessionJSONSHA256: rawChecksum,
            snapshotPayloadSHA256: Self.sessionSnapshotSHA256Hex(for: payloadData),
            rawSessionJSONByteCount: rawData.count,
            snapshotPayloadByteCount: payloadData.count,
            mediaManifest: manifest
        )
        return SessionSnapshotBuildResult(envelope: envelope, payloadData: payloadData)
    }

    nonisolated static func sessionSnapshotStoragePath(
        orgID: UUID,
        propertyID: UUID,
        sessionID: UUID,
        snapshotKind: SessionSnapshotKind,
        snapshotID: UUID
    ) -> String {
        [
            "orgs/\(orgID.uuidString.lowercased())",
            "properties/\(propertyID.uuidString.lowercased())",
            "sessions/\(sessionID.uuidString.lowercased())",
            "snapshots/\(snapshotKind.rawValue)",
            "\(snapshotID.uuidString.lowercased()).json"
        ].joined(separator: "/")
    }

    @MainActor
    @discardableResult
    func refreshManualSessionSnapshotAuthPreflight(checkedAt: Date = Date()) async -> SessionSnapshotAuthPreflightResult {
        let appUserID = authenticatedSupabaseUser?.id.uuidString.lowercased()
        let clientAuth = await sessionSnapshotClientAuthPreflight()
        let clientUserID = Self.trimmedNonEmpty(clientAuth.userID == "nil" ? nil : clientAuth.userID)?.lowercased()
        let usersMatch = appUserID != nil && clientUserID != nil && appUserID == clientUserID
        var payloadOrgID: UUID?
        var payloadPropertyID: UUID?
        var payloadSessionID: UUID?
        var remoteParentStatus = SessionSnapshotAuthPreflightRemoteParentStatus()
        var failureReasons: [String] = []

        if appUserID == nil {
            failureReasons.append("app_auth_user_missing")
        }
        if clientUserID == nil {
            failureReasons.append("client_auth_user_missing")
        }
        if clientAuth.error != "none" {
            failureReasons.append("client_auth_error=\(clientAuth.error)")
        }
        if appUserID != nil, clientUserID != nil, !usersMatch {
            failureReasons.append("app_client_auth_user_mismatch")
        }

        if let target = manualSessionSnapshotUploadTarget {
            payloadPropertyID = target.propertyID
            payloadSessionID = target.sessionID
            do {
                let session = try localSessionForSnapshotUpload(propertyID: target.propertyID, sessionID: target.sessionID)
                let metadata = try localStore.loadSessionMetadata(propertyID: target.propertyID, sessionID: session.id)
                payloadOrgID = metadata.orgID
                if let orgID = metadata.orgID {
                    do {
                        remoteParentStatus = try await sessionSnapshotRemoteParentPreflightStatus(
                            orgID: orgID,
                            propertyID: target.propertyID,
                            sessionID: session.id
                        )
                        if remoteParentStatus.confirmedCanonicalOrgID == orgID {
                            remoteParentStatus.orgIDsMatch = true
                        }
                    } catch {
                        remoteParentStatus.errorMessage = Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160)
                    }
                } else {
                    failureReasons.append("payload_org_id_missing")
                }
            } catch {
                failureReasons.append(Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160) ?? "local_target_unreadable")
            }
        } else {
            failureReasons.append(manualSessionSnapshotUploadTargetResolution.reason)
        }

        if remoteParentStatus.errorMessage != nil {
            failureReasons.append("remote_parent_check_failed")
        } else if payloadOrgID != nil {
            if !remoteParentStatus.propertyExists {
                failureReasons.append("remote_property_missing_or_hidden")
            }
            if !remoteParentStatus.sessionExists {
                failureReasons.append("remote_session_missing_or_hidden")
            }
            if !remoteParentStatus.orgIDsMatch {
                failureReasons.append("remote_parent_org_mismatch")
            }
        }

        let isReady = usersMatch &&
            payloadOrgID != nil &&
            remoteParentStatus.propertyExists &&
            remoteParentStatus.sessionExists &&
            remoteParentStatus.orgIDsMatch &&
            remoteParentStatus.errorMessage == nil
        let failureMessage = isReady ? nil : failureReasons.joined(separator: " | ")
        let result = SessionSnapshotAuthPreflightResult(
            checkedAt: checkedAt,
            appAuthUserID: appUserID,
            clientAuthUserID: clientUserID,
            usersMatch: usersMatch,
            payloadOrgID: payloadOrgID,
            payloadPropertyID: payloadPropertyID,
            payloadSessionID: payloadSessionID,
            remoteParentStatus: remoteParentStatus,
            isReady: isReady,
            failureMessage: Self.diagnosticsPreviewText(failureMessage, maxLength: 160)
        )
        recordSessionSnapshotAuthPreflight(result)
        return result
    }

    private func sessionSnapshotClientAuthPreflight() async -> (
        userID: String,
        email: String,
        error: String
    ) {
        if let sessionSnapshotClientAuthPreflightOverride {
            return await sessionSnapshotClientAuthPreflightOverride()
        }
        return await supabaseClientAuthDiagnostic(supabaseClient)
    }

    private struct SessionSnapshotRemotePropertyPreflightRow: Codable {
        let id: UUID
        let orgID: UUID
        let isArchived: Bool

        enum CodingKeys: String, CodingKey {
            case id
            case orgID = "org_id"
            case isArchived = "is_archived"
        }
    }

    private struct SessionSnapshotRemoteSessionPreflightRow: Codable {
        let id: UUID
        let orgID: UUID
        let propertyID: UUID

        enum CodingKeys: String, CodingKey {
            case id
            case orgID = "org_id"
            case propertyID = "property_id"
        }
    }

    private func sessionSnapshotRemoteParentPreflightStatus(
        orgID: UUID,
        propertyID: UUID,
        sessionID: UUID
    ) async throws -> SessionSnapshotAuthPreflightRemoteParentStatus {
        if let sessionSnapshotRemoteParentPreflightOverride {
            return try await sessionSnapshotRemoteParentPreflightOverride(orgID, propertyID, sessionID)
        }
        guard backendFeatureFlags.supabaseEnabled,
              let client = supabaseClient else {
            throw SessionSnapshotUploadError.missingSupabaseClient
        }

        let properties: [SessionSnapshotRemotePropertyPreflightRow] = try await client
            .from("properties")
            .select("id, org_id, is_archived")
            .eq("id", value: propertyID.uuidString.lowercased())
            .is("deleted_at", value: nil)
            .eq("is_archived", value: false)
            .limit(1)
            .execute()
            .value
        let sessions: [SessionSnapshotRemoteSessionPreflightRow] = try await client
            .from("sessions")
            .select("id, org_id, property_id")
            .eq("id", value: sessionID.uuidString.lowercased())
            .is("deleted_at", value: nil)
            .limit(1)
            .execute()
            .value

        let property = properties.first
        let session = sessions.first
        let sessionPropertyIDMatches = session?.propertyID == propertyID
        return SessionSnapshotAuthPreflightRemoteParentStatus(
            propertyExists: property != nil,
            sessionExists: session != nil,
            propertyOrgID: property?.orgID,
            sessionOrgID: session?.orgID,
            sessionPropertyIDMatches: sessionPropertyIDMatches,
            orgIDsMatch: property?.orgID == orgID && session?.orgID == orgID && sessionPropertyIDMatches,
            errorMessage: nil
        )
    }

    private func sessionSnapshotPreflightOrgMismatchBlockReason(
        propertyID: UUID,
        sessionID: UUID
    ) -> String? {
        let diagnostics = localDiagnostics.sessionSnapshotUpload
        guard diagnostics.lastAuthPreflightPayloadPropertyID == propertyID,
              diagnostics.lastAuthPreflightPayloadSessionID == sessionID,
              diagnostics.lastAuthPreflightRemotePropertyExists == true,
              diagnostics.lastAuthPreflightRemoteSessionExists == true,
              diagnostics.lastAuthPreflightRemoteOrgIDsMatch == false else {
            return nil
        }
        let localOrg = diagnostics.lastAuthPreflightPayloadOrgID?.uuidString ?? "none"
        let remotePropertyOrg = diagnostics.lastAuthPreflightRemotePropertyOrgID?.uuidString ?? "none"
        let remoteSessionOrg = diagnostics.lastAuthPreflightRemoteSessionOrgID?.uuidString ?? "none"
        return "auth preflight remote parent org mismatch: local_org=\(localOrg) remote_property_org=\(remotePropertyOrg) remote_session_org=\(remoteSessionOrg)"
    }

    @MainActor
    @discardableResult
    func runLocalOrgDriftAudit(checkedAt: Date = Date(), sampleLimit: Int = 5) async -> LocalOrgDriftAuditResult {
        let activeLocalProperties = ((try? localStore.fetchProperties()) ?? [])
            .filter { $0.deletedAt == nil }

        var totalPropertiesChecked = 0
        var totalSessionsChecked = 0
        var propertyMismatchCount = 0
        var sessionMismatchCount = 0
        var unableToConfirmCount = 0
        var confirmedMismatches: [LocalOrgDriftAuditSample] = []
        var samples: [LocalOrgDriftAuditSample] = []
        var confirmedCanonicalOrgByProperty: [UUID: UUID] = [:]
        var checkedPropertyIDs = Set<UUID>()

        func appendSample(_ sample: LocalOrgDriftAuditSample) {
            guard samples.count < sampleLimit else { return }
            samples.append(sample)
        }

        for property in activeLocalProperties {
            let localSessions = ((try? localStore.fetchSessionsForCacheBuild(propertyID: property.id)) ?? [])
                .filter { $0.deletedAt == nil }

            guard !localSessions.isEmpty else {
                unableToConfirmCount += 1
                continue
            }

            for session in localSessions {
                let metadata: SessionMetadata
                do {
                    metadata = try localStore.loadSessionMetadata(propertyID: property.id, sessionID: session.id)
                } catch {
                    unableToConfirmCount += 1
                    continue
                }

                guard let probeOrgID = metadata.orgID ?? property.orgId ?? activeOrganizationID else {
                    unableToConfirmCount += 1
                    continue
                }

                let remoteStatus: SessionSnapshotAuthPreflightRemoteParentStatus
                do {
                    remoteStatus = try await sessionSnapshotRemoteParentPreflightStatus(
                        orgID: probeOrgID,
                        propertyID: property.id,
                        sessionID: session.id
                    )
                } catch {
                    unableToConfirmCount += 1
                    continue
                }

                guard let canonicalOrgID = remoteStatus.confirmedCanonicalOrgID else {
                    unableToConfirmCount += 1
                    continue
                }

                if let previousCanonicalOrgID = confirmedCanonicalOrgByProperty[property.id],
                   previousCanonicalOrgID != canonicalOrgID {
                    unableToConfirmCount += 1
                    continue
                }
                confirmedCanonicalOrgByProperty[property.id] = canonicalOrgID
                totalSessionsChecked += 1

                if !checkedPropertyIDs.contains(property.id) {
                    checkedPropertyIDs.insert(property.id)
                    totalPropertiesChecked += 1
                    if property.orgId != canonicalOrgID {
                        propertyMismatchCount += 1
                        let mismatch = LocalOrgDriftAuditSample(
                            subject: "property",
                            propertyID: property.id,
                            sessionID: nil,
                            localOrgID: property.orgId,
                            canonicalOrgID: canonicalOrgID,
                            detail: "local_property_org_differs_from_confirmed_remote_parent_org"
                        )
                        confirmedMismatches.append(mismatch)
                        appendSample(mismatch)
                    }
                }

                if metadata.orgID != canonicalOrgID {
                    sessionMismatchCount += 1
                    let mismatch = LocalOrgDriftAuditSample(
                        subject: "session_metadata",
                        propertyID: property.id,
                        sessionID: session.id,
                        localOrgID: metadata.orgID,
                        canonicalOrgID: canonicalOrgID,
                        detail: "local_session_metadata_org_differs_from_confirmed_remote_parent_org"
                    )
                    confirmedMismatches.append(mismatch)
                    appendSample(mismatch)
                }
            }
        }

        let result = LocalOrgDriftAuditResult(
            checkedAt: checkedAt,
            totalPropertiesChecked: totalPropertiesChecked,
            totalSessionsChecked: totalSessionsChecked,
            propertyMismatchCount: propertyMismatchCount,
            sessionMismatchCount: sessionMismatchCount,
            unableToConfirmCount: unableToConfirmCount,
            confirmedMismatches: confirmedMismatches,
            samples: samples
        )
        recordLocalOrgDriftAudit(result)
        return result
    }

    @MainActor
    @discardableResult
    func repairConfirmedLocalOrgDrift(repairedAt: Date = Date(), sampleLimit: Int = 5) async -> LocalOrgDriftRepairResult {
        let audit = await runLocalOrgDriftAudit(checkedAt: repairedAt, sampleLimit: sampleLimit)
        var repairedPropertyCount = 0
        var repairedSessionCount = 0
        var skippedCount = audit.unableToConfirmCount
        var failureCount = 0
        var samples: [LocalOrgDriftAuditSample] = []
        var repairedProperties = Set<UUID>()

        func appendRepairSample(_ sample: LocalOrgDriftAuditSample) {
            guard samples.count < sampleLimit else { return }
            samples.append(sample)
        }

        for mismatch in audit.confirmedMismatches {
            switch mismatch.subject {
            case "property":
                guard !repairedProperties.contains(mismatch.propertyID) else {
                    skippedCount += 1
                    continue
                }
                do {
                    let organizationName = organizationSelectionOptions.first(where: { $0.id == mismatch.canonicalOrgID })?.name
                        ?? allOrganizations.first(where: { $0.id == mismatch.canonicalOrgID })?.name
                        ?? activeOrganization?.name
                        ?? "Remote Organization"
                    _ = try localStore.repairPropertyOrgIDForSessionSnapshotValidation(
                        propertyID: mismatch.propertyID,
                        canonicalOrgID: mismatch.canonicalOrgID,
                        organizationName: organizationName
                    )
                    repairedProperties.insert(mismatch.propertyID)
                    repairedPropertyCount += 1
                    appendRepairSample(mismatch)
                } catch {
                    failureCount += 1
                }

            case "session_metadata":
                guard let sessionID = mismatch.sessionID else {
                    skippedCount += 1
                    continue
                }
                do {
                    var metadata = try localStore.loadSessionMetadata(
                        propertyID: mismatch.propertyID,
                        sessionID: sessionID
                    )
                    metadata.orgID = mismatch.canonicalOrgID
                    try localStore.saveSessionMetadataAtomically(
                        propertyID: mismatch.propertyID,
                        sessionID: sessionID,
                        metadata: metadata
                    )
                    repairedSessionCount += 1
                    appendRepairSample(mismatch)
                } catch {
                    failureCount += 1
                }

            default:
                skippedCount += 1
            }
        }

        allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
        allProperties = (try? localStore.fetchProperties()) ?? allProperties
        applyTenantScopedState()

        let result = LocalOrgDriftRepairResult(
            repairedAt: repairedAt,
            attemptedCount: audit.confirmedMismatches.count,
            repairedPropertyCount: repairedPropertyCount,
            repairedSessionCount: repairedSessionCount,
            skippedCount: skippedCount,
            failureCount: failureCount,
            samples: samples
        )
        recordLocalOrgDriftRepair(result)
        return result
    }

    @MainActor
    @discardableResult
    func repairSelectedManualSessionSnapshotLocalOrgDrift() async -> SessionSnapshotLocalOrgRepairResult {
        guard let target = manualSessionSnapshotUploadTarget else {
            let result = SessionSnapshotLocalOrgRepairResult(
                repaired: false,
                propertyID: selectedPropertyID,
                sessionID: nil,
                previousLocalOrgID: nil,
                canonicalOrgID: nil,
                message: "no selected manual snapshot upload target"
            )
            recordSessionSnapshotLocalOrgRepair(result)
            return result
        }

        let localSession: Session
        let localMetadata: SessionMetadata
        do {
            localSession = try localSessionForSnapshotUpload(propertyID: target.propertyID, sessionID: target.sessionID)
            localMetadata = try localStore.loadSessionMetadata(propertyID: target.propertyID, sessionID: localSession.id)
        } catch {
            let result = SessionSnapshotLocalOrgRepairResult(
                repaired: false,
                propertyID: target.propertyID,
                sessionID: target.sessionID,
                previousLocalOrgID: nil,
                canonicalOrgID: nil,
                message: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160) ?? "local target unreadable"
            )
            recordSessionSnapshotLocalOrgRepair(result)
            return result
        }

        let previousOrgID = localMetadata.orgID
        let expectedOrgID = previousOrgID ?? activeOrganizationID ?? UUID()
        let remoteStatus: SessionSnapshotAuthPreflightRemoteParentStatus
        do {
            remoteStatus = try await sessionSnapshotRemoteParentPreflightStatus(
                orgID: expectedOrgID,
                propertyID: target.propertyID,
                sessionID: localSession.id
            )
        } catch {
            let result = SessionSnapshotLocalOrgRepairResult(
                repaired: false,
                propertyID: target.propertyID,
                sessionID: localSession.id,
                previousLocalOrgID: previousOrgID,
                canonicalOrgID: nil,
                message: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160) ?? "remote parent check failed"
            )
            recordSessionSnapshotLocalOrgRepair(result)
            return result
        }

        guard let canonicalOrgID = remoteStatus.confirmedCanonicalOrgID else {
            let result = SessionSnapshotLocalOrgRepairResult(
                repaired: false,
                propertyID: target.propertyID,
                sessionID: localSession.id,
                previousLocalOrgID: previousOrgID,
                canonicalOrgID: remoteStatus.propertyOrgID ?? remoteStatus.sessionOrgID,
                message: "remote parent canonical org could not be confirmed"
            )
            recordSessionSnapshotLocalOrgRepair(result)
            return result
        }

        do {
            let organizationName = organizationSelectionOptions.first(where: { $0.id == canonicalOrgID })?.name
                ?? allOrganizations.first(where: { $0.id == canonicalOrgID })?.name
                ?? activeOrganization?.name
                ?? "Remote Organization"
            let repairedProperty = try localStore.repairPropertyOrgIDForSessionSnapshotValidation(
                propertyID: target.propertyID,
                canonicalOrgID: canonicalOrgID,
                organizationName: organizationName
            )
            var repairedMetadata = localMetadata
            repairedMetadata.orgID = canonicalOrgID
            try localStore.saveSessionMetadataAtomically(
                propertyID: target.propertyID,
                sessionID: localSession.id,
                metadata: repairedMetadata
            )

            allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
            if let index = allProperties.firstIndex(where: { $0.id == repairedProperty.id }) {
                allProperties[index] = repairedProperty
            } else {
                allProperties.append(repairedProperty)
            }
            applyTenantScopedState()

            let result = SessionSnapshotLocalOrgRepairResult(
                repaired: true,
                propertyID: target.propertyID,
                sessionID: localSession.id,
                previousLocalOrgID: previousOrgID,
                canonicalOrgID: canonicalOrgID,
                message: previousOrgID == canonicalOrgID ? "selected target already matched canonical org" : "selected target local org repaired"
            )
            recordSessionSnapshotLocalOrgRepair(result)
            _ = await refreshManualSessionSnapshotAuthPreflight()
            return result
        } catch {
            let result = SessionSnapshotLocalOrgRepairResult(
                repaired: false,
                propertyID: target.propertyID,
                sessionID: localSession.id,
                previousLocalOrgID: previousOrgID,
                canonicalOrgID: canonicalOrgID,
                message: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160) ?? "local repair failed"
            )
            recordSessionSnapshotLocalOrgRepair(result)
            return result
        }
    }

    @discardableResult
    func uploadCurrentSessionSnapshotShadowWrite(
        kind: SessionSnapshotKind = .manual,
        trigger: String = "manual_diagnostic"
    ) async -> SessionSnapshotUploadResult {
        guard let target = manualSessionSnapshotUploadTarget else {
            let message = selectedPropertyID == nil
                ? "No property context is available for manual session snapshot upload."
                : "No local session is available for the selected property."
            recordSessionSnapshotUploadFailure(
                outcome: .failed,
                snapshotID: nil,
                propertyID: selectedPropertyID,
                sessionID: nil,
                path: nil,
                kind: kind,
                trigger: trigger,
                error: SessionSnapshotUploadError.notPreviewable(message)
            )
            return SessionSnapshotUploadResult(
                outcome: .failed,
                snapshotID: nil,
                sessionID: nil,
                propertyID: selectedPropertyID,
                storagePath: nil,
                message: message
            )
        }
        let preflight = await refreshManualSessionSnapshotAuthPreflight()
        if preflight.remoteParentStatus.propertyExists,
           preflight.remoteParentStatus.sessionExists,
           !preflight.remoteParentStatus.orgIDsMatch,
           preflight.remoteParentStatus.errorMessage == nil {
            let message = sessionSnapshotPreflightOrgMismatchBlockReason(
                propertyID: target.propertyID,
                sessionID: target.sessionID
            ) ?? "auth preflight remote parent org mismatch"
            let error = SessionSnapshotUploadError.notPreviewable(message)
            recordSessionSnapshotUploadFailure(
                outcome: .failed,
                snapshotID: nil,
                propertyID: target.propertyID,
                sessionID: target.sessionID,
                path: nil,
                kind: kind,
                trigger: trigger,
                error: error
            )
            return SessionSnapshotUploadResult(
                outcome: .failed,
                snapshotID: nil,
                sessionID: target.sessionID,
                propertyID: target.propertyID,
                storagePath: nil,
                message: message
            )
        }
        return await uploadSessionSnapshotShadowWrite(
            propertyID: target.propertyID,
            sessionID: target.sessionID,
            kind: kind,
            trigger: trigger
        )
    }

    @discardableResult
    func uploadSessionSnapshotShadowWrite(
        propertyID: UUID,
        sessionID: UUID,
        kind: SessionSnapshotKind = .manual,
        trigger: String = "manual_diagnostic",
        generatedAt: Date = Date()
    ) async -> SessionSnapshotUploadResult {
        guard backendFeatureFlags.sessionSnapshotShadowWriteEnabled else {
            mutateLocalDiagnostics { diagnostics in
                diagnostics.sessionSnapshotUpload.flagEnabled = false
                diagnostics.sessionSnapshotUpload.remoteAvailability = "disabled"
                diagnostics.sessionSnapshotUpload.lastKind = kind.rawValue
                diagnostics.sessionSnapshotUpload.lastTrigger = trigger
            }
            return SessionSnapshotUploadResult(
                outcome: .disabled,
                snapshotID: nil,
                sessionID: sessionID,
                propertyID: propertyID,
                storagePath: nil,
                message: SessionSnapshotUploadError.disabled.localizedDescription
            )
        }
        if supabaseConfiguration.isProductionSnapshotValidationManualOnly {
            guard kind == .manual && trigger == "manual_diagnostic" else {
                let error = SessionSnapshotUploadError.notPreviewable("Production snapshot validation is manual-only.")
                recordSessionSnapshotUploadFailure(
                    outcome: .failed,
                    snapshotID: nil,
                    propertyID: propertyID,
                    sessionID: sessionID,
                    path: nil,
                    kind: kind,
                    trigger: trigger,
                    error: error
                )
                return SessionSnapshotUploadResult(
                    outcome: .failed,
                    snapshotID: nil,
                    sessionID: sessionID,
                    propertyID: propertyID,
                    storagePath: nil,
                    message: error.localizedDescription
                )
            }
        }
        if let message = sessionSnapshotPreflightOrgMismatchBlockReason(propertyID: propertyID, sessionID: sessionID) {
            let error = SessionSnapshotUploadError.notPreviewable(message)
            recordSessionSnapshotUploadFailure(
                outcome: .failed,
                snapshotID: nil,
                propertyID: propertyID,
                sessionID: sessionID,
                path: nil,
                kind: kind,
                trigger: trigger,
                error: error
            )
            return SessionSnapshotUploadResult(
                outcome: .failed,
                snapshotID: nil,
                sessionID: sessionID,
                propertyID: propertyID,
                storagePath: nil,
                message: message
            )
        }

        let snapshotID = UUID()
        var storagePath: String?
        recordSessionSnapshotUploadAttempt(
            snapshotID: snapshotID,
            propertyID: propertyID,
            sessionID: sessionID,
            path: nil,
            kind: kind,
            trigger: trigger
        )

        do {
            let session = try localSessionForSnapshotUpload(propertyID: propertyID, sessionID: sessionID)
            let buildResult = try makeSessionSnapshotBuildResult(
                propertyID: propertyID,
                session: session,
                generatedAt: generatedAt,
                trigger: trigger
            )
            let envelope = buildResult.envelope
            guard let orgID = envelope.orgID else {
                throw SessionSnapshotUploadError.missingOrgID
            }

            storagePath = Self.sessionSnapshotStoragePath(
                orgID: orgID,
                propertyID: propertyID,
                sessionID: sessionID,
                snapshotKind: kind,
                snapshotID: snapshotID
            )
            let storageObject = SessionSnapshotStorageObject(
                bucket: sessionSnapshotStorageBucket,
                path: storagePath ?? "",
                payloadData: buildResult.payloadData,
                contentType: "application/json",
                payloadSHA256: envelope.snapshotPayloadSHA256
            )
            let uploadRow = makeSessionSnapshotUploadRow(
                snapshotID: snapshotID,
                kind: kind,
                orgID: orgID,
                envelope: envelope,
                storagePath: storageObject.path
            )

            recordSessionSnapshotGeneratedPayloadPath(
                snapshotID: snapshotID,
                propertyID: propertyID,
                sessionID: sessionID,
                path: storageObject.path,
                kind: kind,
                trigger: trigger
            )
            try await uploadSessionSnapshotStorageObject(storageObject)
            recordSessionSnapshotStorageUploadCompleted(
                snapshotID: snapshotID,
                propertyID: propertyID,
                sessionID: sessionID,
                path: storageObject.path,
                kind: kind,
                trigger: trigger
            )
            do {
                try await insertSessionSnapshotRow(uploadRow)
                recordSessionSnapshotRowInsertCompleted(
                    snapshotID: snapshotID,
                    propertyID: propertyID,
                    sessionID: sessionID,
                    path: storageObject.path,
                    kind: kind,
                    trigger: trigger
                )
            } catch {
                let outcome: SessionSnapshotUploadOutcome = isSessionSnapshotRemoteUnavailable(error) ? .unavailable : .orphanRisk
                recordSessionSnapshotUploadFailure(
                    outcome: outcome,
                    snapshotID: snapshotID,
                    propertyID: propertyID,
                    sessionID: sessionID,
                    path: storageObject.path,
                    kind: kind,
                    trigger: trigger,
                    error: error,
                    orphanRisk: true
                )
                return SessionSnapshotUploadResult(
                    outcome: outcome,
                    snapshotID: snapshotID,
                    sessionID: sessionID,
                    propertyID: propertyID,
                    storagePath: storageObject.path,
                    message: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160)
                )
            }

            recordSessionSnapshotUploadSuccess(
                snapshotID: snapshotID,
                propertyID: propertyID,
                sessionID: sessionID,
                path: storageObject.path,
                kind: kind,
                trigger: trigger
            )
            return SessionSnapshotUploadResult(
                outcome: .succeeded,
                snapshotID: snapshotID,
                sessionID: sessionID,
                propertyID: propertyID,
                storagePath: storageObject.path,
                message: nil
            )
        } catch {
            let outcome: SessionSnapshotUploadOutcome = isSessionSnapshotRemoteUnavailable(error) ? .unavailable : .failed
            recordSessionSnapshotUploadFailure(
                outcome: outcome,
                snapshotID: snapshotID,
                propertyID: propertyID,
                sessionID: sessionID,
                path: storagePath,
                kind: kind,
                trigger: trigger,
                error: error
            )
            return SessionSnapshotUploadResult(
                outcome: outcome,
                snapshotID: snapshotID,
                sessionID: sessionID,
                propertyID: propertyID,
                storagePath: storagePath,
                message: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160)
            )
        }
    }

    @discardableResult
    func attemptAutomaticSessionSnapshotUploadForCompletedSealedCheckpoint(
        session: Session,
        triggerSource: String,
        attemptedAt: Date = Date()
    ) async -> SessionSnapshotUploadResult? {
        let propertyID = session.propertyID
        let sessionID = session.id
        let checkpointKey = Self.sessionSnapshotAutoUploadCheckpointKey(session: session, triggerSource: triggerSource)

        guard backendFeatureFlags.sessionSnapshotAutoUploadEnabled else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "auto_upload_disabled"
            )
            return nil
        }
        guard !backendFeatureFlags.sessionSnapshotAutoUploadKillSwitch else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "kill_switch_active"
            )
            return nil
        }
        guard backendFeatureFlags.sessionSnapshotAutoUploadHasAllowlist else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "allowlist_empty"
            )
            return nil
        }
        guard session.status == .completed, session.isSealed, session.deletedAt == nil else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "session_not_completed_sealed"
            )
            return nil
        }
        guard backendFeatureFlags.sessionSnapshotShadowWriteEnabled else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "snapshot_shadow_write_disabled"
            )
            return nil
        }
        guard supabaseConfiguration.isConfigured else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "supabase_config_invalid"
            )
            return nil
        }
        guard supabaseConfiguration.isSessionSnapshotShadowWriteOverrideAllowed else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "snapshot_target_not_approved"
            )
            return nil
        }
        guard !supabaseConfiguration.isProductionSnapshotValidationManualOnly else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "production_validation_manual_only"
            )
            return nil
        }

        let orgID = sessionSnapshotAutoUploadOrgID(for: session)
        guard sessionSnapshotAutoUploadAllowlistMatches(propertyID: propertyID, orgID: orgID) else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "allowlist_no_match"
            )
            return nil
        }
        guard reserveSessionSnapshotAutoUploadCheckpointKey(checkpointKey) else {
            recordSessionSnapshotAutoUploadSkipped(
                propertyID: propertyID,
                sessionID: sessionID,
                triggerSource: triggerSource,
                reason: "duplicate_checkpoint"
            )
            return nil
        }

        recordSessionSnapshotAutoUploadAttempt(
            propertyID: propertyID,
            sessionID: sessionID,
            triggerSource: triggerSource,
            attemptedAt: attemptedAt
        )
        let result = await uploadSessionSnapshotShadowWrite(
            propertyID: propertyID,
            sessionID: sessionID,
            kind: .completed,
            trigger: "auto_completed_sealed_archive:\(triggerSource)",
            generatedAt: attemptedAt
        )
        recordSessionSnapshotAutoUploadResult(result, triggerSource: triggerSource)
        return result
    }

    private func sessionSnapshotAutoUploadOrgID(for session: Session) -> UUID? {
        if let metadata = try? localStore.loadSessionMetadata(propertyID: session.propertyID, sessionID: session.id) {
            return metadata.orgID
        }
        if let property = (try? localStore.fetchProperties())?.first(where: { $0.id == session.propertyID }),
           let orgID = property.orgId {
            return orgID
        }
        return nil
    }

    private func sessionSnapshotAutoUploadAllowlistMatches(propertyID: UUID, orgID: UUID?) -> Bool {
        if backendFeatureFlags.sessionSnapshotAutoUploadPropertyAllowlist.contains(propertyID) {
            return true
        }
        if let orgID, backendFeatureFlags.sessionSnapshotAutoUploadOrgAllowlist.contains(orgID) {
            return true
        }
        return false
    }

    private func reserveSessionSnapshotAutoUploadCheckpointKey(_ key: String) -> Bool {
        if sessionSnapshotAutoUploadCheckpointKeys.contains(key) {
            return false
        }
        sessionSnapshotAutoUploadCheckpointKeys.insert(key)
        return true
    }

    private static func sessionSnapshotAutoUploadCheckpointKey(session: Session, triggerSource: String) -> String {
        let formatter = ISO8601DateFormatter()
        let endedAt = session.endedAt.map { formatter.string(from: $0) } ?? "no-ended-at"
        let exportedAt = session.exportedAt.map { formatter.string(from: $0) } ?? "no-exported-at"
        let firstDeliveredAt = session.firstDeliveredAt.map { formatter.string(from: $0) } ?? "no-first-delivered-at"
        let sealedState = session.isSealed ? "sealed" : "unsealed"
        let parts: [String] = [
            session.propertyID.uuidString.lowercased(),
            session.id.uuidString.lowercased(),
            triggerSource,
            session.status.rawValue,
            sealedState,
            endedAt,
            exportedAt,
            firstDeliveredAt
        ]
        return parts.joined(separator: "|")
    }

    private func localSessionForSnapshotUpload(propertyID: UUID, sessionID: UUID) throws -> Session {
        if let currentSession, currentSession.propertyID == propertyID, currentSession.id == sessionID {
            return currentSession
        }
        if let session = (try? localStore.fetchSessionsForCacheBuild(propertyID: propertyID))
            .flatMap({ sessions in sessions.first { $0.id == sessionID } }) {
            return session
        }
        throw SessionSnapshotUploadError.notPreviewable("local_session_not_found")
    }

    private func makeSessionSnapshotUploadRow(
        snapshotID: UUID,
        kind: SessionSnapshotKind,
        orgID: UUID,
        envelope: SessionSnapshotEnvelope,
        storagePath: String
    ) -> SessionSnapshotUploadRow {
        SessionSnapshotUploadRow(
            id: snapshotID,
            orgID: orgID,
            propertyID: envelope.propertyID,
            sessionID: envelope.sessionID,
            snapshotKind: kind.rawValue,
            snapshotSchemaVersion: envelope.snapshotSchemaVersion,
            sessionMetadataSchemaVersion: envelope.sessionMetadataSchemaVersion,
            trigger: envelope.trigger,
            sessionStatus: envelope.status.rawValue,
            isSealed: envelope.isSealed,
            exportedAt: envelope.exportedAt,
            firstDeliveredAt: envelope.firstDeliveredAt,
            reExportExpiresAt: envelope.reExportExpiresAt,
            payloadStorageBucket: sessionSnapshotStorageBucket,
            payloadStoragePath: storagePath,
            payloadByteSize: envelope.snapshotPayloadByteCount,
            rawSessionJSONSHA256: envelope.rawSessionJSONSHA256,
            snapshotPayloadSHA256: envelope.snapshotPayloadSHA256,
            manifest: SessionSnapshotUploadManifest(media: envelope.mediaManifest),
            shotCount: envelope.shotCount,
            issueCount: envelope.issueCount,
            guidedCount: envelope.guidedCount,
            mediaManifestCount: envelope.mediaManifestCount,
            missingLocalOriginalsCount: envelope.missingLocalOriginalsCount,
            supabaseStorageMetadataCount: envelope.supabaseStorageMetadataCount,
            createdBy: authenticatedSupabaseUser?.id,
            updatedBy: authenticatedSupabaseUser?.id,
            createdAt: nil
        )
    }

    #if DEBUG
    func _debugMakeSessionSnapshotUploadArtifactsForTests(
        propertyID: UUID,
        sessionID: UUID,
        snapshotID: UUID = UUID(),
        kind: SessionSnapshotKind = .manual,
        trigger: String = "manual_diagnostic",
        generatedAt: Date = Date()
    ) throws -> (row: SessionSnapshotUploadRow, object: SessionSnapshotStorageObject) {
        let session = try localSessionForSnapshotUpload(propertyID: propertyID, sessionID: sessionID)
        let buildResult = try makeSessionSnapshotBuildResult(
            propertyID: propertyID,
            session: session,
            generatedAt: generatedAt,
            trigger: trigger
        )
        guard let orgID = buildResult.envelope.orgID else {
            throw SessionSnapshotUploadError.missingOrgID
        }
        let storagePath = Self.sessionSnapshotStoragePath(
            orgID: orgID,
            propertyID: propertyID,
            sessionID: sessionID,
            snapshotKind: kind,
            snapshotID: snapshotID
        )
        let object = SessionSnapshotStorageObject(
            bucket: sessionSnapshotStorageBucket,
            path: storagePath,
            payloadData: buildResult.payloadData,
            contentType: "application/json",
            payloadSHA256: buildResult.envelope.snapshotPayloadSHA256
        )
        let row = makeSessionSnapshotUploadRow(
            snapshotID: snapshotID,
            kind: kind,
            orgID: orgID,
            envelope: buildResult.envelope,
            storagePath: storagePath
        )
        return (row, object)
    }
    #endif

    private func uploadSessionSnapshotStorageObject(_ object: SessionSnapshotStorageObject) async throws {
        if let sessionSnapshotStorageUploadOverride {
            try await sessionSnapshotStorageUploadOverride(object)
            return
        }
        guard backendFeatureFlags.supabaseEnabled,
              let client = supabaseClient else {
            throw SessionSnapshotUploadError.missingSupabaseClient
        }
        _ = try await client.storage.from(object.bucket).upload(
            object.path,
            data: object.payloadData,
            options: FileOptions(
                cacheControl: "31536000",
                contentType: object.contentType,
                upsert: false
            )
        )
    }

    private func insertSessionSnapshotRow(_ row: SessionSnapshotUploadRow) async throws {
        if let sessionSnapshotRowInsertOverride {
            try await sessionSnapshotRowInsertOverride(row)
            return
        }
        guard backendFeatureFlags.supabaseEnabled,
              let client = supabaseClient else {
            throw SessionSnapshotUploadError.missingSupabaseClient
        }
        try await client
            .from("session_snapshots")
            .insert(row, returning: .minimal)
            .execute()
    }

    @discardableResult
    func validateLatestSessionSnapshotRemoteReadback(checkedAt: Date = Date()) async -> SessionSnapshotReadbackResult {
        let snapshotID = localDiagnostics.sessionSnapshotUpload.lastSnapshotID
        let propertyID = localDiagnostics.sessionSnapshotUpload.lastPropertyID ?? manualSessionSnapshotUploadTarget?.propertyID
        let sessionID = localDiagnostics.sessionSnapshotUpload.lastSessionID ?? manualSessionSnapshotUploadTarget?.sessionID

        do {
            let rows = try await fetchSessionSnapshotRows(snapshotID: snapshotID, propertyID: propertyID, sessionID: sessionID)
            guard let row = rows.sorted(by: Self.sessionSnapshotUploadRowSort).first else {
                let result = Self.makeSessionSnapshotReadbackResult(
                    row: nil,
                    payloadData: nil,
                    checkedAt: checkedAt,
                    failureReason: "snapshot row not found"
                )
                recordSessionSnapshotReadback(result)
                return result
            }

            do {
                let payloadData = try await downloadSessionSnapshotPayload(bucket: row.payloadStorageBucket, path: row.payloadStoragePath)
                let result = Self.makeSessionSnapshotReadbackResult(
                    row: row,
                    payloadData: payloadData,
                    checkedAt: checkedAt,
                    failureReason: nil
                )
                recordSessionSnapshotReadback(result)
                return result
            } catch {
                let result = Self.makeSessionSnapshotReadbackResult(
                    row: row,
                    payloadData: nil,
                    checkedAt: checkedAt,
                    failureReason: error.localizedDescription
                )
                recordSessionSnapshotReadback(result)
                return result
            }
        } catch {
            let result = Self.makeSessionSnapshotReadbackResult(
                row: nil,
                payloadData: nil,
                checkedAt: checkedAt,
                failureReason: error.localizedDescription
            )
            recordSessionSnapshotReadback(result)
            return result
        }
    }

    @discardableResult
    func validateLatestSessionSnapshotRestoreDiagnostics(checkedAt: Date = Date()) async -> SessionSnapshotRestoreDiagnosticsResult {
        let propertyID = manualSessionSnapshotUploadTarget?.propertyID ?? localDiagnostics.sessionSnapshotUpload.lastPropertyID
        let sessionID = manualSessionSnapshotUploadTarget?.sessionID ?? localDiagnostics.sessionSnapshotUpload.lastSessionID

        do {
            let rows = try await fetchSessionSnapshotRows(snapshotID: nil, propertyID: propertyID, sessionID: sessionID)
            guard let row = rows.sorted(by: Self.sessionSnapshotUploadRowSort).first else {
                let result = SessionSnapshotRestoreDiagnosticsResult(
                    checkedAt: checkedAt,
                    propertyID: propertyID,
                    sessionID: sessionID,
                    snapshotID: nil,
                    result: .noSnapshotFound,
                    failureReason: "snapshot row not found",
                    rowFound: false,
                    objectReadable: false,
                    checksumVerified: false,
                    byteSizeMatches: false,
                    rowObjectVerified: false,
                    parentRemoteVerified: false,
                    snapshotSchemaVersion: nil,
                    snapshotCreatedAt: nil,
                    snapshotGeneratedAt: nil,
                    localSessionExists: false,
                    localSessionStatus: nil,
                    localShotCount: nil,
                    localIssueCount: nil,
                    localGuidedCount: nil,
                    snapshotShotCount: nil,
                    snapshotIssueCount: nil,
                    snapshotGuidedCount: nil,
                    snapshotMediaManifestCount: nil,
                    snapshotMissingLocalOriginalsCount: nil,
                    snapshotSupabaseStorageMetadataCount: nil,
                    freshness: "unknown",
                    mediaRecoveryDiagnostics: .notChecked
                )
                recordSessionSnapshotRestoreDiagnostics(result)
                return result
            }

            let payloadData: Data
            do {
                payloadData = try await downloadSessionSnapshotPayload(
                    bucket: row.payloadStorageBucket,
                    path: row.payloadStoragePath
                )
            } catch {
                let result = makeSessionSnapshotRestoreDiagnosticsResult(
                    row: row,
                    payloadData: nil,
                    checkedAt: checkedAt,
                    parentStatus: nil,
                    localComparison: nil,
                    outcome: .objectMissing,
                    failureReason: "snapshot payload object missing or unreadable"
                )
                recordSessionSnapshotRestoreDiagnostics(result)
                return result
            }

            let decodedPayload = Self.decodeSessionSnapshotPayload(payloadData)
            let localComparison = localSessionSnapshotRestoreComparison(propertyID: row.propertyID, sessionID: row.sessionID)
            let parentStatus: SessionSnapshotAuthPreflightRemoteParentStatus?
            do {
                parentStatus = try await sessionSnapshotRemoteParentPreflightStatus(
                    orgID: row.orgID,
                    propertyID: row.propertyID,
                    sessionID: row.sessionID
                )
            } catch {
                let result = makeSessionSnapshotRestoreDiagnosticsResult(
                    row: row,
                    payloadData: payloadData,
                    checkedAt: checkedAt,
                    parentStatus: nil,
                    localComparison: localComparison,
                    outcome: .unableToVerify,
                    failureReason: "remote parent check failed"
                )
                recordSessionSnapshotRestoreDiagnostics(result)
                return result
            }

            let readback = Self.makeSessionSnapshotReadbackResult(
                row: row,
                payloadData: payloadData,
                checkedAt: checkedAt,
                failureReason: nil
            )
            let outcomeAndReason = Self.sessionSnapshotRestoreOutcome(
                row: row,
                decodedPayload: decodedPayload,
                readback: readback,
                parentStatus: parentStatus,
                localComparison: localComparison
            )
            let result = makeSessionSnapshotRestoreDiagnosticsResult(
                row: row,
                payloadData: payloadData,
                checkedAt: checkedAt,
                parentStatus: parentStatus,
                localComparison: localComparison,
                outcome: outcomeAndReason.outcome,
                failureReason: outcomeAndReason.reason
            )
            recordSessionSnapshotRestoreDiagnostics(result)
            return result
        } catch {
            let result = SessionSnapshotRestoreDiagnosticsResult(
                checkedAt: checkedAt,
                propertyID: propertyID,
                sessionID: sessionID,
                snapshotID: nil,
                result: .unableToVerify,
                failureReason: "unable to verify snapshot restore diagnostics",
                rowFound: false,
                objectReadable: false,
                checksumVerified: false,
                byteSizeMatches: false,
                rowObjectVerified: false,
                parentRemoteVerified: false,
                snapshotSchemaVersion: nil,
                snapshotCreatedAt: nil,
                snapshotGeneratedAt: nil,
                localSessionExists: false,
                localSessionStatus: nil,
                localShotCount: nil,
                localIssueCount: nil,
                localGuidedCount: nil,
                snapshotShotCount: nil,
                snapshotIssueCount: nil,
                snapshotGuidedCount: nil,
                snapshotMediaManifestCount: nil,
                snapshotMissingLocalOriginalsCount: nil,
                snapshotSupabaseStorageMetadataCount: nil,
                freshness: "unknown",
                mediaRecoveryDiagnostics: .notChecked
            )
            recordSessionSnapshotRestoreDiagnostics(result)
            return result
        }
    }

    @discardableResult
    func hydrateMetadataFromLatestSessionSnapshot(checkedAt: Date = Date()) async -> SessionSnapshotHydrationResult {
        let hydrationPolicy = sessionSnapshotHydrationPolicyDiagnostics
        recordSessionSnapshotHydrationPolicyDiagnostics(hydrationPolicy)
        guard hydrationPolicy.hydrationAvailable else {
            let result = SessionSnapshotHydrationResult(
                hydratedAt: checkedAt,
                allowed: false,
                blockedReason: hydrationPolicy.productionHydrationBlockedReason ?? "hydration_unavailable",
                sourceSnapshotID: nil,
                propertyID: manualSessionSnapshotUploadTarget?.propertyID ?? localDiagnostics.sessionSnapshotUpload.lastPropertyID,
                sessionID: manualSessionSnapshotUploadTarget?.sessionID ?? localDiagnostics.sessionSnapshotUpload.lastSessionID,
                hydratedShotCount: 0,
                hydratedIssueCount: 0,
                hydratedGuidedCount: 0
            )
            recordSessionSnapshotHydration(result)
            return result
        }

        let diagnostics = await validateLatestSessionSnapshotRestoreDiagnostics(checkedAt: checkedAt)
        guard diagnostics.result == .restorableMetadataCandidate,
              diagnostics.checksumVerified,
              diagnostics.rowObjectVerified,
              diagnostics.parentRemoteVerified,
              diagnostics.snapshotSchemaVersion == 1,
              diagnostics.freshness != "local_newer" else {
            let result = SessionSnapshotHydrationResult(
                hydratedAt: checkedAt,
                allowed: false,
                blockedReason: diagnostics.result.rawValue,
                sourceSnapshotID: diagnostics.snapshotID,
                propertyID: diagnostics.propertyID,
                sessionID: diagnostics.sessionID,
                hydratedShotCount: 0,
                hydratedIssueCount: 0,
                hydratedGuidedCount: 0
            )
            recordSessionSnapshotHydration(result)
            return result
        }

        guard let snapshotID = diagnostics.snapshotID,
              let propertyID = diagnostics.propertyID,
              let sessionID = diagnostics.sessionID else {
            let result = SessionSnapshotHydrationResult(
                hydratedAt: checkedAt,
                allowed: false,
                blockedReason: "missing_snapshot_target",
                sourceSnapshotID: diagnostics.snapshotID,
                propertyID: diagnostics.propertyID,
                sessionID: diagnostics.sessionID,
                hydratedShotCount: 0,
                hydratedIssueCount: 0,
                hydratedGuidedCount: 0
            )
            recordSessionSnapshotHydration(result)
            return result
        }

        do {
            let rows = try await fetchSessionSnapshotRows(snapshotID: snapshotID, propertyID: propertyID, sessionID: sessionID)
            guard let row = rows.first(where: { $0.id == snapshotID }) ?? rows.sorted(by: Self.sessionSnapshotUploadRowSort).first else {
                throw SessionSnapshotUploadError.notPreviewable("snapshot_row_not_found")
            }
            let payloadData = try await downloadSessionSnapshotPayload(
                bucket: row.payloadStorageBucket,
                path: row.payloadStoragePath
            )
            guard let payload = Self.decodeSessionSnapshotPayload(payloadData),
                  payload.snapshotSchemaVersion == 1,
                  payload.propertyID == propertyID,
                  payload.sessionID == sessionID else {
                throw SessionSnapshotUploadError.notPreviewable("snapshot_payload_unusable")
            }
            let metadata = try Self.decodeHydratableSessionMetadata(from: payload.rawSessionJSON)
            guard metadata.propertyID == propertyID, metadata.sessionID == sessionID else {
                throw SessionSnapshotUploadError.notPreviewable("snapshot_metadata_target_mismatch")
            }

            let session = Session(
                id: sessionID,
                propertyID: propertyID,
                startedAt: metadata.startedAt,
                status: metadata.status,
                endedAt: metadata.endedAt,
                exportedAt: metadata.exportedAt,
                isSealed: metadata.isSealed,
                firstDeliveredAt: metadata.firstDeliveredAt,
                reExportExpiresAt: metadata.reExportExpiresAt
            )
            _ = try localStore.upsertSession(session)
            try localStore.saveSessionMetadataAtomically(propertyID: propertyID, sessionID: sessionID, metadata: metadata)

            let result = SessionSnapshotHydrationResult(
                hydratedAt: checkedAt,
                allowed: true,
                blockedReason: nil,
                sourceSnapshotID: snapshotID,
                propertyID: propertyID,
                sessionID: sessionID,
                hydratedShotCount: metadata.shots.count,
                hydratedIssueCount: metadata.issues.count,
                hydratedGuidedCount: metadata.guidedShots.count
            )
            recordSessionSnapshotHydration(result)
            return result
        } catch {
            let result = SessionSnapshotHydrationResult(
                hydratedAt: checkedAt,
                allowed: false,
                blockedReason: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160) ?? "hydration_failed",
                sourceSnapshotID: snapshotID,
                propertyID: propertyID,
                sessionID: sessionID,
                hydratedShotCount: 0,
                hydratedIssueCount: 0,
                hydratedGuidedCount: 0
            )
            recordSessionSnapshotHydration(result)
            return result
        }
    }

    var sessionSnapshotHydrationPolicyDiagnostics: SessionSnapshotHydrationPolicyDiagnostics {
        guard supabaseConfiguration.isConfigured else {
            return SessionSnapshotHydrationPolicyDiagnostics(
                hydrationAvailable: false,
                productionHydrationAllowed: false,
                hydrationMode: "blocked_by_default",
                hydrationScope: "none",
                productionHydrationBlockedReason: "supabase_config_invalid"
            )
        }

        if supabaseConfiguration.isExactProductionSnapshotHydrationTarget {
            guard supabaseConfiguration.productionSnapshotHydrationAllowed else {
                return SessionSnapshotHydrationPolicyDiagnostics(
                    hydrationAvailable: false,
                    productionHydrationAllowed: false,
                    hydrationMode: "blocked_by_default",
                    hydrationScope: "none",
                    productionHydrationBlockedReason: "production_hydration_gate_disabled"
                )
            }
            guard manualSessionSnapshotUploadTarget != nil else {
                return SessionSnapshotHydrationPolicyDiagnostics(
                    hydrationAvailable: false,
                    productionHydrationAllowed: true,
                    hydrationMode: "diagnostics_only",
                    hydrationScope: "none",
                    productionHydrationBlockedReason: "single_session_target_required"
                )
            }
            return SessionSnapshotHydrationPolicyDiagnostics(
                hydrationAvailable: true,
                productionHydrationAllowed: true,
                hydrationMode: "operator_approved_single_session",
                hydrationScope: "single_selected_session",
                productionHydrationBlockedReason: nil
            )
        }

        switch supabaseConfiguration.targetClassification {
        case .localDev, .approvedStaging:
            return SessionSnapshotHydrationPolicyDiagnostics(
                hydrationAvailable: true,
                productionHydrationAllowed: false,
                hydrationMode: "diagnostics_only",
                hydrationScope: "local_or_staging_manual",
                productionHydrationBlockedReason: nil
            )
        case .approvedProductionValidation:
            return SessionSnapshotHydrationPolicyDiagnostics(
                hydrationAvailable: false,
                productionHydrationAllowed: false,
                hydrationMode: "production_wide_disabled",
                hydrationScope: "none",
                productionHydrationBlockedReason: "production_hydration_target_not_exact"
            )
        case .remote:
            return SessionSnapshotHydrationPolicyDiagnostics(
                hydrationAvailable: false,
                productionHydrationAllowed: false,
                hydrationMode: "production_wide_disabled",
                hydrationScope: "none",
                productionHydrationBlockedReason: "unapproved_remote_hydration_disabled"
            )
        case .missing:
            return SessionSnapshotHydrationPolicyDiagnostics(
                hydrationAvailable: false,
                productionHydrationAllowed: false,
                hydrationMode: "blocked_by_default",
                hydrationScope: "none",
                productionHydrationBlockedReason: "supabase_config_missing"
            )
        case .invalid:
            return SessionSnapshotHydrationPolicyDiagnostics(
                hydrationAvailable: false,
                productionHydrationAllowed: false,
                hydrationMode: "blocked_by_default",
                hydrationScope: "none",
                productionHydrationBlockedReason: "supabase_config_invalid"
            )
        }
    }

    static func makeSessionSnapshotHydrationConfirmation(
        diagnostics: SessionSnapshotUploadDiagnostics,
        policy: SessionSnapshotHydrationPolicyDiagnostics
    ) -> SessionSnapshotHydrationConfirmation {
        let restoreResult = diagnostics.lastRestoreDiagnosticsResult
        let blockedReason: String? = {
            if !policy.hydrationAvailable {
                return policy.productionHydrationBlockedReason ?? "hydration_policy_blocked"
            }
            guard restoreResult == SessionSnapshotRestoreDiagnosticOutcome.restorableMetadataCandidate.rawValue else {
                return restoreResult == "not_checked" ? "restore_diagnostics_not_checked" : restoreResult
            }
            guard diagnostics.lastRestoreDiagnosticsChecksumVerified else {
                return SessionSnapshotRestoreDiagnosticOutcome.checksumFailed.rawValue
            }
            guard diagnostics.lastRestoreDiagnosticsRowObjectVerified else {
                return "row_object_not_verified"
            }
            guard diagnostics.lastRestoreDiagnosticsParentRemoteVerified else {
                return SessionSnapshotRestoreDiagnosticOutcome.parentMismatch.rawValue
            }
            guard diagnostics.lastRestoreDiagnosticsSnapshotSchemaVersion == 1 else {
                return SessionSnapshotRestoreDiagnosticOutcome.unsupportedSchema.rawValue
            }
            guard diagnostics.lastRestoreDiagnosticsFreshness != "local_newer" else {
                return SessionSnapshotRestoreDiagnosticOutcome.localNewerConflict.rawValue
            }
            guard diagnostics.lastRestoreDiagnosticsPropertyID != nil,
                  diagnostics.lastRestoreDiagnosticsSessionID != nil,
                  diagnostics.lastRestoreDiagnosticsSnapshotID != nil else {
                return "missing_snapshot_target"
            }
            return nil
        }()
        let canHydrate = blockedReason == nil
        let propertyIDText = diagnostics.lastRestoreDiagnosticsPropertyID?.uuidString ?? "none"
        let sessionIDText = diagnostics.lastRestoreDiagnosticsSessionID?.uuidString ?? "none"
        let snapshotIDText = diagnostics.lastRestoreDiagnosticsSnapshotID?.uuidString ?? "none"
        let shotCountText = diagnostics.lastRestoreDiagnosticsSnapshotShotCount.map(String.init) ?? "none"
        let issueCountText = diagnostics.lastRestoreDiagnosticsSnapshotIssueCount.map(String.init) ?? "none"
        let guidedCountText = diagnostics.lastRestoreDiagnosticsSnapshotGuidedCount.map(String.init) ?? "none"
        let blockedText = blockedReason.map { "\n\nBlocked reason: \($0)" } ?? ""
        let message = [
            "Property: \(propertyIDText)",
            "Session: \(sessionIDText)",
            "Snapshot: \(snapshotIDText)",
            "Result: \(restoreResult)",
            "Counts: shots \(shotCountText), issues \(issueCountText), guided \(guidedCountText)",
            "Hydration writes local metadata only.",
            "Media files and original images are not restored or downloaded.",
            "Canonical reads, export, seal, sync, media, and iCloud behavior are unchanged."
        ].joined(separator: "\n") + blockedText

        return SessionSnapshotHydrationConfirmation(
            confirmationRequired: true,
            canHydrate: canHydrate,
            blockedReason: blockedReason,
            propertyIDText: propertyIDText,
            sessionIDText: sessionIDText,
            snapshotIDText: snapshotIDText,
            restoreResult: restoreResult,
            shotCountText: shotCountText,
            issueCountText: issueCountText,
            guidedCountText: guidedCountText,
            messageText: message
        )
    }

    static func makeSessionSnapshotMediaRetrievalConfirmation(
        diagnostics: SessionSnapshotUploadDiagnostics,
        targetClassification: SupabaseRuntimeConfiguration.TargetClassification
    ) -> SessionSnapshotMediaRetrievalConfirmation {
        let maxBatchSize = SessionSnapshotMediaRetrievalPolicyDiagnostics.guardrailsOnly.maxBatchSize
        let blockedReason: String? = {
            switch targetClassification {
            case .localDev, .approvedStaging:
                break
            case .approvedProductionValidation:
                return "production_media_retrieval_blocked"
            case .remote:
                return "unapproved_remote_media_retrieval_blocked"
            case .missing:
                return "supabase_config_missing"
            case .invalid:
                return "supabase_config_invalid"
            }
            guard diagnostics.lastRestoreDiagnosticsResult == SessionSnapshotRestoreDiagnosticOutcome.restorableMetadataCandidate.rawValue else {
                return diagnostics.lastRestoreDiagnosticsResult == "not_checked"
                    ? "restore_diagnostics_not_checked"
                    : diagnostics.lastRestoreDiagnosticsResult
            }
            guard diagnostics.lastRestoreDiagnosticsChecksumVerified else {
                return SessionSnapshotRestoreDiagnosticOutcome.checksumFailed.rawValue
            }
            guard diagnostics.lastRestoreDiagnosticsRowObjectVerified else {
                return "row_object_not_verified"
            }
            guard diagnostics.lastRestoreDiagnosticsParentRemoteVerified else {
                return SessionSnapshotRestoreDiagnosticOutcome.parentMismatch.rawValue
            }
            guard diagnostics.lastRestoreDiagnosticsSnapshotSchemaVersion == 1 else {
                return SessionSnapshotRestoreDiagnosticOutcome.unsupportedSchema.rawValue
            }
            guard diagnostics.lastRestoreDiagnosticsMediaManifestSupported else {
                return "unsupported_media_manifest"
            }
            guard diagnostics.lastRestoreDiagnosticsMediaChecksumUnknownCount == 0 else {
                return "checksum_unknown"
            }
            guard diagnostics.lastRestoreDiagnosticsMediaChecksumMismatchCount == 0 else {
                return "checksum_mismatch"
            }
            guard diagnostics.lastRestoreDiagnosticsMediaMissingRemoteStorageMetadataCount == 0 else {
                return "missing_remote_storage_metadata"
            }
            guard diagnostics.lastRestoreDiagnosticsMediaRecoverableRemoteCount > 0 else {
                return "no_remote_recoverable_media"
            }
            guard diagnostics.lastRestoreDiagnosticsMediaRecoverableRemoteCount <= maxBatchSize else {
                return "max_batch_size_exceeded"
            }
            guard diagnostics.lastRestoreDiagnosticsPropertyID != nil,
                  diagnostics.lastRestoreDiagnosticsSessionID != nil,
                  diagnostics.lastRestoreDiagnosticsSnapshotID != nil else {
                return "missing_snapshot_target"
            }
            return nil
        }()
        let propertyIDText = diagnostics.lastRestoreDiagnosticsPropertyID?.uuidString ?? "none"
        let sessionIDText = diagnostics.lastRestoreDiagnosticsSessionID?.uuidString ?? "none"
        let snapshotIDText = diagnostics.lastRestoreDiagnosticsSnapshotID?.uuidString ?? "none"
        let mediaCount = diagnostics.lastRestoreDiagnosticsMediaRecoverableRemoteCount
        let blockedText = blockedReason.map { "\n\nBlocked reason: \($0)" } ?? ""
        let message = [
            "Property: \(propertyIDText)",
            "Session: \(sessionIDText)",
            "Snapshot: \(snapshotIDText)",
            "Media items: \(mediaCount)",
            "Max batch size: \(maxBatchSize)",
            "Test-only manual retrieval. Production media retrieval remains blocked.",
            "Recovered bytes are written only to the guarded recovered-media location and never over existing originals.",
            "Canonical reads, export, seal, sync, media backfill, and iCloud behavior are unchanged."
        ].joined(separator: "\n") + blockedText

        return SessionSnapshotMediaRetrievalConfirmation(
            confirmationRequired: true,
            canRetrieve: blockedReason == nil,
            blockedReason: blockedReason,
            propertyIDText: propertyIDText,
            sessionIDText: sessionIDText,
            snapshotIDText: snapshotIDText,
            mediaCount: mediaCount,
            maxBatchSize: maxBatchSize,
            messageText: message
        )
    }

    @discardableResult
    func retrieveSnapshotMediaTestOnly(
        checkedAt: Date = Date(),
        manualAction: Bool = true,
        storageQuotaChecked: Bool = true,
        networkApproved: Bool = true,
        batteryApproved: Bool = true
    ) async -> SessionSnapshotMediaRetrievalResult {
        let diagnostics = await validateLatestSessionSnapshotRestoreDiagnostics(checkedAt: checkedAt)
        let policyViolations = Self.sessionSnapshotMediaRetrievalGuardrailViolations(
            requestedBatchSize: diagnostics.mediaRecoveryDiagnostics.recoverableRemoteCount,
            isManual: manualAction,
            isAllowlisted: supabaseConfiguration.targetClassification == .localDev ||
                supabaseConfiguration.targetClassification == .approvedStaging,
            isProductionWide: supabaseConfiguration.targetClassification == .approvedProductionValidation,
            storageQuotaChecked: storageQuotaChecked,
            networkApproved: networkApproved,
            batteryApproved: batteryApproved,
            checksumValidationPlanned: true,
            duplicatePreventionPlanned: true
        )
        if let violation = policyViolations.first {
            let result = makeBlockedSessionSnapshotMediaRetrievalResult(
                checkedAt: checkedAt,
                diagnostics: diagnostics,
                reason: violation
            )
            recordSessionSnapshotMediaRetrieval(result)
            return result
        }

        let confirmation = Self.makeSessionSnapshotMediaRetrievalConfirmation(
            diagnostics: localDiagnostics.sessionSnapshotUpload,
            targetClassification: supabaseConfiguration.targetClassification
        )
        guard confirmation.canRetrieve else {
            let result = makeBlockedSessionSnapshotMediaRetrievalResult(
                checkedAt: checkedAt,
                diagnostics: diagnostics,
                reason: confirmation.blockedReason ?? "media_retrieval_blocked"
            )
            recordSessionSnapshotMediaRetrieval(result)
            return result
        }

        guard let snapshotID = diagnostics.snapshotID,
              let propertyID = diagnostics.propertyID,
              let sessionID = diagnostics.sessionID else {
            let result = makeBlockedSessionSnapshotMediaRetrievalResult(
                checkedAt: checkedAt,
                diagnostics: diagnostics,
                reason: "missing_snapshot_target"
            )
            recordSessionSnapshotMediaRetrieval(result)
            return result
        }

        do {
            let rows = try await fetchSessionSnapshotRows(snapshotID: snapshotID, propertyID: propertyID, sessionID: sessionID)
            guard let row = rows.first(where: { $0.id == snapshotID }) ?? rows.sorted(by: Self.sessionSnapshotUploadRowSort).first else {
                throw SessionSnapshotUploadError.notPreviewable("snapshot_row_not_found")
            }
            let payloadData = try await downloadSessionSnapshotPayload(bucket: row.payloadStorageBucket, path: row.payloadStoragePath)
            guard let payload = Self.decodeSessionSnapshotPayload(payloadData),
                  payload.snapshotSchemaVersion == 1,
                  payload.propertyID == propertyID,
                  payload.sessionID == sessionID,
                  payload.mediaManifestCount == payload.mediaManifest.count else {
                throw SessionSnapshotUploadError.notPreviewable("snapshot_payload_unusable")
            }
            let metadata = try Self.decodeHydratableSessionMetadata(from: payload.rawSessionJSON)
            guard metadata.propertyID == propertyID,
                  metadata.sessionID == sessionID,
                  metadata.shots.count == payload.mediaManifest.count else {
                throw SessionSnapshotUploadError.notPreviewable("snapshot_metadata_target_mismatch")
            }

            let manifestIDs = Set(payload.mediaManifest.map(\.id))
            let remoteShots = metadata.shots
                .filter { manifestIDs.contains($0.shotID) }
                .filter { Self.trimmedNonEmpty($0.storageBucket) != nil && Self.trimmedNonEmpty($0.storagePath) != nil }
            var itemResults: [SessionSnapshotMediaRetrievalItemResult] = []
            itemResults.reserveCapacity(remoteShots.count)
            let recoveredDirectory = sessionSnapshotRecoveredMediaDirectoryURLForDiagnostics(
                propertyID: propertyID,
                sessionID: sessionID,
                snapshotID: snapshotID
            )

            for shot in remoteShots {
                guard let bucket = Self.trimmedNonEmpty(shot.storageBucket),
                      let path = Self.trimmedNonEmpty(shot.storagePath) else {
                    itemResults.append(SessionSnapshotMediaRetrievalItemResult(
                        id: shot.shotID,
                        status: .skippedMissingStorageMetadata,
                        checksumVerified: false,
                        recoveredLocalPathPresent: false,
                        failureReason: "missing_remote_storage_metadata"
                    ))
                    continue
                }
                guard let expectedChecksum = Self.trimmedNonEmpty(shot.checksumSHA256)?.lowercased() else {
                    itemResults.append(SessionSnapshotMediaRetrievalItemResult(
                        id: shot.shotID,
                        status: .skippedChecksumMissing,
                        checksumVerified: false,
                        recoveredLocalPathPresent: false,
                        failureReason: "checksum_unknown"
                    ))
                    continue
                }
                let targetURL = sessionSnapshotRecoveredMediaURL(
                    propertyID: propertyID,
                    sessionID: sessionID,
                    snapshotID: snapshotID,
                    shot: shot
                )
                if FileManager.default.fileExists(atPath: targetURL.path) {
                    itemResults.append(SessionSnapshotMediaRetrievalItemResult(
                        id: shot.shotID,
                        status: .skippedExisting,
                        checksumVerified: false,
                        recoveredLocalPathPresent: true,
                        failureReason: nil
                    ))
                    continue
                }

                do {
                    let data = try await downloadSessionSnapshotMediaObject(bucket: bucket, path: path)
                    guard sha256Hex(for: data) == expectedChecksum else {
                        itemResults.append(SessionSnapshotMediaRetrievalItemResult(
                            id: shot.shotID,
                            status: .rejectedChecksumMismatch,
                            checksumVerified: false,
                            recoveredLocalPathPresent: false,
                            failureReason: "checksum_mismatch"
                        ))
                        continue
                    }
                    try FileManager.default.createDirectory(at: recoveredDirectory, withIntermediateDirectories: true)
                    try data.write(to: targetURL, options: [.atomic])
                    itemResults.append(SessionSnapshotMediaRetrievalItemResult(
                        id: shot.shotID,
                        status: .downloaded,
                        checksumVerified: true,
                        recoveredLocalPathPresent: true,
                        failureReason: nil
                    ))
                } catch {
                    itemResults.append(SessionSnapshotMediaRetrievalItemResult(
                        id: shot.shotID,
                        status: .failed,
                        checksumVerified: false,
                        recoveredLocalPathPresent: false,
                        failureReason: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160)
                    ))
                }
            }

            let result = makeSessionSnapshotMediaRetrievalResult(
                checkedAt: checkedAt,
                allowed: true,
                blockedReason: nil,
                propertyID: propertyID,
                sessionID: sessionID,
                snapshotID: snapshotID,
                recoveredDirectory: recoveredDirectory,
                itemResults: itemResults
            )
            recordSessionSnapshotMediaRetrieval(result)
            return result
        } catch {
            let result = makeBlockedSessionSnapshotMediaRetrievalResult(
                checkedAt: checkedAt,
                diagnostics: diagnostics,
                reason: Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160) ?? "media_retrieval_failed"
            )
            recordSessionSnapshotMediaRetrieval(result)
            return result
        }
    }

    func sessionSnapshotRecoveredMediaDirectoryURLForDiagnostics(
        propertyID: UUID,
        sessionID: UUID,
        snapshotID: UUID
    ) -> URL {
        localStore
            .sessionFolderURL(propertyID: propertyID, sessionID: sessionID)
            .appendingPathComponent("RecoveredMedia", isDirectory: true)
            .appendingPathComponent("SnapshotMedia", isDirectory: true)
            .appendingPathComponent(snapshotID.uuidString.lowercased(), isDirectory: true)
    }

    private func sessionSnapshotRecoveredMediaURL(
        propertyID: UUID,
        sessionID: UUID,
        snapshotID: UUID,
        shot: ShotMetadata
    ) -> URL {
        let filename = sanitizedStorageFilename(shot.originalFilename, fallbackShotID: shot.shotID)
        return sessionSnapshotRecoveredMediaDirectoryURLForDiagnostics(
            propertyID: propertyID,
            sessionID: sessionID,
            snapshotID: snapshotID
        )
        .appendingPathComponent(filename, isDirectory: false)
    }

    private func makeBlockedSessionSnapshotMediaRetrievalResult(
        checkedAt: Date,
        diagnostics: SessionSnapshotRestoreDiagnosticsResult,
        reason: String
    ) -> SessionSnapshotMediaRetrievalResult {
        SessionSnapshotMediaRetrievalResult(
            retrievedAt: checkedAt,
            allowed: false,
            blockedReason: reason,
            propertyID: diagnostics.propertyID,
            sessionID: diagnostics.sessionID,
            snapshotID: diagnostics.snapshotID,
            attemptedCount: 0,
            downloadedCount: 0,
            checksumVerifiedCount: 0,
            skippedExistingCount: 0,
            failedCount: 0,
            recoveredLocalPathCount: 0,
            recoveredMediaDirectoryPathPresent: false,
            items: []
        )
    }

    private func makeSessionSnapshotMediaRetrievalResult(
        checkedAt: Date,
        allowed: Bool,
        blockedReason: String?,
        propertyID: UUID,
        sessionID: UUID,
        snapshotID: UUID,
        recoveredDirectory: URL,
        itemResults: [SessionSnapshotMediaRetrievalItemResult]
    ) -> SessionSnapshotMediaRetrievalResult {
        SessionSnapshotMediaRetrievalResult(
            retrievedAt: checkedAt,
            allowed: allowed,
            blockedReason: blockedReason,
            propertyID: propertyID,
            sessionID: sessionID,
            snapshotID: snapshotID,
            attemptedCount: itemResults.count,
            downloadedCount: itemResults.filter { $0.status == .downloaded }.count,
            checksumVerifiedCount: itemResults.filter(\.checksumVerified).count,
            skippedExistingCount: itemResults.filter { $0.status == .skippedExisting }.count,
            failedCount: itemResults.filter { item in
                item.status == .failed || item.status == .rejectedChecksumMismatch
            }.count,
            recoveredLocalPathCount: itemResults.filter(\.recoveredLocalPathPresent).count,
            recoveredMediaDirectoryPathPresent: FileManager.default.fileExists(atPath: recoveredDirectory.path),
            items: itemResults
        )
    }

    @discardableResult
    func validateSnapshotRecoveryCohort(checkedAt: Date = Date()) async -> SnapshotRecoveryCohortResult {
        let diagnostics = await validateLatestSessionSnapshotRestoreDiagnostics(checkedAt: checkedAt)
        let result = Self.makeSnapshotRecoveryCohortResult(
            from: diagnostics,
            checkedAt: checkedAt,
            hasOrgDriftHistory: sessionSnapshotHasOrgDriftHistory(for: diagnostics)
        )
        recordSnapshotRecoveryCohort(result)
        return result
    }

    private func fetchSessionSnapshotRows(
        snapshotID: UUID?,
        propertyID: UUID?,
        sessionID: UUID?
    ) async throws -> [SessionSnapshotUploadRow] {
        if let sessionSnapshotRowsFetchOverride {
            return try await sessionSnapshotRowsFetchOverride(snapshotID, propertyID, sessionID)
        }
        guard backendFeatureFlags.supabaseEnabled,
              let client = supabaseClient else {
            throw SessionSnapshotUploadError.missingSupabaseClient
        }

        var query = client
            .from("session_snapshots")
            .select("""
                id,
                org_id,
                property_id,
                session_id,
                snapshot_kind,
                snapshot_schema_version,
                session_metadata_schema_version,
                trigger,
                session_status,
                is_sealed,
                exported_at,
                first_delivered_at,
                re_export_expires_at,
                payload_storage_bucket,
                payload_storage_path,
                payload_byte_size,
                raw_session_json_sha256,
                snapshot_payload_sha256,
                manifest,
                shot_count,
                issue_count,
                guided_count,
                media_manifest_count,
                missing_local_originals_count,
                supabase_storage_metadata_count,
                created_by,
                updated_by,
                created_at
                """)
            .is("deleted_at", value: nil)

        if let snapshotID {
            query = query.eq("id", value: snapshotID.uuidString.lowercased())
        } else {
            if let propertyID {
                query = query.eq("property_id", value: propertyID.uuidString.lowercased())
            }
            if let sessionID {
                query = query.eq("session_id", value: sessionID.uuidString.lowercased())
            }
        }

        return try await query
            .order("created_at", ascending: false)
            .limit(5)
            .execute()
            .value as [SessionSnapshotUploadRow]
    }

    private func downloadSessionSnapshotPayload(bucket: String, path: String) async throws -> Data {
        if let sessionSnapshotStorageDownloadOverride {
            return try await sessionSnapshotStorageDownloadOverride(bucket, path)
        }
        guard backendFeatureFlags.supabaseEnabled,
              let client = supabaseClient else {
            throw SessionSnapshotUploadError.missingSupabaseClient
        }
        return try await client.storage.from(bucket).download(path: path)
    }

    private func downloadSessionSnapshotMediaObject(bucket: String, path: String) async throws -> Data {
        if let sessionSnapshotMediaDownloadOverride {
            return try await sessionSnapshotMediaDownloadOverride(bucket, path)
        }
        guard backendFeatureFlags.supabaseEnabled,
              let client = supabaseClient else {
            throw SessionSnapshotUploadError.missingSupabaseClient
        }
        return try await client.storage.from(bucket).download(path: path)
    }

    private struct SessionSnapshotRestoreLocalComparison {
        let sessionExists: Bool
        let status: String?
        let shotCount: Int?
        let issueCount: Int?
        let guidedCount: Int?
        let knownStateAt: Date?
    }

    private static func decodeSessionSnapshotPayload(_ data: Data?) -> SessionSnapshotPayloadForChecksum? {
        guard let data else { return nil }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try? decoder.decode(SessionSnapshotPayloadForChecksum.self, from: data)
    }

    private static func decodeHydratableSessionMetadata(from rawSessionJSON: String) throws -> SessionMetadata {
        guard let data = rawSessionJSON.data(using: .utf8) else {
            throw SessionSnapshotUploadError.notPreviewable("snapshot_raw_session_json_unreadable")
        }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try decoder.decode(SessionMetadata.self, from: data)
    }

    private func localSessionSnapshotRestoreComparison(
        propertyID: UUID,
        sessionID: UUID
    ) -> SessionSnapshotRestoreLocalComparison {
        let session = (try? localStore.fetchSessionsForCacheBuild(propertyID: propertyID))
            .flatMap { sessions in sessions.first { $0.id == sessionID } }
        guard let session else {
            return SessionSnapshotRestoreLocalComparison(
                sessionExists: false,
                status: nil,
                shotCount: nil,
                issueCount: nil,
                guidedCount: nil,
                knownStateAt: nil
            )
        }

        let metadata = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: sessionID)
        let knownDates = [
            session.startedAt,
            session.endedAt,
            session.exportedAt,
            session.firstDeliveredAt,
            session.reExportExpiresAt,
            metadata?.startedAt,
            metadata?.endedAt,
            metadata?.exportedAt,
            metadata?.firstDeliveredAt,
            metadata?.reExportExpiresAt
        ].compactMap { $0 }
        return SessionSnapshotRestoreLocalComparison(
            sessionExists: true,
            status: metadata?.status.rawValue ?? session.status.rawValue,
            shotCount: metadata?.shots.count,
            issueCount: metadata?.issues.count,
            guidedCount: metadata?.guidedShots.count,
            knownStateAt: knownDates.max()
        )
    }

    private static func sessionSnapshotRestoreOutcome(
        row: SessionSnapshotUploadRow,
        decodedPayload: SessionSnapshotPayloadForChecksum?,
        readback: SessionSnapshotReadbackResult,
        parentStatus: SessionSnapshotAuthPreflightRemoteParentStatus?,
        localComparison: SessionSnapshotRestoreLocalComparison
    ) -> (outcome: SessionSnapshotRestoreDiagnosticOutcome, reason: String?) {
        guard let decodedPayload else {
            return (.unableToVerify, "snapshot payload could not be decoded")
        }
        guard row.snapshotSchemaVersion == 1, decodedPayload.snapshotSchemaVersion == 1 else {
            return (.unsupportedSchema, "snapshot schema version unsupported")
        }
        guard readback.checksumVerified else {
            return (.checksumFailed, "snapshot payload checksum mismatch")
        }
        guard readback.byteSizeMatches else {
            return (.unableToVerify, "snapshot payload byte size mismatch")
        }
        guard readback.rowObjectConsistent else {
            return (.parentMismatch, "snapshot row/object consistency failed")
        }
        guard readback.countsValid else {
            return (.unableToVerify, "snapshot row/object counts mismatch")
        }
        guard let parentStatus,
              parentStatus.propertyExists,
              parentStatus.sessionExists,
              parentStatus.sessionPropertyIDMatches,
              parentStatus.orgIDsMatch,
              parentStatus.errorMessage == nil else {
            return (.parentMismatch, "remote parent property/session mismatch")
        }

        if localComparison.sessionExists,
           let localKnownStateAt = localComparison.knownStateAt,
           localKnownStateAt > decodedPayload.generatedAt {
            return (.localNewerConflict, "local session state is newer than snapshot")
        }

        if localComparison.sessionExists,
           let localShotCount = localComparison.shotCount,
           let localIssueCount = localComparison.issueCount,
           let localGuidedCount = localComparison.guidedCount,
           (localShotCount > decodedPayload.shotCount ||
            localIssueCount > decodedPayload.issueCount ||
            localGuidedCount > decodedPayload.guidedCount) {
            return (.staleSnapshot, "snapshot counts are behind local metadata")
        }

        return (.restorableMetadataCandidate, nil)
    }

    private func makeSessionSnapshotRestoreDiagnosticsResult(
        row: SessionSnapshotUploadRow,
        payloadData: Data?,
        checkedAt: Date,
        parentStatus: SessionSnapshotAuthPreflightRemoteParentStatus?,
        localComparison: SessionSnapshotRestoreLocalComparison?,
        outcome: SessionSnapshotRestoreDiagnosticOutcome,
        failureReason: String?
    ) -> SessionSnapshotRestoreDiagnosticsResult {
        let decodedPayload = Self.decodeSessionSnapshotPayload(payloadData)
        let readback = Self.makeSessionSnapshotReadbackResult(
            row: row,
            payloadData: payloadData,
            checkedAt: checkedAt,
            failureReason: failureReason
        )
        let parentVerified = parentStatus?.propertyExists == true &&
            parentStatus?.sessionExists == true &&
            parentStatus?.sessionPropertyIDMatches == true &&
            parentStatus?.orgIDsMatch == true &&
            parentStatus?.errorMessage == nil
        let freshness = Self.sessionSnapshotRestoreFreshness(
            snapshotGeneratedAt: decodedPayload?.generatedAt,
            localKnownStateAt: localComparison?.knownStateAt
        )
        let mediaRecoveryDiagnostics = makeSessionSnapshotMediaRecoveryDiagnostics(
            decodedPayload: decodedPayload,
            rowSnapshotSchemaVersion: row.snapshotSchemaVersion,
            propertyID: row.propertyID,
            sessionID: row.sessionID,
            checkedAt: checkedAt
        )
        return SessionSnapshotRestoreDiagnosticsResult(
            checkedAt: checkedAt,
            propertyID: row.propertyID,
            sessionID: row.sessionID,
            snapshotID: row.id,
            result: outcome,
            failureReason: Self.diagnosticsPreviewText(failureReason, maxLength: 160),
            rowFound: true,
            objectReadable: payloadData != nil,
            checksumVerified: readback.checksumVerified,
            byteSizeMatches: readback.byteSizeMatches,
            rowObjectVerified: readback.rowObjectConsistent,
            parentRemoteVerified: parentVerified,
            snapshotSchemaVersion: decodedPayload?.snapshotSchemaVersion == row.snapshotSchemaVersion ? decodedPayload?.snapshotSchemaVersion : row.snapshotSchemaVersion,
            snapshotCreatedAt: row.createdAt,
            snapshotGeneratedAt: decodedPayload?.generatedAt,
            localSessionExists: localComparison?.sessionExists ?? false,
            localSessionStatus: localComparison?.status,
            localShotCount: localComparison?.shotCount,
            localIssueCount: localComparison?.issueCount,
            localGuidedCount: localComparison?.guidedCount,
            snapshotShotCount: decodedPayload?.shotCount ?? row.shotCount,
            snapshotIssueCount: decodedPayload?.issueCount ?? row.issueCount,
            snapshotGuidedCount: decodedPayload?.guidedCount ?? row.guidedCount,
            snapshotMediaManifestCount: decodedPayload?.mediaManifestCount ?? row.mediaManifestCount,
            snapshotMissingLocalOriginalsCount: decodedPayload?.missingLocalOriginalsCount ?? row.missingLocalOriginalsCount,
            snapshotSupabaseStorageMetadataCount: decodedPayload?.supabaseStorageMetadataCount ?? row.supabaseStorageMetadataCount,
            freshness: freshness,
            mediaRecoveryDiagnostics: mediaRecoveryDiagnostics
        )
    }

    private func makeSessionSnapshotMediaRecoveryDiagnostics(
        decodedPayload: SessionSnapshotPayloadForChecksum?,
        rowSnapshotSchemaVersion: Int,
        propertyID: UUID,
        sessionID: UUID,
        checkedAt: Date
    ) -> SessionSnapshotMediaRecoveryDiagnostics {
        guard let decodedPayload else {
            return .notChecked
        }
        guard rowSnapshotSchemaVersion == 1,
              decodedPayload.snapshotSchemaVersion == 1,
              decodedPayload.mediaManifestCount == decodedPayload.mediaManifest.count,
              let metadata = try? Self.decodeHydratableSessionMetadata(from: decodedPayload.rawSessionJSON),
              metadata.propertyID == propertyID,
              metadata.sessionID == sessionID,
              metadata.shots.count == decodedPayload.mediaManifest.count else {
            return Self.makeUnsupportedSessionSnapshotMediaRecoveryDiagnostics(
                checkedAt: checkedAt,
                manifestCount: max(decodedPayload.mediaManifestCount, decodedPayload.mediaManifest.count)
            )
        }

        let shotsByID = Dictionary(uniqueKeysWithValues: metadata.shots.map { ($0.shotID, $0) })
        guard decodedPayload.mediaManifest.allSatisfy({ shotsByID[$0.id] != nil }) else {
            return Self.makeUnsupportedSessionSnapshotMediaRecoveryDiagnostics(
                checkedAt: checkedAt,
                manifestCount: decodedPayload.mediaManifest.count
            )
        }

        let items = decodedPayload.mediaManifest.map { manifestItem -> SessionSnapshotMediaRecoveryItemDiagnostic in
            let shot = shotsByID[manifestItem.id]
            let localReferencePresent = Self.trimmedNonEmpty(shot?.originalRelativePath) != nil &&
                manifestItem.originalRelativePathPresent
            let localURL = shot.flatMap { shot in
                localStore.resolveSessionRelativeFileURL(
                    propertyID: propertyID,
                    sessionID: sessionID,
                    relativePath: shot.originalRelativePath
                )
            }
            let localFilePresent = localURL.map { FileManager.default.fileExists(atPath: $0.path) } ?? false
            let remoteStorageMetadataPresent = Self.trimmedNonEmpty(shot?.storageBucket) != nil &&
                Self.trimmedNonEmpty(shot?.storagePath) != nil &&
                manifestItem.storageBucketPresent &&
                manifestItem.storagePathPresent
            let checksumPresent = Self.trimmedNonEmpty(shot?.checksumSHA256) != nil && manifestItem.checksumPresent
            let expectedByteSize = shot?.byteSize ?? shot?.originalByteSize ?? manifestItem.storageByteSize ?? manifestItem.originalByteSize
            let actualByteSize = localURL.flatMap { Self.fileSizeBytesIfPresent(at: $0) }
            let checksumVerified = false
            let state: SessionSnapshotMediaRecoveryState
            if checksumPresent,
               let expectedByteSize,
               let actualByteSize,
               actualByteSize != expectedByteSize {
                state = .checksumMismatch
            } else if remoteStorageMetadataPresent {
                state = .recoverableFromSupabaseStorage
            } else if localFilePresent {
                state = .recoverableFromLocalCache
            } else if !localReferencePresent && !remoteStorageMetadataPresent {
                state = .missingBoth
            } else if !remoteStorageMetadataPresent && !localFilePresent {
                state = .missingBoth
            } else if !remoteStorageMetadataPresent {
                state = .missingRemoteStorageMetadata
            } else if !localFilePresent {
                state = .missingLocalFile
            } else if !checksumPresent {
                state = .checksumUnknown
            } else {
                state = .notChecked
            }
            return SessionSnapshotMediaRecoveryItemDiagnostic(
                id: manifestItem.id,
                state: state,
                localReferencePresent: localReferencePresent,
                localFilePresent: localFilePresent,
                remoteStorageMetadataPresent: remoteStorageMetadataPresent,
                checksumPresent: checksumPresent,
                checksumVerified: checksumVerified
            )
        }

        return Self.makeSessionSnapshotMediaRecoveryDiagnostics(checkedAt: checkedAt, items: items)
    }

    private nonisolated static func makeUnsupportedSessionSnapshotMediaRecoveryDiagnostics(
        checkedAt: Date,
        manifestCount: Int
    ) -> SessionSnapshotMediaRecoveryDiagnostics {
        let stateCounts: [SessionSnapshotMediaRecoveryState: Int] = manifestCount > 0
            ? [.unsupportedMediaManifest: manifestCount]
            : [.unsupportedMediaManifest: 1]
        return SessionSnapshotMediaRecoveryDiagnostics(
            checkedAt: checkedAt,
            readiness: SessionSnapshotMediaRecoveryState.unsupportedMediaManifest.rawValue,
            planningState: .unrecoverable,
            sourcePriority: SessionSnapshotMediaRecoverySource.defaultPriority,
            retrievalPolicy: .guardrailsOnly,
            manifestSupported: false,
            manifestCount: manifestCount,
            originalsCount: 0,
            localFilesPresentCount: 0,
            remoteStorageMetadataPresentCount: 0,
            recoverableRemoteCount: 0,
            recoverableLocalCount: 0,
            missingCount: manifestCount,
            missingRemoteStorageMetadataCount: 0,
            missingLocalFileCount: 0,
            checksumVerifiedCount: 0,
            checksumUnknownCount: 0,
            checksumMismatchCount: 0,
            unsupportedCount: stateCounts[.unsupportedMediaManifest] ?? 0,
            notCheckedCount: 0,
            stateCounts: stateCounts,
            items: []
        )
    }

    private nonisolated static func makeSessionSnapshotMediaRecoveryDiagnostics(
        checkedAt: Date,
        items: [SessionSnapshotMediaRecoveryItemDiagnostic]
    ) -> SessionSnapshotMediaRecoveryDiagnostics {
        var stateCounts: [SessionSnapshotMediaRecoveryState: Int] = [:]
        for item in items {
            stateCounts[item.state, default: 0] += 1
        }
        let remoteCount = items.filter(\.remoteStorageMetadataPresent).count
        let localCount = items.filter(\.localFilePresent).count
        let checksumMismatchCount = stateCounts[.checksumMismatch] ?? 0
        let unsupportedCount = stateCounts[.unsupportedMediaManifest] ?? 0
        let notCheckedCount = stateCounts[.notChecked] ?? 0
        let missingCount = items.filter { !$0.remoteStorageMetadataPresent && !$0.localFilePresent }.count
        let planningState = sessionSnapshotMediaRecoveryPlanningState(
            manifestCount: items.count,
            localFilesPresentCount: localCount,
            remoteStorageMetadataPresentCount: remoteCount,
            missingCount: missingCount,
            unsupportedCount: unsupportedCount,
            checksumMismatchCount: checksumMismatchCount
        )
        let readiness: String
        if unsupportedCount > 0 {
            readiness = SessionSnapshotMediaRecoveryState.unsupportedMediaManifest.rawValue
        } else if checksumMismatchCount > 0 {
            readiness = SessionSnapshotMediaRecoveryState.checksumMismatch.rawValue
        } else if missingCount > 0 {
            readiness = "partial"
        } else if items.isEmpty {
            readiness = "no_media_manifest"
        } else {
            readiness = "ready"
        }
        return SessionSnapshotMediaRecoveryDiagnostics(
            checkedAt: checkedAt,
            readiness: readiness,
            planningState: planningState,
            sourcePriority: SessionSnapshotMediaRecoverySource.defaultPriority,
            retrievalPolicy: .guardrailsOnly,
            manifestSupported: true,
            manifestCount: items.count,
            originalsCount: items.filter(\.localReferencePresent).count,
            localFilesPresentCount: localCount,
            remoteStorageMetadataPresentCount: remoteCount,
            recoverableRemoteCount: remoteCount,
            recoverableLocalCount: localCount,
            missingCount: missingCount,
            missingRemoteStorageMetadataCount: items.filter { !$0.remoteStorageMetadataPresent }.count,
            missingLocalFileCount: items.filter { $0.localReferencePresent && !$0.localFilePresent }.count,
            checksumVerifiedCount: items.filter(\.checksumVerified).count,
            checksumUnknownCount: items.filter { !$0.checksumPresent }.count,
            checksumMismatchCount: checksumMismatchCount,
            unsupportedCount: unsupportedCount,
            notCheckedCount: notCheckedCount,
            stateCounts: stateCounts,
            items: items
        )
    }

    nonisolated static func sessionSnapshotMediaRecoveryPlanningState(
        manifestCount: Int,
        localFilesPresentCount: Int,
        remoteStorageMetadataPresentCount: Int,
        missingCount: Int,
        unsupportedCount: Int,
        checksumMismatchCount: Int
    ) -> SessionSnapshotMediaRecoveryPlanningState {
        guard manifestCount > 0,
              unsupportedCount == 0,
              checksumMismatchCount == 0 else {
            return .unrecoverable
        }
        let recoverableCount = max(localFilesPresentCount, remoteStorageMetadataPresentCount)
        if recoverableCount == 0 {
            return .metadataOnly
        }
        if missingCount > 0 {
            return .partiallyRecoverable
        }
        if localFilesPresentCount > 0, remoteStorageMetadataPresentCount == 0 {
            return .localOnly
        }
        if remoteStorageMetadataPresentCount > 0, localFilesPresentCount == 0 {
            return .remoteOnly
        }
        return .fullyRecoverable
    }

    nonisolated static func sessionSnapshotMediaRetrievalGuardrailViolations(
        requestedBatchSize: Int,
        isManual: Bool,
        isAllowlisted: Bool,
        isProductionWide: Bool,
        storageQuotaChecked: Bool,
        networkApproved: Bool,
        batteryApproved: Bool,
        checksumValidationPlanned: Bool,
        duplicatePreventionPlanned: Bool
    ) -> [String] {
        var violations: [String] = []
        let policy = SessionSnapshotMediaRetrievalPolicyDiagnostics.guardrailsOnly
        if !isManual {
            violations.append("manual_only_required")
        }
        if isProductionWide {
            violations.append("production_wide_retrieval_blocked")
        }
        if !isAllowlisted {
            violations.append("allowlisted_test_only_required")
        }
        if requestedBatchSize > policy.maxBatchSize {
            violations.append("max_batch_size_exceeded")
        }
        if !storageQuotaChecked {
            violations.append("storage_quota_check_required")
        }
        if !networkApproved {
            violations.append("network_requirement_not_met")
        }
        if !batteryApproved {
            violations.append("battery_requirement_not_met")
        }
        if !checksumValidationPlanned {
            violations.append("checksum_validation_required")
        }
        if !duplicatePreventionPlanned {
            violations.append("duplicate_prevention_required")
        }
        return violations
    }

    private nonisolated static func fileSizeBytesIfPresent(at url: URL) -> Int? {
        guard let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
              let size = attributes[.size] as? NSNumber else {
            return nil
        }
        return size.intValue
    }

    private static func sessionSnapshotRestoreFreshness(
        snapshotGeneratedAt: Date?,
        localKnownStateAt: Date?
    ) -> String {
        guard let snapshotGeneratedAt, let localKnownStateAt else { return "unknown" }
        if snapshotGeneratedAt == localKnownStateAt { return "equal" }
        return snapshotGeneratedAt > localKnownStateAt ? "snapshot_newer" : "local_newer"
    }

    static func makeSnapshotRecoveryCohortResult(
        from diagnostics: SessionSnapshotRestoreDiagnosticsResult,
        checkedAt: Date = Date(),
        hasOrgDriftHistory: Bool = false
    ) -> SnapshotRecoveryCohortResult {
        let snapshotDate = diagnostics.snapshotGeneratedAt ?? diagnostics.snapshotCreatedAt
        let ageSeconds = snapshotDate.map { max(0, checkedAt.timeIntervalSince($0)) }
        let isStaleByAge = ageSeconds.map { $0 > 7 * 24 * 60 * 60 } ?? false
        let highVolumeCount = max(
            diagnostics.snapshotShotCount ?? diagnostics.localShotCount ?? 0,
            diagnostics.snapshotIssueCount ?? diagnostics.localIssueCount ?? 0,
            diagnostics.snapshotGuidedCount ?? diagnostics.localGuidedCount ?? 0
        )
        let highVolume = highVolumeCount >= 100
        let noMediaManifest = diagnostics.snapshotMediaManifestCount == 0

        let category: SnapshotRecoveryCohortCategory
        switch diagnostics.result {
        case .noSnapshotFound:
            category = .noSnapshotFound
        case .checksumFailed, .objectMissing, .parentMismatch, .unsupportedSchema, .unableToVerify:
            category = .blockedVerification
        case .localNewerConflict:
            category = .localNewerConflict
        case .staleSnapshot:
            category = .staleSnapshot
        case .restorableMetadataCandidate:
            if !diagnostics.localSessionExists {
                category = .missingLocalMetadata
            } else if isStaleByAge {
                category = .staleSnapshot
            } else if hasOrgDriftHistory {
                category = .orgDriftHistory
            } else if highVolume {
                category = .highVolumeMetadata
            } else if noMediaManifest {
                category = .noMediaManifest
            } else if diagnostics.localSessionStatus == Session.Status.draft.rawValue {
                category = .draftSession
            } else if diagnostics.localSessionStatus == Session.Status.completed.rawValue {
                category = .completedSealedSession
            } else {
                category = .unknown
            }
        }

        let readiness: SnapshotRecoveryReadiness
        let risk: SnapshotRestoreRiskLevel
        let reason: String
        switch diagnostics.result {
        case .restorableMetadataCandidate:
            if isStaleByAge {
                readiness = .needsReview
                risk = .medium
                reason = "snapshot_age_review_required"
            } else {
                readiness = .readyForManualHydration
                risk = category == .missingLocalMetadata ? .low : .medium
                reason = "verified_snapshot_manual_hydration_candidate"
            }
        case .localNewerConflict:
            readiness = .blocked
            risk = .blocking
            reason = "local_newer_conflict"
        case .staleSnapshot:
            readiness = .needsReview
            risk = .high
            reason = "stale_snapshot"
        case .noSnapshotFound:
            readiness = .blocked
            risk = .blocking
            reason = "no_snapshot_found"
        case .checksumFailed:
            readiness = .blocked
            risk = .blocking
            reason = "checksum_failed"
        case .objectMissing:
            readiness = .blocked
            risk = .blocking
            reason = "object_missing"
        case .parentMismatch:
            readiness = .blocked
            risk = .blocking
            reason = "parent_mismatch"
        case .unsupportedSchema:
            readiness = .blocked
            risk = .blocking
            reason = "unsupported_schema"
        case .unableToVerify:
            readiness = .blocked
            risk = .unknown
            reason = "unable_to_verify"
        }

        return SnapshotRecoveryCohortResult(
            checkedAt: checkedAt,
            propertyID: diagnostics.propertyID,
            sessionID: diagnostics.sessionID,
            snapshotID: diagnostics.snapshotID,
            category: category,
            readiness: readiness,
            riskLevel: risk,
            snapshotFreshnessAgeSeconds: ageSeconds,
            hydrationEligibilityReason: reason,
            latestSnapshotCovered: diagnostics.rowFound && diagnostics.objectReadable,
            restoreDiagnosticsResult: diagnostics.result.rawValue
        )
    }

    private func sessionSnapshotHasOrgDriftHistory(for diagnostics: SessionSnapshotRestoreDiagnosticsResult) -> Bool {
        let uploadDiagnostics = localDiagnostics.sessionSnapshotUpload
        if let sessionID = diagnostics.sessionID,
           uploadDiagnostics.lastLocalOrgRepairSessionID == sessionID {
            return true
        }
        return uploadDiagnostics.lastLocalOrgDriftRepairAt != nil &&
            uploadDiagnostics.lastLocalOrgDriftRepairSessionCount > 0
    }

    static func makeSessionSnapshotReadbackResult(
        row: SessionSnapshotUploadRow?,
        payloadData: Data?,
        checkedAt: Date = Date(),
        failureReason: String?
    ) -> SessionSnapshotReadbackResult {
        let payloadReadable = payloadData != nil
        let computedChecksum = payloadData.map { sessionSnapshotSHA256Hex(for: $0) }
        let decodedPayload = payloadData.flatMap { data -> SessionSnapshotPayloadForChecksum? in
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            return try? decoder.decode(SessionSnapshotPayloadForChecksum.self, from: data)
        }
        let checksumVerified = row.flatMap { row in
            computedChecksum.map { $0 == row.snapshotPayloadSHA256.lowercased() }
        } ?? false
        let byteSizeMatches = row.flatMap { row in
            payloadData.map { $0.count == row.payloadByteSize }
        } ?? false
        let countsValid: Bool = {
            guard let row else { return false }
            guard row.shotCount >= 0,
                  row.issueCount >= 0,
                  row.guidedCount >= 0,
                  row.mediaManifestCount >= 0,
                  row.missingLocalOriginalsCount >= 0,
                  row.supabaseStorageMetadataCount >= 0 else {
                return false
            }
            guard let decodedPayload else { return payloadData == nil ? true : false }
            return decodedPayload.shotCount == row.shotCount &&
                decodedPayload.issueCount == row.issueCount &&
                decodedPayload.guidedCount == row.guidedCount &&
                decodedPayload.mediaManifestCount == row.mediaManifestCount &&
                decodedPayload.missingLocalOriginalsCount == row.missingLocalOriginalsCount &&
                decodedPayload.supabaseStorageMetadataCount == row.supabaseStorageMetadataCount
        }()
        let rowObjectConsistent: Bool = {
            guard let row else { return false }
            guard let decodedPayload else { return payloadData == nil ? false : false }
            return decodedPayload.orgID == row.orgID &&
                decodedPayload.propertyID == row.propertyID &&
                decodedPayload.sessionID == row.sessionID &&
                decodedPayload.status.rawValue == row.sessionStatus &&
                decodedPayload.trigger == row.trigger &&
                row.payloadStorageBucket == "scoutcapture-session-snapshots" &&
                row.payloadStoragePath == sessionSnapshotStoragePath(
                    orgID: row.orgID,
                    propertyID: row.propertyID,
                    sessionID: row.sessionID,
                    snapshotKind: SessionSnapshotKind(rawValue: row.snapshotKind) ?? .manual,
                    snapshotID: row.id
                )
        }()

        return SessionSnapshotReadbackResult(
            checkedAt: checkedAt,
            snapshotID: row?.id,
            propertyID: row?.propertyID ?? decodedPayload?.propertyID,
            sessionID: row?.sessionID ?? decodedPayload?.sessionID,
            storagePathPresent: trimmedNonEmpty(row?.payloadStoragePath) != nil,
            rowFound: row != nil,
            payloadReadable: payloadReadable,
            checksumVerified: checksumVerified,
            byteSizeMatches: byteSizeMatches,
            countsValid: countsValid,
            rowObjectConsistent: rowObjectConsistent,
            payloadByteSize: payloadData?.count,
            snapshotCreatedAt: row?.createdAt,
            failureReason: diagnosticsPreviewText(failureReason, maxLength: 160)
        )
    }

    private nonisolated static func sessionSnapshotUploadRowSort(_ lhs: SessionSnapshotUploadRow, _ rhs: SessionSnapshotUploadRow) -> Bool {
        switch (lhs.createdAt, rhs.createdAt) {
        case let (left?, right?) where left != right:
            return left > right
        case (_?, nil):
            return true
        case (nil, _?):
            return false
        default:
            return lhs.id.uuidString < rhs.id.uuidString
        }
    }

