    private static func makeSessionSnapshotMediaManifestItem(
        for shot: ShotMetadata,
        propertyID: UUID,
        sessionID: UUID,
        localStore: LocalStore
    ) -> SessionSnapshotMediaManifestItem {
        let relativePath = trimmedNonEmpty(shot.originalRelativePath)
        let localOriginalExists: Bool
        if let relativePath,
           let fileURL = localStore.resolveSessionRelativeFileURL(
            propertyID: propertyID,
            sessionID: sessionID,
            relativePath: relativePath
           ) {
            localOriginalExists = FileManager.default.fileExists(atPath: fileURL.path)
        } else {
            localOriginalExists = false
        }
        return SessionSnapshotMediaManifestItem(
            id: shot.shotID,
            originalFilenamePreview: diagnosticsPreviewText(shot.originalFilename, maxLength: 80),
            originalRelativePathPresent: relativePath != nil,
            originalByteSize: shot.originalByteSize,
            localOriginalExists: localOriginalExists,
            storageBucketPresent: trimmedNonEmpty(shot.storageBucket) != nil,
            storagePathPresent: trimmedNonEmpty(shot.storagePath) != nil,
            checksumPresent: trimmedNonEmpty(shot.checksumSHA256) != nil,
            storageByteSize: shot.byteSize
        )
    }

    private nonisolated static func sessionSnapshotPreviewReason(for error: Error) -> String {
        guard let error = error as? SessionSnapshotPreviewError else {
            return "session_snapshot_preview_failed"
        }
        switch error {
        case .sessionJSONMissingOrUnreadable:
            return "session_json_missing_or_unreadable"
        case .sessionJSONIDMismatch:
            return "session_json_id_mismatch"
        case .checksumGenerationFailed:
            return "checksum_generation_failed"
        }
    }

    private nonisolated static func sessionSnapshotSHA256Hex(for data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    private func makeCompletenessGatesReport(inspectedAt: Date = Date()) -> CompletenessGatesReport {
        let properties = (try? localStore.fetchProperties()) ?? []
        let duplicateShotSessionIDs = completenessDuplicateShotSessionIDs(properties: properties)
        var propertyStates: [CompletenessGateState] = []
        var sessionStates: [CompletenessGateState] = []
        var shotStates: [CompletenessGateState] = []
        var issueStates: [CompletenessGateState] = []
        var guidedStates: [CompletenessGateState] = []
        var mediaStates: [CompletenessGateState] = []
        var freshnessStates: [CompletenessFreshnessState] = []
        var diagnosticRows: [CompletenessDiagnosticRow] = []
        var exportCompleteSessions = 0
        var notExportCompleteSessions = 0

        for property in properties {
            let propertyFreshness = completenessFreshness(for: property.id)
            freshnessStates.append(propertyFreshness)
            let propertyState = Self.completenessStateForLocalProperty(property)
            propertyStates.append(propertyState)
            if property.deletedAt != nil {
                diagnosticRows.append(Self.completenessRow(
                    entityType: "property",
                    entityID: property.id,
                    propertyID: property.id,
                    state: propertyState,
                    freshness: propertyFreshness,
                    reason: "property_deleted",
                    context: [:]
                ))
            } else if property.isArchived {
                diagnosticRows.append(Self.completenessRow(
                    entityType: "property",
                    entityID: property.id,
                    propertyID: property.id,
                    state: propertyState,
                    freshness: propertyFreshness,
                    reason: "property_archived",
                    context: [:]
                ))
            } else if propertyState != .metadataComplete {
                diagnosticRows.append(Self.completenessRow(
                    entityType: "property",
                    entityID: property.id,
                    propertyID: property.id,
                    state: propertyState,
                    freshness: propertyFreshness,
                    reason: "property_minimum_metadata_missing",
                    context: [:]
                ))
            }

            let sessions = (try? localStore.fetchSessionsForCacheBuild(propertyID: property.id)) ?? []
            let localSessionIDs = Set(sessions.map(\.id))
            let guidedRows = (try? localStore.fetchGuidedShots(propertyID: property.id)) ?? []
            for guided in guidedRows {
                let guidedEvaluation = Self.evaluateGuidedCompleteness(guided)
                guidedStates.append(guidedEvaluation.state)
                if guidedEvaluation.diagnosticOnly || guidedEvaluation.state != .metadataComplete {
                    diagnosticRows.append(Self.completenessRow(
                        entityType: "guided",
                        entityID: guided.id,
                        propertyID: property.id,
                        sessionID: guided.retiredInSessionID ?? guided.skipSessionID,
                        state: guidedEvaluation.state,
                        freshness: propertyFreshness,
                        reason: guidedEvaluation.reason,
                        context: guidedEvaluation.context
                    ))
                }
            }

            for session in sessions {
                let sessionContext = Self.completenessSessionContext(for: session, inspectedAt: inspectedAt)
                if session.deletedAt != nil {
                    sessionStates.append(.localOnly)
                    freshnessStates.append(propertyFreshness)
                    notExportCompleteSessions += 1
                    diagnosticRows.append(Self.completenessRow(
                        entityType: "session",
                        entityID: session.id,
                        propertyID: property.id,
                        sessionID: session.id,
                        state: .localOnly,
                        freshness: propertyFreshness,
                        reason: "session_deleted",
                        context: sessionContext
                    ))
                    continue
                }

                let sessionURL = localStore.sessionJSONURL(propertyID: property.id, sessionID: session.id)
                let rawMetadata: SessionMetadata? = {
                    guard FileManager.default.fileExists(atPath: sessionURL.path),
                          let data = try? Data(contentsOf: sessionURL) else {
                        return nil
                    }
                    let decoder = JSONDecoder()
                    decoder.dateDecodingStrategy = .iso8601
                    return try? decoder.decode(SessionMetadata.self, from: data)
                }()
                guard let rawMetadata,
                      let metadata = try? localStore.loadSessionMetadata(propertyID: property.id, sessionID: session.id) else {
                    sessionStates.append(.localOnly)
                    freshnessStates.append(propertyFreshness)
                    notExportCompleteSessions += 1
                    diagnosticRows.append(Self.completenessRow(
                        entityType: "session",
                        entityID: session.id,
                        propertyID: property.id,
                        sessionID: session.id,
                        state: .localOnly,
                        freshness: propertyFreshness,
                        reason: "session_json_missing_or_unreadable",
                        context: sessionContext
                    ))
                    continue
                }

                let sessionMismatch = rawMetadata.propertyID != property.id || rawMetadata.sessionID != session.id
                let sessionFreshness: CompletenessFreshnessState = sessionMismatch ? .needsReview : propertyFreshness
                freshnessStates.append(sessionFreshness)
                if sessionMismatch {
                    sessionStates.append(.localOnly)
                    notExportCompleteSessions += 1
                    diagnosticRows.append(Self.completenessRow(
                        entityType: "session",
                        entityID: session.id,
                        propertyID: property.id,
                        sessionID: session.id,
                        state: .localOnly,
                        freshness: .needsReview,
                        reason: "session_json_id_mismatch",
                        context: sessionContext
                    ))
                    continue
                }

                var sessionExportBlockers: [String] = []
                var exportValidationMetadata = metadata
                exportValidationMetadata.shots = metadata.shots.filter(\.shouldAppearInDefaultExports)
                let validationReport = localStore.validateExport(
                    exportValidationMetadata,
                    phase: "completeness_diagnostics"
                )
                if !validationReport.passed {
                    sessionExportBlockers.append("export_validation_failed")
                }
                if session.status != .completed || !session.isSealed {
                    sessionExportBlockers.append("session_not_completed_and_sealed")
                }

                let exportShotIDs = Set(metadata.shots.filter(\.shouldAppearInDefaultExports).map(\.shotID))
                var allDefaultShotMediaComplete = true
                var allDefaultShotMetadataComplete = true
                for shot in metadata.shots {
                    let shotEvaluation = Self.evaluateShotCompleteness(
                        shot,
                        session: session,
                        propertyID: property.id,
                        sessionID: session.id,
                        inspectedAt: inspectedAt,
                        duplicateShotIDGroupSize: duplicateShotSessionIDs[shot.shotID]?.count ?? 1,
                        duplicateShotIDAcrossSessions: (duplicateShotSessionIDs[shot.shotID]?.count ?? 1) > 1,
                        localStore: localStore
                    )
                    shotStates.append(shotEvaluation.state)
                    freshnessStates.append(shotEvaluation.freshness)
                    if shot.shouldAppearInDefaultExports {
                        allDefaultShotMediaComplete = allDefaultShotMediaComplete && shotEvaluation.mediaComplete
                        allDefaultShotMetadataComplete = allDefaultShotMetadataComplete && shotEvaluation.metadataComplete
                    }
                    if shotEvaluation.diagnosticOnly || !shotEvaluation.metadataComplete || (shot.shouldAppearInDefaultExports && !shotEvaluation.mediaComplete) {
                        diagnosticRows.append(Self.completenessRow(
                            entityType: "shot",
                            entityID: shot.shotID,
                            propertyID: property.id,
                            sessionID: session.id,
                            shotID: shot.shotID,
                            state: shotEvaluation.state,
                            freshness: shotEvaluation.freshness,
                            reason: shotEvaluation.reason,
                            context: Self.mergedCompletenessContext(
                                sessionContext,
                                shotEvaluation.context
                            )
                        ))
                    }
                    if shot.shouldAppearInDefaultExports {
                        mediaStates.append(shotEvaluation.mediaComplete ? .mediaComplete : .metadataComplete)
                    }
                }
                if !allDefaultShotMetadataComplete {
                    sessionExportBlockers.append("active_export_shot_metadata_incomplete")
                }
                if !allDefaultShotMediaComplete {
                    sessionExportBlockers.append("active_export_shot_media_incomplete")
                }

                var allIssuesComplete = true
                var issueHistoryExportBlocker = false
                let allSessionShotIDs = Set(metadata.shots.map(\.shotID))
                for issue in metadata.issues {
                    let issueEvaluation = Self.evaluateIssueCompleteness(
                        issue,
                        sessionID: session.id,
                        localSessionIDs: localSessionIDs,
                        allSessionShotIDs: allSessionShotIDs,
                        exportedShotIDs: exportShotIDs
                    )
                    issueStates.append(issueEvaluation.state)
                    freshnessStates.append(issueEvaluation.freshness)
                    allIssuesComplete = allIssuesComplete && issueEvaluation.metadataComplete
                    issueHistoryExportBlocker = issueHistoryExportBlocker || issueEvaluation.exportBlocked
                    if issueEvaluation.diagnosticOnly || !issueEvaluation.metadataComplete || issueEvaluation.exportBlocked {
                        diagnosticRows.append(Self.completenessRow(
                            entityType: "issue",
                            entityID: issue.issueID,
                            propertyID: property.id,
                            sessionID: session.id,
                            state: issueEvaluation.state,
                            freshness: issueEvaluation.freshness,
                            reason: issueEvaluation.reason,
                            context: Self.mergedCompletenessContext(
                                sessionContext,
                                issueEvaluation.context
                            )
                        ))
                    }
                }
                if issueHistoryExportBlocker {
                    sessionExportBlockers.append("issue_history_orphan_reference")
                }

                let sessionGuidedRows = metadata.guidedShots.isEmpty ? guidedRows : metadata.guidedShots
                var allGuidedComplete = true
                for guided in sessionGuidedRows {
                    let guidedEvaluation = Self.evaluateGuidedCompleteness(guided)
                    allGuidedComplete = allGuidedComplete && guidedEvaluation.metadataComplete
                    if guidedEvaluation.state == .metadataComplete, !guidedRows.contains(where: { $0.id == guided.id }) {
                        guidedStates.append(guidedEvaluation.state)
                    }
                    if guidedEvaluation.diagnosticOnly || !guidedEvaluation.metadataComplete {
                        diagnosticRows.append(Self.completenessRow(
                            entityType: "guided",
                            entityID: guided.id,
                            propertyID: property.id,
                            sessionID: guided.retiredInSessionID ?? guided.skipSessionID ?? session.id,
                            state: guidedEvaluation.state,
                            freshness: propertyFreshness,
                            reason: guidedEvaluation.reason,
                            context: Self.mergedCompletenessContext(
                                sessionContext,
                                guidedEvaluation.context
                            )
                        ))
                    }
                }
                if !allGuidedComplete {
                    sessionExportBlockers.append("guided_metadata_incomplete")
                }

                let sessionMetadataComplete = allDefaultShotMetadataComplete && allIssuesComplete && allGuidedComplete
                let sessionMediaComplete = sessionMetadataComplete && allDefaultShotMediaComplete
                let sessionExportComplete = sessionMediaComplete && sessionExportBlockers.isEmpty
                let sessionState: CompletenessGateState
                if sessionExportComplete {
                    sessionState = .exportComplete
                    exportCompleteSessions += 1
                } else {
                    notExportCompleteSessions += 1
                    if sessionMediaComplete {
                        sessionState = .mediaComplete
                    } else if sessionMetadataComplete {
                        sessionState = .metadataComplete
                    } else {
                        sessionState = .localOnly
                    }
                    diagnosticRows.append(Self.completenessRow(
                        entityType: "session",
                        entityID: session.id,
                        propertyID: property.id,
                        sessionID: session.id,
                        state: sessionState,
                        freshness: sessionFreshness,
                        rowScope: .sessionRollup,
                        reason: sessionExportBlockers.first ?? "session_metadata_incomplete",
                        context: Self.mergedCompletenessContext(
                            sessionContext,
                            ["session_rollup_reason_count": String(sessionExportBlockers.count)]
                        )
                    ))
                }
                sessionStates.append(sessionState)
            }
        }

        return CompletenessGatesReport(
            inspectedAt: inspectedAt,
            activeOrganizationID: activeOrganizationID,
            propertyCounts: Self.completenessCounts(propertyStates),
            sessionCounts: Self.completenessCounts(sessionStates),
            shotCounts: Self.completenessCounts(shotStates),
            issueCounts: Self.completenessCounts(issueStates),
            guidedCounts: Self.completenessCounts(guidedStates),
            mediaCounts: Self.completenessCounts(mediaStates),
            freshnessCounts: Self.freshnessCounts(freshnessStates),
            exportCompleteSessionCount: exportCompleteSessions,
            notExportCompleteSessionCount: notExportCompleteSessions,
            diagnosticOnlyRows: diagnosticRows.sorted { lhs, rhs in
                if lhs.entityType != rhs.entityType { return lhs.entityType < rhs.entityType }
                return (lhs.entityID?.uuidString ?? "") < (rhs.entityID?.uuidString ?? "")
            }
        )
    }

    private func completenessDuplicateShotSessionIDs(properties: [Property]) -> [UUID: Set<UUID>] {
        var sessionIDsByShotID: [UUID: Set<UUID>] = [:]
        for property in properties where property.deletedAt == nil {
            let sessions = (try? localStore.fetchSessionsForCacheBuild(propertyID: property.id)) ?? []
            for session in sessions where session.deletedAt == nil {
                guard let metadata = try? localStore.loadSessionMetadata(propertyID: property.id, sessionID: session.id) else {
                    continue
                }
                for shot in metadata.shots {
                    sessionIDsByShotID[shot.shotID, default: []].insert(session.id)
                }
            }
        }
        return sessionIDsByShotID
    }

    private func completenessFreshness(for propertyID: UUID) -> CompletenessFreshnessState {
        guard let snapshot = propertyOpenFreshnessByPropertyID[propertyID] else { return .unknown }
        switch snapshot.status {
        case .current:
            return .current
        case .remoteUpdatesAvailable:
            return .remoteUpdatesAvailable
        case .needsReview:
            return .needsReview
        case .usingLocalCache:
            return .usingLocalCache
        case .offline:
            return .offline
        case .checkingCloudStatus, .unknown:
            return .unknown
        }
    }

    private static func completenessSessionContext(
        for session: Session,
        inspectedAt: Date
    ) -> [String: String] {
        [
            "session_status": session.status.rawValue,
            "is_sealed": String(session.isSealed),
            "ended_at": session.endedAt.map(completenessDateString) ?? "none",
            "completed_at": session.endedAt.map(completenessDateString) ?? "none",
            "exported_at": session.exportedAt.map(completenessDateString) ?? "none",
            "first_delivered_at": session.firstDeliveredAt.map(completenessDateString) ?? "none",
            "is_export_eligible": String(session.status == .completed && session.isSealed),
            "session_age_bucket": completenessAgeBucket(startedAt: session.startedAt, inspectedAt: inspectedAt)
        ]
    }

    private nonisolated static func completenessDateString(_ date: Date) -> String {
        ISO8601DateFormatter().string(from: date)
    }

    private nonisolated static func completenessAgeBucket(startedAt: Date, inspectedAt: Date) -> String {
        let age = max(0, inspectedAt.timeIntervalSince(startedAt))
        switch age {
        case ..<86400:
            return "lt_1d"
        case ..<(7 * 86400):
            return "lt_7d"
        case ..<(30 * 86400):
            return "lt_30d"
        case ..<(90 * 86400):
            return "lt_90d"
        default:
            return "gte_90d"
        }
    }

    private nonisolated static func mergedCompletenessContext(
        _ lhs: [String: String],
        _ rhs: [String: String]
    ) -> [String: String] {
        lhs.merging(rhs) { _, new in new }
    }

    private static func completenessStateForLocalProperty(_ property: Property) -> CompletenessGateState {
        guard property.deletedAt == nil, !property.isArchived else { return .localOnly }
        return trimmedNonEmpty(property.name) == nil ? .localOnly : .metadataComplete
    }

    private struct ShotCompletenessEvaluation {
        let state: CompletenessGateState
        let freshness: CompletenessFreshnessState
        let metadataComplete: Bool
        let mediaComplete: Bool
        let diagnosticOnly: Bool
        let reason: String
        let context: [String: String]
    }

    private static func evaluateShotCompleteness(
        _ shot: ShotMetadata,
        session: Session,
        propertyID: UUID,
        sessionID: UUID,
        inspectedAt: Date,
        duplicateShotIDGroupSize: Int,
        duplicateShotIDAcrossSessions: Bool,
        localStore: LocalStore
    ) -> ShotCompletenessEvaluation {
        var reasons: [String] = []
        if shot.propertyID != propertyID { reasons.append("shot_property_id_mismatch") }
        if shot.sessionID != sessionID { reasons.append("shot_session_id_mismatch") }
        if trimmedNonEmpty(shot.building) == nil { reasons.append("shot_building_missing") }
        if trimmedNonEmpty(shot.elevation) == nil { reasons.append("shot_elevation_missing") }
        if trimmedNonEmpty(shot.detailType) == nil { reasons.append("shot_detail_type_missing") }
        if shot.angleIndex < 1 { reasons.append("shot_angle_index_invalid") }
        if trimmedNonEmpty(shot.shotKey) == nil { reasons.append("shot_key_missing") }
        if trimmedNonEmpty(shot.originalRelativePath) == nil { reasons.append("shot_original_relative_path_missing") }
        if shot.isFlagged {
            if trimmedNonEmpty(shot.firstCaptureKind) == nil { reasons.append("flagged_shot_first_capture_kind_missing") }
            if trimmedNonEmpty(shot.priority) == nil { reasons.append("flagged_shot_priority_missing") }
        }

        let metadataComplete = reasons.isEmpty
        let originalFilenamePresent = trimmedNonEmpty(shot.originalFilename) != nil
        let originalFilename = safeDiagnosticsFilename(
            originalFilename: shot.originalFilename,
            originalRelativePath: shot.originalRelativePath
        )
        let originalRelativePath = trimmedNonEmpty(shot.originalRelativePath)
        let localOriginalExists: Bool = {
            guard shot.shouldAppearInDefaultExports else { return false }
            guard let relative = originalRelativePath else { return false }
            guard let url = localStore.resolveSessionRelativeFileURL(
                propertyID: propertyID,
                sessionID: sessionID,
                relativePath: relative
            ) else {
                return false
            }
            return FileManager.default.fileExists(atPath: url.path)
        }()
        let mediaComplete = localOriginalExists
        let resolverContext = missingOriginalResolverContext(
            shot: shot,
            propertyID: propertyID,
            sessionID: sessionID,
            localStore: localStore
        )
        let archiveContext = missingOriginalArchiveContext(
            shot: shot,
            propertyID: propertyID,
            sessionID: sessionID,
            localStore: localStore
        )
        let backupContext = missingOriginalICloudBackupContext(
            shot: shot,
            propertyID: propertyID,
            sessionID: sessionID
        )
        let storageBucketPresent = trimmedNonEmpty(shot.storageBucket) != nil
        let storagePathPresent = trimmedNonEmpty(shot.storagePath) != nil
        let checksumPresent = trimmedNonEmpty(shot.checksumSHA256) != nil
        let byteSizePresent = (shot.byteSize ?? shot.originalByteSize ?? 0) > 0

        let diagnosticOnly = shot.isHistorical || shot.hiddenFromGallery == true || shot.hiddenFromReports == true
        let state: CompletenessGateState
        if shot.shouldAppearInDefaultExports, metadataComplete, mediaComplete {
            state = .mediaComplete
        } else if metadataComplete {
            state = .metadataComplete
        } else {
            state = .localOnly
        }

        let reason: String
        if diagnosticOnly {
            reason = shot.isHistorical ? "shot_historical_lifecycle" : "shot_hidden_from_default_workflows"
        } else if !metadataComplete {
            reason = reasons.first ?? "shot_metadata_incomplete"
        } else if shot.shouldAppearInDefaultExports && !mediaComplete {
            reason = "active_export_shot_original_missing"
        } else {
            reason = "shot_metadata_complete"
        }

        var context = [
                "shot_lifecycle_state": shot.lifecycleState.rawValue,
                "shot_original_filename_present": String(originalFilenamePresent),
                "local_original_exists": String(localOriginalExists),
                "should_appear_in_default_exports": String(shot.shouldAppearInDefaultExports),
                "sanitized_original_filename": originalFilename ?? "none",
                "original_relative_path_present": String(originalRelativePath != nil),
                "local_shot_storage_bucket_present": String(storageBucketPresent),
                "local_shot_storage_path_present": String(storagePathPresent),
                "local_shot_checksum_present": String(checksumPresent),
                "local_shot_byte_size_present": String(byteSizePresent),
                "supabase_storage_candidate": String(storageBucketPresent && storagePathPresent),
                "duplicate_shot_id_group_size": String(max(duplicateShotIDGroupSize, 1)),
                "duplicate_shot_id_across_sessions": String(duplicateShotIDAcrossSessions)
            ]
        context.merge(missingOriginalDeliveryRiskContext(for: session, inspectedAt: inspectedAt)) { _, new in new }
        context.merge(resolverContext) { _, new in new }
        context.merge(archiveContext) { _, new in new }
        context.merge(backupContext) { _, new in new }
        context["known_missing_original_provenance"] = knownMissingOriginalProvenance(context)

        return ShotCompletenessEvaluation(
            state: state,
            freshness: reasons.contains { $0.contains("mismatch") } ? .needsReview : .unknown,
            metadataComplete: metadataComplete,
            mediaComplete: mediaComplete,
            diagnosticOnly: diagnosticOnly,
            reason: reason,
            context: context
        )
    }

    private static func missingOriginalDeliveryRiskContext(
        for session: Session,
        inspectedAt: Date
    ) -> [String: String] {
        let isPendingDelivery = session.isSealed && session.firstDeliveredAt == nil
        let isReExportEligible: Bool = {
            guard session.firstDeliveredAt != nil, let expiresAt = session.reExportExpiresAt else { return false }
            return inspectedAt < expiresAt
        }()
        let reExportWindowExpired: Bool = {
            guard session.status == .completed,
                  session.isSealed,
                  session.firstDeliveredAt != nil,
                  let expiresAt = session.reExportExpiresAt else {
                return false
            }
            return inspectedAt >= expiresAt
        }()
        let classification: String
        if isPendingDelivery {
            classification = "active_delivery_risk"
        } else if isReExportEligible {
            classification = "reexport_risk"
        } else if reExportWindowExpired {
            classification = "historical_archive_debt"
        } else {
            classification = "delivered_state_unknown"
        }
        return [
            "is_pending_delivery": String(isPendingDelivery),
            "is_reexport_eligible": String(isReExportEligible),
            "reexport_window_expired": String(reExportWindowExpired),
            "first_delivered_at": session.firstDeliveredAt.map(completenessDateString) ?? "none",
            "exported_at": session.exportedAt.map(completenessDateString) ?? "none",
            "missing_original_risk": classification
        ]
    }

    private static func missingOriginalResolverContext(
        shot: ShotMetadata,
        propertyID: UUID,
        sessionID: UUID,
        localStore: LocalStore
    ) -> [String: String] {
        let relative = trimmedNonEmpty(shot.originalRelativePath)
        let filename = safeDiagnosticsFilename(
            originalFilename: shot.originalFilename,
            originalRelativePath: shot.originalRelativePath
        )
        let sessionRelativeResolverHit: Bool = {
            guard let relative,
                  let url = localStore.resolveSessionRelativeFileURL(
                    propertyID: propertyID,
                    sessionID: sessionID,
                    relativePath: relative
                  ) else {
                return false
            }
            return FileManager.default.fileExists(atPath: url.path)
        }()
        let originalsFilenameFallbackHit: Bool = {
            guard let filename else { return false }
            let url = localStore
                .originalsFolderURL(propertyID: propertyID, sessionID: sessionID)
                .appendingPathComponent(filename, isDirectory: false)
            return FileManager.default.fileExists(atPath: url.path)
        }()
        let activeScoutRootCandidateHit: Bool = {
            guard let relative else { return false }
            let url = localStore
                .sessionFolderURL(propertyID: propertyID, sessionID: sessionID)
                .appendingPathComponent(relative, isDirectory: false)
            return FileManager.default.fileExists(atPath: url.path)
        }()
        let iCloudScoutRootCandidateHit: Bool = {
            guard let relative else { return false }
            let activePath = StorageRoot.scoutRootURL().standardizedFileURL.path
            return StorageRoot.scoutRootCandidates()
                .filter { $0.standardizedFileURL.path != activePath }
                .contains { root in
                    let candidate = root
                        .appendingPathComponent("Properties", isDirectory: true)
                        .appendingPathComponent(propertyID.uuidString, isDirectory: true)
                        .appendingPathComponent("Sessions", isDirectory: true)
                        .appendingPathComponent(sessionID.uuidString, isDirectory: true)
                        .appendingPathComponent(relative, isDirectory: false)
                    return FileManager.default.fileExists(atPath: candidate.path)
                }
        }()
        return [
            "session_relative_resolver_hit": String(sessionRelativeResolverHit),
            "originals_filename_fallback_hit": String(originalsFilenameFallbackHit),
            "active_scout_root_candidate_hit": String(activeScoutRootCandidateHit),
            "icloud_scout_root_candidate_hit": String(iCloudScoutRootCandidateHit)
        ]
    }

    private static func missingOriginalArchiveContext(
        shot: ShotMetadata,
        propertyID: UUID,
        sessionID: UUID,
        localStore: LocalStore
    ) -> [String: String] {
        let provenance = localStore.missingOriginalArchiveProvenance(
            propertyID: propertyID,
            sessionID: sessionID,
            originalFilename: safeDiagnosticsFilename(
                originalFilename: shot.originalFilename,
                originalRelativePath: shot.originalRelativePath
            ),
            originalRelativePath: trimmedNonEmpty(shot.originalRelativePath)
        )
        return [
            "archive_snapshot_exists": String(provenance.snapshotExists),
            "archive_snapshot_count": String(provenance.snapshotCount),
            "latest_archive_snapshot_date": provenance.latestSnapshotDate.map(completenessDateString) ?? "none",
            "archive_payload_originals_candidate_hit": String(provenance.payloadOriginalsCandidateHit),
            "archive_snapshot_candidate": String(provenance.payloadOriginalsCandidateHit)
        ]
    }

    private static func missingOriginalICloudBackupContext(
        shot: ShotMetadata,
        propertyID: UUID,
        sessionID: UUID
    ) -> [String: String] {
        guard let backupRoot = StorageRoot.cloudBackupRootURL() else {
            return [
                "icloud_backup_manifest_available": "false",
                "icloud_backup_manifest_logical_path_hit": "false",
                "icloud_backup_blob_checksum_candidate_hit": "false",
                "icloud_backup_candidate": "false"
            ]
        }
        let latest = backupRoot.appendingPathComponent("latest", isDirectory: true)
        let manifestURL = latest.appendingPathComponent("manifest.json", isDirectory: false)
        guard FileManager.default.fileExists(atPath: manifestURL.path),
              let data = try? Data(contentsOf: manifestURL) else {
            return [
                "icloud_backup_manifest_available": "false",
                "icloud_backup_manifest_logical_path_hit": "false",
                "icloud_backup_blob_checksum_candidate_hit": "false",
                "icloud_backup_candidate": "false"
            ]
        }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        guard let manifest = try? decoder.decode(CloudBackupManifest.self, from: data) else {
            return [
                "icloud_backup_manifest_available": "false",
                "icloud_backup_manifest_logical_path_hit": "false",
                "icloud_backup_blob_checksum_candidate_hit": "false",
                "icloud_backup_candidate": "false"
            ]
        }
        let relative = trimmedNonEmpty(shot.originalRelativePath)
        let filename = safeDiagnosticsFilename(
            originalFilename: shot.originalFilename,
            originalRelativePath: shot.originalRelativePath
        )
        var candidatePaths: Set<String> = []
        if let relative {
            candidatePaths.insert("storage-root/SCOUT/Properties/\(propertyID.uuidString)/Sessions/\(sessionID.uuidString)/\(relative)")
        }
        if let filename {
            candidatePaths.insert("storage-root/SCOUT/Properties/\(propertyID.uuidString)/Sessions/\(sessionID.uuidString)/Originals/\(filename)")
        }
        let matchingRecords = manifest.files.filter { candidatePaths.contains($0.relativePath) }
        let logicalHit = !matchingRecords.isEmpty
        let blobHit = matchingRecords.contains { record in
            guard let contentRelativePath = record.contentRelativePath else { return false }
            let blobURL = latest.appendingPathComponent(contentRelativePath, isDirectory: false)
            return FileManager.default.fileExists(atPath: blobURL.path)
        }
        return [
            "icloud_backup_manifest_available": "true",
            "icloud_backup_manifest_logical_path_hit": String(logicalHit),
            "icloud_backup_blob_checksum_candidate_hit": String(blobHit),
            "icloud_backup_candidate": String(logicalHit || blobHit)
        ]
    }

    private static func knownMissingOriginalProvenance(_ context: [String: String]) -> String {
        let hasKnown = context["archive_snapshot_candidate"] == "true" ||
            context["icloud_backup_candidate"] == "true" ||
            context["supabase_storage_candidate"] == "true" ||
            context["originals_filename_fallback_hit"] == "true" ||
            context["active_scout_root_candidate_hit"] == "true" ||
            context["icloud_scout_root_candidate_hit"] == "true"
        return hasKnown ? "true" : "false"
    }

    private struct IssueCompletenessEvaluation {
        let state: CompletenessGateState
        let freshness: CompletenessFreshnessState
        let metadataComplete: Bool
        let exportBlocked: Bool
        let diagnosticOnly: Bool
        let reason: String
        let context: [String: String]
    }

    private static func evaluateIssueCompleteness(
        _ issue: IssueMetadata,
        sessionID: UUID,
        localSessionIDs: Set<UUID>,
        allSessionShotIDs: Set<UUID>,
        exportedShotIDs: Set<UUID>
    ) -> IssueCompletenessEvaluation {
        var reasons: [String] = []
        var context: [String: String] = [:]
        if trimmedNonEmpty(issue.currentReason) == nil {
            reasons.append("issue_current_reason_missing")
        }
        let normalizedStatus = trimmedNonEmpty(issue.issueStatus)?.lowercased()
        if normalizedStatus != "active" && normalizedStatus != "resolved" {
            reasons.append("issue_status_invalid")
        }

        var exportBlocked = false
        for event in issue.historyEvents where event.sessionId == sessionID {
            let rawShotID = trimmedNonEmpty(event.details["shotId"] ?? event.details["shotID"])
            if let rawShotID {
                guard let shotID = UUID(uuidString: rawShotID) else {
                    exportBlocked = true
                    context["referenced_issue_history_shot_exists_in_all_session_shots"] = "false"
                    context["referenced_issue_history_shot_exists_in_default_export_shots"] = "false"
                    reasons.append("issue_history_orphan_shot_reference")
                    break
                }
                let existsInAllSessionShots = allSessionShotIDs.contains(shotID)
                let existsInDefaultExportShots = exportedShotIDs.contains(shotID)
                context["referenced_issue_history_shot_exists_in_all_session_shots"] = String(existsInAllSessionShots)
                context["referenced_issue_history_shot_exists_in_default_export_shots"] = String(existsInDefaultExportShots)
                guard existsInDefaultExportShots else {
                    exportBlocked = true
                    reasons.append(existsInAllSessionShots ? "issue_history_non_export_shot_reference" : "issue_history_orphan_shot_reference")
                    break
                }
            }
        }
        for event in issue.historyEvents {
            if let eventSessionID = event.sessionId, eventSessionID != sessionID {
                let referencedSessionExistsLocally = localSessionIDs.contains(eventSessionID)
                context["referenced_issue_history_session_exists_locally"] = String(referencedSessionExistsLocally)
                if referencedSessionExistsLocally {
                    reasons.append("issue_history_cross_session_reference")
                } else {
                    exportBlocked = true
                    reasons.append("issue_history_missing_session_reference")
                }
                break
            }
        }

        let metadataComplete = reasons.filter {
            !$0.hasPrefix("issue_history_orphan")
                && $0 != "issue_history_missing_session_reference"
                && $0 != "issue_history_non_export_shot_reference"
        }.isEmpty
        let state: CompletenessGateState = metadataComplete ? .metadataComplete : .localOnly
        let reason = reasons.first ?? "issue_metadata_complete"
        return IssueCompletenessEvaluation(
            state: state,
            freshness: exportBlocked ? .needsReview : .unknown,
            metadataComplete: metadataComplete,
            exportBlocked: exportBlocked,
            diagnosticOnly: normalizedStatus == "resolved" || reason == "issue_history_cross_session_reference",
            reason: reason,
            context: context
        )
    }

    private struct GuidedCompletenessEvaluation {
        let state: CompletenessGateState
        let metadataComplete: Bool
        let diagnosticOnly: Bool
        let reason: String
        let context: [String: String]
    }

    private static func evaluateGuidedCompleteness(_ guided: GuidedShot) -> GuidedCompletenessEvaluation {
        if guided.status == .retired || guided.isRetired {
            return GuidedCompletenessEvaluation(
                state: .metadataComplete,
                metadataComplete: true,
                diagnosticOnly: true,
                reason: "guided_retired",
                context: ["guided_status": guided.status.rawValue]
            )
        }

        var reasons: [String] = []
        if trimmedNonEmpty(guided.title) == nil { reasons.append("guided_title_missing") }
        if trimmedNonEmpty(guided.building) == nil { reasons.append("guided_building_missing") }
        if trimmedNonEmpty(guided.targetElevation) == nil { reasons.append("guided_elevation_missing") }
        if trimmedNonEmpty(guided.detailType) == nil { reasons.append("guided_detail_type_missing") }
        if (guided.angleIndex ?? 0) < 1 { reasons.append("guided_angle_index_missing") }

        let complete = reasons.isEmpty
        return GuidedCompletenessEvaluation(
            state: complete ? .metadataComplete : .localOnly,
            metadataComplete: complete,
            diagnosticOnly: false,
            reason: reasons.first ?? "guided_metadata_complete",
            context: ["guided_status": guided.status.rawValue]
        )
    }

    private nonisolated static func completenessRow(
        entityType: String,
        entityID: UUID?,
        propertyID: UUID? = nil,
        sessionID: UUID? = nil,
        shotID: UUID? = nil,
        state: CompletenessGateState,
        freshness: CompletenessFreshnessState,
        rowScope: CompletenessDiagnosticRowScope = .childDetail,
        reason: String
    ) -> CompletenessDiagnosticRow {
        completenessRow(
            entityType: entityType,
            entityID: entityID,
            propertyID: propertyID,
            sessionID: sessionID,
            shotID: shotID,
            state: state,
            freshness: freshness,
            rowScope: rowScope,
            reason: reason,
            context: [:]
        )
    }

    private nonisolated static func completenessRow(
        entityType: String,
        entityID: UUID?,
        propertyID: UUID? = nil,
        sessionID: UUID? = nil,
        shotID: UUID? = nil,
        state: CompletenessGateState,
        freshness: CompletenessFreshnessState,
        rowScope: CompletenessDiagnosticRowScope = .childDetail,
        reason: String,
        context: [String: String]
    ) -> CompletenessDiagnosticRow {
        CompletenessDiagnosticRow(
            id: UUID(),
            entityType: entityType,
            entityID: entityID,
            propertyID: propertyID,
            sessionID: sessionID,
            shotID: shotID,
            state: state,
            freshness: freshness,
            rowScope: rowScope,
            reason: sanitizedDiagnosticsErrorMessage(reason),
            context: context.reduce(into: [:]) { sanitizedContext, element in
                let key = sanitizedDiagnosticsErrorMessage(element.key)
                let value = sanitizedDiagnosticsErrorMessage(element.value)
                sanitizedContext[key] = value
            }
        )
    }

    private nonisolated static func completenessCounts(_ states: [CompletenessGateState]) -> [CompletenessGateCount] {
        let grouped = Dictionary(grouping: states, by: { $0 }).mapValues(\.count)
        return CompletenessGateState.allCases.map { state in
            CompletenessGateCount(state: state, count: grouped[state] ?? 0)
        }
    }

    private nonisolated static func freshnessCounts(_ states: [CompletenessFreshnessState]) -> [CompletenessFreshnessCount] {
        let grouped = Dictionary(grouping: states, by: { $0 }).mapValues(\.count)
        return CompletenessFreshnessState.allCases.map { state in
            CompletenessFreshnessCount(state: state, count: grouped[state] ?? 0)
        }
    }

    nonisolated static func dedupedCompletenessDiagnosticRows(
        _ rows: [CompletenessDiagnosticRow]
    ) -> [CompletenessDiagnosticSummaryRow] {
        var grouped: [String: (row: CompletenessDiagnosticRow, count: Int)] = [:]
        for row in rows {
            let key = completenessDiagnosticKey(for: row)
            if let existing = grouped[key] {
                grouped[key] = (existing.row, existing.count + 1)
            } else {
                grouped[key] = (row, 1)
            }
        }

        return grouped.map { key, value in
            CompletenessDiagnosticSummaryRow(
                id: key,
                entityType: value.row.entityType,
                entityID: value.row.entityID,
                propertyID: value.row.propertyID,
                sessionID: value.row.sessionID,
                shotID: value.row.shotID,
                state: value.row.state,
                freshness: value.row.freshness,
                rowScope: value.row.rowScope,
                reason: value.row.reason,
                duplicateCount: value.count,
                classification: completenessDiagnosticClassification(for: value.row),
                context: value.row.context
            )
        }
        .sorted { lhs, rhs in
            if lhs.classification != rhs.classification {
                return lhs.classification.rawValue < rhs.classification.rawValue
            }
            if lhs.reason != rhs.reason { return lhs.reason < rhs.reason }
            if lhs.entityType != rhs.entityType { return lhs.entityType < rhs.entityType }
            return lhs.id < rhs.id
        }
    }

    nonisolated static func completenessDiagnosticReasonCounts(
        _ rows: [CompletenessDiagnosticSummaryRow]
    ) -> [CompletenessDiagnosticReasonCount] {
        let grouped = Dictionary(grouping: rows, by: { "\($0.classification.rawValue)|\($0.reason)" })
        return grouped.map { key, rows in
            let first = rows[0]
            return CompletenessDiagnosticReasonCount(
                reason: first.reason,
                count: rows.reduce(0) { $0 + $1.duplicateCount },
                classification: first.classification
            )
        }
        .sorted { lhs, rhs in
            if lhs.classification != rhs.classification {
                return lhs.classification.rawValue < rhs.classification.rawValue
            }
            if lhs.count != rhs.count { return lhs.count > rhs.count }
            return lhs.reason < rhs.reason
        }
    }

    private nonisolated static func completenessDiagnosticKey(for row: CompletenessDiagnosticRow) -> String {
        [
            row.entityType,
            row.entityID?.uuidString ?? "none",
            row.propertyID?.uuidString ?? "none",
            row.sessionID?.uuidString ?? "none",
            row.shotID?.uuidString ?? "none",
            row.state.rawValue,
            row.freshness.rawValue,
            row.rowScope.rawValue,
            row.reason
        ].joined(separator: "|")
    }

    private nonisolated static func completenessDiagnosticClassification(
        for row: CompletenessDiagnosticRow
    ) -> CompletenessDiagnosticClassification {
        if row.rowScope == .sessionRollup {
            return .sessionRollup
        }
        switch row.reason {
        case "active_export_shot_original_missing":
            guard row.context["is_export_eligible"] == "true" else { return .preExportWarning }
            switch row.context["missing_original_risk"] {
            case "historical_archive_debt":
                return .informational
            case "active_delivery_risk", "reexport_risk", "delivered_state_unknown":
                return .actionable
            default:
                return .actionable
            }
        case "issue_history_orphan_session_reference",
             "issue_history_missing_session_reference",
             "issue_history_orphan_shot_reference",
             "issue_history_non_export_shot_reference",
             "issue_history_orphan_reference",
             "export_validation_failed",
             "active_export_shot_metadata_incomplete",
             "guided_metadata_incomplete",
             "guided_title_missing",
             "guided_building_missing",
             "guided_elevation_missing",
             "guided_detail_type_missing",
             "guided_angle_index_missing",
             "issue_current_reason_missing",
             "issue_status_invalid",
             "session_json_id_mismatch",
             "session_json_missing_or_unreadable":
            return .actionable
        case "active_export_shot_media_incomplete",
             "issue_history_cross_session_reference":
            return .informational
        case "guided_retired",
             "shot_historical_lifecycle",
             "session_not_completed_and_sealed",
             "property_archived",
             "property_deleted",
             "session_deleted":
            return .informational
        default:
            return row.freshness == .needsReview ? .actionable : .informational
        }
    }

    nonisolated static func sessionSnapshotPreviewReportText(_ report: SessionSnapshotPreviewReport) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Session Snapshot Preview")
        lines.append("Inspected: \(report.inspectedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(report.activeOrganizationID?.uuidString ?? "none")")
        lines.append("Read-only local-only diagnostics. This preview does not upload snapshots, change Supabase schema, change RLS, switch canonical reads, hydrate sessions or shots, download media, relink files, repair data, change export behavior, change sealing/completion behavior, change sync, change media recovery, change iCloud fallback, delete local/remote data, or include media payloads.")
        lines.append("")
        lines.append("Summary Counts")
        lines.append("- sessions_inspected: \(report.sessionsInspected)")
        lines.append("- previewable_sessions: \(report.previewableSessions)")
        lines.append("- missing_or_unreadable_session_json: \(report.missingOrUnreadableSessionJSONCount)")
        lines.append("- checksum_generation_pass: \(report.checksumGenerationPassCount)")
        lines.append("- checksum_generation_fail: \(report.checksumGenerationFailCount)")
        lines.append("- total_shot_count: \(report.totalShotCount)")
        lines.append("- total_issue_count: \(report.totalIssueCount)")
        lines.append("- total_guided_count: \(report.totalGuidedCount)")
        lines.append("- total_media_manifest_count: \(report.totalMediaManifestCount)")
        lines.append("- total_missing_local_originals: \(report.totalMissingLocalOriginalsCount)")
        lines.append("- total_supabase_storage_metadata_count: \(report.totalSupabaseStorageMetadataCount)")
        lines.append("")
        lines.append("Completeness Diagnostics Comparison")
        lines.append("- Preview shot_count, issue_count, guided_count, missing_local_originals, and media_manifest_count are derived from local session.json and local original resolution, matching the same local-only evidence class used by completeness diagnostics where practical.")
        lines.append("- This preview hashes raw session.json plus a deterministic snapshot payload for trust inspection only; it does not approve hydration or canonical-read changes.")
        lines.append("")
        lines.append("Per-Session Sanitized Rows")
        if report.rows.isEmpty {
            lines.append("none")
        } else {
            for row in report.rows {
                if let envelope = row.envelope {
                    lines.append(
                        [
                            "- property_id=\(row.propertyID.uuidString)",
                            "local_property_name=\(diagnosticsPreviewText(row.localPropertyName, maxLength: 80) ?? "none")",
                            "session_id=\(row.sessionID.uuidString)",
                            "previewable=true",
                            "trigger=\(diagnosticsPreviewText(envelope.trigger, maxLength: 40) ?? "none")",
                            "schema=\(envelope.snapshotSchemaVersion)",
                            "session_schema=\(envelope.sessionMetadataSchemaVersion.map(String.init) ?? "none")",
                            "status=\(envelope.status.rawValue)",
                            "sealed=\(envelope.isSealed)",
                            "exported_at=\(envelope.exportedAt?.formatted(date: .abbreviated, time: .standard) ?? "none")",
                            "first_delivered_at=\(envelope.firstDeliveredAt?.formatted(date: .abbreviated, time: .standard) ?? "none")",
                            "re_export_expires_at=\(envelope.reExportExpiresAt?.formatted(date: .abbreviated, time: .standard) ?? "none")",
                            "shots=\(envelope.shotCount)",
                            "issues=\(envelope.issueCount)",
                            "guided=\(envelope.guidedCount)",
                            "media_manifest=\(envelope.mediaManifestCount)",
                            "missing_local_originals=\(envelope.missingLocalOriginalsCount)",
                            "storage_metadata=\(envelope.supabaseStorageMetadataCount)",
                            "raw_json_sha256=\(envelope.rawSessionJSONSHA256)",
                            "payload_sha256=\(envelope.snapshotPayloadSHA256)",
                            "raw_json_bytes=\(envelope.rawSessionJSONByteCount)",
                            "payload_bytes=\(envelope.snapshotPayloadByteCount)"
                        ]
                            .joined(separator: " ")
                    )
                } else {
                    lines.append(
                        [
                            "- property_id=\(row.propertyID.uuidString)",
                            "local_property_name=\(diagnosticsPreviewText(row.localPropertyName, maxLength: 80) ?? "none")",
                            "session_id=\(row.sessionID.uuidString)",
                            "previewable=false",
                            "status=\(row.status?.rawValue ?? "unknown")",
                            "reason=\(diagnosticsPreviewText(row.failureReason, maxLength: 120) ?? "none")"
                        ]
                            .joined(separator: " ")
                    )
                }
            }
        }
        lines.append("")
        lines.append("Redaction Notes")
        lines.append("- Report rows intentionally omit raw session.json text, local paths, signed URLs, auth tokens, storage object paths, and media bytes.")
        lines.append("- Media manifest is represented by counts and per-shot provenance in memory only; the copyable report stays count-based.")
        return lines.joined(separator: "\n")
    }

