    nonisolated static func canonicalReadRolloutReportText(_ diagnostics: SessionSnapshotUploadDiagnostics) -> String {
        let readiness = makeCanonicalRolloutReadinessDiagnostics(diagnostics)
        let productionReadiness = makeProductionAllowlistReadinessDiagnostics(diagnostics)
        let cohortControlPlane = makeProductionCohortControlPlaneDiagnostics(diagnostics)
        let cohortApproval = makeProductionCohortOperatorApprovalDiagnostics(cohortControlPlane)
        let singleSessionGate = makeProductionSingleSessionActivationGateDiagnostics(
            policy: .disabled,
            approval: nil,
            targetClassification: .approvedProductionValidation,
            diagnostics: diagnostics
        )
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Canonical Read Rollout Report")
        lines.append("Operator validation report. This report is diagnostic-only: it does not switch canonical reads, enable production canonical reads, change candidate gating, build or activate overlays, mutate local/remote data, change export, seal, sync, media, or iCloud behavior, loosen RLS, or delete data.")
        lines.append("")
        lines.append("Summary")
        lines.append("- readiness_state: \(readiness.state.rawValue)")
        lines.append("- readiness_blockers: \(readiness.blockers.isEmpty ? "none" : readiness.blockers.joined(separator: ", "))")
        lines.append("- next_recommended_action: \(readiness.nextRecommendedAction)")
        lines.append("- rollout_checklist_passed: \(readiness.checklistPassed)")
        lines.append("- canonical_read_result: \(diagnosticsPreviewText(diagnostics.lastCanonicalReadDiagnosticsResult, maxLength: 80) ?? "local_only")")
        lines.append("- recommendation: \(diagnosticsPreviewText(diagnostics.lastCanonicalReadDiagnosticsRecommendation, maxLength: 140) ?? "local_first")")
        lines.append("- parity_completeness_score: \(String(format: "%.2f", diagnostics.lastParityCompletenessScore))")
        lines.append("- normalized_parity_completeness: \(diagnosticsPreviewText(diagnostics.lastNormalizedParityCompleteness, maxLength: 140) ?? "not_checked")")
        lines.append("- missing_child_count: \(diagnostics.lastMissingChildCount)")
        lines.append("- candidate_allowed: \(diagnostics.lastCanonicalReadCandidateAllowed)")
        lines.append("- candidate_blocked_reason: \(diagnosticsPreviewText(diagnostics.lastCanonicalReadCandidateBlockedReason, maxLength: 220) ?? "not_checked")")
        lines.append("- overlay_built: \(diagnostics.lastCanonicalCandidateOverlayBuilt)")
        lines.append("- overlay_blocked_reason: \(diagnosticsPreviewText(diagnostics.lastCanonicalCandidateOverlayBlockedReason, maxLength: 220) ?? "not_checked")")
        lines.append("- overlay_comparison_result: \(diagnostics.lastCanonicalCandidateOverlayComparisonResult)")
        lines.append("- activation_allowed: \(diagnostics.lastCanonicalCandidateActivationAllowed)")
        lines.append("- activation_blocked_reason: \(diagnosticsPreviewText(diagnostics.lastCanonicalCandidateActivationBlockedReason, maxLength: 220) ?? "not_checked")")
        lines.append("- active_source: \(diagnosticsPreviewText(diagnostics.lastCanonicalCandidateActivationActiveSource, maxLength: 80) ?? "local")")
        lines.append("- rollback_available: \(diagnostics.lastCanonicalCandidateActivationRollbackAvailable)")
        lines.append("- fallback_available: \(diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable)")
        lines.append("- production_candidate_wide_enabled: \(diagnostics.lastCanonicalReadCandidateProductionWideEnabled)")
        lines.append("- production_overlay_blocked: \(diagnostics.lastCanonicalCandidateOverlayProductionBlocked)")
        lines.append("- production_activation_blocked: \(diagnostics.lastCanonicalCandidateActivationProductionBlocked)")
        lines.append("- rollout_blockers: \(diagnostics.lastCanonicalReadRolloutBlockers.isEmpty ? "none" : diagnostics.lastCanonicalReadRolloutBlockers.joined(separator: ", "))")
        lines.append("")
        lines.append("Local Health Rows")
        lines.append("- production readiness state: \(productionReadiness.state.rawValue)")
        lines.append("- production rollout blockers: \(productionReadiness.blockers.isEmpty ? "none" : productionReadiness.blockers.joined(separator: ", "))")
        lines.append("- operator approval required: \(productionReadiness.operatorApprovalRequired)")
