    nonisolated static func completenessGatesReportText(_ report: CompletenessGatesReport) -> String {
        let dedupedRows = dedupedCompletenessDiagnosticRows(report.diagnosticOnlyRows)
        let reasonCounts = completenessDiagnosticReasonCounts(dedupedRows)
        let missingOriginalRiskCounts = completenessMissingOriginalRiskCounts(dedupedRows)
        let actionableRows = dedupedRows.filter { $0.classification == .actionable }
        let preExportWarningRows = dedupedRows.filter { $0.classification == .preExportWarning }
        let sessionRollupRows = dedupedRows.filter { $0.classification == .sessionRollup }
        let informationalRows = dedupedRows.filter { $0.classification == .informational }
        let unknownFreshnessCount = report.freshnessCounts.first { $0.state == .unknown }?.count ?? 0
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Completeness Gates")
        lines.append("Inspected: \(report.inspectedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(report.activeOrganizationID?.uuidString ?? "none")")
        lines.append("Read-only diagnostics. This report does not enforce gates, block export, block sealing, change history visibility, switch canonical reads, hydrate data, download media, change sync, media recovery, iCloud fallback, migrations, RLS, or local/remote data.")
        lines.append("")
        lines.append("Summary Counts")
        lines.append("- raw_diagnostic_rows: \(report.diagnosticOnlyRows.count)")
        lines.append("- deduped_diagnostic_rows: \(dedupedRows.count)")
        lines.append("- actionable_needs_review_rows: \(actionableRows.count)")
        lines.append("- pre_export_warning_rows: \(preExportWarningRows.count)")
        lines.append("- session_rollup_rows: \(sessionRollupRows.count)")
        lines.append("- historical_informational_rows: \(informationalRows.count)")
        lines.append("- export_complete_sessions: \(report.exportCompleteSessionCount)")
        lines.append("- not_export_complete_sessions: \(report.notExportCompleteSessionCount)")
        appendCompletenessCounts("Properties", report.propertyCounts, to: &lines)
        appendCompletenessCounts("Sessions", report.sessionCounts, to: &lines)
        appendCompletenessCounts("Shots", report.shotCounts, to: &lines)
        appendCompletenessCounts("Issues", report.issueCounts, to: &lines)
        appendCompletenessCounts("Guided Rows", report.guidedCounts, to: &lines)
        appendCompletenessCounts("Media", report.mediaCounts, to: &lines)
        lines.append("")
        lines.append("Freshness Counts")
        for count in report.freshnessCounts {
            lines.append("- \(count.state.rawValue): \(count.count)")
        }
        lines.append("")
        lines.append("Freshness Explanation")
        if unknownFreshnessCount > 0 {
            lines.append("Many historical entities may show unknown freshness because property-open freshness is checked only for opened properties, not every historical entity. Unknown freshness alone is not treated as an active regression in this diagnostics report.")
        } else {
            lines.append("No unknown freshness rows were counted in this snapshot. Freshness remains scoped to property-open checks unless broader child metadata freshness is added later.")
        }
        lines.append("")
        lines.append("Classification Notes")
        lines.append("- active_export_shot_media_incomplete is a session-level rollup; inspect child shot rows for the missing-original detail.")
        lines.append("- Issue history can legitimately reference other sessions. Cross-session references are informational when the referenced session exists locally and actionable only when the referenced session or shot is missing or unresolvable.")
        lines.append("- Missing originals on draft, unsealed, or otherwise non-export-eligible sessions are pre-export warnings, not immediate export blockers in this diagnostics report.")
        lines.append("- Missing-original provenance is read-only. Archive, iCloud backup, Supabase storage, and duplicate shot ID hints do not approve repair, relink, download, hydration, or automatic media equivalence.")
        lines.append("- Pending delivery missing originals are active_delivery_risk; re-export window hits are reexport_risk; already delivered and expired rows are historical_archive_debt.")
        lines.append("")
        lines.append("Diagnostic Reason Counts")
        if reasonCounts.isEmpty {
            lines.append("none")
        } else {
            for reason in reasonCounts {
                lines.append("- \(reason.classification.rawValue) | \(diagnosticsPreviewText(reason.reason, maxLength: 120) ?? "none"): \(reason.count)")
            }
        }
        lines.append("")
        lines.append("Missing Original Risk / Provenance Counts")
        if missingOriginalRiskCounts.isEmpty {
            lines.append("none")
        } else {
            for count in missingOriginalRiskCounts {
                lines.append("- \(count.key): \(count.value)")
            }
        }
        lines.append("")
        lines.append("Actionable / Needs Review Diagnostics")
        appendCompletenessDiagnosticRows(actionableRows, to: &lines)
        lines.append("")
        lines.append("Pre-Export Warning Diagnostics")
        appendCompletenessDiagnosticRows(preExportWarningRows, to: &lines)
        lines.append("")
        lines.append("Session Rollup Diagnostics")
        appendCompletenessDiagnosticRows(sessionRollupRows, to: &lines)
        lines.append("")
        lines.append("Historical / Informational Diagnostics")
        appendCompletenessDiagnosticRows(informationalRows, to: &lines)
        lines.append("")
        lines.append("Full Diagnostic Rows, Deduped: \(dedupedRows.count)")
        appendCompletenessDiagnosticRows(dedupedRows, to: &lines)
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeExportSealPreflightReport(
        from completenessReport: CompletenessGatesReport
    ) -> ExportSealPreflightReport {
        let rows = dedupedCompletenessDiagnosticRows(completenessReport.diagnosticOnlyRows)
        let sections = ExportSealPreflightScope.allCases.map { scope in
            let findings = rows.compactMap { row -> ExportSealPreflightFinding? in
                guard let category = exportSealPreflightCategory(for: row, scope: scope) else {
                    return nil
                }
                return ExportSealPreflightFinding(
                    id: "\(scope.rawValue)|\(row.id)",
                    category: category,
                    entityType: row.entityType,
                    entityID: row.entityID,
                    propertyID: row.propertyID,
                    sessionID: row.sessionID,
                    shotID: row.shotID,
                    freshness: row.freshness,
                    reason: row.reason,
                    duplicateCount: row.duplicateCount,
                    context: row.context
                )
            }
            return ExportSealPreflightSection(
                scope: scope,
                counts: ExportSealPreflightReport.counts(for: findings),
                findings: findings.sorted { lhs, rhs in
                    if lhs.category != rhs.category {
                        return lhs.category.rawValue < rhs.category.rawValue
                    }
                    if lhs.reason != rhs.reason { return lhs.reason < rhs.reason }
                    if lhs.entityType != rhs.entityType { return lhs.entityType < rhs.entityType }
                    return lhs.id < rhs.id
                },
                reasonSummaries: exportSealPreflightReasonSummaries(for: findings)
            )
        }
        return ExportSealPreflightReport(
            inspectedAt: completenessReport.inspectedAt,
            activeOrganizationID: completenessReport.activeOrganizationID,
            sections: sections
        )
    }

    private nonisolated static func exportSealPreflightCategory(
        for row: CompletenessDiagnosticSummaryRow,
        scope: ExportSealPreflightScope
    ) -> ExportSealPreflightCategory? {
        if row.entityType == "property" {
            if row.reason == "property_deleted" || row.reason == "property_archived" {
                return .hardBlockCandidate
            }
            if row.freshness == .needsReview {
                return .hardBlockCandidate
            }
            if row.freshness == .offline || row.freshness == .unknown || row.freshness == .usingLocalCache {
                return .softWarningCandidate
            }
        }

        if row.freshness == .needsReview, row.entityType == "property" {
            return .hardBlockCandidate
        }

        switch row.reason {
        case "session_json_missing_or_unreadable",
             "session_json_id_mismatch",
             "issue_history_orphan_session_reference",
             "issue_history_missing_session_reference",
             "issue_history_orphan_shot_reference",
             "issue_history_non_export_shot_reference",
             "issue_history_orphan_reference",
             "export_validation_failed",
             "active_export_shot_metadata_incomplete",
             "guided_metadata_incomplete",
             "guided_title_missing",
             "guided_building_missing",
             "guided_elevation_missing",
             "guided_detail_type_missing",
             "guided_angle_index_missing",
             "issue_current_reason_missing",
             "issue_status_invalid":
            return .hardBlockCandidate
        case "active_export_shot_original_missing":
            return exportSealPreflightMissingOriginalCategory(for: row, scope: scope)
        case "active_export_shot_media_incomplete":
            return .informationalOnly
        case "session_not_completed_and_sealed":
            return scope == .sealComplete ? .informationalOnly : .softWarningCandidate
        case "issue_history_cross_session_reference",
             "guided_retired",
             "shot_historical_lifecycle",
             "shot_hidden_from_default_workflows",
             "session_deleted":
            return .informationalOnly
        default:
            if row.freshness == .needsReview {
                return .unknownNeedsReview
            }
            if row.freshness == .offline || row.freshness == .unknown || row.freshness == .usingLocalCache {
                return .softWarningCandidate
            }
            return row.classification == .informational ? .informationalOnly : .unknownNeedsReview
        }
    }

    private nonisolated static func exportSealPreflightMissingOriginalCategory(
        for row: CompletenessDiagnosticSummaryRow,
        scope: ExportSealPreflightScope
    ) -> ExportSealPreflightCategory {
        switch row.context["missing_original_risk"] {
        case "active_delivery_risk":
            return scope == .reExport ? .softWarningCandidate : .hardBlockCandidate
        case "reexport_risk":
            return scope == .reExport ? .hardBlockCandidate : .softWarningCandidate
        case "historical_archive_debt":
            return .informationalOnly
        case "delivered_state_unknown":
            return .unknownNeedsReview
        default:
            if row.context["supabase_storage_candidate"] == "true" ||
                row.context["duplicate_shot_id_across_sessions"] == "true" {
                return .softWarningCandidate
            }
            return row.context["is_export_eligible"] == "false" ? .softWarningCandidate : .unknownNeedsReview
        }
    }

    private nonisolated static func exportSealPreflightReasonDescriptor(
        for finding: ExportSealPreflightFinding
    ) -> (title: String, explanation: String) {
        if finding.reason == "active_export_shot_original_missing" {
            if finding.context["duplicate_shot_id_across_sessions"] == "true" {
                return (
                    "Duplicate shot ID context",
                    "A missing-original finding has duplicate shot ID context, so it is advisory until a future policy decides how to interpret it."
                )
            }
            if finding.context["supabase_storage_candidate"] == "true" {
                return (
                    "Supabase storage candidate",
                    "Remote storage metadata exists while the local original is missing; this is informational for review and does not download or relink media."
                )
            }
            switch finding.context["missing_original_risk"] {
            case "historical_archive_debt":
                return (
                    "Historical archive debt",
                    "Already delivered and re-export-expired missing originals are retained for audit/history and are not operational blockers."
                )
            case "active_delivery_risk":
                return (
                    "Pending delivery missing original",
                    "A pending-delivery session has a local original missing; this is a future hard-block candidate only."
                )
            case "reexport_risk":
                return (
                    "Re-export eligible missing original",
                    "A re-export-eligible session has a local original missing; this is a future hard-block candidate for re-export."
                )
            case "delivered_state_unknown":
                return (
                    "Delivery state unknown",
                    "The delivery or re-export state could not be determined, so this needs operator review before enforcement."
                )
            default:
                return (
                    "Missing local original",
                    "A referenced export original is not locally readable; this remains advisory in the current app behavior."
                )
            }
        }

        switch finding.reason {
        case "guided_retired":
            return (
                "Retired guided rows",
                "Retired guided rows are retained for history and are not operational blockers."
            )
        case "shot_historical_lifecycle",
             "shot_hidden_from_default_workflows":
            return (
                "Retired or historical shots",
                "Historical or hidden shots are preserved for audit and are not part of active export blocking."
            )
        case "issue_history_cross_session_reference":
            return (
                "Cross-session issue history",
                "Issue history references another existing session, which is retained as context and does not block."
            )
        case "active_export_shot_media_incomplete":
            return (
                "Session rollup advisory",
                "A session-level rollup points to child media findings; inspect the detailed rows for the specific missing-original context."
            )
        case "session_not_completed_and_sealed":
            return (
                "Completed/sealed state advisory",
                "The session state is inconsistent with export readiness, but current export and sealing behavior is unchanged."
            )
        case "session_json_missing_or_unreadable":
            return (
                "Missing session metadata",
                "The session metadata file is missing or unreadable and may later become a hard blocker."
            )
        case "session_json_id_mismatch":
            return (
                "Session identity mismatch",
                "The session metadata identity does not match the local target and may later become a hard blocker."
            )
        case "issue_history_orphan_session_reference",
             "issue_history_missing_session_reference",
             "issue_history_orphan_shot_reference",
             "issue_history_non_export_shot_reference",
             "issue_history_orphan_reference":
            return (
                "Issue/export linkage missing references",
                "Issue history or export linkage is missing required references and may later become a hard blocker."
            )
        default:
            if finding.freshness == .unknown || finding.freshness == .offline || finding.freshness == .usingLocalCache {
                return (
                    "Unknown freshness",
                    "Freshness is offline, unknown, or local-cache based; review may be useful, but this does not block export or sealing."
                )
            }
            return (
                diagnosticsPreviewText(finding.reason, maxLength: 80) ?? "Other preflight finding",
                "This grouped diagnostic is advisory in the current app behavior; use the copyable report for technical details."
            )
        }
    }

    nonisolated static func exportSealPreflightReportText(_ report: ExportSealPreflightReport) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Export / Seal Preflight")
        lines.append("Inspected: \(report.inspectedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(report.activeOrganizationID?.uuidString ?? "none")")
        lines.append("Read-only advisory diagnostics. No behavior changed. Export is not blocked. Sealing is not blocked. This report does not enforce gates, block export, block sealing, change history visibility, switch canonical reads, hydrate sessions or shots, download media, relink files, repair data, change sync, media recovery, iCloud fallback, migrations, RLS, or local/remote data.")
        lines.append("")
        lines.append("Summary Counts")
        appendExportSealPreflightCounts(report.totalCounts, to: &lines)
        lines.append("")
        lines.append("Preflight Category Definitions")
        lines.append("- hard_block_candidate: would likely block a future strict seal/export rule, but does not block anything now.")
        lines.append("- soft_warning_candidate: would likely warn or need operator awareness, but does not block anything now.")
        lines.append("- informational_only: historical, retired, cross-session, or otherwise non-active advisory context.")
        lines.append("- unknown_needs_review: context is unresolved enough that a future rule needs review before deciding.")
        lines.append("")
        for section in report.sections {
            lines.append(section.scope.title)
            appendExportSealPreflightCounts(section.counts, to: &lines)
            appendExportSealPreflightFindings(section.findings, to: &lines)
            lines.append("")
        }
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeEnforcementPolicyMatrixReport(
        inspectedAt: Date = Date()
    ) -> EnforcementPolicyMatrixReport {
        let sections = EnforcementPolicyOperation.allCases.map { operation in
            EnforcementPolicyMatrixSection(
                operation: operation,
                rows: enforcementPolicyConditionDefinitions.map { definition in
                    enforcementPolicyRow(for: definition, operation: operation)
                }
            )
        }
        return EnforcementPolicyMatrixReport(inspectedAt: inspectedAt, sections: sections)
    }

    nonisolated static func enforcementPolicyMatrixReportText(
        _ report: EnforcementPolicyMatrixReport
    ) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Enforcement Policy Matrix")
        lines.append("Inspected: \(report.inspectedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Read-only policy diagnostics. No behavior changed. This matrix does not enforce gates, block export, block sealing, change history visibility, switch canonical reads, hydrate sessions or shots, download media, relink files, repair data, change sync, media recovery, iCloud fallback, migrations, RLS, or local/remote data.")
        lines.append("")
        lines.append("Technical Policy Rows")
        for section in report.sections {
            lines.append("")
            lines.append(section.operation.title)
            for row in section.rows {
                lines.append([
                    "operation=\(row.operation.rawValue)",
                    "condition_key=\(row.conditionKey)",
                    "current_severity=\(row.currentSeverity.rawValue)",
                    "eventual_severity=\(row.eventualSeverity.rawValue)",
                    "readiness=\(row.readiness.rawValue)",
                    "deferral_reason=\(diagnosticsPreviewText(row.deferralReason, maxLength: 160) ?? "none")",
                    "notes=\(diagnosticsPreviewText(row.notes, maxLength: 180) ?? "none")"
                ].joined(separator: " | "))
            }
        }
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeEnforcementWarningSummaryReport(
        from matrix: EnforcementPolicyMatrixReport? = nil,
        inspectedAt: Date = Date()
    ) -> EnforcementWarningSummaryReport {
        let matrixReport = matrix ?? makeEnforcementPolicyMatrixReport(inspectedAt: inspectedAt)
        let groups = EnforcementWarningGroup.allCases.map { group in
            let keys = enforcementWarningConditionKeys(for: group)
            let rows = matrixReport.rows
                .filter { keys.contains($0.conditionKey) }
                .sorted { lhs, rhs in
                    if lhs.conditionKey != rhs.conditionKey { return lhs.conditionKey < rhs.conditionKey }
                    return lhs.operation.rawValue < rhs.operation.rawValue
                }
            return EnforcementWarningGroupSummary(
                group: group,
                count: Set(rows.map(\.conditionKey)).count,
                posture: enforcementWarningPosture(for: rows),
                rows: rows
            )
        }
        return EnforcementWarningSummaryReport(
            inspectedAt: matrixReport.inspectedAt,
            groups: groups
        )
    }

