    private nonisolated static func completenessMissingOriginalRiskCounts(
        _ rows: [CompletenessDiagnosticSummaryRow]
    ) -> [(key: String, value: Int)] {
        let missingOriginalRows = rows.filter { $0.reason == "active_export_shot_original_missing" }
        guard !missingOriginalRows.isEmpty else { return [] }
        let keys = [
            "active_delivery_risk",
            "reexport_risk",
            "historical_archive_debt",
            "delivered_state_unknown",
            "archive_snapshot_candidate",
            "icloud_backup_candidate",
            "supabase_storage_candidate",
            "no_known_provenance",
            "duplicate_shot_id_group"
        ]
        var counts = Dictionary(uniqueKeysWithValues: keys.map { ($0, 0) })
        for row in missingOriginalRows {
            let duplicateCount = row.duplicateCount
            let risk = row.context["missing_original_risk"] ?? "delivered_state_unknown"
            if counts[risk] != nil {
                counts[risk, default: 0] += duplicateCount
            }
            if row.context["archive_snapshot_candidate"] == "true" {
                counts["archive_snapshot_candidate", default: 0] += duplicateCount
            }
            if row.context["icloud_backup_candidate"] == "true" {
                counts["icloud_backup_candidate", default: 0] += duplicateCount
            }
            if row.context["supabase_storage_candidate"] == "true" {
                counts["supabase_storage_candidate", default: 0] += duplicateCount
            }
            if row.context["known_missing_original_provenance"] != "true" {
                counts["no_known_provenance", default: 0] += duplicateCount
            }
            if row.context["duplicate_shot_id_across_sessions"] == "true" {
                counts["duplicate_shot_id_group", default: 0] += duplicateCount
            }
        }
        return keys.compactMap { key in
            guard let value = counts[key], value > 0 else { return nil }
            return (key, value)
        }
    }

    private nonisolated static func appendCompletenessDiagnosticRows(
        _ rows: [CompletenessDiagnosticSummaryRow],
        to lines: inout [String]
    ) {
        if rows.isEmpty {
            lines.append("none")
            return
        }

        for row in rows {
            lines.append([
                "- entity=\(diagnosticsPreviewText(row.entityType, maxLength: 60) ?? "unknown")",
                "entity_id=\(row.entityID?.uuidString ?? "none")",
                "property_id=\(row.propertyID?.uuidString ?? "none")",
                "session_id=\(row.sessionID?.uuidString ?? "none")",
                "shot_id=\(row.shotID?.uuidString ?? "none")",
                "state=\(row.state.rawValue)",
                "freshness=\(row.freshness.rawValue)",
                "classification=\(row.classification.rawValue)",
                "row_scope=\(row.rowScope.rawValue)",
                "duplicates=\(row.duplicateCount)",
                "reason=\(diagnosticsPreviewText(row.reason, maxLength: 120) ?? "none")",
                "context=\(completenessContextText(row.context))"
            ].joined(separator: " | "))
        }
    }

    private nonisolated static func completenessContextText(_ context: [String: String]) -> String {
        guard !context.isEmpty else { return "none" }
        return context
            .sorted { $0.key < $1.key }
            .map { key, value in
                "\(diagnosticsPreviewText(key, maxLength: 80) ?? "unknown")=\(diagnosticsPreviewText(value, maxLength: 120) ?? "none")"
            }
            .joined(separator: ",")
    }

    nonisolated static func makeCanonicalTransitionPolicyDiagnostics(
        checkedAt: Date = Date(),
        restoreDiagnostics: SessionSnapshotRestoreDiagnosticsResult?,
        recoveryCohort: SnapshotRecoveryCohortResult?,
        hydrationPolicy: SessionSnapshotHydrationPolicyDiagnostics?,
        uploadDiagnostics: SessionSnapshotUploadDiagnostics? = nil
    ) -> CanonicalTransitionPolicyDiagnostics {
        let mediaDiagnostics = restoreDiagnostics?.mediaRecoveryDiagnostics
        let mediaRecoveryConfidence = canonicalMediaRecoveryConfidence(mediaDiagnostics)
        let hydrationConfidence = canonicalHydrationConfidence(
            restoreDiagnostics: restoreDiagnostics,
            recoveryCohort: recoveryCohort,
            hydrationPolicy: hydrationPolicy
        )
        let conflictState = canonicalConflictState(
            restoreDiagnostics: restoreDiagnostics,
            mediaRecoveryConfidence: mediaRecoveryConfidence
        )
        let remoteFreshnessAgeSeconds = canonicalRemoteFreshnessAgeSeconds(
            checkedAt: checkedAt,
            restoreDiagnostics: restoreDiagnostics
        )
        let readState = canonicalReadState(
            restoreDiagnostics: restoreDiagnostics,
            recoveryCohort: recoveryCohort,
            conflictState: conflictState,
            hydrationConfidence: hydrationConfidence,
            mediaRecoveryConfidence: mediaRecoveryConfidence
        )
        let recommendationAndReason = canonicalSourceRecommendation(
            readState: readState,
            conflictState: conflictState,
            hydrationConfidence: hydrationConfidence,
            mediaRecoveryConfidence: mediaRecoveryConfidence
        )
        let prerequisites: [String: String] = [
            "snapshot_freshness": restoreDiagnostics?.freshness ?? "not_checked",
            "checksum_verification": restoreDiagnostics?.checksumVerified == true ? "verified" : "not_verified",
            "media_recoverability": mediaRecoveryConfidence,
            "hydration_success_rate": "not_measured_policy_only",
            "upload_success_metrics": canonicalUploadSuccessMetric(uploadDiagnostics),
            "recovery_cohort_confidence": recoveryCohort?.readiness.rawValue ?? "not_checked",
            "parent_consistency": restoreDiagnostics?.parentRemoteVerified == true ? "verified" : "not_verified"
        ]

        return CanonicalTransitionPolicyDiagnostics(
            checkedAt: checkedAt,
            readState: readState,
            canonicalSourceRecommendation: recommendationAndReason.recommendation,
            canonicalSourceReason: recommendationAndReason.reason,
            conflictState: conflictState,
            recoveryFallbackState: canonicalRecoveryFallbackState(
                readState: readState,
                conflictState: conflictState,
                mediaRecoveryConfidence: mediaRecoveryConfidence
            ),
            remoteFreshnessAgeSeconds: remoteFreshnessAgeSeconds,
            hydrationConfidence: hydrationConfidence,
            mediaRecoveryConfidence: mediaRecoveryConfidence,
            trustHierarchy: CanonicalTrustSource.defaultHierarchy,
            rolloutPhase: .testOnlyCanonicalReadDiagnostics,
            prerequisites: prerequisites,
            iCloudNearTermRole: "unchanged_local_offline_backup_rail",
            iCloudMediumTermRole: "secondary_recovery_offline_continuity",
            iCloudLongTermRole: "optional_redundancy_after_supabase_recovery_is_proven",
            noBehaviorChangedText: "No behavior changed: this policy report is read-only diagnostics and does not switch canonical reads, hydrate data, download media, change export, change seal, change sync, change iCloud behavior, loosen RLS, or mutate local/remote data."
        )
    }

    nonisolated static func canonicalTransitionPolicyDiagnosticsText(_ diagnostics: CanonicalTransitionPolicyDiagnostics) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Canonical Transition Policy")
        lines.append("Checked: \(diagnostics.checkedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Read State: \(diagnostics.readState.rawValue)")
        lines.append("Canonical Source Recommendation: \(diagnosticsPreviewText(diagnostics.canonicalSourceRecommendation, maxLength: 120) ?? "unknown")")
        lines.append("Canonical Source Reason: \(diagnosticsPreviewText(diagnostics.canonicalSourceReason, maxLength: 180) ?? "unknown")")
        lines.append("Conflict State: \(diagnostics.conflictState.rawValue)")
        lines.append("Recovery Fallback State: \(diagnosticsPreviewText(diagnostics.recoveryFallbackState, maxLength: 120) ?? "unknown")")
        lines.append("Remote Freshness Age Seconds: \(diagnostics.remoteFreshnessAgeSeconds.map { String(Int($0)) } ?? "unknown")")
        lines.append("Hydration Confidence: \(diagnosticsPreviewText(diagnostics.hydrationConfidence, maxLength: 120) ?? "unknown")")
        lines.append("Media Recovery Confidence: \(diagnosticsPreviewText(diagnostics.mediaRecoveryConfidence, maxLength: 120) ?? "unknown")")
        lines.append("Rollout Phase: \(diagnostics.rolloutPhase.rawValue)")
        lines.append("Trust Hierarchy: \(diagnostics.trustHierarchy.map(\.rawValue).joined(separator: " > "))")
        lines.append("iCloud Near Term Role: \(diagnostics.iCloudNearTermRole)")
        lines.append("iCloud Medium Term Role: \(diagnostics.iCloudMediumTermRole)")
        lines.append("iCloud Long Term Role: \(diagnostics.iCloudLongTermRole)")
        lines.append(diagnostics.noBehaviorChangedText)
        lines.append("")
        lines.append("Prerequisites")
        for key in diagnostics.prerequisites.keys.sorted() {
            lines.append("- \(key): \(diagnosticsPreviewText(diagnostics.prerequisites[key], maxLength: 120) ?? "unknown")")
        }
        return lines.joined(separator: "\n")
    }

    @MainActor
    func runCanonicalReadDiagnosticsForSelectedSession(checkedAt: Date = Date()) async -> CanonicalReadDiagnosticsResult {
        let propertyID = selectedPropertyID ?? currentSession?.propertyID
        let sessionID = currentSession?.id
        let localSnapshot = makeCanonicalReadLocalSnapshot(
            propertyID: propertyID,
            sessionID: sessionID
        )
        let remoteSnapshot: CanonicalReadRemoteSnapshot?
        if let propertyID {
            remoteSnapshot = await fetchCanonicalReadRemoteSnapshotIfAvailable(
                activeOrganizationID: activeOrganizationID,
                propertyID: propertyID,
                sessionID: sessionID
            )
        } else {
            remoteSnapshot = nil
        }
        let result = Self.makeCanonicalReadDiagnostics(
            checkedAt: checkedAt,
            activeOrganizationID: activeOrganizationID,
            local: localSnapshot,
            remote: remoteSnapshot
        )
        recordCanonicalReadDiagnostics(result)
        return result
    }

    private func makeCanonicalReadLocalSnapshot(
        propertyID: UUID?,
        sessionID: UUID?
    ) -> CanonicalReadLocalSnapshot {
        let property = propertyID.flatMap { targetID in
            ((try? localStore.fetchProperties()) ?? allProperties).first { $0.id == targetID }
        }
        let session = propertyID.flatMap { targetPropertyID in
            ((try? localStore.fetchSessionsForCacheBuild(propertyID: targetPropertyID)) ?? sessionIndexByProperty[targetPropertyID] ?? [])
                .first { session in
                    guard let sessionID else { return true }
                    return session.id == sessionID
                }
        }
        let metadata = session.flatMap {
            try? localStore.loadSessionMetadata(propertyID: $0.propertyID, sessionID: $0.id)
        }
        let knownDates = [
            property?.updatedAt,
            session?.startedAt,
            session?.endedAt,
            session?.exportedAt,
            session?.firstDeliveredAt,
            session?.reExportExpiresAt,
            metadata?.startedAt,
            metadata?.endedAt,
            metadata?.exportedAt,
            metadata?.firstDeliveredAt,
            metadata?.reExportExpiresAt
        ].compactMap { $0 }

        return CanonicalReadLocalSnapshot(
            propertyID: property?.id ?? propertyID,
            orgID: metadata?.orgID ?? property?.orgId,
            sessionID: session?.id ?? sessionID,
            sessionPropertyID: session?.propertyID,
            sessionStatus: metadata?.status.rawValue ?? session?.status.rawValue,
            shotCount: metadata?.shots.count,
            issueObservationCount: metadata?.issues.count,
            guidedCount: metadata?.guidedShots.count,
            updatedAt: knownDates.max(),
            localPropertyFound: property != nil,
            localSessionFound: session != nil
        )
    }

    private func recordCanonicalReadDiagnostics(_ result: CanonicalReadDiagnosticsResult) {
        var diagnostics = localDiagnostics
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsAt = result.checkedAt
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsPropertyID = result.propertyID
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsSessionID = result.sessionID
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsResult = result.result.rawValue
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRemotePropertyFound = result.remotePropertyFound
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRemoteSessionFound = result.remoteSessionFound
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsLocalPropertyFound = result.localPropertyFound
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsLocalSessionFound = result.localSessionFound
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsCountParity = result.countParity
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsStatusParity = result.statusParity
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsParentOrgConsistent = result.parentOrgConsistent
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsParentPropertyConsistent = result.parentPropertyConsistent
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsLocalShotCount = result.localShotCount
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRemoteShotCount = result.remoteShotCount
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsLocalIssueObservationCount = result.localIssueObservationCount
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRemoteIssueObservationCount = result.remoteIssueObservationCount
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsLocalGuidedCount = result.localGuidedCount
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRemoteGuidedCount = result.remoteGuidedCount
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRemoteFreshnessAgeSeconds = result.remoteFreshnessAgeSeconds
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRemoteRevision = result.remoteRevision
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsRecommendation = result.canonicalRecommendation
        diagnostics.sessionSnapshotUpload.lastCanonicalReadDiagnosticsBlockedReason = result.blockedReason
        let parityGapReport = Self.makeNormalizedParityGapReport(
            checkedAt: result.checkedAt,
            canonicalDiagnostics: result,
            uploadDiagnostics: diagnostics.sessionSnapshotUpload
        )
        diagnostics.sessionSnapshotUpload.lastNormalizedParityGapTaxonomy = parityGapReport.taxonomy.map(\.rawValue)
        diagnostics.sessionSnapshotUpload.lastNormalizedParityCompleteness = parityGapReport.normalizedParityCompleteness
        diagnostics.sessionSnapshotUpload.lastRemoteShadowWriteCoverage = parityGapReport.remoteShadowWriteCoverage
        diagnostics.sessionSnapshotUpload.lastMissingRemoteEntityClassification = parityGapReport.missingRemoteEntityClassification
        diagnostics.sessionSnapshotUpload.lastLineageDivergenceSource = parityGapReport.lineageDivergenceSource
        diagnostics.sessionSnapshotUpload.lastParityRepairToolingRecommended = parityGapReport.parityRepairToolingRecommended
        diagnostics.sessionSnapshotUpload.lastCanonicalReadsRemainBlocked = parityGapReport.canonicalReadsRemainBlocked
        diagnostics.sessionSnapshotUpload.lastCanonicalReadRolloutBlockers = parityGapReport.rolloutBlockers
        diagnostics.sessionSnapshotUpload.lastCanonicalReadPrerequisitesBeforeAllowlist = parityGapReport.prerequisitesBeforeAllowlist
        diagnostics.sessionSnapshotUpload.lastCanonicalReadProbableCauses = parityGapReport.probableCauses
        diagnostics.sessionSnapshotUpload.lastParityRepairStrategies = parityGapReport.repairStrategies.map(\.rawValue)
        diagnostics.sessionSnapshotUpload.lastParityRepairSafetyRules = parityGapReport.repairSafetyRules
        diagnostics.sessionSnapshotUpload.lastParityDiagnosticsBeforeRepair = parityGapReport.diagnosticsBeforeRepair
        diagnostics.sessionSnapshotUpload.lastParityCompletenessScore = parityGapReport.parityCompletenessScore
        diagnostics.sessionSnapshotUpload.lastShadowWriteCoverageScore = parityGapReport.shadowWriteCoverageScore
        diagnostics.sessionSnapshotUpload.lastLineageConfidence = parityGapReport.lineageConfidence
        diagnostics.sessionSnapshotUpload.lastMissingChildCount = parityGapReport.missingChildCount
        diagnostics.sessionSnapshotUpload.lastReplayEligibility = parityGapReport.replayEligibility
        diagnostics.sessionSnapshotUpload.lastParityRepairRolloutPhase = parityGapReport.repairRolloutPhase
        let backfillPlan = Self.makeNormalizedBackfillReplayPlan(
            checkedAt: result.checkedAt,
            canonicalDiagnostics: result,
            parityReport: parityGapReport
        )
        diagnostics.sessionSnapshotUpload.lastNormalizedBackfillEligible = backfillPlan.eligible
        diagnostics.sessionSnapshotUpload.lastNormalizedBackfillBlockedReason = backfillPlan.blockedReason ?? "none"
        diagnostics.sessionSnapshotUpload.lastNormalizedBackfillPlannedSessionUpserts = backfillPlan.sessionRowUpsertNeeded ? 1 : 0
        diagnostics.sessionSnapshotUpload.lastNormalizedBackfillPlannedShotUpserts = backfillPlan.shotRowUpsertsNeeded
        diagnostics.sessionSnapshotUpload.lastNormalizedBackfillPlannedObservationUpserts = backfillPlan.observationIssueRowUpsertsNeeded
        diagnostics.sessionSnapshotUpload.lastNormalizedBackfillRemoteNewerConflictCount = backfillPlan.remoteNewerConflictCount
        diagnostics.sessionSnapshotUpload.lastNormalizedBackfillProductionBlocked = true
        let candidateDiagnostics = Self.makeCanonicalReadCandidateDiagnostics(
            checkedAt: result.checkedAt,
            configuration: canonicalReadCandidateConfiguration,
            targetClassification: supabaseConfiguration.targetClassification,
            canonicalDiagnostics: result,
            parityReport: parityGapReport,
            mediaRecoveryConfidence: Self.canonicalCandidateMediaRecoveryConfidence(
                uploadDiagnostics: diagnostics.sessionSnapshotUpload
            )
        )
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateAllowed = candidateDiagnostics.allowed
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateBlockedReason = candidateDiagnostics.blockedReason ?? "none"
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateEffectiveSourceRecommendation = candidateDiagnostics.effectiveSourceRecommendation
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateLocalFallbackAvailable = candidateDiagnostics.localFallbackAvailable
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateParityConfidence = candidateDiagnostics.parityConfidence
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateReplayConfidence = candidateDiagnostics.replayConfidence
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateMediaRecoveryConfidence = candidateDiagnostics.mediaRecoveryConfidence
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateRemoteStateReadable = candidateDiagnostics.remoteCandidateStateReadable
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateFlagEnabled = candidateDiagnostics.candidateFlagEnabled
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateOrgAllowlisted = candidateDiagnostics.orgAllowlisted
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidatePropertyAllowlisted = candidateDiagnostics.propertyAllowlisted
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateSessionAllowlisted = candidateDiagnostics.sessionAllowlisted
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateProductionWideEnabled = candidateDiagnostics.productionWideCanonicalReadsEnabled
        diagnostics.sessionSnapshotUpload.lastCanonicalReadCandidateWarnings = candidateDiagnostics.warnings
        localDiagnostics = diagnostics
    }

    @MainActor
    func buildCanonicalCandidateOverlayForSelectedSession(checkedAt: Date = Date()) async -> CanonicalCandidateOverlayBuildResult {
        let canonicalDiagnostics = await runCanonicalReadDiagnosticsForSelectedSession(checkedAt: checkedAt)
        let parityReport = Self.makeNormalizedParityGapReport(
            checkedAt: checkedAt,
            canonicalDiagnostics: canonicalDiagnostics,
            uploadDiagnostics: localDiagnostics.sessionSnapshotUpload
        )
        let candidateDiagnostics = Self.makeCanonicalReadCandidateDiagnostics(
            checkedAt: checkedAt,
            configuration: canonicalReadCandidateConfiguration,
            targetClassification: supabaseConfiguration.targetClassification,
            canonicalDiagnostics: canonicalDiagnostics,
            parityReport: parityReport,
            mediaRecoveryConfidence: Self.canonicalCandidateMediaRecoveryConfidence(
                uploadDiagnostics: localDiagnostics.sessionSnapshotUpload
            )
        )
        let result = Self.buildCanonicalCandidateOverlayTestOnly(
            checkedAt: checkedAt,
            targetClassification: supabaseConfiguration.targetClassification,
            canonicalDiagnostics: canonicalDiagnostics,
            parityReport: parityReport,
            candidateDiagnostics: candidateDiagnostics
        )
        let comparison = Self.makeCanonicalCandidateOverlayComparison(
            checkedAt: checkedAt,
            canonicalDiagnostics: canonicalDiagnostics,
            overlayResult: result,
            parityReport: parityReport
        )
        recordCanonicalCandidateOverlayBuild(result, comparison: comparison)
        return result
    }

