    nonisolated static func makeNormalizedParityGapReport(
        checkedAt: Date = Date(),
        canonicalDiagnostics: CanonicalReadDiagnosticsResult,
        uploadDiagnostics: SessionSnapshotUploadDiagnostics? = nil
    ) -> NormalizedParityGapReport {
        var taxonomy: [NormalizedParityGap] = []
        let localHasChildren = (canonicalDiagnostics.localShotCount ?? 0) > 0 ||
            (canonicalDiagnostics.localIssueObservationCount ?? 0) > 0 ||
            (canonicalDiagnostics.localGuidedCount ?? 0) > 0
        let remoteChildrenMissing = localHasChildren &&
            (canonicalDiagnostics.remoteShotCount ?? 0) == 0 &&
            (canonicalDiagnostics.remoteIssueObservationCount ?? 0) == 0
        if remoteChildrenMissing {
            taxonomy.append(.missingRemoteChildren)
        }
        if canonicalDiagnostics.parentOrgConsistent == false {
            taxonomy.append(.parentOrgDivergence)
        }
        if canonicalDiagnostics.result == .remoteMissing,
           canonicalDiagnostics.localSessionFound {
            taxonomy.append(.legacyLocalOnlySession)
        }
        if canonicalDiagnostics.result == .remoteMissing ||
            !canonicalDiagnostics.remotePropertyFound ||
            !canonicalDiagnostics.remoteSessionFound {
            taxonomy.append(.remoteMissing)
        }
        if canonicalDiagnostics.result == .localNewerConflict {
            taxonomy.append(.staleLocalProjection)
        }
        let hasShadowWriteFailure = (uploadDiagnostics?.failureCount ?? 0) > 0 ||
            trimmedNonEmpty(uploadDiagnostics?.lastUploadErrorMessage) != nil ||
            trimmedNonEmpty(uploadDiagnostics?.lastFailureMessage) != nil
        let remoteChildrenPartial = localHasChildren &&
            ((canonicalDiagnostics.remoteShotCount ?? 0) < (canonicalDiagnostics.localShotCount ?? 0) ||
             (canonicalDiagnostics.remoteIssueObservationCount ?? 0) < (canonicalDiagnostics.localIssueObservationCount ?? 0))
        if hasShadowWriteFailure || remoteChildrenPartial {
            taxonomy.append(.partialShadowWrite)
        }
        if taxonomy.isEmpty, canonicalDiagnostics.result != .remoteMatchesLocal {
            taxonomy.append(.unknownParityGap)
        }
        taxonomy = taxonomy.reduce(into: []) { partial, gap in
            if !partial.contains(gap) {
                partial.append(gap)
            }
        }

        let normalizedParityCompleteness: String
        if canonicalDiagnostics.result == .remoteMatchesLocal {
            normalizedParityCompleteness = "complete_for_checked_scope"
        } else if remoteChildrenMissing {
            normalizedParityCompleteness = "parents_present_children_missing"
        } else if canonicalDiagnostics.parentOrgConsistent == false {
            normalizedParityCompleteness = "blocked_by_parent_org_divergence"
        } else if canonicalDiagnostics.remotePropertyFound || canonicalDiagnostics.remoteSessionFound {
            normalizedParityCompleteness = "partial_remote_normalized_projection"
        } else {
            normalizedParityCompleteness = "remote_normalized_projection_missing"
        }

        let remoteShadowWriteCoverage: String
        if canonicalDiagnostics.remotePropertyFound && canonicalDiagnostics.remoteSessionFound && !remoteChildrenMissing {
            remoteShadowWriteCoverage = "property_session_children_present_for_checked_scope"
        } else if canonicalDiagnostics.remotePropertyFound && canonicalDiagnostics.remoteSessionFound {
            remoteShadowWriteCoverage = "property_session_present_child_shadow_writes_missing_or_unverified"
        } else if canonicalDiagnostics.remotePropertyFound || canonicalDiagnostics.remoteSessionFound {
            remoteShadowWriteCoverage = "partial_parent_shadow_write_coverage"
        } else {
            remoteShadowWriteCoverage = "no_remote_parent_shadow_write_coverage_for_checked_scope"
        }

        let missingRemoteEntityClassification: String
        if remoteChildrenMissing {
            missingRemoteEntityClassification = "remote_shots_and_observations_missing"
        } else if (canonicalDiagnostics.localShotCount ?? 0) > (canonicalDiagnostics.remoteShotCount ?? 0) {
            missingRemoteEntityClassification = "remote_shots_incomplete"
        } else if (canonicalDiagnostics.localIssueObservationCount ?? 0) > (canonicalDiagnostics.remoteIssueObservationCount ?? 0) {
            missingRemoteEntityClassification = "remote_observations_incomplete"
        } else if !canonicalDiagnostics.remotePropertyFound || !canonicalDiagnostics.remoteSessionFound {
            missingRemoteEntityClassification = "remote_parent_missing"
        } else {
            missingRemoteEntityClassification = "none_detected"
        }

        let lineageDivergenceSource: String
        if canonicalDiagnostics.parentOrgConsistent == false {
            lineageDivergenceSource = "property_or_session_org_id_differs_from_local_or_active_org"
        } else if canonicalDiagnostics.parentPropertyConsistent == false {
            lineageDivergenceSource = "remote_session_property_id_differs_from_local_property"
        } else {
            lineageDivergenceSource = "none_detected"
        }

        var probableCauses: [String] = []
        if taxonomy.contains(.parentOrgDivergence) {
            probableCauses.append("org_drift_history_or_stale_remote_parent_lineage")
        }
        if taxonomy.contains(.missingRemoteChildren) {
            probableCauses.append("shots_or_observations_were_local_only_or_not_backfilled_to_normalized_rows")
        }
        if taxonomy.contains(.partialShadowWrite) {
            probableCauses.append("incomplete_shadow_write_coverage_or_failed_remote_write")
        }
        if taxonomy.contains(.legacyLocalOnlySession) {
            probableCauses.append("session_predates_shadow_write_coverage_or_was_created_offline")
        }
        if taxonomy.contains(.remoteMissing) {
            probableCauses.append("remote_parent_rows_were_never_written_or_are_not_visible_under_current_RLS")
        }
        if taxonomy.contains(.staleLocalProjection) {
            probableCauses.append("local_metadata_projection_is_newer_than_remote_normalized_rows")
        }
        if taxonomy.contains(.unknownParityGap) {
            probableCauses.append("insufficient_diagnostics_to_identify_gap")
        }

        var rolloutBlockers: [String] = []
        if canonicalDiagnostics.parentOrgConsistent == false {
            rolloutBlockers.append("parent_org_consistency_not_verified")
        }
        if canonicalDiagnostics.countParity == false || remoteChildrenMissing {
            rolloutBlockers.append("remote_child_row_count_parity_not_verified")
        }
        if canonicalDiagnostics.result != .remoteMatchesLocal && canonicalDiagnostics.result != .remoteNewerCandidate {
            rolloutBlockers.append("canonical_read_diagnostic_result_blocks_remote_candidate")
        }

        let prerequisites = [
            "remote_property_and_session_org_lineage_must_match_active_local_scope",
            "remote_shot_rows_must_match_local_session_shots",
            "remote_observation_or_issue_rows_must_match_local_session_issues_when_represented",
            "shadow_write_failures_and_RLS_debt_must_be_zero_or_acknowledged_as_historical",
            "parity_repair_or_backfill_plan_must_be_defined_before_allowlisted_canonical_reads"
        ]
        let localShotCount = canonicalDiagnostics.localShotCount ?? 0
        let remoteShotCount = canonicalDiagnostics.remoteShotCount ?? 0
        let localObservationCount = canonicalDiagnostics.localIssueObservationCount ?? 0
        let remoteObservationCount = canonicalDiagnostics.remoteIssueObservationCount ?? 0
        let localChildCount = localShotCount + localObservationCount
        let remoteChildCount = min(remoteShotCount, localShotCount) + min(remoteObservationCount, localObservationCount)
        let missingChildCount = max(localShotCount - remoteShotCount, 0) + max(localObservationCount - remoteObservationCount, 0)
        let parentCount = 2
        let presentParentCount = (canonicalDiagnostics.remotePropertyFound ? 1 : 0) + (canonicalDiagnostics.remoteSessionFound ? 1 : 0)
        let parityCompletenessScore: Double
        if localChildCount == 0 {
            parityCompletenessScore = Double(presentParentCount) / Double(parentCount)
        } else {
            parityCompletenessScore = Double(presentParentCount + remoteChildCount) / Double(parentCount + localChildCount)
        }
        let shadowWriteCoverageScore = localChildCount == 0 ? parityCompletenessScore : Double(remoteChildCount) / Double(localChildCount)
        let lineageConfidence: String
        if canonicalDiagnostics.parentOrgConsistent == true && canonicalDiagnostics.parentPropertyConsistent == true {
            lineageConfidence = "high"
        } else if canonicalDiagnostics.parentOrgConsistent == false || canonicalDiagnostics.parentPropertyConsistent == false {
            lineageConfidence = "blocked"
        } else {
            lineageConfidence = "unknown"
        }
        let replayEligibility: String
        if canonicalDiagnostics.parentOrgConsistent == false || canonicalDiagnostics.parentPropertyConsistent == false {
            replayEligibility = "blocked_until_parent_lineage_reconciled"
        } else if taxonomy.contains(.legacyLocalOnlySession) || taxonomy.contains(.remoteMissing) {
            replayEligibility = "requires_manual_parent_backfill_plan"
        } else if taxonomy.contains(.missingRemoteChildren) || taxonomy.contains(.partialShadowWrite) {
            replayEligibility = "candidate_for_test_only_shadow_write_replay_after_snapshot_verification"
        } else if taxonomy.contains(.staleLocalProjection) {
            replayEligibility = "compare_newer_local_projection_before_any_replay"
        } else {
            replayEligibility = "not_needed"
        }
        var repairStrategies: [NormalizedParityRepairStrategy] = []
        if taxonomy.isEmpty {
            repairStrategies.append(.noOpBlock)
        }
        if taxonomy.contains(.parentOrgDivergence) {
            repairStrategies.append(.lineageReconciliation)
            repairStrategies.append(.noOpBlock)
        }
        if taxonomy.contains(.remoteMissing) || taxonomy.contains(.legacyLocalOnlySession) {
            repairStrategies.append(.remoteBackfill)
        }
        if taxonomy.contains(.missingRemoteChildren) {
            repairStrategies.append(.childRowRegeneration)
            repairStrategies.append(.remoteBackfill)
        }
        if taxonomy.contains(.partialShadowWrite) {
            repairStrategies.append(.shadowWriteReplay)
        }
        if taxonomy.contains(.staleLocalProjection) {
            repairStrategies.append(.localOnlyRepair)
            repairStrategies.append(.noOpBlock)
        }
        if taxonomy.contains(.unknownParityGap) {
            repairStrategies.append(.noOpBlock)
        }
        repairStrategies = repairStrategies.reduce(into: []) { partial, strategy in
            if !partial.contains(strategy) {
                partial.append(strategy)
            }
        }
        let repairSafetyRules = [
            "no_blind_overwrite",
            "preserve_newer_remote_rows",
            "preserve_newer_local_state",
            "require_parent_consistency_first",
            "operator_manual_gating_required",
            "snapshot_or_checksum_evidence_required_before_remote_backfill",
            "production_repair_requires_explicit_allowlist_and_separate_approval"
        ]
        let diagnosticsBeforeRepair = [
            "parity_completeness_score",
            "shadow_write_coverage_score",
            "lineage_confidence",
            "missing_child_counts",
            "replay_eligibility",
            "queued_mutation_or_RLS_debt",
            "snapshot_checksum_and_parent_verification"
        ]
        let repairRolloutPhase: String
        if taxonomy.isEmpty {
            repairRolloutPhase = "canonical_read_candidate_readiness"
        } else if lineageConfidence == "blocked" {
            repairRolloutPhase = "diagnostics_only"
        } else if repairStrategies.contains(.shadowWriteReplay) || repairStrategies.contains(.childRowRegeneration) {
            repairRolloutPhase = "test_only_replay_backfill"
        } else if repairStrategies.contains(.remoteBackfill) {
            repairRolloutPhase = "allowlisted_manual_repair_tooling"
        } else {
            repairRolloutPhase = "diagnostics_only"
        }

        return NormalizedParityGapReport(
            checkedAt: checkedAt,
            propertyID: canonicalDiagnostics.propertyID,
            sessionID: canonicalDiagnostics.sessionID,
            taxonomy: taxonomy,
            normalizedParityCompleteness: normalizedParityCompleteness,
            remoteShadowWriteCoverage: remoteShadowWriteCoverage,
            missingRemoteEntityClassification: missingRemoteEntityClassification,
            lineageDivergenceSource: lineageDivergenceSource,
            probableCauses: probableCauses,
            rolloutBlockers: rolloutBlockers,
            repairStrategies: repairStrategies,
            repairSafetyRules: repairSafetyRules,
            diagnosticsBeforeRepair: diagnosticsBeforeRepair,
            parityCompletenessScore: max(0, min(parityCompletenessScore, 1)),
            shadowWriteCoverageScore: max(0, min(shadowWriteCoverageScore, 1)),
            lineageConfidence: lineageConfidence,
            missingChildCount: missingChildCount,
            replayEligibility: replayEligibility,
            repairRolloutPhase: repairRolloutPhase,
            parityRepairToolingRecommended: !taxonomy.isEmpty && taxonomy != [.staleLocalProjection],
            canonicalReadsRemainBlocked: !rolloutBlockers.isEmpty,
            prerequisitesBeforeAllowlist: prerequisites,
            noBehaviorChangedText: "No behavior changed: this parity gap report is read-only diagnostics and does not switch canonical reads, hydrate data, restore files, download media, change export, change seal, change sync, change iCloud behavior, loosen RLS, repair parity, backfill rows, or mutate local/remote data."
        )
    }

    nonisolated static func normalizedParityGapReportText(_ report: NormalizedParityGapReport) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Remote Normalized Parity Gap")
        lines.append("Checked: \(report.checkedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Property ID: \(report.propertyID?.uuidString ?? "none")")
        lines.append("Session ID: \(report.sessionID?.uuidString ?? "none")")
        lines.append("Taxonomy: \(report.taxonomy.isEmpty ? "none" : report.taxonomy.map(\.rawValue).joined(separator: ", "))")
        lines.append("Normalized Parity Completeness: \(report.normalizedParityCompleteness)")
        lines.append("Remote Shadow-Write Coverage: \(report.remoteShadowWriteCoverage)")
        lines.append("Missing Remote Entity Classification: \(report.missingRemoteEntityClassification)")
        lines.append("Lineage Divergence Source: \(report.lineageDivergenceSource)")
        lines.append("Repair Strategies: \(report.repairStrategies.isEmpty ? "none" : report.repairStrategies.map(\.rawValue).joined(separator: ", "))")
        lines.append("Parity Completeness Score: \(String(format: "%.2f", report.parityCompletenessScore))")
        lines.append("Shadow-Write Coverage Score: \(String(format: "%.2f", report.shadowWriteCoverageScore))")
        lines.append("Lineage Confidence: \(report.lineageConfidence)")
        lines.append("Missing Child Count: \(report.missingChildCount)")
        lines.append("Replay Eligibility: \(report.replayEligibility)")
        lines.append("Repair Rollout Phase: \(report.repairRolloutPhase)")
        lines.append("Parity Repair Tooling Recommended: \(report.parityRepairToolingRecommended)")
        lines.append("Canonical Reads Remain Blocked: \(report.canonicalReadsRemainBlocked)")
        lines.append(report.noBehaviorChangedText)
        lines.append("")
        lines.append("Probable Causes")
        for cause in report.probableCauses {
            lines.append("- \(diagnosticsPreviewText(cause, maxLength: 120) ?? "unknown")")
        }
        lines.append("")
        lines.append("Rollout Blockers")
        for blocker in report.rolloutBlockers {
            lines.append("- \(diagnosticsPreviewText(blocker, maxLength: 120) ?? "none")")
        }
        lines.append("")
        lines.append("Repair Safety Rules")
        for rule in report.repairSafetyRules {
            lines.append("- \(diagnosticsPreviewText(rule, maxLength: 140) ?? "unknown")")
        }
        lines.append("")
        lines.append("Diagnostics Before Repair")
        for diagnostic in report.diagnosticsBeforeRepair {
            lines.append("- \(diagnosticsPreviewText(diagnostic, maxLength: 140) ?? "unknown")")
        }
        lines.append("")
        lines.append("Prerequisites Before Allowlist")
        for prerequisite in report.prerequisitesBeforeAllowlist {
            lines.append("- \(diagnosticsPreviewText(prerequisite, maxLength: 140) ?? "unknown")")
        }
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeNormalizedBackfillReplayPlan(
        checkedAt: Date = Date(),
        canonicalDiagnostics: CanonicalReadDiagnosticsResult,
        parityReport: NormalizedParityGapReport? = nil,
        useLocalAsExplicitSource: Bool = false
    ) -> NormalizedBackfillReplayPlan {
        let report = parityReport ?? makeNormalizedParityGapReport(
            checkedAt: checkedAt,
            canonicalDiagnostics: canonicalDiagnostics
        )
        let localShotCount = canonicalDiagnostics.localShotCount ?? 0
        let remoteShotCount = canonicalDiagnostics.remoteShotCount ?? 0
        let localObservationCount = canonicalDiagnostics.localIssueObservationCount ?? 0
        let remoteObservationCount = canonicalDiagnostics.remoteIssueObservationCount ?? 0
        let shotUpsertsNeeded = max(localShotCount - remoteShotCount, 0)
        let observationUpsertsNeeded = max(localObservationCount - remoteObservationCount, 0)
        let sessionRowUpsertNeeded = canonicalDiagnostics.localSessionFound && !canonicalDiagnostics.remoteSessionFound
        let parentLineageRepairNeeded = canonicalDiagnostics.parentOrgConsistent == false ||
            canonicalDiagnostics.parentPropertyConsistent == false
        let remoteNewerConflictCount = canonicalDiagnostics.result == .remoteNewerCandidate ? 1 : 0
        let plannedCount = (sessionRowUpsertNeeded ? 1 : 0) + shotUpsertsNeeded + observationUpsertsNeeded

        var blockedReasons: [String] = []
        if canonicalDiagnostics.propertyID == nil || canonicalDiagnostics.sessionID == nil {
            blockedReasons.append("selected_single_session_required")
        }
        if !canonicalDiagnostics.localPropertyFound || !canonicalDiagnostics.localSessionFound {
            blockedReasons.append("local_property_session_identity_not_confirmed")
        }
        if canonicalDiagnostics.result == .remoteNewerCandidate {
            blockedReasons.append("remote_newer_conflict_blocks_backfill")
        }
        if canonicalDiagnostics.result == .localNewerConflict && !useLocalAsExplicitSource {
            blockedReasons.append("local_newer_ambiguity_requires_explicit_local_source")
        }
        if canonicalDiagnostics.parentOrgConsistent == nil || canonicalDiagnostics.parentPropertyConsistent == nil {
            blockedReasons.append("parent_lineage_unable_to_verify")
        }
        if parentLineageRepairNeeded && !report.repairStrategies.contains(.lineageReconciliation) {
            blockedReasons.append("parent_lineage_repair_not_planned")
        }
        if plannedCount == 0 && !parentLineageRepairNeeded {
            blockedReasons.append("no_missing_normalized_rows_planned")
        }

        let blockedReason = blockedReasons.isEmpty ? nil : blockedReasons.joined(separator: ", ")
        return NormalizedBackfillReplayPlan(
            checkedAt: checkedAt,
            propertyID: canonicalDiagnostics.propertyID,
            sessionID: canonicalDiagnostics.sessionID,
            eligible: blockedReason == nil,
            blockedReason: blockedReason,
            evidenceSourcePriority: [
                "verified_snapshot_payload",
                "local_session_metadata",
                "local_shot_issue_guided_metadata"
            ],
            parentLineageRepairNeeded: parentLineageRepairNeeded,
            sessionRowUpsertNeeded: sessionRowUpsertNeeded,
            shotRowUpsertsNeeded: shotUpsertsNeeded,
            observationIssueRowUpsertsNeeded: observationUpsertsNeeded,
            skippedReason: blockedReason,
            remoteNewerConflictCount: remoteNewerConflictCount,
            canonicalReadsRemainBlocked: true,
            noBehaviorChangedText: "No behavior changed: this test-only normalized backfill/replay plan is read-only by default and does not switch canonical reads, hydrate data, restore local state, run bulk backfill, change export, change seal, change sync, change media, change iCloud behavior, loosen RLS, delete data, or mutate production data."
        )
    }

    nonisolated static func executeNormalizedBackfillReplayTestOnly(
        plan: NormalizedBackfillReplayPlan,
        targetClassification: SupabaseRuntimeConfiguration.TargetClassification,
        operation: (NormalizedBackfillEntityKind, Int) async throws -> NormalizedBackfillEntityResult
    ) async -> NormalizedBackfillReplayExecutionResult {
        guard targetClassification == .localDev || targetClassification == .approvedStaging else {
            let productionBlocked = targetClassification == .approvedProductionValidation || targetClassification == .remote
            return NormalizedBackfillReplayExecutionResult(
                allowed: false,
                blockedReason: productionBlocked ? "production_backfill_blocked" : "target_environment_not_allowed",
                productionBlocked: productionBlocked,
                attemptedEntityCount: 0,
                executedEntityCount: 0,
                skippedEntityCount: 0,
                failedEntityCount: 0,
                remoteNewerConflictCount: plan.remoteNewerConflictCount,
                results: [],
                noBehaviorChangedText: "Production normalized backfill remains blocked. No canonical reads were switched and no production repair/backfill was executed."
            )
        }
        guard plan.eligible else {
            return NormalizedBackfillReplayExecutionResult(
                allowed: false,
                blockedReason: plan.blockedReason ?? "plan_not_eligible",
                productionBlocked: false,
                attemptedEntityCount: 0,
                executedEntityCount: 0,
                skippedEntityCount: 0,
                failedEntityCount: 0,
                remoteNewerConflictCount: plan.remoteNewerConflictCount,
                results: [],
                noBehaviorChangedText: "No normalized backfill executed because the test-only plan was not eligible."
            )
        }

        let plannedOperations: [(NormalizedBackfillEntityKind, Int)] = [
            (.session, plan.sessionRowUpsertNeeded ? 1 : 0),
            (.shot, plan.shotRowUpsertsNeeded),
            (.observation, plan.observationIssueRowUpsertsNeeded)
        ].filter { $0.1 > 0 }

        var results: [NormalizedBackfillEntityResult] = []
        for (kind, count) in plannedOperations {
            do {
                results.append(try await operation(kind, count))
            } catch {
                results.append(NormalizedBackfillEntityResult(
                    kind: kind,
                    attemptedCount: count,
                    upsertedCount: 0,
                    skippedCount: 0,
                    failedCount: count,
                    message: sanitizedDiagnosticsErrorMessage(error.localizedDescription)
                ))
            }
        }
        let attempted = results.reduce(0) { $0 + $1.attemptedCount }
        let executed = results.reduce(0) { $0 + $1.upsertedCount }
        let skipped = results.reduce(0) { $0 + $1.skippedCount }
        let failed = results.reduce(0) { $0 + $1.failedCount }
        return NormalizedBackfillReplayExecutionResult(
            allowed: true,
            blockedReason: nil,
            productionBlocked: false,
            attemptedEntityCount: attempted,
            executedEntityCount: executed,
            skippedEntityCount: skipped,
            failedEntityCount: failed,
            remoteNewerConflictCount: plan.remoteNewerConflictCount,
            results: results,
            noBehaviorChangedText: "Test-only normalized backfill/replay executed only through the supplied local/staging operation hook. No canonical reads were switched, no bulk backfill was run, no local state was hydrated/restored, and production backfill remains blocked."
        )
    }

    nonisolated static func validateNormalizedBackfillReplay(
        before: CanonicalReadDiagnosticsResult,
        after: CanonicalReadDiagnosticsResult,
        execution: NormalizedBackfillReplayExecutionResult
    ) -> NormalizedBackfillReplayValidationResult {
        let beforeReport = makeNormalizedParityGapReport(
            checkedAt: before.checkedAt,
            canonicalDiagnostics: before
        )
        let afterReport = makeNormalizedParityGapReport(
            checkedAt: after.checkedAt,
            canonicalDiagnostics: after
        )
        let beforeRank = canonicalDiagnosticRecommendationRank(before.result)
        let afterRank = canonicalDiagnosticRecommendationRank(after.result)
        var remainingBlockers = afterReport.rolloutBlockers
        if after.parentOrgConsistent != true {
            remainingBlockers.append("parent_org_consistency_not_verified_after_replay")
        }
        if after.countParity != true {
            remainingBlockers.append("count_parity_not_verified_after_replay")
        }
        if execution.failedEntityCount > 0 {
            remainingBlockers.append("replay_entity_failures_present")
        }
        if execution.remoteNewerConflictCount > 0 {
            remainingBlockers.append("remote_newer_conflict_present")
        }
        remainingBlockers = remainingBlockers.reduce(into: []) { partial, blocker in
            if !partial.contains(blocker) {
                partial.append(blocker)
            }
        }

        return NormalizedBackfillReplayValidationResult(
            beforeRecommendation: before.canonicalRecommendation,
            afterRecommendation: after.canonicalRecommendation,
            beforeParityCompletenessScore: beforeReport.parityCompletenessScore,
            afterParityCompletenessScore: afterReport.parityCompletenessScore,
            beforeMissingChildCount: beforeReport.missingChildCount,
            afterMissingChildCount: afterReport.missingChildCount,
            parityCompletenessImproved: afterReport.parityCompletenessScore > beforeReport.parityCompletenessScore,
            missingChildCountDecreased: afterReport.missingChildCount < beforeReport.missingChildCount,
            recommendationImproved: afterRank > beforeRank ||
                after.canonicalRecommendation != before.canonicalRecommendation,
            parentOrgConsistencyRepaired: before.parentOrgConsistent == false && after.parentOrgConsistent == true,
            replayExecutedEntityCount: execution.executedEntityCount,
            replaySkippedEntityCount: execution.skippedEntityCount,
            replayFailedEntityCount: execution.failedEntityCount,
            remoteNewerConflictCount: execution.remoteNewerConflictCount,
            remainingCanonicalBlockers: remainingBlockers,
            noBehaviorChangedText: "No behavior changed: this parity replay validation only compares before/after diagnostics and test-only replay results. It does not switch canonical reads, enable production remote reads, hydrate or restore local state, change export, change seal, change sync, change media, change iCloud behavior, loosen RLS, delete data, or mutate production data."
        )
    }

    nonisolated static func makeProductionSingleSessionActivationGateDiagnostics(
        checkedAt: Date = Date(),
        policy: ProductionSingleSessionActivationGatePolicy = .disabled,
        approval: ProductionCohortOperatorApprovalDiagnostics? = nil,
        targetClassification: SupabaseRuntimeConfiguration.TargetClassification,
        diagnostics: SessionSnapshotUploadDiagnostics
    ) -> ProductionSingleSessionActivationGateDiagnostics {
        let orgID = approval?.approvedScope.orgID
        let propertyID = diagnostics.lastCanonicalCandidateOverlayPropertyID ?? diagnostics.lastCanonicalReadDiagnosticsPropertyID
        let sessionID = diagnostics.lastCanonicalCandidateOverlaySessionID ?? diagnostics.lastCanonicalReadDiagnosticsSessionID
        let selectedScope = ProductionCohortApprovalScope(
            orgID: orgID,
            propertyID: propertyID,
            sessionID: sessionID
        )
        let approvedScope = approval?.approvedScope ?? ProductionCohortApprovalScope(
            orgID: nil,
            propertyID: nil,
            sessionID: nil
        )

        let exactScopeMatch = orgID.map { policy.orgAllowlist == Set([$0]) } ?? false &&
            propertyID.map { policy.propertyAllowlist == Set([$0]) } ?? false &&
            sessionID.map { policy.sessionAllowlist == Set([$0]) } ?? false
        let approvalFresh = approval.map { !$0.staleApproval && $0.state == .approved } ?? false
        let operatorApprovalMatch = approvalFresh &&
            approval?.approvedScope.orgID == orgID &&
            approval?.approvedScope.propertyID == propertyID &&
            approval?.approvedScope.sessionID == sessionID
        let productionWideDisabledConfirmed = !diagnostics.lastCanonicalReadCandidateProductionWideEnabled
        let candidateEvidencePasses = diagnostics.lastCanonicalReadDiagnosticsResult == CanonicalReadDiagnosticResult.remoteMatchesLocal.rawValue ||
            diagnostics.lastCanonicalReadDiagnosticsRecommendation == "remote_candidate_after_replay_validation"
        let noParentMismatch = diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent == true &&
            diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent == true
        let noMissingChildren = diagnostics.lastMissingChildCount == 0 &&
            !diagnostics.lastNormalizedParityGapTaxonomy.contains("missing_remote_children")
        let noRemoteNewerConflict = diagnostics.lastCanonicalReadDiagnosticsResult != CanonicalReadDiagnosticResult.remoteNewerCandidate.rawValue &&
            diagnostics.lastNormalizedBackfillRemoteNewerConflictCount == 0
        let candidateDiagnosticsPass = diagnostics.lastCanonicalReadCandidateFlagEnabled &&
            diagnostics.lastCanonicalReadCandidateOrgAllowlisted &&
            diagnostics.lastCanonicalReadCandidatePropertyAllowlisted &&
            diagnostics.lastCanonicalReadCandidateSessionAllowlisted &&
            diagnostics.lastCanonicalReadCandidateParityConfidence >= policy.parityConfidenceThreshold &&
            diagnostics.lastCanonicalReadCandidateReplayConfidence >= policy.replayConfidenceThreshold &&
            diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable &&
            candidateEvidencePasses &&
            noParentMismatch &&
            noMissingChildren &&
            noRemoteNewerConflict
        let overlayVerified = diagnostics.lastCanonicalCandidateOverlayBuilt &&
            diagnostics.lastCanonicalCandidateOverlayAllowed
        let comparisonVerified = diagnostics.lastCanonicalCandidateOverlayComparisonResult == CanonicalCandidateOverlayComparisonResult.candidateMatchesLocal.rawValue
        let activationReadinessPass = diagnostics.lastCanonicalCandidateActivationAllowed ||
            (
                overlayVerified &&
                comparisonVerified &&
                diagnostics.lastCanonicalCandidateOverlayRollbackAvailable &&
                diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable &&
                noParentMismatch &&
                noMissingChildren &&
                noRemoteNewerConflict
            )
        let rollbackPreflightPassed = diagnostics.lastCanonicalCandidateOverlayRollbackAvailable &&
            diagnostics.lastCanonicalCandidateActivationRollbackAvailable &&
            diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable
        let preflightPassed = productionWideDisabledConfirmed &&
            candidateDiagnosticsPass &&
            overlayVerified &&
            comparisonVerified &&
            activationReadinessPass &&
            rollbackPreflightPassed

        var blockers: [String] = []
        if targetClassification != .approvedProductionValidation {
            blockers.append("target_not_production_validation")
        }
        if !policy.productionSingleSessionCanonicalActivationEnabled {
            blockers.append("production_single_session_canonical_activation_disabled")
        }
        if !exactScopeMatch {
            blockers.append("exact_scope_match_required")
        }
        if !operatorApprovalMatch {
            blockers.append("operator_approval_exact_scope_required")
        }
        if approval?.state == .expired || approval?.staleApproval == true {
            blockers.append("operator_approval_expired")
        }
        if approval == nil {
            blockers.append("operator_approval_missing")
        }
        if !productionWideDisabledConfirmed {
            blockers.append("production_wide_canonical_reads_not_disabled")
        }
        if !candidateDiagnosticsPass {
            blockers.append("candidate_diagnostics_not_passed")
        }
        if !overlayVerified {
            blockers.append("overlay_not_verified")
        }
        if !comparisonVerified {
            blockers.append("comparison_not_candidate_matches_local")
        }
        if !activationReadinessPass {
            blockers.append("activation_readiness_not_passed")
        }
        if !rollbackPreflightPassed {
            blockers.append("rollback_preflight_not_passed")
        }
        if !noParentMismatch {
            blockers.append("parent_org_or_property_divergence")
        }
        if !noMissingChildren {
            blockers.append("missing_remote_children")
        }
        if !noRemoteNewerConflict {
            blockers.append("remote_newer_conflict")
        }

        let dedupedBlockers = Array(Set(blockers)).sorted()
        return ProductionSingleSessionActivationGateDiagnostics(
            productionSingleSessionActivationGateEnabled: policy.productionSingleSessionCanonicalActivationEnabled,
            gateAllowed: dedupedBlockers.isEmpty,
            gateBlockedReason: dedupedBlockers.isEmpty ? nil : dedupedBlockers.joined(separator: ", "),
            exactScopeMatch: exactScopeMatch,
            operatorApprovalMatch: operatorApprovalMatch,
            preflightPassed: preflightPassed,
            rollbackPreflightPassed: rollbackPreflightPassed,
            productionWideDisabledConfirmed: productionWideDisabledConfirmed,
            selectedScope: selectedScope,
            approvedScope: approvedScope,
            noBehaviorChangedText: "No behavior changed: production single-session activation gate is default-off readiness gating only. It does not activate production sessions, enable production-wide canonical reads, enable cohort activation, mutate production data, remove local/iCloud fallback, change export, seal, sync, media, or iCloud behavior, loosen RLS, or delete data."
        )
    }

    nonisolated static func productionSingleSessionActivationGateReportText(
        _ diagnostics: ProductionSingleSessionActivationGateDiagnostics
    ) -> String {
        var lines: [String] = []
        lines.append("Production Single-Session Activation Gate")
        lines.append("- production_single_session_activation_gate_enabled: \(diagnostics.productionSingleSessionActivationGateEnabled)")
        lines.append("- gate_allowed: \(diagnostics.gateAllowed)")
        lines.append("- gate_blocked_reason: \(diagnosticsPreviewText(diagnostics.gateBlockedReason, maxLength: 220) ?? "none")")
        lines.append("- exact_scope_match: \(diagnostics.exactScopeMatch)")
        lines.append("- operator_approval_match: \(diagnostics.operatorApprovalMatch)")
        lines.append("- preflight_passed: \(diagnostics.preflightPassed)")
        lines.append("- rollback_preflight_passed: \(diagnostics.rollbackPreflightPassed)")
        lines.append("- production_wide_disabled_confirmed: \(diagnostics.productionWideDisabledConfirmed)")
        lines.append("- selected_scope: \(diagnostics.selectedScope.description)")
        lines.append("- approved_scope: \(diagnostics.approvedScope.description)")
        lines.append(diagnostics.noBehaviorChangedText)
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeCanonicalReadCandidateDiagnostics(
        checkedAt: Date = Date(),
        configuration: CanonicalReadCandidateConfiguration,
        targetClassification: SupabaseRuntimeConfiguration.TargetClassification,
        canonicalDiagnostics: CanonicalReadDiagnosticsResult,
        parityReport: NormalizedParityGapReport,
        replayValidation: NormalizedBackfillReplayValidationResult? = nil,
        mediaRecoveryConfidence: Double = 1,
        productionActivationGate: ProductionSingleSessionActivationGateDiagnostics? = nil
    ) -> CanonicalReadCandidateDiagnostics {
        let orgAllowlisted = canonicalDiagnostics.activeOrganizationID.map { configuration.orgAllowlist.contains($0) } ?? false
        let propertyAllowlisted = canonicalDiagnostics.propertyID.map { configuration.propertyAllowlist.contains($0) } ?? false
        let sessionAllowlisted = canonicalDiagnostics.sessionID.map { configuration.sessionAllowlist.contains($0) } ?? false
        let localFallbackAvailable = canonicalDiagnostics.localPropertyFound || canonicalDiagnostics.localSessionFound
        let replayConfidence: Double
        if let replayValidation {
            replayConfidence = replayValidation.remainingCanonicalBlockers.isEmpty &&
                replayValidation.replayFailedEntityCount == 0 &&
                replayValidation.remoteNewerConflictCount == 0 ? 1 : 0
        } else if canonicalDiagnostics.canonicalRecommendation == "remote_candidate_after_replay_validation" {
            replayConfidence = 1
        } else {
            replayConfidence = canonicalDiagnostics.result == .remoteMatchesLocal ? 1 : 0
        }
        let parityConfidence = parityReport.parityCompletenessScore
        let remoteCandidateEvidencePasses = canonicalDiagnostics.result == .remoteMatchesLocal ||
            canonicalDiagnostics.canonicalRecommendation == "remote_candidate_after_replay_validation"
        var blockers: [String] = []

        if !configuration.enabled {
            blockers.append("canonical_read_candidate_flag_disabled")
        }
        switch targetClassification {
        case .localDev, .approvedStaging:
            break
        case .approvedProductionValidation:
            if productionActivationGate?.gateAllowed != true {
                blockers.append("production_canonical_read_candidate_requires_separate_explicit_approval")
            }
        case .remote:
            blockers.append("random_remote_canonical_read_candidate_blocked")
        case .missing, .invalid:
            blockers.append("supabase_target_not_verified")
        }
        if !orgAllowlisted {
            blockers.append("org_not_allowlisted")
        }
        if !propertyAllowlisted {
            blockers.append("property_not_allowlisted")
        }
        if !sessionAllowlisted {
            blockers.append("session_not_allowlisted")
        }
        if !remoteCandidateEvidencePasses {
            blockers.append("canonical_read_diagnostic_result_not_candidate")
        }
        if parityConfidence < configuration.parityCompletenessThreshold {
            blockers.append("parity_completeness_below_threshold")
        }
        if canonicalDiagnostics.parentOrgConsistent != true || canonicalDiagnostics.parentPropertyConsistent != true {
            blockers.append("parent_org_or_property_divergence")
        }
        if parityReport.missingChildCount > 0 || parityReport.taxonomy.contains(.missingRemoteChildren) {
            blockers.append("missing_remote_children")
        }
        if canonicalDiagnostics.result == .remoteNewerCandidate {
            blockers.append("remote_newer_conflict")
        }
        if mediaRecoveryConfidence < configuration.mediaRecoveryConfidenceThreshold {
            blockers.append("media_recovery_confidence_below_threshold")
        }
        if !localFallbackAvailable {
            blockers.append("local_fallback_unavailable")
        }

        let allowed = blockers.isEmpty
        let effectiveSourceRecommendation = allowed
            ? "remote_normalized_candidate_with_local_fallback"
            : "local_first_block_canonical_read"
        return CanonicalReadCandidateDiagnostics(
            checkedAt: checkedAt,
            propertyID: canonicalDiagnostics.propertyID,
            sessionID: canonicalDiagnostics.sessionID,
            activeOrganizationID: canonicalDiagnostics.activeOrganizationID,
            targetClassification: targetClassification,
            candidateFlagEnabled: configuration.enabled,
            orgAllowlisted: orgAllowlisted,
            propertyAllowlisted: propertyAllowlisted,
            sessionAllowlisted: sessionAllowlisted,
            allowed: allowed,
            blockedReason: blockers.isEmpty ? nil : blockers.joined(separator: ", "),
            effectiveSourceRecommendation: effectiveSourceRecommendation,
            localFallbackAvailable: localFallbackAvailable,
            parityConfidence: max(0, min(parityConfidence, 1)),
            replayConfidence: max(0, min(replayConfidence, 1)),
            mediaRecoveryConfidence: max(0, min(mediaRecoveryConfidence, 1)),
            remoteCandidateStateReadable: allowed,
            productionWideCanonicalReadsEnabled: false,
            warnings: [
                "test_only_allowlisted_canonical_read_candidate",
                "local_fallback_retained",
                "not_production_wide",
                "does_not_discard_local_state"
            ],
            noBehaviorChangedText: "No behavior changed: allowlisted canonical-read candidate diagnostics do not switch global reads, discard local state, hydrate local data, change export, change seal, change sync, change media, change iCloud behavior, loosen RLS, delete data, or mutate production data."
        )
    }

    nonisolated static func canonicalReadCandidateDiagnosticsText(_ diagnostics: CanonicalReadCandidateDiagnostics) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Allowlisted Canonical Read Candidate")
        lines.append("Checked: \(diagnostics.checkedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Property ID: \(diagnostics.propertyID?.uuidString ?? "none")")
        lines.append("Session ID: \(diagnostics.sessionID?.uuidString ?? "none")")
        lines.append("Target: \(diagnostics.targetClassification.rawValue)")
        lines.append("Candidate Flag Enabled: \(diagnostics.candidateFlagEnabled)")
        lines.append("Org Allowlisted: \(diagnostics.orgAllowlisted)")
        lines.append("Property Allowlisted: \(diagnostics.propertyAllowlisted)")
        lines.append("Session Allowlisted: \(diagnostics.sessionAllowlisted)")
        lines.append("Canonical Candidate Allowed: \(diagnostics.allowed)")
        lines.append("Candidate Blocked Reason: \(diagnosticsPreviewText(diagnostics.blockedReason, maxLength: 180) ?? "none")")
        lines.append("Effective Source Recommendation: \(diagnostics.effectiveSourceRecommendation)")
        lines.append("Local Fallback Available: \(diagnostics.localFallbackAvailable)")
        lines.append("Parity Confidence: \(String(format: "%.2f", diagnostics.parityConfidence))")
        lines.append("Replay Confidence: \(String(format: "%.2f", diagnostics.replayConfidence))")
        lines.append("Media Recovery Confidence: \(String(format: "%.2f", diagnostics.mediaRecoveryConfidence))")
        lines.append("Remote Candidate State Readable: \(diagnostics.remoteCandidateStateReadable)")
        lines.append("Production-Wide Canonical Reads Enabled: \(diagnostics.productionWideCanonicalReadsEnabled)")
        lines.append(diagnostics.noBehaviorChangedText)
        lines.append("")
        lines.append("Warnings")
        for warning in diagnostics.warnings {
            lines.append("- \(warning)")
        }
        return lines.joined(separator: "\n")
    }

    nonisolated static func buildCanonicalCandidateOverlayTestOnly(
        checkedAt: Date = Date(),
        targetClassification: SupabaseRuntimeConfiguration.TargetClassification,
        canonicalDiagnostics: CanonicalReadDiagnosticsResult,
        parityReport: NormalizedParityGapReport,
        candidateDiagnostics: CanonicalReadCandidateDiagnostics,
        productionActivationGate: ProductionSingleSessionActivationGateDiagnostics? = nil
    ) -> CanonicalCandidateOverlayBuildResult {
        var blockers: [String] = []
        switch targetClassification {
        case .localDev, .approvedStaging:
            break
        case .approvedProductionValidation:
            if productionActivationGate?.gateAllowed != true {
                blockers.append("production_canonical_candidate_overlay_blocked")
            }
        case .remote:
            blockers.append("random_remote_canonical_candidate_overlay_blocked")
        case .missing, .invalid:
            blockers.append("supabase_target_not_verified")
        }
        if !candidateDiagnostics.candidateFlagEnabled {
            blockers.append("canonical_read_candidate_flag_disabled")
        }
        if !candidateDiagnostics.allowed {
            blockers.append(candidateDiagnostics.blockedReason ?? "canonical_candidate_not_allowed")
        }
        let candidateEvidencePasses = canonicalDiagnostics.result == .remoteMatchesLocal ||
            canonicalDiagnostics.canonicalRecommendation == "remote_candidate_after_replay_validation"
        if !candidateEvidencePasses {
            blockers.append("canonical_read_diagnostic_result_not_candidate")
        }
        if canonicalDiagnostics.parentOrgConsistent != true || canonicalDiagnostics.parentPropertyConsistent != true {
            blockers.append("parent_org_or_property_divergence")
        }
        if parityReport.missingChildCount > 0 || parityReport.taxonomy.contains(.missingRemoteChildren) {
            blockers.append("missing_remote_children")
        }
        if !candidateDiagnostics.localFallbackAvailable {
            blockers.append("local_fallback_unavailable")
        }

        let rowCounts = [
            "remote_shots": canonicalDiagnostics.remoteShotCount ?? 0,
            "remote_issue_observations": canonicalDiagnostics.remoteIssueObservationCount ?? 0,
            "remote_guided": canonicalDiagnostics.remoteGuidedCount ?? 0
        ]
        let allowed = blockers.isEmpty
        let overlay = allowed ? CanonicalCandidateOverlay(
            builtAt: checkedAt,
            source: "remote_normalized_candidate_with_local_fallback",
            propertyID: canonicalDiagnostics.propertyID,
            sessionID: canonicalDiagnostics.sessionID,
            organizationID: canonicalDiagnostics.activeOrganizationID,
            remoteShotCount: canonicalDiagnostics.remoteShotCount ?? 0,
            remoteIssueObservationCount: canonicalDiagnostics.remoteIssueObservationCount ?? 0,
            remoteGuidedCount: canonicalDiagnostics.remoteGuidedCount,
            fallbackSource: "local",
            activeSource: "local",
            rollbackAvailable: true,
            noBehaviorChangedText: "No behavior changed: this test-only canonical candidate overlay is inspectable candidate state only. It does not switch global reads, overwrite local files, delete local metadata, remove iCloud backup paths, change export, change seal, change sync, change media, loosen RLS, delete data, or mutate production data."
        ) : nil
        return CanonicalCandidateOverlayBuildResult(
            checkedAt: checkedAt,
            allowed: allowed,
            blockedReason: blockers.isEmpty ? nil : blockers.joined(separator: ", "),
            overlay: overlay,
            remoteCandidateRowCounts: rowCounts,
            localFallbackRetained: candidateDiagnostics.localFallbackAvailable,
            activeSourceRemainsLocal: true,
            rollbackAvailable: true,
            productionBlocked: true,
            noBehaviorChangedText: "No behavior changed: canonical candidate consumption is limited to a test-only overlay. Active app state remains local unless explicitly viewing the overlay, local fallback is retained, production canonical reads remain disabled, and export, seal, sync, media, and iCloud behavior are unchanged."
        )
    }

    nonisolated static func canonicalCandidateOverlayReportText(_ result: CanonicalCandidateOverlayBuildResult) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Canonical Candidate Overlay")
        lines.append("Checked: \(result.checkedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Overlay Built: \(result.overlay != nil)")
        lines.append("Consumption Allowed: \(result.allowed)")
        lines.append("Consumption Blocked Reason: \(diagnosticsPreviewText(result.blockedReason, maxLength: 180) ?? "none")")
        lines.append("Overlay Source: \(result.overlay?.source ?? "not_built")")
        lines.append("Overlay Property ID: \(result.overlay?.propertyID?.uuidString ?? "none")")
        lines.append("Overlay Session ID: \(result.overlay?.sessionID?.uuidString ?? "none")")
        lines.append("Overlay Shot Count: \(result.overlay?.remoteShotCount ?? 0)")
        lines.append("Overlay Issue/Observation Count: \(result.overlay?.remoteIssueObservationCount ?? 0)")
        lines.append("Overlay Guided Count: \(result.overlay?.remoteGuidedCount.map(String.init) ?? "not_represented")")
        lines.append("Fallback Source: \(result.overlay?.fallbackSource ?? "local")")
        lines.append("Active Source: \(result.overlay?.activeSource ?? "local")")
        lines.append("Local Fallback Retained: \(result.localFallbackRetained)")
        lines.append("Rollback/Fallback Available: \(result.rollbackAvailable)")
        lines.append("Production Blocked: \(result.productionBlocked)")
        lines.append(result.noBehaviorChangedText)
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeCanonicalCandidateOverlayComparison(
        checkedAt: Date = Date(),
        canonicalDiagnostics: CanonicalReadDiagnosticsResult,
        overlayResult: CanonicalCandidateOverlayBuildResult,
        parityReport: NormalizedParityGapReport,
        localSessionStatus: String? = nil,
        remoteCandidateSessionStatus: String? = nil
    ) -> CanonicalCandidateOverlayComparison {
        let overlay = overlayResult.overlay
        let localShotCount = canonicalDiagnostics.localShotCount
        let remoteShotCount = overlay?.remoteShotCount ?? canonicalDiagnostics.remoteShotCount
        let localIssueObservationCount = canonicalDiagnostics.localIssueObservationCount
        let remoteIssueObservationCount = overlay?.remoteIssueObservationCount ?? canonicalDiagnostics.remoteIssueObservationCount
        let fallbackSource = overlay?.fallbackSource ?? "local"
        let activeSource = overlay?.activeSource ?? "local"
        let overlaySource = overlay?.source ?? "not_built"
        let rollbackAvailable = overlay?.rollbackAvailable ?? overlayResult.rollbackAvailable
        var blockers: [String] = []

        if !overlayResult.allowed || overlay == nil {
            blockers.append(overlayResult.blockedReason ?? "canonical_candidate_overlay_unavailable")
        }
        if parityReport.missingChildCount > 0 {
            blockers.append("missing_remote_children")
        }
        if canonicalDiagnostics.parentOrgConsistent != true || canonicalDiagnostics.parentPropertyConsistent != true {
            blockers.append("parent_org_or_property_divergence")
        }
        if canonicalDiagnostics.result == .localNewerConflict {
            blockers.append("local_newer_than_remote_candidate")
        }
        if canonicalDiagnostics.result == .divergentConflict {
            blockers.append("candidate_diverges_from_local")
        }
        if canonicalDiagnostics.countParity == false || canonicalDiagnostics.statusParity == false {
            blockers.append("candidate_count_or_status_parity_failed")
        }

        let result: CanonicalCandidateOverlayComparisonResult
        if parityReport.missingChildCount > 0 {
            result = .candidateIncomplete
        } else if canonicalDiagnostics.result == .localNewerConflict {
            result = .candidateLocalNewer
        } else if canonicalDiagnostics.result == .remoteNewerCandidate {
            result = .candidateRemoteNewer
        } else if canonicalDiagnostics.result == .divergentConflict ||
                    canonicalDiagnostics.countParity == false ||
                    canonicalDiagnostics.statusParity == false {
            result = .candidateDivergent
        } else if overlay == nil {
            result = .candidateUnavailable
        } else if canonicalDiagnostics.result == .remoteMatchesLocal ||
                    canonicalDiagnostics.canonicalRecommendation == "remote_candidate_after_replay_validation" {
            result = .candidateMatchesLocal
        } else {
            result = .candidateUnavailable
            blockers.append("canonical_read_diagnostic_result_not_candidate")
        }

        let trustedReason: String
        switch result {
        case .candidateMatchesLocal:
            trustedReason = "remote_matches_local_with_parent_consistency_and_local_fallback"
        case .candidateRemoteNewer:
            trustedReason = "remote_candidate_newer_requires_manual_review_before_consumption"
        case .candidateLocalNewer:
            trustedReason = "local_newer_blocks_candidate_consumption"
        case .candidateDivergent:
            trustedReason = "divergent_candidate_blocks_consumption"
        case .candidateIncomplete:
            trustedReason = "incomplete_candidate_blocks_consumption"
        case .candidateUnavailable:
            trustedReason = "candidate_overlay_not_available"
        }

        return CanonicalCandidateOverlayComparison(
            checkedAt: checkedAt,
            result: result,
            propertyID: canonicalDiagnostics.propertyID,
            sessionID: canonicalDiagnostics.sessionID,
            localSessionStatus: localSessionStatus,
            remoteCandidateSessionStatus: remoteCandidateSessionStatus,
            localShotCount: localShotCount,
            remoteCandidateShotCount: remoteShotCount,
            localIssueObservationCount: localIssueObservationCount,
            remoteCandidateIssueObservationCount: remoteIssueObservationCount,
            localUpdatedAt: canonicalDiagnostics.localUpdatedAt,
            remoteCandidateUpdatedAt: canonicalDiagnostics.remoteUpdatedAt,
            parityConfidence: max(0, min(parityReport.parityCompletenessScore, 1)),
            fallbackSource: fallbackSource,
            activeSource: activeSource,
            overlaySource: overlaySource,
            rollbackAvailable: rollbackAvailable,
            trustedReason: trustedReason,
            blockedReason: blockers.isEmpty ? nil : blockers.joined(separator: ", "),
            noBehaviorChangedText: "No behavior changed: canonical candidate overlay comparison is inspect-only. Active app state remains local, local fallback remains available, production canonical reads remain disabled, and export, seal, sync, media, and iCloud behavior are unchanged."
        )
    }

    nonisolated static func canonicalCandidateOverlayComparisonReportText(_ comparison: CanonicalCandidateOverlayComparison) -> String {
        var lines: [String] = []
        lines.append("Canonical Candidate Overlay Comparison")
        lines.append("- result: \(comparison.result.rawValue)")
        lines.append("- property_id: \(comparison.propertyID?.uuidString ?? "none")")
        lines.append("- session_id: \(comparison.sessionID?.uuidString ?? "none")")
        lines.append("- local_session_status: \(diagnosticsPreviewText(comparison.localSessionStatus, maxLength: 80) ?? "unknown")")
        lines.append("- remote_candidate_session_status: \(diagnosticsPreviewText(comparison.remoteCandidateSessionStatus, maxLength: 80) ?? "unknown")")
        lines.append("- local_shot_count: \(comparison.localShotCount.map(String.init) ?? "none")")
        lines.append("- remote_candidate_shot_count: \(comparison.remoteCandidateShotCount.map(String.init) ?? "none")")
        lines.append("- local_issue_observation_count: \(comparison.localIssueObservationCount.map(String.init) ?? "none")")
        lines.append("- remote_candidate_issue_observation_count: \(comparison.remoteCandidateIssueObservationCount.map(String.init) ?? "none")")
        lines.append("- local_updated_at: \(comparison.localUpdatedAt?.formatted(date: .abbreviated, time: .standard) ?? "unknown")")
        lines.append("- remote_candidate_updated_at: \(comparison.remoteCandidateUpdatedAt?.formatted(date: .abbreviated, time: .standard) ?? "unknown")")
        lines.append("- parity_confidence: \(String(format: "%.2f", comparison.parityConfidence))")
        lines.append("- active_source: \(comparison.activeSource)")
        lines.append("- overlay_source: \(comparison.overlaySource)")
        lines.append("- fallback_source: \(comparison.fallbackSource)")
        lines.append("- rollback_available: \(comparison.rollbackAvailable)")
        lines.append("- why_candidate_is_trusted: \(comparison.trustedReason)")
        lines.append("- why_candidate_is_blocked: \(diagnosticsPreviewText(comparison.blockedReason, maxLength: 180) ?? "none")")
        lines.append(comparison.noBehaviorChangedText)
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeCanonicalCandidateActivationResult(
        checkedAt: Date = Date(),
        targetClassification: SupabaseRuntimeConfiguration.TargetClassification,
        diagnostics: SessionSnapshotUploadDiagnostics,
        productionActivationGate: ProductionSingleSessionActivationGateDiagnostics? = nil
    ) -> CanonicalCandidateActivationResult {
        var blockers: [String] = []
        switch targetClassification {
        case .localDev, .approvedStaging:
            break
        case .approvedProductionValidation:
            if productionActivationGate?.gateAllowed != true {
                blockers.append("production_canonical_candidate_activation_blocked")
            }
        case .remote:
            blockers.append("random_remote_canonical_candidate_activation_blocked")
        case .missing, .invalid:
            blockers.append("supabase_target_not_verified")
        }
        if !diagnostics.lastCanonicalReadCandidateFlagEnabled {
            blockers.append("canonical_read_candidate_flag_disabled")
        }
        if !diagnostics.lastCanonicalReadCandidateOrgAllowlisted {
            blockers.append("org_not_allowlisted")
        }
        if !diagnostics.lastCanonicalReadCandidatePropertyAllowlisted {
            blockers.append("property_not_allowlisted")
        }
        if !diagnostics.lastCanonicalReadCandidateSessionAllowlisted {
            blockers.append("session_not_allowlisted")
        }
        if !diagnostics.lastCanonicalReadCandidateAllowed {
            blockers.append(diagnostics.lastCanonicalReadCandidateBlockedReason == "none" ? "canonical_candidate_not_allowed" : diagnostics.lastCanonicalReadCandidateBlockedReason)
        }
        if !diagnostics.lastCanonicalCandidateOverlayBuilt || !diagnostics.lastCanonicalCandidateOverlayAllowed {
            blockers.append(diagnostics.lastCanonicalCandidateOverlayBlockedReason == "none" ? "canonical_candidate_overlay_not_built" : diagnostics.lastCanonicalCandidateOverlayBlockedReason)
        }
        if diagnostics.lastCanonicalCandidateOverlayComparisonResult != CanonicalCandidateOverlayComparisonResult.candidateMatchesLocal.rawValue {
            blockers.append("canonical_candidate_comparison_not_matching_local")
        }
        if !diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable {
            blockers.append("local_fallback_unavailable")
        }
        if !diagnostics.lastCanonicalCandidateOverlayRollbackAvailable {
            blockers.append("rollback_unavailable")
        }
        if diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent != true ||
            diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent != true {
            blockers.append("parent_org_or_property_divergence")
        }
        if diagnostics.lastMissingChildCount > 0 ||
            diagnostics.lastNormalizedParityGapTaxonomy.contains("missing_remote_children") {
            blockers.append("missing_remote_children")
        }
        if diagnostics.lastCanonicalReadDiagnosticsResult == CanonicalReadDiagnosticResult.remoteNewerCandidate.rawValue {
            blockers.append("remote_newer_conflict_diagnostic_only")
        }
        if diagnostics.lastNormalizedBackfillRemoteNewerConflictCount > 0 {
            blockers.append("remote_newer_conflict")
        }

        let allowed = blockers.isEmpty
        return CanonicalCandidateActivationResult(
            checkedAt: checkedAt,
            allowed: allowed,
            blockedReason: allowed ? nil : Array(Set(blockers)).sorted().joined(separator: ", "),
            activeSource: allowed ? .canonicalCandidate : .local,
            rollbackSource: .local,
            activationScope: "selected_session_only",
            propertyID: diagnostics.lastCanonicalCandidateOverlayPropertyID ?? diagnostics.lastCanonicalReadDiagnosticsPropertyID,
            sessionID: diagnostics.lastCanonicalCandidateOverlaySessionID ?? diagnostics.lastCanonicalReadDiagnosticsSessionID,
            rollbackAvailable: diagnostics.lastCanonicalCandidateOverlayRollbackAvailable,
            productionBlocked: true,
            noBehaviorChangedText: "No behavior changed: controlled canonical candidate activation is selected-session diagnostic scope only. It does not switch global reads, mutate local state, write remote state, discard local files, remove iCloud fallback, change export, change seal, change sync, change media, loosen RLS, delete data, or enable production canonical reads."
        )
    }

    nonisolated static func makeCanonicalCandidateRollbackResult(
        checkedAt: Date = Date(),
        diagnostics: SessionSnapshotUploadDiagnostics
    ) -> CanonicalCandidateActivationResult {
        CanonicalCandidateActivationResult(
            checkedAt: checkedAt,
            allowed: true,
            blockedReason: nil,
            activeSource: .local,
            rollbackSource: .local,
            activationScope: "selected_session_only",
            propertyID: diagnostics.lastCanonicalCandidateActivationPropertyID ?? diagnostics.lastCanonicalCandidateOverlayPropertyID,
            sessionID: diagnostics.lastCanonicalCandidateActivationSessionID ?? diagnostics.lastCanonicalCandidateOverlaySessionID,
            rollbackAvailable: true,
            productionBlocked: true,
            noBehaviorChangedText: "No behavior changed: rollback restores Local Health diagnostic active source to local for the selected session only. It does not mutate local state, write remote state, change export, seal, sync, media, or iCloud behavior, or enable production canonical reads."
        )
    }

    nonisolated static func canonicalCandidateActivationReportText(_ result: CanonicalCandidateActivationResult) -> String {
        var lines: [String] = []
        lines.append("Canonical Candidate Activation")
