        lines.append("- rollback_source: \(result.rollbackSource.rawValue)")
        lines.append("- activation_scope: \(result.activationScope)")
        lines.append("- active_candidate_property_id: \(result.propertyID?.uuidString ?? "none")")
        lines.append("- active_candidate_session_id: \(result.sessionID?.uuidString ?? "none")")
        lines.append("- rollback_available: \(result.rollbackAvailable)")
        lines.append("- production_activation_blocked: \(result.productionBlocked)")
        lines.append(result.noBehaviorChangedText)
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeCanonicalRolloutReadinessDiagnostics(
        _ diagnostics: SessionSnapshotUploadDiagnostics
    ) -> CanonicalRolloutReadinessDiagnostics {
        let canonicalCandidateResult = diagnostics.lastCanonicalReadDiagnosticsResult == CanonicalReadDiagnosticResult.remoteMatchesLocal.rawValue ||
            diagnostics.lastCanonicalReadDiagnosticsRecommendation == "remote_candidate_after_replay_validation"
        let parentConsistent = diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent == true &&
            diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent == true
        let parentDivergent = diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent == false ||
            diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent == false
        let noMissingChildren = diagnostics.lastMissingChildCount == 0 &&
            !diagnostics.lastNormalizedParityGapTaxonomy.contains("missing_remote_children")
        let noRemoteNewerConflict = diagnostics.lastCanonicalReadDiagnosticsResult != CanonicalReadDiagnosticResult.remoteNewerCandidate.rawValue &&
            diagnostics.lastNormalizedBackfillRemoteNewerConflictCount == 0
        let productionWideDisabled = !diagnostics.lastCanonicalReadCandidateProductionWideEnabled
        let productionBlocked = diagnostics.lastCanonicalCandidateOverlayProductionBlocked &&
            diagnostics.lastCanonicalCandidateActivationProductionBlocked
        let rollbackAvailable = diagnostics.lastCanonicalCandidateOverlayRollbackAvailable &&
            diagnostics.lastCanonicalCandidateActivationRollbackAvailable
        let operatorReportAvailable = true

        let checklist = [
            CanonicalRolloutChecklistItem(
                id: "local_fallback_retained",
                label: "Local fallback retained",
                passed: diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable,
                detail: diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable ? "available" : "missing"
            ),
            CanonicalRolloutChecklistItem(
                id: "rollback_tested",
                label: "Rollback tested",
                passed: rollbackAvailable,
                detail: rollbackAvailable ? "rollback available" : "rollback unavailable"
            ),
            CanonicalRolloutChecklistItem(
                id: "production_wide_disabled",
                label: "Production-wide disabled",
                passed: productionWideDisabled && productionBlocked,
                detail: productionWideDisabled && productionBlocked ? "disabled and blocked" : "production-wide risk present"
            ),
            CanonicalRolloutChecklistItem(
                id: "allowlist_required",
                label: "Allowlist required",
                passed: diagnostics.lastCanonicalReadCandidateFlagEnabled &&
                    diagnostics.lastCanonicalReadCandidateOrgAllowlisted &&
                    diagnostics.lastCanonicalReadCandidatePropertyAllowlisted &&
                    diagnostics.lastCanonicalReadCandidateSessionAllowlisted,
                detail: "org=\(diagnostics.lastCanonicalReadCandidateOrgAllowlisted) property=\(diagnostics.lastCanonicalReadCandidatePropertyAllowlisted) session=\(diagnostics.lastCanonicalReadCandidateSessionAllowlisted)"
            ),
            CanonicalRolloutChecklistItem(
                id: "no_missing_children",
                label: "No missing children",
                passed: noMissingChildren,
                detail: noMissingChildren ? "missing_child_count=0" : "missing_child_count=\(diagnostics.lastMissingChildCount)"
            ),
            CanonicalRolloutChecklistItem(
                id: "no_parent_mismatch",
                label: "No parent mismatch",
                passed: parentConsistent,
                detail: "org=\(diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent.map(String.init) ?? "not_checked") property=\(diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent.map(String.init) ?? "not_checked")"
            ),
            CanonicalRolloutChecklistItem(
                id: "no_remote_newer_conflict",
                label: "No remote-newer conflict",
                passed: noRemoteNewerConflict,
                detail: noRemoteNewerConflict ? "none" : "remote_newer_conflict_present"
            ),
            CanonicalRolloutChecklistItem(
                id: "operator_report_available",
                label: "Operator report available",
                passed: operatorReportAvailable,
                detail: "canonical_read_rollout_report_available"
            )
        ]

        var blockers: [String] = []
        if !productionWideDisabled || !productionBlocked {
            blockers.append("production_wide_canonical_reads_not_blocked")
        }
        if diagnostics.lastCanonicalReadDiagnosticsResult != CanonicalReadDiagnosticResult.localOnly.rawValue &&
            diagnostics.lastParityCompletenessScore < 0.95 {
            blockers.append("parity_completeness_below_threshold")
        }
        if parentDivergent {
            blockers.append("parent_org_or_property_divergence")
        }
        if !noMissingChildren {
            blockers.append("missing_remote_children")
        }
        if !noRemoteNewerConflict {
            blockers.append("remote_newer_conflict")
        }
        if !canonicalCandidateResult {
            blockers.append("canonical_diagnostics_not_candidate")
        }
        if !diagnostics.lastCanonicalReadCandidateAllowed {
            blockers.append(diagnostics.lastCanonicalReadCandidateBlockedReason == "none" ? "canonical_candidate_not_allowed" : diagnostics.lastCanonicalReadCandidateBlockedReason)
        }
        if !diagnostics.lastCanonicalCandidateOverlayBuilt {
            blockers.append(diagnostics.lastCanonicalCandidateOverlayBlockedReason == "none" ? "canonical_candidate_overlay_not_built" : diagnostics.lastCanonicalCandidateOverlayBlockedReason)
        }
        if diagnostics.lastCanonicalCandidateOverlayComparisonResult != CanonicalCandidateOverlayComparisonResult.candidateMatchesLocal.rawValue {
            blockers.append("canonical_candidate_comparison_not_matching_local")
        }
        if !diagnostics.lastCanonicalCandidateActivationAllowed {
            blockers.append(diagnostics.lastCanonicalCandidateActivationBlockedReason == "none" ? "canonical_candidate_activation_not_allowed" : diagnostics.lastCanonicalCandidateActivationBlockedReason)
        }
        if !rollbackAvailable {
            blockers.append("rollback_unavailable")
        }
        if !diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable {
            blockers.append("local_fallback_unavailable")
        }

        let dedupedBlockers = Array(Set(blockers)).sorted()
        let hardBlocked = dedupedBlockers.contains("production_wide_canonical_reads_not_blocked") ||
            dedupedBlockers.contains("parent_org_or_property_divergence") ||
            dedupedBlockers.contains("missing_remote_children") ||
            dedupedBlockers.contains("remote_newer_conflict") ||
            dedupedBlockers.contains("rollback_unavailable") ||
            dedupedBlockers.contains("local_fallback_unavailable") ||
            dedupedBlockers.contains("parity_completeness_below_threshold")

        let state: CanonicalRolloutReadinessState
        if hardBlocked {
            state = .blocked
        } else if diagnostics.lastCanonicalCandidateActivationAllowed &&
                    diagnostics.lastCanonicalCandidateOverlayComparisonResult == CanonicalCandidateOverlayComparisonResult.candidateMatchesLocal.rawValue &&
                    diagnostics.lastCanonicalCandidateOverlayBuilt &&
                    diagnostics.lastCanonicalReadCandidateAllowed &&
                    canonicalCandidateResult &&
                    dedupedBlockers.isEmpty {
            state = .readyForSingleSessionActivation
        } else if diagnostics.lastCanonicalReadCandidateAllowed && canonicalCandidateResult {
            state = .readyForStagingCandidate
        } else {
            state = .notReady
        }

        let nextRecommendedAction: String
        switch state {
        case .notReady:
            if !canonicalCandidateResult {
                nextRecommendedAction = "run_canonical_read_diagnostics"
            } else if !diagnostics.lastCanonicalReadCandidateAllowed {
                nextRecommendedAction = "fix_candidate_allowlist_or_blockers"
            } else if !diagnostics.lastCanonicalCandidateOverlayBuilt {
                nextRecommendedAction = "build_canonical_candidate_overlay"
            } else if diagnostics.lastCanonicalCandidateOverlayComparisonResult != CanonicalCandidateOverlayComparisonResult.candidateMatchesLocal.rawValue {
                nextRecommendedAction = "review_overlay_comparison"
            } else {
                nextRecommendedAction = "review_activation_gate"
            }
        case .readyForStagingCandidate:
            nextRecommendedAction = "build_overlay_and_compare_candidate"
        case .readyForSingleSessionActivation:
            nextRecommendedAction = "manual_single_session_activation_validation"
        case .readyForLimitedProductionAllowlist:
            nextRecommendedAction = "prepare_limited_production_allowlist_review"
        case .blocked:
            nextRecommendedAction = "resolve_rollout_blockers_before_candidate_consumption"
        }

        return CanonicalRolloutReadinessDiagnostics(
            state: state,
            blockers: dedupedBlockers,
            nextRecommendedAction: nextRecommendedAction,
            checklist: checklist,
            checklistPassed: checklist.allSatisfy(\.passed),
            noBehaviorChangedText: "No behavior changed: canonical rollout readiness is diagnostics-only. It does not switch canonical reads, enable production canonical reads, mutate production data, discard local state, change export, seal, sync, media, or iCloud behavior, loosen RLS, or delete data."
        )
    }

    nonisolated static func canonicalRolloutReadinessReportText(
        _ readiness: CanonicalRolloutReadinessDiagnostics
    ) -> String {
        var lines: [String] = []
        lines.append("Canonical Rollout Readiness")
        lines.append("- readiness_state: \(readiness.state.rawValue)")
        lines.append("- readiness_blockers: \(readiness.blockers.isEmpty ? "none" : readiness.blockers.joined(separator: ", "))")
        lines.append("- next_recommended_action: \(readiness.nextRecommendedAction)")
        lines.append("- rollout_checklist_passed: \(readiness.checklistPassed)")
        lines.append("")
        lines.append("Rollout Checklist")
        for item in readiness.checklist {
            lines.append("- \(item.id): \(item.passed ? "pass" : "fail") (\(item.detail))")
        }
        lines.append(readiness.noBehaviorChangedText)
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeProductionAllowlistReadinessDiagnostics(
        _ diagnostics: SessionSnapshotUploadDiagnostics,
        policy: ProductionAllowlistReadinessPolicy = .diagnosticsOnly
    ) -> ProductionAllowlistReadinessDiagnostics {
        let canonicalCandidateResult = diagnostics.lastCanonicalReadDiagnosticsResult == CanonicalReadDiagnosticResult.remoteMatchesLocal.rawValue ||
            diagnostics.lastCanonicalReadDiagnosticsRecommendation == "remote_candidate_after_replay_validation"
        let explicitAllowlistsPresent = diagnostics.lastCanonicalReadCandidateOrgAllowlisted &&
            diagnostics.lastCanonicalReadCandidatePropertyAllowlisted &&
            diagnostics.lastCanonicalReadCandidateSessionAllowlisted
        let parityValidated = diagnostics.lastParityCompletenessScore >= policy.parityConfidenceThreshold &&
            diagnostics.lastCanonicalReadCandidateParityConfidence >= policy.parityConfidenceThreshold
        let replayValidated = diagnostics.lastCanonicalReadCandidateReplayConfidence >= policy.replayConfidenceThreshold
        let rollbackValidated = diagnostics.lastCanonicalCandidateOverlayRollbackAvailable &&
            diagnostics.lastCanonicalCandidateActivationRollbackAvailable
        let productionWideDisabled = !diagnostics.lastCanonicalReadCandidateProductionWideEnabled &&
            diagnostics.lastCanonicalCandidateOverlayProductionBlocked &&
            diagnostics.lastCanonicalCandidateActivationProductionBlocked
        let noUnresolvedBlockers = diagnostics.lastMissingChildCount == 0 &&
            !diagnostics.lastNormalizedParityGapTaxonomy.contains("missing_remote_children") &&
            diagnostics.lastNormalizedBackfillRemoteNewerConflictCount == 0 &&
            diagnostics.lastCanonicalReadDiagnosticsResult != CanonicalReadDiagnosticResult.remoteNewerCandidate.rawValue &&
            diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent == true &&
            diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent == true &&
            diagnostics.lastCanonicalCandidateOverlayComparisonResult == CanonicalCandidateOverlayComparisonResult.candidateMatchesLocal.rawValue &&
            diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable

        var blockers: [String] = []
        if !productionWideDisabled {
            blockers.append("production_wide_enablement_blocked")
        }
        if !explicitAllowlistsPresent {
            if !diagnostics.lastCanonicalReadCandidateOrgAllowlisted {
                blockers.append("org_allowlist_required")
            }
            if !diagnostics.lastCanonicalReadCandidatePropertyAllowlisted {
                blockers.append("property_allowlist_required")
            }
            if !diagnostics.lastCanonicalReadCandidateSessionAllowlisted {
                blockers.append("session_allowlist_required")
            }
        }
        if !diagnostics.lastCanonicalReadCandidateAllowed {
            blockers.append(diagnostics.lastCanonicalReadCandidateBlockedReason == "none" ? "canonical_candidate_not_allowed" : diagnostics.lastCanonicalReadCandidateBlockedReason)
        }
        if !canonicalCandidateResult {
            blockers.append("canonical_diagnostics_not_candidate")
        }
        if !parityValidated {
            blockers.append("parity_confidence_below_threshold")
        }
        if !replayValidated {
            blockers.append("replay_confidence_below_threshold")
        }
        if !rollbackValidated {
            blockers.append("rollback_validation_required")
        }
        if !noUnresolvedBlockers {
            blockers.append("unresolved_rollout_blockers")
        }
        if diagnostics.lastCanonicalReadCandidateProductionWideEnabled {
            blockers.append("production_wide_canonical_reads_not_allowed")
        }

        let dedupedBlockers = Array(Set(blockers)).sorted()
        let hardBlocked = dedupedBlockers.contains("production_wide_enablement_blocked") ||
            dedupedBlockers.contains("production_wide_canonical_reads_not_allowed") ||
            dedupedBlockers.contains("rollback_validation_required") ||
            dedupedBlockers.contains("unresolved_rollout_blockers") ||
            dedupedBlockers.contains("parity_confidence_below_threshold") ||
            dedupedBlockers.contains("replay_confidence_below_threshold")

        var workflow: [ProductionOperatorWorkflowDiagnostic] = []
        if !parityValidated {
            workflow.append(.pendingParityValidation)
        }
        if !rollbackValidated {
            workflow.append(.pendingRollbackValidation)
        }
        if dedupedBlockers.contains("unresolved_rollout_blockers") ||
            dedupedBlockers.contains("production_wide_enablement_blocked") ||
            dedupedBlockers.contains("production_wide_canonical_reads_not_allowed") {
            workflow.append(.blockedByUnresolvedConflicts)
        }

        let candidateTechnicallyReady = dedupedBlockers.isEmpty
        let state: ProductionAllowlistReadinessState
        if hardBlocked {
            state = .productionBlocked
        } else if candidateTechnicallyReady && policy.operatorApproved {
            state = .productionCandidateReady
            workflow.append(.approvedForCandidate)
        } else if candidateTechnicallyReady {
            state = .productionAllowlistPendingOperatorApproval
            workflow.append(.pendingOperatorReview)
        } else {
            state = .productionNotReady
            if workflow.isEmpty {
                workflow.append(.pendingOperatorReview)
            }
        }

        let nextRecommendedAction: String
        switch state {
        case .productionNotReady:
            nextRecommendedAction = "complete_allowlist_policy_and_candidate_evidence"
        case .productionCandidateReady:
            nextRecommendedAction = "hold_for_future_non_activation_production_allowlist_review"
        case .productionAllowlistPendingOperatorApproval:
            nextRecommendedAction = "operator_review_limited_production_allowlist"
        case .productionBlocked:
            nextRecommendedAction = "resolve_production_rollout_blockers_before_operator_review"
        }

        return ProductionAllowlistReadinessDiagnostics(
            state: state,
            blockers: dedupedBlockers,
            operatorWorkflowDiagnostics: workflow,
            operatorApprovalRequired: !policy.operatorApproved,
            rollbackValidated: rollbackValidated,
            productionCohortSizeRecommendation: policy.recommendedCohortSize,
            parityConfidenceThreshold: policy.parityConfidenceThreshold,
            replayConfidenceThreshold: policy.replayConfidenceThreshold,
            nextRecommendedAction: nextRecommendedAction,
            noBehaviorChangedText: "No behavior changed: limited production allowlist readiness is diagnostics-only. It does not enable production canonical reads, enable production-wide remote reads, activate production candidates, build or activate production overlays, discard local state, mutate production data, remove iCloud/local fallback, change export, seal, sync, media, or iCloud behavior, loosen RLS, or delete data."
        )
    }

    nonisolated static func limitedProductionRolloutReadinessReportText(
        _ readiness: ProductionAllowlistReadinessDiagnostics
    ) -> String {
        var lines: [String] = []
        lines.append("Limited Production Rollout Readiness")
        lines.append("- production_readiness_state: \(readiness.state.rawValue)")
        lines.append("- production_rollout_blockers: \(readiness.blockers.isEmpty ? "none" : readiness.blockers.joined(separator: ", "))")
        lines.append("- operator_workflow_diagnostics: \(readiness.operatorWorkflowDiagnostics.map(\.rawValue).joined(separator: ", "))")
        lines.append("- operator_approval_required: \(readiness.operatorApprovalRequired)")
        lines.append("- rollback_validated: \(readiness.rollbackValidated)")
        lines.append("- parity_confidence_threshold: \(String(format: "%.2f", readiness.parityConfidenceThreshold))")
        lines.append("- replay_confidence_threshold: \(String(format: "%.2f", readiness.replayConfidenceThreshold))")
        lines.append("- production_cohort_size_recommendation: \(readiness.productionCohortSizeRecommendation)")
        lines.append("- next_recommended_action: \(readiness.nextRecommendedAction)")
        lines.append(readiness.noBehaviorChangedText)
        return lines.joined(separator: "\n")
    }

    nonisolated static func makeProductionCohortControlPlaneDiagnostics(
        _ diagnostics: SessionSnapshotUploadDiagnostics,
        orgID: UUID? = nil,
        policy: ProductionCohortControlPlanePolicy = .diagnosticsOnly
    ) -> ProductionCohortControlPlaneDiagnostics {
        let propertyID = diagnostics.lastCanonicalReadDiagnosticsPropertyID ?? diagnostics.lastCanonicalCandidateOverlayPropertyID
        let sessionID = diagnostics.lastCanonicalReadDiagnosticsSessionID ?? diagnostics.lastCanonicalCandidateOverlaySessionID
        let allowlistComplete = diagnostics.lastCanonicalReadCandidateOrgAllowlisted &&
            diagnostics.lastCanonicalReadCandidatePropertyAllowlisted &&
            diagnostics.lastCanonicalReadCandidateSessionAllowlisted
        let parityVerified = diagnostics.lastParityCompletenessScore >= policy.parityConfidenceThreshold &&
            diagnostics.lastCanonicalReadCandidateParityConfidence >= policy.parityConfidenceThreshold &&
            diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent == true &&
            diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent == true
        let replayBackfillVerified = diagnostics.lastCanonicalReadCandidateReplayConfidence >= policy.replayConfidenceThreshold &&
            diagnostics.lastNormalizedBackfillRemoteNewerConflictCount == 0
        let overlayVerified = diagnostics.lastCanonicalCandidateOverlayBuilt &&
            diagnostics.lastCanonicalCandidateOverlayAllowed &&
            diagnostics.lastCanonicalCandidateOverlayComparisonResult == CanonicalCandidateOverlayComparisonResult.candidateMatchesLocal.rawValue
        let activationRollbackVerified = diagnostics.lastCanonicalCandidateOverlayRollbackAvailable &&
            diagnostics.lastCanonicalCandidateActivationRollbackAvailable
        let productionWideDisabled = !policy.productionWideCanonicalReadsEnabled &&
            !diagnostics.lastCanonicalReadCandidateProductionWideEnabled &&
            diagnostics.lastCanonicalCandidateOverlayProductionBlocked &&
            diagnostics.lastCanonicalCandidateActivationProductionBlocked

        var unresolved: [String] = []
        if diagnostics.lastMissingChildCount > 0 ||
            diagnostics.lastNormalizedParityGapTaxonomy.contains("missing_remote_children") {
            unresolved.append("missing_remote_children")
        }
        if diagnostics.lastCanonicalReadDiagnosticsParentOrgConsistent == false ||
            diagnostics.lastCanonicalReadDiagnosticsParentPropertyConsistent == false {
            unresolved.append("parent_org_or_property_divergence")
        }
        if diagnostics.lastCanonicalReadDiagnosticsResult == CanonicalReadDiagnosticResult.remoteNewerCandidate.rawValue ||
            diagnostics.lastNormalizedBackfillRemoteNewerConflictCount > 0 {
            unresolved.append("remote_newer_conflict")
        }
        if !diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable {
            unresolved.append("local_fallback_unavailable")
        }

        var blockers: [String] = []
        if orgID == nil {
            blockers.append("org_id_required")
        }
        if propertyID == nil {
            blockers.append("property_id_required")
        }
        if !productionWideDisabled {
            blockers.append("production_wide_canonical_reads_not_disabled")
        }
        if policy.operatorApprovalState == .rejected {
            blockers.append("operator_rejected")
        }
        if policy.operatorApprovalState == .expired {
            blockers.append("operator_approval_expired")
        }
        if policy.requestedStage == .singleSessionActivation ||
            policy.requestedStage == .propertyCohortActivation {
            if sessionID == nil && policy.requestedStage == .singleSessionActivation {
                blockers.append("session_id_required_for_single_session_activation_readiness")
            }
            if policy.requestedStage == .propertyCohortActivation {
                blockers.append("property_cohort_activation_not_enabled_in_this_phase")
            }
            if !allowlistComplete {
                blockers.append("allowlist_incomplete")
            }
            if !parityVerified {
                blockers.append("parity_not_verified")
            }
            if !replayBackfillVerified {
                blockers.append("replay_backfill_not_verified")
            }
            if !overlayVerified {
                blockers.append("overlay_not_verified")
            }
            if !activationRollbackVerified {
                blockers.append("activation_rollback_not_verified")
            }
            if policy.operatorApprovalState != .approved {
                blockers.append("operator_approval_required")
            }
        } else if policy.requestedStage == .candidateOverlayOnly {
            if !allowlistComplete {
                blockers.append("allowlist_incomplete")
            }
            if !parityVerified {
                blockers.append("parity_not_verified")
            }
            if !replayBackfillVerified {
                blockers.append("replay_backfill_not_verified")
            }
            if !overlayVerified {
                blockers.append("overlay_not_verified")
            }
        }
        blockers.append(contentsOf: unresolved.map { "unresolved_\($0)" })

        let dedupedBlockers = Array(Set(blockers)).sorted()
        let stage: ProductionCohortRolloutStage
        let activationEligibility: ProductionCohortActivationEligibility
        if !dedupedBlockers.isEmpty {
            if policy.requestedStage == .diagnosticsOnly &&
                orgID != nil &&
                propertyID != nil &&
                productionWideDisabled &&
                policy.operatorApprovalState != .rejected &&
                policy.operatorApprovalState != .expired {
                stage = .diagnosticsOnly
                activationEligibility = .diagnosticsOnly
            } else {
                stage = .blocked
                activationEligibility = .blocked
            }
        } else {
            switch policy.requestedStage {
            case .diagnosticsOnly:
                stage = .diagnosticsOnly
                activationEligibility = .diagnosticsOnly
            case .candidateOverlayOnly:
                stage = .candidateOverlayOnly
                activationEligibility = .notEligible
            case .singleSessionActivation:
                stage = .singleSessionActivation
                activationEligibility = .singleSessionReadinessOnly
            case .propertyCohortActivation:
                stage = .blocked
                activationEligibility = .blocked
            case .blocked:
                stage = .blocked
                activationEligibility = .blocked
            }
        }

        let rollbackState: ProductionCohortValidationState = activationRollbackVerified ? .verified : .notValidated
        let parityState: ProductionCohortValidationState = parityVerified ? .verified : .notValidated
        let recommendedNextAction: String
        switch stage {
        case .diagnosticsOnly:
            recommendedNextAction = "collect_cohort_overlay_parity_and_rollback_evidence"
        case .candidateOverlayOnly:
            recommendedNextAction = "review_candidate_overlay_before_any_activation_readiness"
        case .singleSessionActivation:
            recommendedNextAction = "hold_as_single_session_activation_readiness_only"
        case .propertyCohortActivation:
            recommendedNextAction = "not_available_in_phase_2c_27b"
        case .blocked:
            recommendedNextAction = "resolve_cohort_control_plane_blockers"
        }

        return ProductionCohortControlPlaneDiagnostics(
            cohort: ProductionCohortModel(
                orgID: orgID,
                propertyID: propertyID,
                sessionID: sessionID,
                rolloutStage: stage,
                operatorApprovalState: policy.operatorApprovalState,
                rollbackValidationState: rollbackState,
                parityValidationState: parityState,
                activationEligibility: activationEligibility
            ),
            eligibility: ProductionCohortEligibilityDiagnostics(
                allowlistComplete: allowlistComplete,
                parityVerified: parityVerified,
                replayBackfillVerified: replayBackfillVerified,
                overlayVerified: overlayVerified,
                activationRollbackVerified: activationRollbackVerified,
                productionWideDisabled: productionWideDisabled,
                unresolvedBlockers: Array(Set(unresolved)).sorted()
            ),
            blockers: dedupedBlockers,
            recommendedNextAction: recommendedNextAction,
            noBehaviorChangedText: "No behavior changed: production cohort control plane is diagnostics-only. It does not enable production canonical reads, activate production candidates, switch global canonical reads, mutate production data, discard local state, remove iCloud/local fallback, change export, seal, sync, media, or iCloud behavior, loosen RLS, or delete data."
        )
    }

