    nonisolated static func makeProductionCohortOperatorApprovalDiagnostics(
        _ controlPlane: ProductionCohortControlPlaneDiagnostics,
        requestedState: ProductionCohortOperatorApprovalState? = nil,
        approvalTimestamp: Date? = nil,
        expirationTimestamp: Date? = nil,
        checkedAt: Date = Date()
    ) -> ProductionCohortOperatorApprovalDiagnostics {
        let staleApproval = expirationTimestamp.map { $0 <= checkedAt } ?? false
        let state = staleApproval && (requestedState ?? controlPlane.cohort.operatorApprovalState) == .approved
            ? ProductionCohortOperatorApprovalState.expired
            : (requestedState ?? controlPlane.cohort.operatorApprovalState)

        var blockers: [String] = []
        if controlPlane.cohort.orgID == nil {
            blockers.append("org_id_required")
        }
        if controlPlane.cohort.propertyID == nil {
            blockers.append("property_id_required")
        }
        if !controlPlane.eligibility.allowlistComplete {
            blockers.append("allowlist_incomplete")
        }
        if !controlPlane.eligibility.parityVerified {
            blockers.append("parity_not_verified")
        }
        if !controlPlane.eligibility.replayBackfillVerified {
            blockers.append("replay_backfill_not_verified")
        }
        if !controlPlane.eligibility.overlayVerified {
            blockers.append("overlay_not_verified")
        }
        if !controlPlane.eligibility.activationRollbackVerified {
            blockers.append("rollback_not_validated")
        }
        if !controlPlane.eligibility.productionWideDisabled {
            blockers.append("production_wide_canonical_reads_not_disabled")
        }
        blockers.append(contentsOf: controlPlane.eligibility.unresolvedBlockers.map { "unresolved_\($0)" })
        if state == .rejected {
            blockers.append("operator_rejected")
        }
        if state == .expired || staleApproval {
            blockers.append("operator_approval_expired")
        }

        let dedupedBlockers = Array(Set(blockers)).sorted()
        let approvalEligible = dedupedBlockers.isEmpty
        let nextRecommendedAction: String
        switch state {
        case .notRequested:
            nextRecommendedAction = approvalEligible ? "request_operator_review" : "resolve_approval_blockers"
        case .pendingReview:
            nextRecommendedAction = approvalEligible ? "operator_review_pending" : "resolve_approval_blockers_before_approval"
        case .approved:
            nextRecommendedAction = approvalEligible ? "hold_approved_readiness_diagnostics_only" : "revoke_or_refresh_approval_after_blockers"
        case .rejected:
            nextRecommendedAction = "operator_rejected_resolve_before_new_review"
        case .expired:
            nextRecommendedAction = "refresh_operator_approval_after_revalidation"
        }

        let actions: [ProductionCohortOperatorAction]
        if state == .rejected || state == .expired {
            actions = [.requestOperatorReview]
        } else if approvalEligible {
            actions = [
                .requestOperatorReview,
                .approveProductionCohortReadiness,
                .rejectProductionCohortReadiness
            ]
        } else {
            actions = [.requestOperatorReview]
        }

        return ProductionCohortOperatorApprovalDiagnostics(
            state: state,
            approvalEligible: approvalEligible,
            approvalBlockedReason: dedupedBlockers.isEmpty ? nil : dedupedBlockers.joined(separator: ", "),
            approvedScope: ProductionCohortApprovalScope(
                orgID: controlPlane.cohort.orgID,
                propertyID: controlPlane.cohort.propertyID,
                sessionID: controlPlane.cohort.sessionID
            ),
            approvalTimestamp: approvalTimestamp,
            expirationTimestamp: expirationTimestamp,
            staleApproval: staleApproval,
            nextRecommendedAction: nextRecommendedAction,
            allowedManualActions: actions,
            noBehaviorChangedText: "No behavior changed: operator approval workflow updates diagnostic approval state only. It does not enable production canonical reads, activate production candidates, switch global canonical reads, mutate production data, remove local/iCloud fallback, change export, seal, sync, media, or iCloud behavior, loosen RLS, or delete data."
        )
    }

    nonisolated static func productionCohortOperatorApprovalReportText(
        _ diagnostics: ProductionCohortOperatorApprovalDiagnostics
    ) -> String {
        var lines: [String] = []
        lines.append("Production Cohort Operator Approval")
        lines.append("- operator_approval_state: \(diagnostics.state.rawValue)")
        lines.append("- approval_eligibility: \(diagnostics.approvalEligible)")
        lines.append("- approval_blockers: \(diagnosticsPreviewText(diagnostics.approvalBlockedReason, maxLength: 220) ?? "none")")
        lines.append("- approved_org_id: \(diagnostics.approvedScope.orgID?.uuidString ?? "none")")
        lines.append("- approved_property_id: \(diagnostics.approvedScope.propertyID?.uuidString ?? "none")")
        lines.append("- approved_session_id: \(diagnostics.approvedScope.sessionID?.uuidString ?? "none")")
        lines.append("- approved_scope: \(diagnostics.approvedScope.description)")
        lines.append("- approval_timestamp: \(diagnostics.approvalTimestamp?.formatted(date: .abbreviated, time: .standard) ?? "none")")
        lines.append("- expiration_timestamp: \(diagnostics.expirationTimestamp?.formatted(date: .abbreviated, time: .standard) ?? "none")")
        lines.append("- approval_freshness: \(diagnostics.staleApproval ? "stale" : "fresh_or_not_started")")
        lines.append("- next_recommended_action: \(diagnostics.nextRecommendedAction)")
        lines.append("- manual_actions: \(diagnostics.allowedManualActions.map(\.rawValue).joined(separator: ", "))")
        lines.append(diagnostics.noBehaviorChangedText)
        return lines.joined(separator: "\n")
    }

    nonisolated static func requestProductionCohortOperatorReview(
        _ controlPlane: ProductionCohortControlPlaneDiagnostics,
        requestedAt: Date = Date(),
        expirationTimestamp: Date? = nil
    ) -> ProductionCohortOperatorActionResult {
        let diagnostics = makeProductionCohortOperatorApprovalDiagnostics(
            controlPlane,
            requestedState: .pendingReview,
            approvalTimestamp: nil,
            expirationTimestamp: expirationTimestamp,
            checkedAt: requestedAt
        )
        return ProductionCohortOperatorActionResult(
            action: .requestOperatorReview,
            diagnostics: diagnostics,
            noBehaviorChangedText: diagnostics.noBehaviorChangedText
        )
    }

    nonisolated static func approveProductionCohortReadiness(
        _ controlPlane: ProductionCohortControlPlaneDiagnostics,
        approvedAt: Date = Date(),
        expiresAt: Date? = nil
    ) -> ProductionCohortOperatorActionResult {
        let candidate = makeProductionCohortOperatorApprovalDiagnostics(
            controlPlane,
            requestedState: .approved,
            approvalTimestamp: approvedAt,
            expirationTimestamp: expiresAt,
            checkedAt: approvedAt
        )
        let diagnostics = candidate.approvalEligible ? candidate : makeProductionCohortOperatorApprovalDiagnostics(
            controlPlane,
            requestedState: .pendingReview,
            approvalTimestamp: nil,
            expirationTimestamp: expiresAt,
            checkedAt: approvedAt
        )
        return ProductionCohortOperatorActionResult(
            action: .approveProductionCohortReadiness,
            diagnostics: diagnostics,
            noBehaviorChangedText: diagnostics.noBehaviorChangedText
        )
    }

    nonisolated static func rejectProductionCohortReadiness(
        _ controlPlane: ProductionCohortControlPlaneDiagnostics,
        rejectedAt: Date = Date()
    ) -> ProductionCohortOperatorActionResult {
        let diagnostics = makeProductionCohortOperatorApprovalDiagnostics(
            controlPlane,
            requestedState: .rejected,
            approvalTimestamp: rejectedAt,
            expirationTimestamp: nil,
            checkedAt: rejectedAt
        )
        return ProductionCohortOperatorActionResult(
            action: .rejectProductionCohortReadiness,
            diagnostics: diagnostics,
            noBehaviorChangedText: diagnostics.noBehaviorChangedText
        )
    }

    nonisolated static func generateProductionRolloutDryRun(
        _ diagnostics: SessionSnapshotUploadDiagnostics,
        orgID: UUID? = nil,
        policy: ProductionCohortControlPlanePolicy = .diagnosticsOnly,
        approvalTimestamp: Date? = nil,
        expirationTimestamp: Date? = nil,
        checkedAt: Date = Date()
    ) -> ProductionRolloutDryRunPackage {
        let rolloutReadiness = makeCanonicalRolloutReadinessDiagnostics(diagnostics)
        let productionReadiness = makeProductionAllowlistReadinessDiagnostics(
            diagnostics,
            policy: ProductionAllowlistReadinessPolicy(
                operatorApproved: policy.operatorApprovalState == .approved,
                parityConfidenceThreshold: policy.parityConfidenceThreshold,
                replayConfidenceThreshold: policy.replayConfidenceThreshold,
                recommendedCohortSize: "single_org_property_session"
            )
        )
        let controlPlane = makeProductionCohortControlPlaneDiagnostics(
            diagnostics,
            orgID: orgID,
            policy: policy
        )
        let approval = makeProductionCohortOperatorApprovalDiagnostics(
            controlPlane,
            requestedState: policy.operatorApprovalState,
            approvalTimestamp: approvalTimestamp,
            expirationTimestamp: expirationTimestamp,
            checkedAt: checkedAt
        )

        let parityReplayReady = controlPlane.eligibility.parityVerified &&
            controlPlane.eligibility.replayBackfillVerified
        let candidateReady = diagnostics.lastCanonicalReadCandidateAllowed &&
            diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable
        let overlayReady = controlPlane.eligibility.overlayVerified
        let activationReady = diagnostics.lastCanonicalCandidateActivationAllowed &&
            diagnostics.lastCanonicalCandidateActivationProductionBlocked
        let rollbackFallbackReady = controlPlane.eligibility.activationRollbackVerified &&
            diagnostics.lastCanonicalReadCandidateLocalFallbackAvailable
        let productionWideDisabled = controlPlane.eligibility.productionWideDisabled

        var blockers: [String] = []
        if controlPlane.cohort.orgID == nil {
            blockers.append("org_id_required")
        }
        if controlPlane.cohort.propertyID == nil {
            blockers.append("property_id_required")
        }
        if controlPlane.cohort.sessionID == nil {
            blockers.append("session_id_required")
        }
        if !productionWideDisabled {
            blockers.append("production_wide_canonical_reads_not_disabled")
        }
        if !controlPlane.eligibility.allowlistComplete {
            blockers.append("allowlist_incomplete")
        }
        if !parityReplayReady {
            blockers.append("parity_or_replay_not_verified")
        }
        if !candidateReady {
            blockers.append("candidate_not_ready")
        }
        if !overlayReady {
            blockers.append("overlay_not_verified")
        }
        if !activationReady {
            blockers.append("activation_readiness_not_verified")
        }
        if !rollbackFallbackReady {
            blockers.append("rollback_or_fallback_not_verified")
        }
        blockers.append(contentsOf: controlPlane.eligibility.unresolvedBlockers.map { "unresolved_\($0)" })
        if approval.state == .rejected {
            blockers.append("operator_rejected")
        }
        if approval.state == .expired || approval.staleApproval {
            blockers.append("operator_approval_expired")
        }
        if let approvalBlockedReason = approval.approvalBlockedReason,
           approval.state == .approved || approval.state == .rejected || approval.state == .expired {
            blockers.append(contentsOf: approvalBlockedReason.split(separator: ",").map {
                "approval_\($0.trimmingCharacters(in: .whitespaces))"
            })
        }

        let dedupedBlockers = Array(Set(blockers)).sorted()
        let state: ProductionRolloutDryRunState
        if !dedupedBlockers.isEmpty {
            state = .dryRunBlocked
        } else if approval.state == .approved {
            state = .dryRunReadyForSingleSessionAllowlist
        } else {
            state = .dryRunReadyForOperatorReview
        }

        let requiredOperatorActions: [String]
        switch state {
        case .dryRunReadyForOperatorReview:
            requiredOperatorActions = [
                ProductionCohortOperatorAction.requestOperatorReview.rawValue,
                ProductionCohortOperatorAction.approveProductionCohortReadiness.rawValue
            ]
        case .dryRunReadyForSingleSessionAllowlist:
            requiredOperatorActions = ["copy_dry_run_report_to_operator_rollout_record"]
        case .dryRunNotReady:
            requiredOperatorActions = ["resolve_dry_run_readiness_gaps"]
        case .dryRunBlocked:
            requiredOperatorActions = ["disable_production_wide_canonical_reads_before_any_review"]
        }

        let readinessSummary = [
            "canonical=\(rolloutReadiness.state.rawValue)",
            "production_allowlist=\(productionReadiness.state.rawValue)",
            "cohort=\(controlPlane.cohort.rolloutStage.rawValue)",
            "operator_approval=\(approval.state.rawValue)",
            "parity_replay=\(parityReplayReady)",
            "candidate=\(candidateReady)",
            "overlay=\(overlayReady)",
            "activation_readiness=\(activationReady)",
            "rollback_fallback=\(rollbackFallbackReady)"
        ].joined(separator: " ")

        return ProductionRolloutDryRunPackage(
            state: state,
            canonicalDiagnostics: diagnostics,
            rolloutReadiness: rolloutReadiness,
            productionAllowlistReadiness: productionReadiness,
            cohortControlPlane: controlPlane,
            operatorApprovalReadiness: approval,
            parityReplayReady: parityReplayReady,
            candidateReady: candidateReady,
            overlayReady: overlayReady,
            activationReady: activationReady,
            rollbackFallbackReady: rollbackFallbackReady,
            readinessSummary: readinessSummary,
            blockers: dedupedBlockers,
            requiredOperatorActions: requiredOperatorActions,
            rollbackPlan: "Keep active source local; if any future allowlist validation fails, restore diagnostic active source to local for the selected session and retain local/iCloud fallback.",
            fallbackPlan: "Continue local-first reads with iCloud/local fallback retained; do not consume production canonical rows in this dry run.",
            productionWideDisabledConfirmation: productionWideDisabled,
            localHealthAction: "Generate Production Rollout Dry Run",
            noChangesPerformedText: "No changes performed: production rollout dry run is diagnostics-only. It does not enable production reads, activate candidates, switch global canonical reads, build a production overlay, write local or remote state, discard local state, remove local/iCloud fallback, change export, seal, sync, media, or iCloud behavior, loosen RLS, or delete data."
        )
    }

    nonisolated static func productionRolloutDryRunReportText(
        _ package: ProductionRolloutDryRunPackage
    ) -> String {
        var lines: [String] = []
        lines.append("Production Rollout Dry Run")
        lines.append("- selected_org_id: \(package.cohortControlPlane.cohort.orgID?.uuidString ?? "none")")
        lines.append("- selected_property_id: \(package.cohortControlPlane.cohort.propertyID?.uuidString ?? "none")")
        lines.append("- selected_session_id: \(package.cohortControlPlane.cohort.sessionID?.uuidString ?? "none")")
        lines.append("- dry_run_state: \(package.state.rawValue)")
        lines.append("- readiness_summary: \(package.readinessSummary)")
        lines.append("- blockers: \(package.blockers.isEmpty ? "none" : package.blockers.joined(separator: ", "))")
        lines.append("- required_operator_actions: \(package.requiredOperatorActions.isEmpty ? "none" : package.requiredOperatorActions.joined(separator: ", "))")
        lines.append("- rollback_plan: \(package.rollbackPlan)")
        lines.append("- fallback_plan: \(package.fallbackPlan)")
        lines.append("- production_wide_disabled_confirmation: \(package.productionWideDisabledConfirmation)")
        lines.append("- parity_replay_ready: \(package.parityReplayReady)")
        lines.append("- candidate_ready: \(package.candidateReady)")
        lines.append("- overlay_ready: \(package.overlayReady)")
        lines.append("- activation_ready: \(package.activationReady)")
        lines.append("- rollback_fallback_ready: \(package.rollbackFallbackReady)")
        lines.append("- local_health_action: \(package.localHealthAction)")
        lines.append(package.noChangesPerformedText)
        return lines.joined(separator: "\n")
    }

    private nonisolated static func canonicalCandidateMediaRecoveryConfidence(
        uploadDiagnostics: SessionSnapshotUploadDiagnostics
    ) -> Double {
        let manifestCount = uploadDiagnostics.lastRestoreDiagnosticsMediaManifestCount
        guard manifestCount > 0 else { return 1 }
        if uploadDiagnostics.lastRestoreDiagnosticsMediaChecksumMismatchCount > 0 ||
            uploadDiagnostics.lastRestoreDiagnosticsMediaMissingCount > 0 ||
            uploadDiagnostics.lastRestoreDiagnosticsMediaUnsupportedCount > 0 {
            return 0
        }
        let recoverable = max(
            uploadDiagnostics.lastRestoreDiagnosticsMediaRecoverableRemoteCount,
            uploadDiagnostics.lastRestoreDiagnosticsMediaRecoverableLocalCount
        )
        return min(Double(recoverable) / Double(manifestCount), 1)
    }

    private nonisolated static func canonicalDiagnosticRecommendationRank(_ result: CanonicalReadDiagnosticResult) -> Int {
        switch result {
        case .localOnly, .remoteMissing, .unableToVerify:
            return 0
        case .parentMismatch, .divergentConflict, .localNewerConflict:
            return 1
        case .remoteNewerCandidate:
            return 2
        case .remoteMatchesLocal:
            return 3
        }
    }

    private nonisolated static func canonicalReadState(
        restoreDiagnostics: SessionSnapshotRestoreDiagnosticsResult?,
        recoveryCohort: SnapshotRecoveryCohortResult?,
        conflictState: CanonicalConflictState,
        hydrationConfidence: String,
        mediaRecoveryConfidence: String
    ) -> CanonicalReadState {
        guard let restoreDiagnostics else { return .localOnly }
        if conflictState != .none { return .conflictMode }
        guard restoreDiagnostics.result == .restorableMetadataCandidate else {
            return restoreDiagnostics.result == .noSnapshotFound || restoreDiagnostics.result == .objectMissing
                ? .localOnly
                : .recoveryMode
        }
        if mediaRecoveryConfidence == "partial_missing_media" || mediaRecoveryConfidence == "blocked_checksum_mismatch" {
            return .recoveryMode
        }
        if recoveryCohort?.readiness == .readyForManualHydration,
           hydrationConfidence == "manual_metadata_hydration_ready",
           restoreDiagnostics.checksumVerified,
           restoreDiagnostics.rowObjectVerified,
           restoreDiagnostics.parentRemoteVerified {
            return .remoteCandidate
        }
        return .localPreferredRemoteVerified
    }

    private nonisolated static func canonicalConflictState(
        restoreDiagnostics: SessionSnapshotRestoreDiagnosticsResult?,
        mediaRecoveryConfidence: String
    ) -> CanonicalConflictState {
        guard let restoreDiagnostics else { return .notChecked }
        switch restoreDiagnostics.result {
        case .localNewerConflict:
            return .localNewerThanRemote
        case .staleSnapshot:
            return .staleSnapshot
        case .checksumFailed, .parentMismatch:
            return .divergentEdits
        default:
            break
        }
        if mediaRecoveryConfidence == "partial_missing_media" { return .partialMediaRecovery }
        if mediaRecoveryConfidence == "missing_media" { return .missingMedia }
        return .none
    }

    private nonisolated static func canonicalHydrationConfidence(
        restoreDiagnostics: SessionSnapshotRestoreDiagnosticsResult?,
        recoveryCohort: SnapshotRecoveryCohortResult?,
        hydrationPolicy: SessionSnapshotHydrationPolicyDiagnostics?
    ) -> String {
        guard let restoreDiagnostics else { return "not_checked" }
        guard restoreDiagnostics.result == .restorableMetadataCandidate else {
            return "blocked_restore_diagnostics_\(restoreDiagnostics.result.rawValue)"
        }
        guard recoveryCohort?.readiness == .readyForManualHydration else {
            return "needs_recovery_cohort_review"
        }
        guard hydrationPolicy?.hydrationAvailable == true else {
            return "hydration_policy_not_available"
        }
        if hydrationPolicy?.productionHydrationAllowed == false {
            return "manual_metadata_hydration_ready"
        }
        return "manual_metadata_hydration_ready_production_override_present"
    }

    private nonisolated static func canonicalMediaRecoveryConfidence(
        _ diagnostics: SessionSnapshotMediaRecoveryDiagnostics?
    ) -> String {
        guard let diagnostics else { return "not_checked" }
        if diagnostics.manifestCount == 0 { return "no_media_manifest" }
        if diagnostics.checksumMismatchCount > 0 { return "blocked_checksum_mismatch" }
        if diagnostics.unsupportedCount > 0 || !diagnostics.manifestSupported { return "unsupported_media_manifest" }
        if diagnostics.missingCount >= diagnostics.manifestCount { return "missing_media" }
        if diagnostics.missingCount > 0 { return "partial_missing_media" }
        if diagnostics.recoverableRemoteCount + diagnostics.recoverableLocalCount >= diagnostics.manifestCount {
            return "recoverable"
        }
        if diagnostics.checksumUnknownCount > 0 { return "checksum_unknown" }
        return "not_recoverable"
    }

    private nonisolated static func canonicalRemoteFreshnessAgeSeconds(
        checkedAt: Date,
        restoreDiagnostics: SessionSnapshotRestoreDiagnosticsResult?
    ) -> TimeInterval? {
        guard let generatedAt = restoreDiagnostics?.snapshotGeneratedAt else { return nil }
        return max(0, checkedAt.timeIntervalSince(generatedAt))
    }

    private nonisolated static func canonicalUploadSuccessMetric(
        _ diagnostics: SessionSnapshotUploadDiagnostics?
    ) -> String {
        guard let diagnostics else { return "not_available" }
        return "attempted=\(diagnostics.attemptedCount) success=\(diagnostics.successCount) failure=\(diagnostics.failureCount)"
    }

    private nonisolated static func canonicalSourceRecommendation(
        readState: CanonicalReadState,
        conflictState: CanonicalConflictState,
        hydrationConfidence: String,
        mediaRecoveryConfidence: String
    ) -> (recommendation: String, reason: String) {
        switch readState {
        case .remoteCandidate:
            return (
                "local_preferred_remote_candidate",
                "Remote snapshot and parent verification are strong enough for allowlisted canonical-read candidate diagnostics, but reads remain local-first."
            )
        case .localPreferredRemoteVerified:
            return (
                "local_preferred_remote_verified",
                "Remote data is useful for comparison and recovery planning, while local/iCloud remains the operational source."
            )
        case .recoveryMode:
            return (
                "local_with_recovery_assist",
                "Recovery prerequisites are incomplete: hydration=\(hydrationConfidence) media=\(mediaRecoveryConfidence)."
            )
        case .conflictMode:
            return (
                "local_until_operator_review",
                "Conflict state \(conflictState.rawValue) blocks canonical transition."
            )
        case .remoteCanonical:
            return (
                "remote_canonical_future_only",
                "Reserved for a later rollout phase; Phase 2C-26E never enables remote canonical reads."
            )
        case .localOnly:
            return (
                "local_only",
                "Remote snapshot readiness is not verified enough to recommend a canonical-read candidate."
            )
        }
    }

    private nonisolated static func canonicalRecoveryFallbackState(
        readState: CanonicalReadState,
        conflictState: CanonicalConflictState,
        mediaRecoveryConfidence: String
    ) -> String {
        if conflictState != .none && conflictState != .notChecked {
            return "operator_review_required_before_recovery"
        }
        if mediaRecoveryConfidence == "recoverable" {
            return "snapshot_metadata_plus_guarded_media_recovery_available"
        }
        if readState == .localOnly {
            return "local_icloud_backup_primary"
        }
        return "snapshot_metadata_recovery_only"
    }

    nonisolated static func makeCanonicalReadinessReport(
        inspectedAt: Date = Date(),
        activeOrganizationID: UUID?,
        diagnostics: LocalDiagnosticsState,
        retryCappedMediaCount: Int,
        pendingMediaCount: Int,
        mediaRecoveryCandidateCount: Int?,
        divergenceAuditSummary: DivergenceAuditSummary?,
        syncDebtInspectionReport: SyncDebtInspectionReport?,
        remoteOnlySessionDetailReport: RemoteOnlySessionDetailReport?
    ) -> CanonicalReadinessReport {
        let queueSection = canonicalQueueReadinessSection(diagnostics: diagnostics)
        let mediaSection = canonicalMediaReadinessSection(
            retryCappedMediaCount: retryCappedMediaCount,
            pendingMediaCount: pendingMediaCount,
            mediaRecoveryCandidateCount: mediaRecoveryCandidateCount
        )
        let divergenceSection = canonicalDivergenceReadinessSection(
            divergenceAuditSummary: divergenceAuditSummary,
            syncDebtInspectionReport: syncDebtInspectionReport,
            remoteOnlySessionDetailReport: remoteOnlySessionDetailReport
        )
        let remoteScopeSection = canonicalRemoteScopeReadinessSection(
            activeOrganizationID: activeOrganizationID,
            divergenceAuditSummary: divergenceAuditSummary,
            remoteOnlySessionDetailReport: remoteOnlySessionDetailReport
        )
        let propertySection = canonicalStaticReadinessSection(
            id: "property_metadata",
            title: "Property Metadata Readiness",
            status: .warn,
            summary: "Mostly ready for scoped property canonical reads.",
            rows: [
                canonicalRow("property_reads", "Supabase property reads", .pass, "available", "Foreground/background property refresh can read Supabase and preserve local fallback."),
                canonicalRow("property_writes", "Supabase property writes", .pass, "healthy", "Property shadow writes/upserts are established."),
                canonicalRow("property_scope", "Recommended scope", .warn, "scoped only", "Broad metadata canonical switching should not be inferred from property readiness alone.")
            ]
        )
        let sessionSection = canonicalStaticReadinessSection(
            id: "session_metadata",
            title: "Session Metadata Readiness",
            status: .block,
            summary: "Blocked for broad canonical reads because full session.json remains local-first.",
            rows: [
                canonicalRow("session_rows", "Supabase session rows", .pass, "available", "Session row deltas and writes cover lifecycle basics."),
                canonicalRow("session_json", "Full session.json", .block, "local-first", "The export/session UI package is not reconstructed canonically from Supabase."),
                canonicalRow("session_hydration", "Session hydration", .block, "not enabled", "Remote sessions are not hydrated into local shells by normal sync.")
            ]
        )
        let shotSection = canonicalStaticReadinessSection(
            id: "shot_metadata",
            title: "Shot Metadata Readiness",
            status: .warn,
            summary: "Partial: rich writes exist, but remote read reconstruction is not complete.",
            rows: [
                canonicalRow("shot_writes", "Rich shot metadata writes", .pass, "available", "Shot metadata and storage fields are written to Supabase."),
                canonicalRow("shot_reconstruction", "Remote-to-local shot reconstruction", .block, "missing", "Remote shot rows do not yet rebuild local SessionMetadata.shots for normal history."),
                canonicalRow("shot_media", "Media reads", .warn, "lazy/by-need", "Downloads require local shot metadata and storage paths.")
            ]
        )
        let issuesGuidedSection = canonicalStaticReadinessSection(
            id: "issues_guided",
            title: "Issues/Guided Readiness",
            status: .block,
            summary: "Blocked: issues, observations, and guided checkpoints remain local/session JSON based.",
            rows: [
                canonicalRow("issues", "Issues/observations", .block, "local-first", "Issue history and observation state are not fully canonical remote read sources."),
                canonicalRow("guided", "Guided rows/checkpoints", .block, "local-first", "Guided rows and reference state remain local/session metadata based.")
            ]
        )
        let exportSection = canonicalStaticReadinessSection(
            id: "export_scoutprocess",
            title: "Export/ScoutProcess Safety",
            status: .block,
            summary: "Protected from canonical switching until complete local packages are guaranteed.",
            rows: [
                canonicalRow("export_package", "Export package", .block, "local complete required", "ScoutProcess/export requires session.json, CSVs, issue history, guided rows, and local media."),
                canonicalRow("export_guard", "Rollout guard", .pass, "protected", "Canonical read rollout should not change export eligibility.")
            ]
        )
        let iCloudSection = canonicalStaticReadinessSection(
            id: "icloud_fallback",
            title: "iCloud Fallback Status",
            status: .warn,
            summary: "Required during transition.",
            rows: [
                canonicalRow("icloud_role", "iCloud role", .warn, "required", "iCloud remains backup, fallback, and transition safety net."),
                canonicalRow("icloud_reduction", "Fallback reduction", .pass, "none", "Canonical readiness reporting does not remove or reduce iCloud behavior.")
            ]
        )
        let uxSection = canonicalStaticReadinessSection(
            id: "ux_freshness",
            title: "UX/Freshness Readiness",
            status: .block,
            summary: "Partial: property-open freshness exists for property rows; broader child metadata freshness and portal conflict rules remain blocked.",
            rows: [
                canonicalRow("freshness_check", "Property open freshness check", .warn, "scoped property-only implemented", "Checks Supabase property row on open without auto-merge; broader child metadata freshness remains deferred."),
                canonicalRow("conflict_rules", "Web portal conflict rules", .block, "deferred", "Future portal edits need freshness and conflict UX before broad canonical reads.")
            ]
        )

        let sections = [
            queueSection,
            mediaSection,
            divergenceSection,
            remoteScopeSection,
            propertySection,
            sessionSection,
            shotSection,
            issuesGuidedSection,
            exportSection,
            iCloudSection,
            uxSection
        ]

        let blockingOperationalGate = [queueSection, mediaSection, divergenceSection, remoteScopeSection].contains { $0.status == .block }
        let overall: CanonicalReadinessOverallStatus
        if activeOrganizationID == nil {
            overall = .unknown
        } else if blockingOperationalGate {
            overall = .blocked
        } else {
            overall = .notReadyForBroadCanonicalReads
        }

        return CanonicalReadinessReport(
            inspectedAt: inspectedAt,
            activeOrganizationID: activeOrganizationID,
            overallStatus: overall,
            sections: sections,
            recommendedNextSlices: [
                "Add read-only canonical readiness trend/report history.",
                "Add property-open remote freshness check before showing cached metadata as current.",
                "Define metadata completeness gates for session, shot, issue, and guided rows.",
                "Prototype metadata-only session/shot hydration behind manual review.",
                "Keep export and ScoutProcess local-package gated until metadata/media completeness is proven."
            ],
            noBehaviorChangedText: "No behavior changed: this report is read-only diagnostics and does not switch canonical reads, hydrate sessions, retry queues, download media, change exports, change sync, change iCloud fallback, or mutate local/remote data."
        )
    }

    nonisolated static func canonicalReadinessReportText(_ report: CanonicalReadinessReport) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Canonical Readiness")
        lines.append("Inspected: \(report.inspectedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(report.activeOrganizationID?.uuidString ?? "none")")
        lines.append("Overall Status: \(report.overallStatus.rawValue)")
        lines.append(report.noBehaviorChangedText)
        lines.append("")
        lines.append("Readiness Gates")
        for section in report.sections {
            lines.append("")
            lines.append("\(section.title): \(section.status.rawValue)")
            lines.append("Summary: \(diagnosticsPreviewText(section.summary, maxLength: 180) ?? "none")")
            for row in section.rows {
                lines.append([
                    row.status.rawValue,
                    diagnosticsPreviewText(row.label, maxLength: 80) ?? "row",
                    diagnosticsPreviewText(row.value, maxLength: 80) ?? "none",
                    diagnosticsPreviewText(row.detail, maxLength: 180) ?? "none"
                ].joined(separator: " | "))
            }
        }
        lines.append("")
        lines.append("Recommended Next Slices")
        for slice in report.recommendedNextSlices {
            lines.append("- \(diagnosticsPreviewText(slice, maxLength: 180) ?? "next slice")")
        }
        return lines.joined(separator: "\n")
    }

    private nonisolated static func canonicalQueueReadinessSection(
        diagnostics: LocalDiagnosticsState
    ) -> CanonicalReadinessSection {
        let retryableFailed = diagnostics.offlineQueue.failedCount
        let status: CanonicalReadinessGateStatus = retryableFailed == 0 ? .pass : .block
        return canonicalStaticReadinessSection(
            id: "queue_health",
            title: "Queue Health",
            status: status,
            summary: retryableFailed == 0
                ? "Retryable failed queue is clean; acknowledged historical debt is informational."
                : "Retryable failed queue must be zero before canonical reads expand.",
            rows: [
                canonicalRow("retryable_failed_queue", "Retryable failed queue", retryableFailed == 0 ? .pass : .block, String(retryableFailed), "Must be 0."),
                canonicalRow("acknowledged_historical_queue_debt", "Acknowledged historical debt", .warn, String(diagnostics.offlineQueue.acknowledgedHistoricalCount), "Allowed but listed separately; does not block readiness."),
                canonicalRow("pending_queue", "Pending queue", diagnostics.offlineQueue.pendingCount == 0 ? .pass : .warn, String(diagnostics.offlineQueue.pendingCount), "Pending queue is operational cache, not canonical read proof.")
            ]
        )
    }

    private nonisolated static func canonicalMediaReadinessSection(
        retryCappedMediaCount: Int,
        pendingMediaCount: Int,
        mediaRecoveryCandidateCount: Int?
    ) -> CanonicalReadinessSection {
        let mediaRecoveryStatus: CanonicalReadinessGateStatus
        if let mediaRecoveryCandidateCount {
            mediaRecoveryStatus = mediaRecoveryCandidateCount == 0 ? .pass : .block
        } else {
            mediaRecoveryStatus = .unknown
        }
        let status: CanonicalReadinessGateStatus
        if pendingMediaCount > 0 || retryCappedMediaCount > 0 || (mediaRecoveryCandidateCount ?? 0) > 0 {
            status = .block
        } else if mediaRecoveryCandidateCount == nil {
            status = .unknown
        } else {
            status = .pass
        }
        return canonicalStaticReadinessSection(
            id: "media_health",
            title: "Media Health",
            status: status,
            summary: status == .pass
                ? "Pending, retry-capped, and recovery candidate media counts are clean."
                : "Media readiness requires pending, retry-capped, and recovery candidate counts to be zero.",
            rows: [
                canonicalRow("pending_media", "Pending media", pendingMediaCount == 0 ? .pass : .block, String(pendingMediaCount), "Must be 0."),
                canonicalRow("retry_capped_media", "Retry-capped media", retryCappedMediaCount == 0 ? .pass : .block, String(retryCappedMediaCount), "Must be 0."),
                canonicalRow("media_recovery_candidates", "Media recovery candidates", mediaRecoveryStatus, mediaRecoveryCandidateCount.map(String.init) ?? "not inspected", "Must be 0 after inspection.")
            ]
        )
    }

    private nonisolated static func canonicalDivergenceReadinessSection(
        divergenceAuditSummary: DivergenceAuditSummary?,
        syncDebtInspectionReport: SyncDebtInspectionReport?,
        remoteOnlySessionDetailReport: RemoteOnlySessionDetailReport?
    ) -> CanonicalReadinessSection {
        let missingHydrationCount =
            remoteOnlySessionDetailReport?.items.filter { $0.classification == .missingLocalHydration }.count ??
            syncDebtInspectionReport?.divergenceItems.filter { $0.classification == .missingLocalHydration }.count
        let emptyShellCount = remoteOnlySessionDetailReport?.items.filter { $0.classification == .emptyRemoteDraftShell }.count ?? 0
        let remoteOnlyActionable = remoteOnlySessionDetailReport?.items.filter {
            $0.classification == .missingLocalHydration ||
                $0.classification == .trueParityDebt ||
                $0.classification == .manualReview ||
                $0.labels.contains(.possibleHydrationCandidate)
        }.count
        let activeParityFindings = divergenceAuditSummary?.items.filter { item in
            item.lifecycle == .activeSyncFailure &&
                item.category != .remoteUnavailable &&
                item.category != .remoteOnlySession
        }.count
        let status: CanonicalReadinessGateStatus
        if (missingHydrationCount ?? 0) > 0 || (remoteOnlyActionable ?? 0) > 0 || (activeParityFindings ?? 0) > 0 {
            status = .block
        } else if missingHydrationCount == nil || activeParityFindings == nil {
            status = .unknown
        } else {
            status = .pass
        }
        return canonicalStaticReadinessSection(
            id: "divergence_health",
            title: "Divergence Health",
            status: status,
            summary: status == .pass
                ? "No actionable hydration/parity debt is currently indicated; empty remote draft shells are informational."
                : "Divergence readiness requires missing hydration and actionable parity findings to be zero.",
            rows: [
                canonicalRow("missing_local_hydration", "Missing local hydration", missingHydrationCount == nil ? .unknown : ((missingHydrationCount ?? 0) == 0 ? .pass : .block), missingHydrationCount.map(String.init) ?? "not inspected", "Must be 0."),
                canonicalRow("empty_remote_draft_shells", "Empty remote draft shells", .warn, String(emptyShellCount), "Informational and not recommended for hydration; does not block."),
                canonicalRow("remote_only_actionable", "Actionable remote-only sessions", remoteOnlyActionable == nil ? .unknown : ((remoteOnlyActionable ?? 0) == 0 ? .pass : .block), remoteOnlyActionable.map(String.init) ?? "not inspected", "Must be 0, excluding empty draft shells/historical rows."),
                canonicalRow("active_parity_findings", "Active property/session parity findings", activeParityFindings == nil ? .unknown : ((activeParityFindings ?? 0) == 0 ? .pass : .block), activeParityFindings.map(String.init) ?? "not inspected", "Must be 0 before broad canonical reads.")
            ]
        )
    }

    private nonisolated static func canonicalRemoteScopeReadinessSection(
        activeOrganizationID: UUID?,
        divergenceAuditSummary: DivergenceAuditSummary?,
        remoteOnlySessionDetailReport: RemoteOnlySessionDetailReport?
    ) -> CanonicalReadinessSection {
        let remoteAvailable = divergenceAuditSummary?.remoteScopeAvailable ?? remoteOnlySessionDetailReport?.remoteScopeAvailable
        let status: CanonicalReadinessGateStatus = {
            guard activeOrganizationID != nil else { return .unknown }
            guard let remoteAvailable else { return .unknown }
            return remoteAvailable ? .pass : .block
        }()
        return canonicalStaticReadinessSection(
            id: "remote_scope_org",
            title: "Remote Scope/Org Health",
            status: status,
            summary: status == .pass ? "Active org and remote diagnostic scope are available." : "Remote scope and active org must be available before rollout.",
            rows: [
                canonicalRow("active_org", "Active org", activeOrganizationID == nil ? .unknown : .pass, activeOrganizationID?.uuidString ?? "none", "Required for scoped Supabase canonical reads."),
                canonicalRow("remote_scope", "Remote scope available", remoteAvailable == nil ? .unknown : (remoteAvailable == true ? .pass : .block), remoteAvailable.map { $0 ? "yes" : "no" } ?? "not inspected", "Required for trustworthy readiness decisions.")
            ]
        )
    }

    private nonisolated static func canonicalStaticReadinessSection(
        id: String,
        title: String,
        status: CanonicalReadinessGateStatus,
        summary: String,
        rows: [CanonicalReadinessRow]
    ) -> CanonicalReadinessSection {
        CanonicalReadinessSection(
            id: id,
            title: title,
            status: status,
            summary: summary,
            rows: rows
        )
    }

    private nonisolated static func canonicalRow(
        _ id: String,
        _ label: String,
        _ status: CanonicalReadinessGateStatus,
        _ value: String,
        _ detail: String
    ) -> CanonicalReadinessRow {
        CanonicalReadinessRow(id: id, label: label, status: status, value: value, detail: detail)
    }

    nonisolated static func remoteOnlySessionDetailReportText(_ report: RemoteOnlySessionDetailReport) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Remote-Only Session Detail Inspector")
        lines.append("Inspected: \(report.inspectedAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(report.activeOrganizationID?.uuidString ?? "none")")
        lines.append("Remote Scope Available: \(report.remoteScopeAvailable ? "yes" : "no")")
        if let unavailableReason = diagnosticsPreviewText(report.unavailableReason, maxLength: 160) {
            lines.append("Unavailable Reason: \(unavailableReason)")
        }
        lines.append("Remote-Only Sessions: \(report.items.count)")

        if report.items.isEmpty {
            lines.append("none")
            return lines.joined(separator: "\n")
        }

        for item in report.items {
            lines.append("")
            lines.append("Session \(item.sessionID.uuidString)")
            lines.append("  property_id: \(item.propertyID.uuidString)")
            lines.append("  org_id: \(item.orgID.uuidString)")
            lines.append("  remote_status: \(diagnosticsPreviewText(item.remoteStatus, maxLength: 60) ?? "unknown")")
            lines.append("  started_at: \(diagnosticsPreviewText(item.startedAt, maxLength: 80) ?? "none")")
            lines.append("  completed_at: \(diagnosticsPreviewText(item.completedAt, maxLength: 80) ?? "none")")
            lines.append("  updated_at: \(item.updatedAt?.formatted(date: .abbreviated, time: .standard) ?? "none")")
            lines.append("  deleted_at: \(item.deletedAt?.formatted(date: .abbreviated, time: .standard) ?? "none")")
            lines.append("  capture_profile: \(diagnosticsPreviewText(item.captureProfile, maxLength: 60) ?? "none")")
            lines.append("  parent_property_exists_locally: \(item.parentPropertyExistsLocally ? "yes" : "no")")
            lines.append("  local_property_name: \(diagnosticsPreviewText(item.localPropertyName, maxLength: 80) ?? "none")")
            lines.append("  local_session_row_exists: \(item.localSessionRowExists ? "yes" : "no")")
            lines.append("  local_session_folder_exists: \(item.localSessionFolderExists ? "yes" : "no")")
            lines.append("  local_session_json_exists: \(item.localSessionJSONExists ? "yes" : "no")")
            lines.append("  local_originals_folder_exists: \(item.localOriginalsFolderExists ? "yes" : "no")")
            lines.append("  remote_shot_count: \(item.remoteShotCount)")
            lines.append("  remote_issue_observation_count: \(item.remoteIssueObservationCount.map(String.init) ?? "unavailable")")
            lines.append("  remote_shots_with_storage_path: \(item.remoteShotsWithStoragePathCount)")
            lines.append("  remote_shots_missing_storage_path: \(item.remoteShotsMissingStoragePathCount)")
            lines.append("  appears_deleted: \(item.appearsDeleted ? "yes" : "no")")
            lines.append("  appears_stale: \(item.appearsStale ? "yes" : "no")")
            lines.append("  appears_draft: \(item.appearsDraft ? "yes" : "no")")
            lines.append("  appears_completed: \(item.appearsCompleted ? "yes" : "no")")
            lines.append("  classification: \(item.classification.rawValue)")
            lines.append("  classification_reason: \(diagnosticsPreviewText(item.classificationReason, maxLength: 180) ?? "none")")
            lines.append("  labels: \(item.labels.map(\.rawValue).joined(separator: ", "))")
        }

        return lines.joined(separator: "\n")
    }

    nonisolated static func divergenceAuditSnapshotText(_ summary: DivergenceAuditSummary) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Divergence Audit")
        lines.append("Ran: \(summary.ranAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(summary.activeOrganizationID?.uuidString ?? "none")")
        lines.append("Remote Scope Available: \(summary.remoteScopeAvailable ? "yes" : "no")")
        lines.append("")
        lines.append("Core Sync Health")
        lines.append("Matched Properties: \(summary.matchedPropertyCount) / local \(summary.localPropertyCount) / remote \(summary.remotePropertyCount)")
        lines.append("Matched Sessions: \(summary.matchedSessionCount) / local \(summary.localSessionCount) / remote \(summary.remoteSessionCount)")
        lines.append("Matched Shots: \(summary.matchedShotCount) / local \(summary.localShotCount) / remote \(summary.remoteShotCount)")
        lines.append("Local-Only Properties: \(summary.localOnlyPropertyCount)")
        lines.append("Remote-Only Properties: \(summary.remoteOnlyPropertyCount)")
        lines.append("Local-Only Sessions: \(summary.localOnlySessionCount)")
        lines.append("Remote-Only Sessions: \(summary.remoteOnlySessionCount)")
        lines.append("")
        lines.append("Active Sync Issues")
        lines.append("Actionable Failure Findings: \(summary.activeSyncIssueCount)")
        lines.append("")
        lines.append("Recoverable Issues")
        lines.append("Recoverable Findings: \(summary.recoverableIssueCount)")
        lines.append("Local-Only Shots: \(summary.localOnlyShotCount)")
        lines.append("Remote-Only Shots: \(summary.remoteOnlyShotCount)")
        lines.append("")
        lines.append("Historical / Informational States")
        lines.append("Historical or Informational Findings: \(summary.historicalInformationalCount)")
        lines.append("Stale Org Reconciled Properties: \(summary.staleOrgReconciledPropertyCount)")
        lines.append("Stale Org Reconciled Shots: \(summary.staleOrgReconciledShotCount)")
        lines.append("Stale org reconciled means remote active-org ownership proved historical local org metadata safe for audit.")
        lines.append("")
        let groupedHistoricalFindings = summary.groupedHistoricalFindings
        if !groupedHistoricalFindings.isEmpty {
            lines.append("Grouped Historical Summaries")
            for group in groupedHistoricalFindings {
                lines.append([
                    group.category.rawValue,
                    "total \(group.totalCount)",
                    "properties \(group.affectedPropertyCount)",
                    "sessions \(group.affectedSessionCount)",
                    "shots \(group.affectedShotCount)"
                ].joined(separator: " | "))
                for sample in group.sampleItems {
                    lines.append([
                        "sample",
                        sample.entityID?.uuidString ?? "none",
                        sample.propertyID?.uuidString ?? "none",
                        sample.sessionID?.uuidString ?? "none",
                        sample.shotID?.uuidString ?? "none"
                    ].joined(separator: " | "))
                }
            }
            lines.append("")
        }
        lines.append("Category Counts")
        let counts = Dictionary(grouping: summary.items, by: \.category).mapValues(\.count)
        for category in DivergenceAuditCategory.allCases {
            let count = counts[category] ?? 0
            if count > 0 {
                lines.append("\(category.rawValue): \(count)")
            }
        }
        lines.append("")
        lines.append("Findings")
        for item in summary.items {
            lines.append([
                item.severity.rawValue,
                item.category.rawValue,
                item.entityType,
                item.entityID?.uuidString ?? "none",
                item.propertyID?.uuidString ?? "none",
                item.sessionID?.uuidString ?? "none",
                item.shotID?.uuidString ?? "none",
                item.orgID?.uuidString ?? "none",
                diagnosticsPreviewText(item.reason, maxLength: 240) ?? "none"
            ].joined(separator: " | "))
        }
        return lines.joined(separator: "\n")
    }

    nonisolated static func syncDebtInspectionReportText(_ report: SyncDebtInspectionReport) -> String {
        var lines: [String] = []
        lines.append("ScoutCapture Local Health - Sync Debt Inspection")
        lines.append("Ran: \(report.ranAt.formatted(date: .abbreviated, time: .standard))")
        lines.append("Active Org: \(report.activeOrganizationID?.uuidString ?? "none")")
        lines.append("")
        lines.append("Failed Queue Debt")
        lines.append("Failed Queue Items: \(report.failedQueueItems.count)")
        if report.failedQueueItems.isEmpty {
            lines.append("none")
        } else {
            for item in report.failedQueueItems {
                let payload = item.payloadSummary
                lines.append([
                    item.classification.rawValue,
                    item.entityType,
                    item.entityID.uuidString,
                    item.operation,
                    "queue_id \(item.id.uuidString)",
                    "org \(item.orgID.uuidString)",
                    "property \(item.propertyID?.uuidString ?? payload.payloadPropertyID?.uuidString ?? "none")",
                    "session \(item.sessionID?.uuidString ?? payload.payloadSessionID?.uuidString ?? "none")",
                    "idempotency \(item.idempotencyKey)",
                    "attempts \(item.attemptCount)",
                    "created \(item.createdAt.formatted(date: .abbreviated, time: .standard))",
                    "last_attempt \(item.lastAttemptAt?.formatted(date: .abbreviated, time: .standard) ?? "none")",
                    "next_attempt \(item.nextAttemptAt?.formatted(date: .abbreviated, time: .standard) ?? "none")",
                    "error_category \(item.lastErrorCategory.rawValue)",
                    "error \(diagnosticsPreviewText(item.lastErrorMessage, maxLength: 180) ?? "none")",
                    "payload_kind \(payload.payloadKind)",
                    "payload_org \(payload.payloadOrgID?.uuidString ?? "none")",
                    "payload_property \(payload.payloadPropertyID?.uuidString ?? "none")",
                    "payload_session \(payload.payloadSessionID?.uuidString ?? "none")",
                    "property_name \(diagnosticsPreviewText(payload.propertyName, maxLength: 80) ?? "none")",
                    "session_status \(diagnosticsPreviewText(payload.sessionStatus, maxLength: 40) ?? "none")",
                    "session_started_at \(diagnosticsPreviewText(payload.sessionStartedAt, maxLength: 60) ?? "none")",
                    "updated_by \(item.updatedBy?.uuidString ?? "none")",
                    "decode_error \(diagnosticsPreviewText(payload.decodeError, maxLength: 120) ?? "none")",
                    "acknowledged_at \(item.acknowledgedAt?.formatted(date: .abbreviated, time: .standard) ?? "none")",
                    "acknowledged_classification \(item.acknowledgedClassification ?? "none")",
                    "acknowledgement_source \(diagnosticsPreviewText(item.acknowledgementSource, maxLength: 80) ?? "none")",
                    "acknowledged_reason \(diagnosticsPreviewText(item.acknowledgedReason, maxLength: 120) ?? "none")"
                ].joined(separator: " | "))
            }
        }

        lines.append("")
        lines.append("Divergence Debt")
        lines.append("Findings: \(report.divergenceItems.count)")
        if report.divergenceItems.isEmpty {
            lines.append("none")
        } else {
            for item in report.divergenceItems {
                lines.append([
                    item.classification.rawValue,
                    item.category.rawValue,
                    item.entityType,
                    "entity \(item.entityID?.uuidString ?? "none")",
                    "property \(item.propertyID?.uuidString ?? "none")",
                    "session \(item.sessionID?.uuidString ?? "none")",
                    "shot \(item.shotID?.uuidString ?? "none")",
                    "org \(item.orgID?.uuidString ?? "none")",
                    "reason \(diagnosticsPreviewText(item.reason, maxLength: 180) ?? "none")",
                    "classification_reason \(diagnosticsPreviewText(item.classificationReason, maxLength: 180) ?? "none")"
                ].joined(separator: " | "))
            }
        }

        lines.append("")
        lines.append("Grouped Historical / Informational Findings")
        if report.groupedHistoricalFindings.isEmpty {
            lines.append("none")
        } else {
            for group in report.groupedHistoricalFindings {
                lines.append([
                    group.category.rawValue,
                    "total \(group.totalCount)",
                    "properties \(group.affectedPropertyCount)",
                    "sessions \(group.affectedSessionCount)",
                    "shots \(group.affectedShotCount)"
                ].joined(separator: " | "))
            }
        }
        return lines.joined(separator: "\n")
    }

    private func performQueuedPropertyRemoteWrite(
        property: Property,
        payload: SupabasePropertyPayload
    ) async throws {
        do {
            if let propertyShadowWriteOverride {
                try await propertyShadowWriteOverride(property)
            } else {
                try await upsertPropertyRowToSupabase(payload)
            }
            recordShadowWriteDiagnostics(entity: .property, succeeded: true)
        } catch {
            recordShadowWriteDiagnostics(entity: .property, succeeded: false, error: error)
            throw error
        }
    }

    private func performRemotePropertyInsert(
        property: Property,
        payload: SupabasePropertyPayload
    ) async throws {
        if let propertyRemoteInsertOverride {
            try await propertyRemoteInsertOverride(property)
        } else {
            try await insertPropertyRowToSupabase(payload)
        }
    }

    private func performQueuedSessionRemoteWrite(
        property: Property,
        session: Session,
        metadata: SessionMetadata,
        payload: QueuedSessionMutationPayload
    ) async throws {
        print(
            "[SessionCoordinationWrite] event=begin " +
            "entityType=session " +
            "entityID=\(session.id.uuidString) " +
            "operation=upsert_session " +
            "orgID=\(property.orgId?.uuidString ?? "nil")"
        )
        do {
            if let sessionShadowWriteOverride {
                try await sessionShadowWriteOverride(property, session, metadata)
            } else {
                let canonicalPayload = canonicalQueuedSessionMutationPayload(
                    payload,
                    property: property,
                    session: session,
                    metadata: metadata
                )
                try await upsertPropertyRowToSupabase(canonicalPayload.property)
                print(
                    "[SessionCoordinationWrite] event=session_upsert_attempt " +
                    "entityID=\(session.id.uuidString) " +
                    "captureProfile=\(canonicalPayload.session.captureProfile ?? "nil")"
                )
                try await upsertSessionRowToSupabase(canonicalPayload.session)
                print(
                    "[SessionCoordinationWrite] event=session_upsert_success " +
                    "entityID=\(session.id.uuidString) " +
                    "captureProfile=\(canonicalPayload.session.captureProfile ?? "nil")"
                )
            }
            recordShadowWriteDiagnostics(entity: .session, succeeded: true)
        } catch {
            print(
                "[SessionCoordinationWrite] event=failed " +
                "entityID=\(session.id.uuidString) " +
                "error=\(error.localizedDescription)"
            )
            recordShadowWriteDiagnostics(entity: .session, succeeded: false, error: error)
            throw error
        }
    }

    private func canonicalQueuedSessionMutationPayload(
        _ payload: QueuedSessionMutationPayload,
        property: Property,
        session: Session,
        metadata: SessionMetadata
    ) -> QueuedSessionMutationPayload {
        QueuedSessionMutationPayload(
            property: payload.property,
            session: makeSupabaseSessionPayload(
                sessionID: session.id,
                propertyID: property.id,
                orgID: payload.session.orgID,
                property: property,
                metadata: metadata,
                session: session
            )
        )
    }

