    private func resolveShotStorageMetadata(
        propertyID: UUID,
        sessionID: UUID,
        shot: ShotMetadata,
        allowRelaxedLookupFallback: Bool = false
    ) async -> ShotMetadata {
        let hasLocalBucket = shot.storageBucket?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
        let hasLocalPath = shot.storagePath?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
        guard !(hasLocalBucket && hasLocalPath) else {
            return shot
        }

        let strictRemote = try? await fetchShotStorageMetadataFromSupabase(
            sessionID: sessionID,
            shotID: shot.shotID
        )

        let remote: SupabaseShotStorageRecord?
        if let strict = strictRemote {
            remote = strict
        } else if allowRelaxedLookupFallback {
            remote = try? await fetchShotStorageMetadataFromSupabaseForBackfillRepair(
                shotID: shot.shotID
            )
        } else {
            remote = nil
        }

        guard let remote else {
            return shot
        }

        try? localStore.updateShotStorageMetadata(propertyID: propertyID, sessionID: sessionID, shotID: shot.shotID) { localShot in
            localShot.storageBucket = remote.storageBucket ?? localShot.storageBucket
            localShot.storagePath = remote.storagePath ?? localShot.storagePath
            localShot.checksumSHA256 = remote.checksumSHA256 ?? localShot.checksumSHA256
            localShot.byteSize = remote.byteSize ?? localShot.byteSize
            localShot.uploadState = remote.uploadState
            localShot.uploadAttempts = max(localShot.uploadAttempts, remote.uploadAttempts)
            localShot.lastUploadError = remote.lastUploadError ?? localShot.lastUploadError
        }

        var resolvedShot = shot
        resolvedShot.storageBucket = remote.storageBucket ?? resolvedShot.storageBucket
        resolvedShot.storagePath = remote.storagePath ?? resolvedShot.storagePath
        resolvedShot.checksumSHA256 = remote.checksumSHA256 ?? resolvedShot.checksumSHA256
        resolvedShot.byteSize = remote.byteSize ?? resolvedShot.byteSize
        resolvedShot.uploadState = remote.uploadState
        resolvedShot.uploadAttempts = max(resolvedShot.uploadAttempts, remote.uploadAttempts)
        resolvedShot.lastUploadError = remote.lastUploadError ?? resolvedShot.lastUploadError
        return resolvedShot
    }

    private func operationalMediaStoragePath(
        sessionID: UUID,
        shotID: UUID,
        originalFilename: String
    ) -> String {
        let normalizedFilename = sanitizedStorageFilename(originalFilename, fallbackShotID: shotID)
        return "sessions/\(sessionID.uuidString.lowercased())/shots/\(shotID.uuidString.lowercased())/\(normalizedFilename)"
    }

    private func sanitizedStorageFilename(_ originalFilename: String, fallbackShotID: UUID) -> String {
        let candidate = URL(fileURLWithPath: originalFilename).lastPathComponent
        let fallback = "\(fallbackShotID.uuidString.lowercased()).heic"
        let base = candidate.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? fallback : candidate
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "._-"))
        let sanitizedScalars = base.unicodeScalars.map { allowed.contains($0) ? Character($0) : "_" }
        let sanitized = String(sanitizedScalars)
        return sanitized.isEmpty ? fallback : sanitized
    }

    private func contentType(for fileURL: URL) -> String {
        let fileExtension = fileURL.pathExtension.trimmingCharacters(in: .whitespacesAndNewlines)
        #if canImport(UniformTypeIdentifiers)
        if let type = UTType(filenameExtension: fileExtension),
           let mimeType = type.preferredMIMEType {
            return mimeType
        }
        #endif

        switch fileExtension.lowercased() {
        case "heic", "heif":
            return "image/heic"
        case "jpg", "jpeg":
            return "image/jpeg"
        case "png":
            return "image/png"
        default:
            return "application/octet-stream"
        }
    }

    private func sha256Hex(for data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    private func supabaseUploadOperationKey(sessionID: UUID, shotID: UUID) -> String {
        "upload|\(sessionID.uuidString.lowercased())|\(shotID.uuidString.lowercased())"
    }

    private func beginSupabaseMediaOperation(_ key: String) -> Bool {
        supabaseMediaOperationQueue.sync {
            if inFlightSupabaseMediaOperations.contains(key) {
                return false
            }
            inFlightSupabaseMediaOperations.insert(key)
            return true
        }
    }

    private func endSupabaseMediaOperation(_ key: String) {
        let _: Void = supabaseMediaOperationQueue.sync {
            inFlightSupabaseMediaOperations.remove(key)
        }
    }

    private func snapshotInFlightSupabaseMediaOperations() -> Set<String> {
        supabaseMediaOperationQueue.sync {
            inFlightSupabaseMediaOperations
        }
    }

    private func beginSupabaseMediaBackfillRun() -> Bool {
        supabaseMediaOperationQueue.sync {
            if isSupabaseMediaBackfillInProgress {
                return false
            }
            isSupabaseMediaBackfillInProgress = true
            return true
        }
    }

    private func endSupabaseMediaBackfillRun() {
        let _: Void = supabaseMediaOperationQueue.sync {
            isSupabaseMediaBackfillInProgress = false
        }
    }

    private func fetchRemotePropertyList(activeOrganizationID: UUID) async throws -> [RemotePropertyRecord] {
        guard let client = supabaseClient else {
            throw RemotePropertyFetchError.missingClient
        }

        return try await withThrowingTaskGroup(of: [RemotePropertyRecord].self) { group in
            group.addTask {
                try await client
                    .from("properties")
                    .select(
                        """
                        id,
                        org_id,
                        folder_id,
                        capture_profile,
                        client_name,
                        client_email,
                        client_phone,
                        name,
                        address_line1,
                        city,
                        state,
                        postal_code,
                        baseline_session_id,
                        is_archived,
                        deleted_at,
                        created_at,
                        updated_at,
                        updated_by,
                        revision
                        """
                    )
                    .eq("org_id", value: activeOrganizationID.uuidString.lowercased())
                    .execute()
                    .value as [RemotePropertyRecord]
            }

            group.addTask {
                try await Task.sleep(nanoseconds: 3_000_000_000)
                throw RemotePropertyFetchError.timedOut
            }

            guard let firstResult = try await group.next() else {
                throw RemotePropertyFetchError.timedOut
            }
            group.cancelAll()
            return firstResult
        }
    }

    private func validateRemotePropertyResponse(
        records: [RemotePropertyRecord],
        localCacheCount: Int,
        activeOrganizationID: UUID
    ) throws -> [RemotePropertyRecord] {
        if localCacheCount > 0 &&
            records.isEmpty &&
            !isPropertyScopedOrganization(activeOrganizationID) {
            throw RemotePropertyFetchError.emptyResponseRejected(localCacheCount: localCacheCount)
        }

        var seenIDs = Set<UUID>()
        for record in records {
            let trimmedName = record.name.trimmingCharacters(in: .whitespacesAndNewlines)
            let trimmedAddressLine1 = record.addressLine1.trimmingCharacters(in: .whitespacesAndNewlines)
            let trimmedCity = record.city.trimmingCharacters(in: .whitespacesAndNewlines)
            let trimmedState = record.state.trimmingCharacters(in: .whitespacesAndNewlines)
            let trimmedPostalCode = record.postalCode.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmedName.isEmpty else {
                throw RemotePropertyFetchError.invalidPropertyName(record.id)
            }
            guard !trimmedAddressLine1.isEmpty else {
                throw RemotePropertyFetchError.invalidAddressLine1(record.id)
            }
            guard !trimmedCity.isEmpty else {
                throw RemotePropertyFetchError.invalidCity(record.id)
            }
            guard !trimmedState.isEmpty else {
                throw RemotePropertyFetchError.invalidState(record.id)
            }
            guard !trimmedPostalCode.isEmpty else {
                throw RemotePropertyFetchError.invalidPostalCode(record.id)
            }
            guard record.orgID == activeOrganizationID else {
                throw RemotePropertyFetchError.orgScopeMismatch(
                    expected: activeOrganizationID,
                    actual: record.orgID,
                    propertyID: record.id
                )
            }
            guard seenIDs.insert(record.id).inserted else {
                throw RemotePropertyFetchError.duplicatePropertyID(record.id)
            }
            guard remotePropertyDateIsValid(record.updatedAt) else {
                logRemotePropertyTimestampIssue(
                    kind: "updated_at",
                    propertyID: record.id,
                    orgID: record.orgID,
                    value: record.updatedAt
                )
                throw RemotePropertyFetchError.invalidUpdatedAt(record.id)
            }
            if let createdAt = record.createdAt,
               !remotePropertyDateIsValid(createdAt) {
                logRemotePropertyTimestampIssue(
                    kind: "created_at",
                    propertyID: record.id,
                    orgID: record.orgID,
                    value: createdAt
                )
                throw RemotePropertyFetchError.invalidCreatedAt(record.id)
            }
            if let deletedAt = record.deletedAt,
               !remotePropertyDateIsValid(deletedAt) {
                logRemotePropertyTimestampIssue(
                    kind: "deleted_at",
                    propertyID: record.id,
                    orgID: record.orgID,
                    value: deletedAt
                )
                throw RemotePropertyFetchError.invalidUpdatedAt(record.id)
            }
        }

        return records
    }

    private func backingPropertyCount(for organizationID: UUID) -> Int {
        allProperties.reduce(into: 0) { count, property in
            if property.orgId == organizationID {
                count += 1
            }
        }
    }

    private func orgScopedProperties(
        in properties: [Property],
        organizationID: UUID
    ) -> [Property] {
        properties.filter { $0.orgId == organizationID }
    }

    private func beginPropertyRefreshAuthority(
        orgID: UUID?,
        priority: PropertyRefreshPriority,
        source: String
    ) -> PropertyRefreshAuthority {
        nextPropertyRefreshToken &+= 1
        let authority = PropertyRefreshAuthority(
            token: nextPropertyRefreshToken,
            orgID: orgID,
            priority: priority,
            userID: authenticatedSupabaseUser?.id,
            contextGeneration: authenticatedAccessContextGeneration,
            source: source
        )
        if let orgID {
            newestStartedPropertyRefreshByOrg[orgID] = authority
        }
        return authority
    }

    private func shouldApplyRefreshPayload(
        _ payload: PropertyRefreshPayload,
        authority: PropertyRefreshAuthority?,
        replacingOrganizationID: UUID?
    ) -> Bool {
        guard let authority else {
            return true
        }

        guard authority.userID == authenticatedSupabaseUser?.id,
              authority.contextGeneration == authenticatedAccessContextGeneration else {
            print(
                "[RefreshAuthority] reject reason=stale_auth_context " +
                "source=\(authority.source) token=\(authority.token)"
            )
            return false
        }

        guard let organizationID = replacingOrganizationID ?? authority.orgID else {
            return true
        }

        let orgProperties = orgScopedProperties(in: payload.properties, organizationID: organizationID)
        let uniquePropertyIDs = Set(orgProperties.map(\.id))
        guard uniquePropertyIDs.count == orgProperties.count else {
            print(
                "[RefreshAuthority] reject reason=duplicate_property_ids " +
                "source=\(authority.source) token=\(authority.token) " +
                "orgID=\(organizationID.uuidString) " +
                "orgScopedCount=\(orgProperties.count) uniqueCount=\(uniquePropertyIDs.count)"
            )
            return false
        }

        if let newestAuthority = newestStartedPropertyRefreshByOrg[organizationID],
           newestAuthority.token != authority.token,
           newestAuthority.priority.rawValue >= authority.priority.rawValue {
            print(
                "[RefreshAuthority] reject reason=newer_or_higher_priority_refresh_exists " +
                "source=\(authority.source) token=\(authority.token) " +
                "orgID=\(organizationID.uuidString) " +
                "newestToken=\(newestAuthority.token) newestPriority=\(newestAuthority.priority.rawValue)"
            )
            return false
        }

        if let lastAppliedState = lastAppliedPropertyRefreshByOrg[organizationID] {
            if lastAppliedState.fingerprint == payload.fingerprint &&
                lastAppliedState.orgScopedCount != orgProperties.count {
                print(
                    "[RefreshAuthority] reject reason=fingerprint_count_mismatch " +
                    "source=\(authority.source) token=\(authority.token) " +
                    "orgID=\(organizationID.uuidString) " +
                    "fingerprint=\(payload.fingerprint) " +
                    "incomingCount=\(orgProperties.count) appliedCount=\(lastAppliedState.orgScopedCount)"
                )
                return false
            }

            if lastAppliedState.priority.rawValue > authority.priority.rawValue &&
                (lastAppliedState.fingerprint != payload.fingerprint ||
                 lastAppliedState.orgScopedCount != orgProperties.count) {
                let isExpectedNormalFallbackRejection =
                    authority.priority == .fallback &&
                    authority.source == "background_fast_local"
                if !isExpectedNormalFallbackRejection {
                    print(
                        "[RefreshAuthority] reject reason=lower_priority_cannot_override " +
                        "source=\(authority.source) token=\(authority.token) " +
                        "orgID=\(organizationID.uuidString) " +
                        "incomingPriority=\(authority.priority.rawValue) " +
                        "appliedPriority=\(lastAppliedState.priority.rawValue)"
                    )
                }
                return false
            }
        }

        lastAppliedPropertyRefreshByOrg[organizationID] = AppliedPropertyRefreshState(
            token: authority.token,
            priority: authority.priority,
            fingerprint: payload.fingerprint,
            orgScopedCount: orgProperties.count
        )
        return true
    }

    private func makeRemotePropertyRefreshPayload(
        validatedRecords: [RemotePropertyRecord],
        requestedOrganizationID: UUID
    ) throws -> PropertyRefreshPayload {
        let normalizedRecords = try normalizedRemotePropertyRecordsForPayload(
            validatedRecords,
            requestedOrganizationID: requestedOrganizationID
        )
        let properties: [Property] = try normalizedRecords.map { record in
            let trimmedAddressLine1 = record.addressLine1.trimmingCharacters(in: .whitespacesAndNewlines)
            let trimmedCity = record.city.trimmingCharacters(in: .whitespacesAndNewlines)
            let trimmedState = record.state.trimmingCharacters(in: .whitespacesAndNewlines)
            let trimmedPostalCode = record.postalCode.trimmingCharacters(in: .whitespacesAndNewlines)
            let createdAt = try resolvedRemotePropertyCreatedAt(for: record)
            let address = "\(trimmedAddressLine1), \(trimmedCity), \(trimmedState) \(trimmedPostalCode)"
            return Property(
                id: record.id,
                orgId: record.orgID,
                folderId: normalizedRemotePropertyText(record.folderID),
                captureProfile: CaptureProfile(storedValue: record.captureProfile)
                    ?? allProperties.first(where: { $0.id == record.id })?.captureProfile,
                clientName: normalizedRemotePropertyText(record.clientName),
                clientPhone: normalizedRemotePropertyText(record.clientPhone),
                clientEmail: normalizedRemotePropertyText(record.clientEmail),
                name: record.name.trimmingCharacters(in: .whitespacesAndNewlines),
                address: address,
                street: trimmedAddressLine1,
                city: trimmedCity,
                state: trimmedState,
                zip: trimmedPostalCode,
                baselineSessionID: record.baselineSessionID,
                isArchived: record.isArchived,
                deletedAt: record.deletedAt,
                createdAt: createdAt,
                updatedAt: record.updatedAt
            )
        }.sorted(by: Self.propertyIsOrderedBefore)
        let organizations = allOrganizations.isEmpty ? organizations : allOrganizations
        let caches = makeHubCaches(for: properties)
        let fingerprint = try remotePropertyFingerprint(
            for: normalizedRecords,
            activeOrganizationID: requestedOrganizationID
        )
        return PropertyRefreshPayload(
            properties: properties,
            organizations: organizations,
            caches: caches,
            fingerprint: fingerprint
        )
    }

    private func normalizedRemotePropertyRecordsForPayload(
        _ records: [RemotePropertyRecord],
        requestedOrganizationID: UUID
    ) throws -> [RemotePropertyRecord] {
        let sortedRecords = records.sorted { lhs, rhs in
            lhs.id.uuidString.lowercased() < rhs.id.uuidString.lowercased()
        }
        for record in sortedRecords {
            guard record.orgID == requestedOrganizationID else {
                throw RemotePropertyFetchError.orgScopeMismatch(
                    expected: requestedOrganizationID,
                    actual: record.orgID,
                    propertyID: record.id
                )
            }
            guard remotePropertyDateIsValid(record.updatedAt) else {
                logRemotePropertyTimestampIssue(
                    kind: "updated_at",
                    propertyID: record.id,
                    orgID: record.orgID,
                    value: record.updatedAt
                )
                throw RemotePropertyFetchError.invalidUpdatedAt(record.id)
            }
            if let createdAt = record.createdAt,
               !remotePropertyDateIsValid(createdAt) {
                logRemotePropertyTimestampIssue(
                    kind: "created_at",
                    propertyID: record.id,
                    orgID: record.orgID,
                    value: createdAt
                )
                throw RemotePropertyFetchError.invalidCreatedAt(record.id)
            }
            if let deletedAt = record.deletedAt,
               !remotePropertyDateIsValid(deletedAt) {
                logRemotePropertyTimestampIssue(
                    kind: "deleted_at",
                    propertyID: record.id,
                    orgID: record.orgID,
                    value: deletedAt
                )
                throw RemotePropertyFetchError.invalidUpdatedAt(record.id)
            }
            _ = try resolvedRemotePropertyCreatedAt(for: record)
        }
        return sortedRecords
    }

    private func remotePropertyDateIsValid(_ value: Date) -> Bool {
        let interval = value.timeIntervalSince1970
        guard interval.isFinite else { return false }
        guard interval > 0 else { return false }
        let minimum = Date(timeIntervalSince1970: 946684800) // 2000-01-01T00:00:00Z
        let maximum = Date(timeIntervalSince1970: 4_102_444_800) // 2100-01-01T00:00:00Z
        return value >= minimum && value <= maximum
    }

    private func resolvedRemotePropertyCreatedAt(for record: RemotePropertyRecord) throws -> Date {
        if let createdAt = record.createdAt {
            return createdAt
        }
        if let localCreatedAt = allProperties.first(where: { $0.id == record.id })?.createdAt
            ?? properties.first(where: { $0.id == record.id })?.createdAt {
            print(
                "[RemotePropertyFetch] " +
                "outcome=used_local_createdAt_fallback " +
                "propertyID=\(record.id.uuidString) " +
                "orgID=\(record.orgID.uuidString)"
            )
            return localCreatedAt
        }
        throw RemotePropertyFetchError.missingLocalCreatedAtFallback(record.id)
    }

    private func normalizedRemotePropertyText(_ value: String?) -> String? {
        guard let value else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    private func logRemotePropertyTimestampIssue(
        kind: String,
        propertyID: UUID,
        orgID: UUID,
        value: Date
    ) {
        let formatter = ISO8601DateFormatter()
        print(
            "[RemotePropertyFetch] " +
            "outcome=invalid_timestamp " +
            "field=\(kind) " +
            "propertyID=\(propertyID.uuidString) " +
            "orgID=\(orgID.uuidString) " +
            "value=\(formatter.string(from: value))"
        )
    }

    private func remotePropertyFingerprint(
        for records: [RemotePropertyRecord],
        activeOrganizationID: UUID
    ) throws -> String {
        let formatter = ISO8601DateFormatter()
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        let normalizedRecords = records.sorted { lhs, rhs in
            lhs.id.uuidString.lowercased() < rhs.id.uuidString.lowercased()
        }
        let joined = try normalizedRecords.map { record in
            [
                activeOrganizationID.uuidString.lowercased(),
                record.id.uuidString.lowercased(),
                record.orgID.uuidString.lowercased(),
                normalizedRemotePropertyText(record.folderID) ?? "",
                CaptureProfile(storedValue: record.captureProfile)?.rawValue ?? "",
                normalizedRemotePropertyText(record.clientName) ?? "",
                normalizedRemotePropertyText(record.clientEmail) ?? "",
                normalizedRemotePropertyText(record.clientPhone) ?? "",
                record.name.trimmingCharacters(in: .whitespacesAndNewlines),
                record.addressLine1.trimmingCharacters(in: .whitespacesAndNewlines),
                record.city.trimmingCharacters(in: .whitespacesAndNewlines),
                record.state.trimmingCharacters(in: .whitespacesAndNewlines),
                record.postalCode.trimmingCharacters(in: .whitespacesAndNewlines),
                record.baselineSessionID?.uuidString.lowercased() ?? "",
                record.isArchived ? "true" : "false",
                record.deletedAt.map { formatter.string(from: $0) } ?? "",
                formatter.string(from: try resolvedRemotePropertyCreatedAt(for: record)),
                formatter.string(from: record.updatedAt)
            ].joined(separator: "|")
        }.joined(separator: "\n")
        let digest = SHA256.hash(data: Data(joined.utf8))
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    private func logRemotePropertyFetchResult(
        outcome: String,
        recordCount: Int?,
        error: Error?,
        fingerprint: String? = nil
    ) {
        let countText = recordCount.map(String.init) ?? "nil"
        let errorText = error?.localizedDescription ?? "nil"
        let fingerprintText = fingerprint ?? "nil"
        print(
            "[RemotePropertyFetch] " +
            "outcome=\(outcome) " +
            "recordCount=\(countText) " +
            "fingerprint=\(fingerprintText) " +
            "error=\(errorText)"
        )
    }

    private func testFetchRemoteProperties() async {
        guard backendFeatureFlags.supabaseEnabled,
              backendFeatureFlags.supabaseReadEnabled else {
            logRemotePropertyFetchResult(
                outcome: "skipped_gate_disabled",
                recordCount: nil,
                error: nil
            )
            return
        }

        guard supabaseClient != nil else {
            logRemotePropertyFetchResult(
                outcome: "skipped_missing_client",
                recordCount: nil,
                error: RemotePropertyFetchError.missingClient
            )
            return
        }

        guard let activeOrganizationID else {
            logRemotePropertyFetchResult(
                outcome: "skipped_missing_active_org",
                recordCount: nil,
                error: RemotePropertyFetchError.missingActiveOrganization
            )
            return
        }

        do {
            let localBackingCount = backingPropertyCount(for: activeOrganizationID)
            let records = try await fetchRemotePropertyList(activeOrganizationID: activeOrganizationID)
            let validated = try validateRemotePropertyResponse(
                records: records,
                localCacheCount: localBackingCount,
                activeOrganizationID: activeOrganizationID
            )
            let payload = try makeRemotePropertyRefreshPayload(
                validatedRecords: validated,
                requestedOrganizationID: activeOrganizationID
            )
            logRemotePropertyFetchResult(
                outcome: "success",
                recordCount: payload.properties.count,
                error: nil,
                fingerprint: payload.fingerprint
            )
        } catch {
            let outcome: String
            if let remoteError = error as? RemotePropertyFetchError,
               case .timedOut = remoteError {
                outcome = "timeout"
            } else {
                outcome = "rejected"
            }
            logRemotePropertyFetchResult(
                outcome: outcome,
                recordCount: nil,
                error: error
            )
        }
    }

    func loadIfNeeded() {
        guard !didLoad else { return }
        didLoad = true
        refreshProperties()
    }

    func warmLaunchReadiness(completion: @escaping () -> Void) {
        guard !didLoad else {
            completion()
            return
        }
        didLoad = true
        isStartupHydrationInProgress = true
        setLoadingState(allProperties.isEmpty)

        if allProperties.isEmpty,
           let localState = try? localStore.fetchPropertyAndOrganizationStateFromLocalHubIndexCache(),
           !localState.properties.isEmpty {
            let caches = makeHubCaches(for: localState.properties)
            applyHubCachePayload(
                properties: localState.properties,
                organizations: localState.organizations,
                caches: caches
            )
            setLoadingState(false)
            logHubFetch(
                phase: "warmLaunch",
                source: localState.source.rawValue,
                properties: localState.properties.count,
                orgs: localState.organizations.count,
                elapsedMs: 0
            )
        }

        DispatchQueue.global(qos: .utility).async {
            let start = Date()
            let fetchedState = try? self.localStore.fetchPropertyAndOrganizationStateFromHubIndex(downloadTimeout: self.startupHubIndexTimeout)
            DispatchQueue.main.async { [weak self] in
                guard let self else { return }
                if let fetchedState, !fetchedState.properties.isEmpty {
                    let elapsedMs = Int(Date().timeIntervalSince(start) * 1000)
                    self.logHubFetch(
                        phase: "warmLaunch",
                        source: fetchedState.source.rawValue,
                        properties: fetchedState.properties.count,
                        orgs: fetchedState.organizations.count,
                        elapsedMs: elapsedMs
                    )
                    let caches = self.makeHubCaches(for: fetchedState.properties)
                    self.applyHubCachePayload(
                        properties: fetchedState.properties,
                        organizations: fetchedState.organizations,
                        caches: caches
                    )
                } else {
                    let elapsedMs = Int(Date().timeIntervalSince(start) * 1000)
                    self.logHubFetch(
                        phase: "warmLaunch",
                        source: "none",
                        properties: 0,
                        orgs: 0,
                        elapsedMs: elapsedMs
                    )
                }
                self.setLoadingState(false)
                self.isStartupHydrationInProgress = false
                self.startupHydrationCompletedAt = Date()
                completion()
            }
        }
    }

    func refreshProperties() {
        cloudBackupManager?.refreshStatus()
        setLoadingState(true)
        guard isRemotePropertyRefreshEnabled else {
            performLocalPropertyRefreshFallback(
                orgID: activeOrganizationID,
                source: "refresh_properties_local"
            )
            setLoadingState(false)
            return
        }

        Task { @MainActor [weak self] in
            guard let self else { return }
            defer { self.setLoadingState(false) }
            await self.performForegroundRemotePropertyRefresh()
        }
    }

    @MainActor
    func refreshPropertiesAwaitingForegroundRefresh() async {
        cloudBackupManager?.refreshStatus()
        setLoadingState(true)
        defer { setLoadingState(false) }

        guard isRemotePropertyRefreshEnabled else {
            performLocalPropertyRefreshFallback(
                orgID: activeOrganizationID,
                source: "awaited_refresh_local"
            )
            return
        }

        await performForegroundRemotePropertyRefresh()
    }

    func refreshPropertiesInBackground() {
        cloudBackupManager?.refreshStatus()
        if isStartupHydrationInProgress {
            return
        }
        if currentSession?.status == .draft {
            return
        }
        let now = Date()
        if isBackgroundRefreshInFlight { return }
        if !allProperties.isEmpty,
           let lastBackgroundRefreshStartedAt,
           now.timeIntervalSince(lastBackgroundRefreshStartedAt) < minimumBackgroundRefreshInterval {
            return
        }
        isBackgroundRefreshInFlight = true
        lastBackgroundRefreshStartedAt = now
        setLoadingState(allProperties.isEmpty)
        DispatchQueue.global(qos: .userInitiated).async {
            let fastPayload = try? self.makeRefreshPayloadForHubIndexOnly()
            let fastHasProperties = (fastPayload?.properties.isEmpty == false)
            let withinStartupFallbackGraceWindow: Bool = {
                guard self.allProperties.isEmpty,
                      let completedAt = self.startupHydrationCompletedAt else {
                    return false
                }
                return Date().timeIntervalSince(completedAt) < self.startupFallbackGraceWindow
            }()
            // When the hub is empty, start full fallback immediately to avoid long "syncing" dead time.
            let shouldRunFallback: Bool = {
                if fastHasProperties { return false }
                if self.allProperties.isEmpty { return true }
                return !withinStartupFallbackGraceWindow
            }()

            DispatchQueue.main.async { [weak self] in
                guard let self else { return }
                if let fastPayload, fastHasProperties || self.allProperties.isEmpty {
                    let authority = self.beginPropertyRefreshAuthority(
                        orgID: self.activeOrganizationID,
                        priority: .fallback,
                        source: "background_fast_local"
                    )
                    self.applyRefreshPayload(
                        fastPayload,
                        authority: authority,
                        replacingOrganizationID: self.activeOrganizationID
                    )
                    self.scheduleOffloadEligibleSessionMedia(excludingSessionID: self.currentSession?.id)
                }
                if fastHasProperties || !self.allProperties.isEmpty {
                    self.setLoadingState(false)
                }
                if !fastHasProperties, withinStartupFallbackGraceWindow {
                    self.setLoadingState(false)
                    self.isBackgroundRefreshInFlight = false
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
                        guard let self else { return }
                        self.refreshPropertiesInBackground()
                    }
                    return
                }
                if !shouldRunFallback {
                    if self.isRemotePropertyRefreshEnabled {
                        Task { @MainActor [weak self] in
                            guard let self else { return }
                            await self.performBackgroundRemotePropertyRefresh()
                        }
                    } else {
                        self.isBackgroundRefreshInFlight = false
                    }
                }
            }

            guard shouldRunFallback else { return }

            do {
                let payload = try self.makeRefreshPayload()
                DispatchQueue.main.async { [weak self] in
                    guard let self else { return }
                    let authority = self.beginPropertyRefreshAuthority(
                        orgID: self.activeOrganizationID,
                        priority: .fallback,
                        source: "background_full_local"
                    )
                    self.applyRefreshPayload(
                        payload,
                        authority: authority,
                        replacingOrganizationID: self.activeOrganizationID
                    )
                    self.scheduleOffloadEligibleSessionMedia(excludingSessionID: self.currentSession?.id)
                    self.setLoadingState(false)
                    if self.isRemotePropertyRefreshEnabled {
                        Task { @MainActor [weak self] in
                            guard let self else { return }
                            await self.performBackgroundRemotePropertyRefresh()
                        }
                    } else {
                        self.isBackgroundRefreshInFlight = false
                    }
                }
            } catch {
                DispatchQueue.main.async { [weak self] in
                    guard let self else { return }
                    // Preserve current in-memory view on transient iCloud read failures.
                    print("[PropertiesRefresh] transient read failure: \(error.localizedDescription)")
                    self.setLoadingState(false)
                    self.isBackgroundRefreshInFlight = false
                }
            }
        }
    }

    func refreshPropertySessionState(propertyID: UUID) {
        guard canAccessProperty(propertyID) else { return }
        reloadSessionCache(for: propertyID)
    }

    func canonicalLockSession(for propertyID: UUID) -> Session? {
        sessions(for: propertyID)
            .sorted { $0.startedAt > $1.startedAt }
            .first
    }

    func isPropertyOccupiedByOther(propertyID: UUID) -> Bool {
        guard let occupancy = propertySessionOccupancyByPropertyID[propertyID] else { return false }
        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        let isOwnedByCurrentActor =
            occupancy.occupiedByUserID == currentUserID &&
            normalizedSupabaseText(occupancy.occupiedByDeviceID) == currentDeviceID
        let hasOccupancy =
            occupancy.occupiedByUserID != nil ||
            normalizedSupabaseText(occupancy.occupiedByDeviceID) != nil
        return hasOccupancy && !isOwnedByCurrentActor
    }

    func clearLocalLocks() {
        locallyLockedPropertyIDs.removeAll()
    }

    func reconcileLocalLocksAfterRefresh() async {
        var stillLocked: Set<UUID> = []

        for propertyID in locallyLockedPropertyIDs {
            guard let property = properties.first(where: { $0.id == propertyID }),
                  let orgID = property.orgId else { continue }
            guard propertyStatusByPropertyID[propertyID] == nil else { continue }
            let currentUserID = authenticatedSupabaseUser?.id
            let currentDeviceID = currentDeviceIdentifier()

            if let activeOtherLock = await activeRemotePropertyLockOwnedByOther(
                orgID: orgID,
                propertyID: propertyID,
                currentUserID: currentUserID,
                currentDeviceID: currentDeviceID
            ) {
                setSessionCoordinationState(
                    sessionID: activeOtherLock.id,
                    lockedByUserID: activeOtherLock.lockedByUserID,
                    lockedByDeviceID: normalizedSupabaseText(activeOtherLock.lockedByDeviceID),
                    lockedAt: activeOtherLock.lockedAt.flatMap(parseSupabaseDateString)
                )
                stillLocked.insert(propertyID)
                if userDefaults.bool(forKey: "lock_badge_refresh_verbose_logging") {
                    print(
                        "[LockBadge] propertyID=\(propertyID.uuidString) " +
                        "visible=true reason=active_remote_property_lock " +
                        "lockSessionID=\(activeOtherLock.id.uuidString)"
                    )
                }
                continue
            }

            guard let session = canonicalLockSession(for: propertyID) else {
                if userDefaults.bool(forKey: "lock_badge_refresh_verbose_logging") {
                    print(
                        "[LockBadge] propertyID=\(propertyID.uuidString) " +
                        "visible=false reason=no_active_remote_or_local_lock_session"
                    )
                }
                continue
            }

            let remoteRecord = try? await fetchRemoteSessionCoordinationRecord(
                orgID: orgID,
                propertyID: propertyID,
                sessionID: session.id
            )
            let remoteLockedAt = remoteRecord?.lockedAt.flatMap(parseSupabaseDateString)
            let remoteHasLockFields = hasActiveRemoteLock(
                session: session,
                lockedByUserID: remoteRecord?.lockedByUserID,
                lockedByDeviceID: remoteRecord?.lockedByDeviceID,
                lockedAt: remoteLockedAt
            )

            if remoteRecord != nil, remoteHasLockFields {
                setSessionCoordinationState(
                    sessionID: session.id,
                    lockedByUserID: remoteRecord?.lockedByUserID,
                    lockedByDeviceID: normalizedSupabaseText(remoteRecord?.lockedByDeviceID),
                    lockedAt: remoteLockedAt
                )
            } else {
                setSessionCoordinationState(
                    sessionID: session.id,
                    lockedByUserID: nil,
                    lockedByDeviceID: nil,
                    lockedAt: nil
                )
            }

            let isStillLocked: Bool = {
                guard let remote = remoteRecord else { return false }

                let hasLock = hasActiveRemoteLock(
                    session: session,
                    lockedByUserID: remote.lockedByUserID,
                    lockedByDeviceID: remote.lockedByDeviceID,
                    lockedAt: remote.lockedAt.flatMap(parseSupabaseDateString)
                )

                let isOwnedByCurrentActor =
                    remote.lockedByUserID == currentUserID &&
                    normalizedSupabaseText(remote.lockedByDeviceID) == currentDeviceID

                return hasLock && !isOwnedByCurrentActor
            }()

            if isStillLocked {
                stillLocked.insert(propertyID)
                if userDefaults.bool(forKey: "lock_badge_refresh_verbose_logging") {
                    print(
                        "[LockBadge] propertyID=\(propertyID.uuidString) " +
                        "visible=true reason=active_remote_session_lock " +
                        "lockSessionID=\(session.id.uuidString)"
                    )
                }
            }
        }

        await MainActor.run {
            self.locallyLockedPropertyIDs = stillLocked
        }
    }

    private struct RefreshLockBadgeDecision {
        let propertyID: UUID
        let showLocked: Bool
        let reason: String
        let occupancyState: PropertySessionOccupancyState?
        let sessionLockState: (sessionID: UUID, state: SessionCoordinationState)?
        let clearSessionIDs: [UUID]
        let lockTimestamp: Date?
        let finalizationTimestamp: Date?
        let precedenceWinner: String
    }

    private struct PropertyFinalizationEvidence {
        let sessionID: UUID?
        let eventType: String
        let timestamp: Date
    }

    @MainActor
    private func refreshVisibleLockBadgesFromEntrySources(
        orgID: UUID,
        propertyIDs: [UUID],
        reason: String
    ) async {
        let uniquePropertyIDs = Array(Set(propertyIDs))
        guard !uniquePropertyIDs.isEmpty else { return }

        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        let statusOwnedPropertyIDs = Set(uniquePropertyIDs.filter { propertyStatusByPropertyID[$0] != nil })
        let legacyPropertyIDs = uniquePropertyIDs.filter { propertyStatusByPropertyID[$0] == nil }
        var decisions: [RefreshLockBadgeDecision] = []

        for propertyID in legacyPropertyIDs {
            let lockRecords = await fetchRemotePropertySessionLockRecordsForPrecedence(
                orgID: orgID,
                propertyID: propertyID
            )
            let finalizationEvidence = await latestFinalizationEvidence(
                orgID: orgID,
                propertyID: propertyID,
                lockRecords: lockRecords
            )
            let activeLockRecords = lockRecords
                .filter { hasActiveRemoteLock(record: $0) }
                .filter { !finalizationEvidenceBeatsLock(finalizationEvidence, lockTimestamp: lockTimestamp(for: $0)) }
                .sorted {
                    (lockTimestamp(for: $0) ?? .distantPast) >
                    (lockTimestamp(for: $1) ?? .distantPast)
                }
            let activeOtherLock = activeLockRecords.first { record in
                let lockedByDeviceID = normalizedSupabaseText(record.lockedByDeviceID)
                let ownedByCurrentActor =
                    (lockedByDeviceID != nil && lockedByDeviceID == currentDeviceID) ||
                    (record.lockedByUserID != nil && record.lockedByUserID == currentUserID)
                return !ownedByCurrentActor
            }
            let clearableSessionIDs = Array(
                Set((allSessionIndexByProperty[propertyID] ?? []).map(\.id))
                    .union((sessionIndexByProperty[propertyID] ?? []).map(\.id))
                    .union(lockRecords.map(\.id))
            )
            if let activeOtherLock {
                let propertyOccupancy = try? await fetchRemotePropertySessionOccupancyRecord(
                    orgID: orgID,
                    propertyID: propertyID
                )
                let activeLockTimestamp = lockTimestamp(for: activeOtherLock)
                let occupancyState = PropertySessionOccupancyState(
                    occupiedByUserID: propertyOccupancy?.occupiedByUserID ?? activeOtherLock.lockedByUserID,
                    occupiedByDeviceID: normalizedSupabaseText(propertyOccupancy?.occupiedByDeviceID) ??
                        normalizedSupabaseText(activeOtherLock.lockedByDeviceID),
                    occupiedAt: propertyOccupancy?.occupiedAt.flatMap(parseSupabaseDateString) ??
                        activeLockTimestamp
                )
                decisions.append(
                    RefreshLockBadgeDecision(
                        propertyID: propertyID,
                        showLocked: true,
                        reason: "active_remote_property_lock",
                        occupancyState: occupancyState,
                        sessionLockState: (
                            activeOtherLock.id,
                            SessionCoordinationState(
                                lockedByUserID: activeOtherLock.lockedByUserID,
                                lockedByDeviceID: normalizedSupabaseText(activeOtherLock.lockedByDeviceID),
                                lockedAt: activeOtherLock.lockedAt.flatMap(parseSupabaseDateString)
                            )
                        ),
                        clearSessionIDs: [],
                        lockTimestamp: activeLockTimestamp,
                        finalizationTimestamp: finalizationEvidence?.timestamp,
                        precedenceWinner: "lock"
                    )
                )
                continue
            }

            if let activeOwnOrNeutralLock = activeLockRecords.first {
                let lockOwnerDeviceID = normalizedSupabaseText(activeOwnOrNeutralLock.lockedByDeviceID)
                let lockOwnedByCurrentActor =
                    (lockOwnerDeviceID != nil && lockOwnerDeviceID == currentDeviceID) ||
                    (activeOwnOrNeutralLock.lockedByUserID != nil && activeOwnOrNeutralLock.lockedByUserID == currentUserID)
                let propertyOccupancy = try? await fetchRemotePropertySessionOccupancyRecord(
                    orgID: orgID,
                    propertyID: propertyID
                )
                let activeLockTimestamp = lockTimestamp(for: activeOwnOrNeutralLock)
                let occupancyState = PropertySessionOccupancyState(
                    occupiedByUserID: propertyOccupancy?.occupiedByUserID ?? activeOwnOrNeutralLock.lockedByUserID,
                    occupiedByDeviceID: normalizedSupabaseText(propertyOccupancy?.occupiedByDeviceID) ?? lockOwnerDeviceID,
                    occupiedAt: propertyOccupancy?.occupiedAt.flatMap(parseSupabaseDateString) ??
                        activeLockTimestamp
                )
                decisions.append(
                    RefreshLockBadgeDecision(
                        propertyID: propertyID,
                        showLocked: !lockOwnedByCurrentActor,
                        reason: lockOwnedByCurrentActor ? "material_draft_lock_owned_by_current_device" : "material_draft_lock_other_device",
                        occupancyState: occupancyState,
                        sessionLockState: (
                            activeOwnOrNeutralLock.id,
                            SessionCoordinationState(
                                lockedByUserID: activeOwnOrNeutralLock.lockedByUserID,
                                lockedByDeviceID: lockOwnerDeviceID,
                                lockedAt: activeOwnOrNeutralLock.lockedAt.flatMap(parseSupabaseDateString)
                            )
                        ),
                        clearSessionIDs: [],
                        lockTimestamp: activeLockTimestamp,
                        finalizationTimestamp: finalizationEvidence?.timestamp,
                        precedenceWinner: lockOwnedByCurrentActor ? "owner_draft" : "lock"
                    )
                )
                continue
            }

            let propertyOccupancy = try? await fetchRemotePropertySessionOccupancyRecord(
                orgID: orgID,
                propertyID: propertyID
            )
            if propertySessionOccupancyIsActive(propertyOccupancy) {
                let occupancyOwnerUserID = propertyOccupancy?.occupiedByUserID
                let occupancyOwnerDeviceID = normalizedSupabaseText(propertyOccupancy?.occupiedByDeviceID)
                let occupancyTimestamp = propertyOccupancy?.occupiedAt.flatMap(parseSupabaseDateString)
                if finalizationEvidenceBeatsLock(finalizationEvidence, lockTimestamp: occupancyTimestamp) {
                    decisions.append(
                        RefreshLockBadgeDecision(
                            propertyID: propertyID,
                            showLocked: false,
                            reason: "finalization_newer_than_occupancy",
                            occupancyState: nil,
                            sessionLockState: nil,
                            clearSessionIDs: clearableSessionIDs,
                            lockTimestamp: occupancyTimestamp,
                            finalizationTimestamp: finalizationEvidence?.timestamp,
                            precedenceWinner: "finalization"
                        )
                    )
                    continue
                }
                let occupancyOwnedByCurrentActor =
                    occupancyOwnerUserID == currentUserID &&
                    occupancyOwnerDeviceID == currentDeviceID
                let occupancyState = PropertySessionOccupancyState(
                    occupiedByUserID: occupancyOwnerUserID,
                    occupiedByDeviceID: occupancyOwnerDeviceID,
                    occupiedAt: occupancyTimestamp
                )
                decisions.append(
                    RefreshLockBadgeDecision(
                        propertyID: propertyID,
                        showLocked: !occupancyOwnedByCurrentActor,
                        reason: occupancyOwnedByCurrentActor ? "active_occupancy_owned_by_current_device" : "active_remote_occupancy",
                        occupancyState: occupancyState,
                        sessionLockState: nil,
                        clearSessionIDs: [],
                        lockTimestamp: occupancyTimestamp,
                        finalizationTimestamp: finalizationEvidence?.timestamp,
                        precedenceWinner: "occupancy"
                    )
                )
                continue
            }

            let staleOccupancySeen = propertyOccupancy != nil
            decisions.append(
                RefreshLockBadgeDecision(
                    propertyID: propertyID,
                    showLocked: false,
                    reason: finalizationEvidence != nil ? "finalization_cleared_lock" : (staleOccupancySeen ? "stale_or_released_occupancy_cleared" : "no_entry_lock_found"),
                    occupancyState: nil,
                    sessionLockState: nil,
                    clearSessionIDs: clearableSessionIDs,
                    lockTimestamp: nil,
                    finalizationTimestamp: finalizationEvidence?.timestamp,
                    precedenceWinner: finalizationEvidence != nil ? "finalization" : "none"
                )
            )
        }

        var nextLockedPropertyIDs = locallyLockedPropertyIDs.subtracting(uniquePropertyIDs)
        if !statusOwnedPropertyIDs.isEmpty || !legacyPropertyIDs.isEmpty {
            print(
                "[LockBadgeRefresh] summary " +
                "trigger=\(reason) " +
                "property_status_legacy_skipped_count=\(statusOwnedPropertyIDs.count) " +
                "legacy_fallback_count=\(legacyPropertyIDs.count) " +
                "lock_badge_refresh_skipped_property_status_count=\(statusOwnedPropertyIDs.count)"
            )
        }
        for decision in decisions {
            if decision.showLocked {
                nextLockedPropertyIDs.insert(decision.propertyID)
            }
            if let occupancyState = decision.occupancyState {
                setPropertySessionOccupancyState(
                    propertyID: decision.propertyID,
                    occupiedByUserID: occupancyState.occupiedByUserID,
                    occupiedByDeviceID: occupancyState.occupiedByDeviceID,
                    occupiedAt: occupancyState.occupiedAt
                )
            } else {
                propertySessionOccupancyByPropertyID.removeValue(forKey: decision.propertyID)
            }
            if let sessionLockState = decision.sessionLockState {
                setSessionCoordinationState(
                    sessionID: sessionLockState.sessionID,
                    lockedByUserID: sessionLockState.state.lockedByUserID,
                    lockedByDeviceID: sessionLockState.state.lockedByDeviceID,
                    lockedAt: sessionLockState.state.lockedAt
                )
            }
            for sessionID in decision.clearSessionIDs {
                sessionCoordinationStateBySessionID.removeValue(forKey: sessionID)
            }
            if userDefaults.bool(forKey: "lock_badge_refresh_verbose_logging") {
                print(
                    "[LockBadgeRefresh] source=entry_blocking " +
                    "trigger=\(reason) " +
                    "propertyID=\(decision.propertyID.uuidString) " +
                    "visible=\(decision.showLocked) " +
                    "reason=\(decision.reason) " +
                    "lockTimestamp=\(decision.lockTimestamp?.ISO8601Format() ?? "nil") " +
                    "finalizationTimestamp=\(decision.finalizationTimestamp?.ISO8601Format() ?? "nil") " +
                    "precedenceWinner=\(decision.precedenceWinner)"
                )
            }
        }
        locallyLockedPropertyIDs = nextLockedPropertyIDs
    }

    func isSessionLockedByOther(sessionID: UUID) -> Bool {
        guard let coord = sessionCoordinationStateBySessionID[sessionID] else { return false }
        let session = allSessionIndexByProperty.values.flatMap { $0 }.first(where: { $0.id == sessionID }) ??
            sessionIndexByProperty.values.flatMap { $0 }.first(where: { $0.id == sessionID }) ??
            (currentSession?.id == sessionID ? currentSession : nil)
        guard hasActiveRemoteLock(
            session: session,
            lockedByUserID: coord.lockedByUserID,
            lockedByDeviceID: coord.lockedByDeviceID,
            lockedAt: coord.lockedAt
        ) else { return false }
        if let lockedByDeviceID = normalizedSupabaseText(coord.lockedByDeviceID) {
            return lockedByDeviceID != currentDeviceIdentifier()
        }
        guard let lockedByUser = coord.lockedByUserID else { return false }
        return lockedByUser != authenticatedSupabaseUser?.id
    }

    func propertyCardBadgeModel(for propertyID: UUID) -> PropertyCardBadgeModel {
        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        let reExportSession = reExportCandidateSession(for: propertyID)
        let showReExport = reExportSession != nil
        let reExportReason = showReExport ? "local_archive_available" : "no_local_archive_available"

        if let propertyStatus = propertyStatusByPropertyID[propertyID] {
            let propertyStatusAnswer = Self.makePropertyStatusCompareAnswer(
                record: propertyStatus,
                currentUserID: currentUserID,
                currentDeviceID: currentDeviceID
            )
            let propertyStatusBadgeState = propertyStatusAnswer.visibleBadgeState
            let propertyStatusOwnedByCurrentActor = Self.propertyStatusActorOwnedByCurrentActor(
                record: propertyStatus,
                currentUserID: currentUserID,
                currentDeviceID: currentDeviceID
            )
            let propertyStatusSourceSessionID: UUID? = {
                switch propertyStatus.status {
                case .occupied:
                    return propertyStatus.activeSessionID
                case .draft:
                    return propertyStatus.draftSessionID
                case .pendingExport:
                    return propertyStatus.pendingExportSessionID
                case .exported:
                    return propertyStatus.lastExportedSessionID
                case .idle:
                    return nil
                }
            }()
            let propertyStatusReasonPrefix = "property_status:\(propertyStatus.status.rawValue)"
            return PropertyCardBadgeModel(
                propertyID: propertyID,
                activeOccupancySessionID: propertyStatus.status == .occupied ? propertyStatus.activeSessionID : nil,
                occupancyOwnerUserID: propertyStatus.status == .occupied ? propertyStatus.ownerUserID : nil,
                occupancyOwnerDeviceID: propertyStatus.status == .occupied ? normalizedSupabaseText(propertyStatus.ownerDeviceID) : nil,
                currentUserID: currentUserID,
                currentDeviceID: currentDeviceID,
                materialDraftSessionID: propertyStatus.status == .draft ? propertyStatusSourceSessionID : nil,
                draftOwnerUserID: propertyStatus.status == .draft ? propertyStatus.ownerUserID : nil,
                draftOwnerDeviceID: propertyStatus.status == .draft ? normalizedSupabaseText(propertyStatus.ownerDeviceID) : nil,
                finalizedOrExported: propertyStatus.status == .exported,
                showLock: propertyStatusBadgeState == .locked,
                showDraft: propertyStatusBadgeState == .draft,
                showPendingExport: propertyStatusBadgeState == .pendingExport,
                showReExport: showReExport,
                lockReason: propertyStatusBadgeState == .locked
                    ? "\(propertyStatusReasonPrefix):owner_mismatch"
                    : "\(propertyStatusReasonPrefix):lock_hidden",
                draftReason: propertyStatusBadgeState == .draft
                    ? "\(propertyStatusReasonPrefix):owner_match"
                    : "\(propertyStatusReasonPrefix):draft_hidden_owner_match=\(propertyStatusOwnedByCurrentActor)",
                pendingExportReason: propertyStatusBadgeState == .pendingExport
                    ? "\(propertyStatusReasonPrefix):pending_export"
                    : "\(propertyStatusReasonPrefix):pending_export_hidden",
                reExportReason: reExportReason,
                badgeSource: "property_status"
            )
        }

        let materialDraft = draftSession(for: propertyID)
        let draftLockState = materialDraft.flatMap { sessionCoordinationStateBySessionID[$0.id] }
        let draftOwnerUserID = draftLockState?.lockedByUserID
        let draftOwnerDeviceID = normalizedSupabaseText(draftLockState?.lockedByDeviceID)

        let occupancy = propertySessionOccupancyByPropertyID[propertyID]
        let occupancyOwnerUserID = occupancy?.occupiedByUserID
        let occupancyOwnerDeviceID = normalizedSupabaseText(occupancy?.occupiedByDeviceID)
        let occupancyHasOwner = occupancyOwnerUserID != nil || occupancyOwnerDeviceID != nil
        let occupancyActive = occupancyHasOwner && !isStaleCoordinationLock(lockedAt: occupancy?.occupiedAt)
        let occupancyOwnedByCurrentActor =
            (occupancyOwnerDeviceID != nil && occupancyOwnerDeviceID == currentDeviceID) ||
            (occupancyOwnerUserID != nil && occupancyOwnerUserID == currentUserID)
        let occupiedByOther = occupancyActive && !occupancyOwnedByCurrentActor
        let lockedDraftByOther = materialDraft.map { isSessionLockedByOther(sessionID: $0.id) } ?? false
        let locallyLocked = locallyLockedPropertyIDs.contains(propertyID)
        let showLock = occupiedByOther || lockedDraftByOther || locallyLocked
        let finalizedOrExported = isFinalSession(materialDraft)
        let lockReason: String = {
            if occupiedByOther { return "active_occupancy_other_device" }
            if lockedDraftByOther { return "locked_by_other" }
            if locallyLocked { return "locally_locked" }
            if occupancyActive { return "active_occupancy_owned_by_current_device" }
            if occupancyHasOwner { return "stale_occupancy_ignored" }
            return "no_active_occupancy"
        }()

        let draftOwnedByCurrentActor: Bool = {
            guard let materialDraft else { return false }
            if currentSession?.id == materialDraft.id { return true }
            if let draftOwnerDeviceID {
                return draftOwnerDeviceID == currentDeviceID
            }
            if let draftOwnerUserID {
                return draftOwnerUserID == currentUserID
            }
            return false
        }()
        let showDraft = materialDraft != nil &&
            !finalizedOrExported &&
            !showLock &&
            draftOwnedByCurrentActor
        let draftReason: String = {
            guard materialDraft != nil else { return "no_material_draft" }
            if finalizedOrExported { return "finalized_or_exported" }
            if showLock { return "hidden_by_other_device_occupancy" }
            if draftOwnedByCurrentActor { return "visible_owned_by_current_device" }
            if draftOwnerDeviceID != nil || draftOwnerUserID != nil {
                return "hidden_non_owner"
            }
            return "hidden_unverified_local_owner"
        }()

        let legacyPendingExport = sessions(for: propertyID).contains { isPendingDeliveryLocallyAvailable($0) }
        let legacyPendingExportReason = legacyPendingExport ? "pending_delivery_local_archive_available" : "no_pending_delivery_local_archive"

        return PropertyCardBadgeModel(
            propertyID: propertyID,
            activeOccupancySessionID: nil,
            occupancyOwnerUserID: occupancyOwnerUserID,
            occupancyOwnerDeviceID: occupancyOwnerDeviceID,
            currentUserID: currentUserID,
            currentDeviceID: currentDeviceID,
            materialDraftSessionID: materialDraft?.id,
            draftOwnerUserID: draftOwnerUserID,
            draftOwnerDeviceID: draftOwnerDeviceID,
            finalizedOrExported: finalizedOrExported,
            showLock: showLock,
            showDraft: showDraft,
            showPendingExport: legacyPendingExport,
            showReExport: showReExport,
            lockReason: lockReason,
            draftReason: draftReason,
            pendingExportReason: legacyPendingExportReason,
            reExportReason: reExportReason,
            badgeSource: "legacy"
        )
    }

    func reExportCandidateSession(for propertyID: UUID, now: Date = Date()) -> Session? {
        let candidates = sessions(for: propertyID)
            .sorted { lhs, rhs in
                let l = lhs.firstDeliveredAt ?? .distantPast
                let r = rhs.firstDeliveredAt ?? .distantPast
                if l == r {
                    return lhs.startedAt > rhs.startedAt
                }
                return l > r
            }
        reExportAvailabilityDiagnostics.candidatesScanned += candidates.count
        return candidates.first { isReExportLocallyAvailable($0, now: now) }
    }

    func propertyStatusRecord(for propertyID: UUID) -> PropertyStatusRecord? {
        propertyStatusByPropertyID[propertyID]
    }

    func evaluatePropertyStatusEntryPreflight(
        propertyID: UUID,
        context: String? = nil
    ) -> PropertyStatusEntryPreflightDecision? {
        guard let record = propertyStatusByPropertyID[propertyID] else {
            if let context {
                logPropertyStatusEntryPreflight(
                    propertyID: propertyID,
                    decision: nil,
                    context: context
                )
            }
            return nil
        }
        let decision = makePropertyStatusEntryPreflightDecision(propertyID: propertyID, record: record)
        if let context {
            logPropertyStatusEntryPreflight(
                propertyID: propertyID,
                decision: decision,
                context: context
            )
        }
        return decision
    }

    @MainActor
    func evaluateFreshPropertyStatusEntryPreflight(
        propertyID: UUID,
        context: String
    ) async -> PropertyStatusEntryPreflightEvaluation {
        guard let cachedRecord = propertyStatusByPropertyID[propertyID] else {
            logPropertyStatusEntryPreflight(
                propertyID: propertyID,
                decision: nil,
                context: context
            )
            return PropertyStatusEntryPreflightEvaluation(
                decision: nil,
                skipCachedPropertyStatusPreflight: false,
                source: "legacy",
                reason: "missing_property_status_row"
            )
        }

        let cachedDecision = makePropertyStatusEntryPreflightDecision(
            propertyID: propertyID,
            record: cachedRecord
        )
        let requiresFreshTransientRead =
            cachedRecord.status == .idle ||
            cachedRecord.status == .exported ||
            cachedRecord.status == .occupied
        guard requiresFreshTransientRead else {
            let resolvedCachedDecision = await resolvedPropertyStatusEntryPreflightDecisionOwner(
                cachedDecision,
                record: cachedRecord
            )
            logPropertyStatusEntryPreflight(
                propertyID: propertyID,
                decision: resolvedCachedDecision,
                context: context
            )
            return PropertyStatusEntryPreflightEvaluation(
                decision: resolvedCachedDecision,
                skipCachedPropertyStatusPreflight: false,
                source: "property_status_cached",
                reason: "cached_status_authoritative_\(cachedRecord.status.rawValue)"
            )
        }

        do {
            guard let freshRecord = try await fetchPropertyStatusRecord(propertyID: propertyID) else {
                propertyStatusByPropertyID.removeValue(forKey: propertyID)
                print(
                    "[PropertyStatusEntry] " +
                    "context=\(context) " +
                    "propertyID=\(propertyID.uuidString) " +
                    "entry_source=legacy " +
                    "property_status_entry_decision=missing_fresh_row " +
                    "property_status_entry_reason=fresh_read_missing_row " +
                    "cached_status=\(cachedRecord.status.rawValue)"
                )
                return PropertyStatusEntryPreflightEvaluation(
                    decision: nil,
                    skipCachedPropertyStatusPreflight: true,
                    source: "legacy",
                    reason: "fresh_read_missing_row"
                )
            }

            var nextCache = propertyStatusByPropertyID
            nextCache[propertyID] = freshRecord
            propertyStatusByPropertyID = nextCache
            lastPropertyStatusRefreshAt = Date()

            let freshDecision = makePropertyStatusEntryPreflightDecision(
                propertyID: propertyID,
                record: freshRecord
            )
            let resolvedFreshDecision = await resolvedPropertyStatusEntryPreflightDecisionOwner(
                freshDecision,
                record: freshRecord
            )
            logPropertyStatusEntryPreflight(
                propertyID: propertyID,
                decision: resolvedFreshDecision,
                context: "\(context)_fresh"
            )
            if freshRecord.status == .occupied,
               resolvedFreshDecision.isBlocked {
                print(
                    "[PropertyStatusEntry] " +
                    "property_status_entry_blocked_by_fresh_occupied=true " +
                    "context=\(context) " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sourceSessionID=\(freshRecord.activeSessionID?.uuidString ?? "nil")"
                )
            }
            return PropertyStatusEntryPreflightEvaluation(
                decision: resolvedFreshDecision,
                skipCachedPropertyStatusPreflight: false,
                source: "property_status_fresh",
                reason: "fresh_read_status_\(freshRecord.status.rawValue)"
            )
        } catch {
            propertyStatusByPropertyID.removeValue(forKey: propertyID)
            print(
                "[PropertyStatusEntry] " +
                "context=\(context) " +
                "propertyID=\(propertyID.uuidString) " +
                "entry_source=legacy " +
                "property_status_entry_decision=fresh_read_failed " +
                "property_status_entry_reason=legacy_fallback_after_fresh_read_failure " +
                "cached_status=\(cachedRecord.status.rawValue) " +
                "error=\(Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 120) ?? "unknown_error")"
            )
            return PropertyStatusEntryPreflightEvaluation(
                decision: nil,
                skipCachedPropertyStatusPreflight: true,
                source: "legacy",
                reason: "fresh_read_failed"
            )
        }
    }

    private func makePropertyStatusEntryPreflightDecision(
        propertyID: UUID,
        record: PropertyStatusRecord
    ) -> PropertyStatusEntryPreflightDecision {
        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        let ownedByCurrentActor = Self.propertyStatusActorOwnedByCurrentActor(
            record: record,
            currentUserID: currentUserID,
            currentDeviceID: currentDeviceID
        )
        let ownerDescription = propertyStatusEntryOwnerDescription(record: record)
        let lockedAt = record.heartbeatAt ?? record.updatedAt

        switch record.status {
        case .idle:
            return PropertyStatusEntryPreflightDecision(
                source: "property_status",
                decision: "allow",
                reason: "status_idle",
                block: nil
            )
        case .exported:
            return PropertyStatusEntryPreflightDecision(
                source: "property_status",
                decision: "allow",
                reason: "status_exported",
                block: nil
            )
        case .occupied:
            if isStalePropertyStatusOccupied(record) {
                print(
                    "[PropertyStatusEntry] " +
                    "property_status_occupied_stale_recovery=\(ownedByCurrentActor ? "owned_reclaimable" : "claimable_via_rpc") " +
                    "propertyID=\(propertyID.uuidString) " +
                    "activeSessionID=\(record.activeSessionID?.uuidString ?? "nil") " +
                    "ownerUserID=\(record.ownerUserID?.uuidString ?? "nil") " +
                    "ownerDeviceID=\(record.ownerDeviceID ?? "nil") " +
                    "heartbeatAt=\(record.heartbeatAt?.ISO8601Format() ?? "nil")"
                )
                return PropertyStatusEntryPreflightDecision(
                    source: "property_status",
                    decision: "allow",
                    reason: ownedByCurrentActor ? "occupied_stale_owned_by_current_actor" : "occupied_stale_claimable_via_rpc",
                    block: nil
                )
            }
            guard !ownedByCurrentActor else {
                return PropertyStatusEntryPreflightDecision(
                    source: "property_status",
                    decision: "allow",
                    reason: "occupied_owned_by_current_actor",
                    block: nil
                )
            }
            return PropertyStatusEntryPreflightDecision(
                source: "property_status",
                decision: "block",
                reason: "occupied_owned_by_other_actor",
                block: SessionEntryCoordinationBlock(
                    ownerDescription: ownerDescription,
                    lockedAt: lockedAt,
                    blockContext: "occupied"
                )
            )
        case .draft:
            guard !ownedByCurrentActor else {
                return PropertyStatusEntryPreflightDecision(
                    source: "property_status",
                    decision: "allow",
                    reason: "draft_owned_by_current_actor",
                    block: nil
                )
            }
            return PropertyStatusEntryPreflightDecision(
                source: "property_status",
                decision: "block",
                reason: "draft_owned_by_other_actor",
                block: SessionEntryCoordinationBlock(
                    ownerDescription: ownerDescription,
                    lockedAt: lockedAt,
                    blockContext: "draft"
                )
            )
        case .pendingExport:
            return PropertyStatusEntryPreflightDecision(
                source: "property_status",
                decision: "block",
                reason: "pending_export",
                block: SessionEntryCoordinationBlock(
                    ownerDescription: "pending export",
                    lockedAt: lockedAt,
                    blockContext: "pending_export"
                )
            )
        }
    }

    private func propertyStatusEntryOwnerDescription(record: PropertyStatusRecord) -> String {
        let deviceDescription = friendlyDeviceDescription(for: record.ownerDeviceID)
        if let ownerUserID = record.ownerUserID {
            let owner = localOwnerDisplayName(for: ownerUserID) ?? fallbackOwnerDisplayName(for: ownerUserID)
            return combineOwnerAndDeviceDescription(owner: owner, device: deviceDescription)
        }
        return deviceDescription.map { "another signed-in user on \($0)" } ?? "another signed-in user"
    }

    private func resolvedPropertyStatusEntryPreflightDecisionOwner(
        _ decision: PropertyStatusEntryPreflightDecision,
        record: PropertyStatusRecord
    ) async -> PropertyStatusEntryPreflightDecision {
        guard let block = decision.block,
              record.status == .occupied || record.status == .draft else {
            return decision
        }

        let resolvedOwnerDescription: String
        if record.ownerUserID != nil {
            resolvedOwnerDescription = await ownerDescription(
                for: record.ownerUserID,
                lockedByDeviceID: record.ownerDeviceID
            )
        } else {
            resolvedOwnerDescription = propertyStatusEntryOwnerDescription(record: record)
        }

        guard resolvedOwnerDescription != block.ownerDescription else {
            return decision
        }

        return PropertyStatusEntryPreflightDecision(
            source: decision.source,
            decision: decision.decision,
            reason: decision.reason,
            block: SessionEntryCoordinationBlock(
                ownerDescription: resolvedOwnerDescription,
                lockedAt: block.lockedAt,
                blockContext: block.blockContext
            )
        )
    }

    private func logPropertyStatusEntryPreflight(
        propertyID: UUID,
        decision: PropertyStatusEntryPreflightDecision?,
        context: String
    ) {
        if let decision {
            print(
                "[PropertyStatusEntry] " +
                "context=\(context) " +
                "propertyID=\(propertyID.uuidString) " +
                "entry_source=\(decision.source) " +
                "property_status_entry_decision=\(decision.decision) " +
                "property_status_entry_reason=\(decision.reason) " +
                "property_status_block_context=\(decision.block?.blockContext ?? "none") " +
                "legacy_entry_decision_compare=skipped_property_status_present"
            )
        } else {
            print(
                "[PropertyStatusEntry] " +
                "context=\(context) " +
                "propertyID=\(propertyID.uuidString) " +
                "entry_source=legacy " +
                "property_status_entry_decision=missing_row " +
                "property_status_entry_reason=no_property_status_row " +
                "legacy_entry_decision_compare=not_checked"
            )
        }
    }

    func propertyStatusDiagnostic(for propertyID: UUID) -> PropertyStatusDiagnosticComparison? {
        propertyStatusDiagnostics[propertyID]
    }

    private func schedulePropertyStatusShadowWrite(
        transition: PropertyStatusShadowTransition,
        propertyID: UUID,
        sessionID: UUID? = nil,
        reason: String
    ) {
        guard backendFeatureFlags.supabaseEnabled,
              backendFeatureFlags.shadowWriteEnabled,
              supabaseClient != nil,
              canAccessProperty(propertyID) else {
            return
        }
        guard !transition.requiresSessionID || sessionID != nil else {
            print(
                "[PropertyStatusShadowWrite] property_status_shadow_write_failure " +
                "property_status_transition=\(transition.rawValue) " +
                "rpc=\(transition.rpcName) " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=nil " +
                "reason=\(reason) " +
                "error=missing_session_id"
            )
            return
        }

        let deviceID = currentDeviceIdentifier()
        print(
            "[PropertyStatusShadowWrite] property_status_shadow_write_started " +
            "property_status_transition=\(transition.rawValue) " +
            "rpc=\(transition.rpcName) " +
            "propertyID=\(propertyID.uuidString) " +
            "sessionID=\(sessionID?.uuidString ?? "nil") " +
            "ownerDeviceID=\(deviceID) " +
            "reason=\(reason)"
        )
        Task { @MainActor [weak self] in
            _ = await self?.performPropertyStatusShadowWrite(
                transition: transition,
                propertyID: propertyID,
                sessionID: sessionID,
                deviceID: deviceID,
                reason: reason
            )
        }
    }

    @discardableResult
    private func performPropertyStatusShadowWrite(
        transition: PropertyStatusShadowTransition,
        propertyID: UUID,
        sessionID: UUID?,
        deviceID: String,
        reason: String
    ) async -> Bool {
        guard let client = supabaseClient else {
            print(
                "[PropertyStatusShadowWrite] property_status_shadow_write_failure " +
                "property_status_transition=\(transition.rawValue) " +
                "rpc=\(transition.rpcName) " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID?.uuidString ?? "nil") " +
                "reason=\(reason) " +
                "error=missing_supabase_client"
            )
            return false
        }

        do {
            var localCacheApplied = true
            switch transition {
            case .claim, .promoteDraft, .pendingExport, .exported:
                guard let sessionID else {
                    throw NSError(
                        domain: "ScoutCapture.PropertyStatusShadowWrite",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "Missing session id for \(transition.rawValue)."]
                    )
                }
                let params = PropertyStatusSessionRPCPayload(
                    targetPropertyID: propertyID,
                    targetSessionID: sessionID,
                    targetDeviceID: deviceID,
                    targetStatusReason: reason
                )
                if transition == .claim {
                    let returnedRecord = try await (try client.rpc(transition.rpcName, params: params))
                        .execute()
                        .value as PropertyStatusRecord
                    print(
                        "[PropertyStatusShadowWrite] property_status_claim_returned_status " +
                        "propertyID=\(propertyID.uuidString) " +
                        "sessionID=\(sessionID.uuidString) " +
                        "property_status_status=\(returnedRecord.status.rawValue)"
                    )
                    localCacheApplied = updateLocalPropertyStatusCacheAfterClaim(
                        returnedRecord,
                        propertyID: propertyID,
                        sessionID: sessionID,
                        deviceID: deviceID,
                        reason: reason
                    )
                } else if transition == .promoteDraft {
                    let returnedRecord = try await (try client.rpc(transition.rpcName, params: params))
                        .execute()
                        .value as PropertyStatusRecord
                    updateLocalPropertyStatusCacheAfterDraftPromotion(
                        returnedRecord,
                        propertyID: propertyID,
                        sessionID: sessionID,
                        deviceID: deviceID,
                        reason: reason
                    )
                } else if transition == .exported {
                    let returnedRecord = try await (try client.rpc(transition.rpcName, params: params))
                        .execute()
                        .value as PropertyStatusRecord
                    updateLocalPropertyStatusCacheAfterExport(
                        returnedRecord,
                        propertyID: propertyID,
                        sessionID: sessionID,
                        reason: reason
                    )
                } else {
                    _ = try await (try client.rpc(transition.rpcName, params: params)).execute()
                }
            case .heartbeat, .release:
                let params = PropertyStatusDeviceRPCPayload(
                    targetPropertyID: propertyID,
                    targetDeviceID: deviceID,
                    targetStatusReason: reason
                )
                let returnedRecord = try await (try client.rpc(transition.rpcName, params: params))
                    .execute()
                    .value as PropertyStatusRecord
                if transition == .release {
                    localCacheApplied = updateLocalPropertyStatusCacheAfterRelease(
                        returnedRecord,
                        propertyID: propertyID,
                        deviceID: deviceID,
                        reason: reason
                    )
                }
            }

            print(
                "[PropertyStatusShadowWrite] property_status_shadow_write_success " +
                "property_status_transition=\(transition.rawValue) " +
                "rpc=\(transition.rpcName) " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID?.uuidString ?? "nil") " +
                "ownerDeviceID=\(deviceID) " +
                "reason=\(reason)"
            )
            return localCacheApplied
        } catch {
            print(
                "[PropertyStatusShadowWrite] property_status_shadow_write_failure " +
                "property_status_transition=\(transition.rawValue) " +
                "rpc=\(transition.rpcName) " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID?.uuidString ?? "nil") " +
                "ownerDeviceID=\(deviceID) " +
                "reason=\(reason) " +
                "error=\(Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 160) ?? "unknown_error")"
            )
            return false
        }
    }

    private func updateLocalPropertyStatusCacheAfterDraftPromotion(
        _ record: PropertyStatusRecord,
        propertyID: UUID,
        sessionID: UUID,
        deviceID: String,
        reason: String
    ) {
        let currentUserID = authenticatedSupabaseUser?.id
        let ownerDeviceMatches = normalizedSupabaseText(record.ownerDeviceID) == deviceID
        let ownerUserMatches = record.ownerUserID == currentUserID
        guard record.propertyID == propertyID,
              record.status == .draft,
              record.draftSessionID == sessionID,
              ownerDeviceMatches,
              ownerUserMatches else {
            print(
                "[PropertyStatusShadowWrite] property_status_local_cache_updated_after_draft=false " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID.uuidString) " +
                "returnedPropertyID=\(record.propertyID.uuidString) " +
                "property_status_status=\(record.status.rawValue) " +
                "draftSessionID=\(record.draftSessionID?.uuidString ?? "nil") " +
                "ownerUserMatches=\(ownerUserMatches) " +
                "ownerDeviceMatches=\(ownerDeviceMatches) " +
                "reason=returned_row_not_owner_draft_match " +
                "statusReason=\(reason)"
            )
            return
        }

        var nextCache = propertyStatusByPropertyID
        nextCache[propertyID] = record
        propertyStatusByPropertyID = nextCache
        lastPropertyStatusRefreshAt = Date()
        let badge = propertyCardBadgeModel(for: propertyID)
        print(
            "[PropertyStatusShadowWrite] property_status_local_cache_updated_after_draft " +
            "propertyID=\(propertyID.uuidString) " +
            "sessionID=\(sessionID.uuidString) " +
            "property_status_status=\(record.status.rawValue) " +
            "draft_badge_visible_after_local_cache_update=\(badge.showDraft) " +
            "reason=\(reason)"
        )
    }

    @discardableResult
    private func updateLocalPropertyStatusCacheAfterClaim(
        _ record: PropertyStatusRecord,
        propertyID: UUID,
        sessionID: UUID,
        deviceID: String,
        reason: String
    ) -> Bool {
        let currentUserID = authenticatedSupabaseUser?.id
        let ownerDeviceMatches = normalizedSupabaseText(record.ownerDeviceID) == deviceID
        let ownerUserMatches = record.ownerUserID == currentUserID
        let currentSessionMatches =
            currentSession?.propertyID == propertyID &&
            currentSession?.id == sessionID &&
            record.activeSessionID == currentSession?.id
        guard record.propertyID == propertyID,
              record.status == .occupied,
              record.activeSessionID == sessionID,
              currentSessionMatches,
              ownerDeviceMatches,
              ownerUserMatches else {
            print(
                "[PropertyStatusShadowWrite] property_status_local_cache_updated_after_claim=false " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID.uuidString) " +
                "returnedPropertyID=\(record.propertyID.uuidString) " +
                "property_status_status=\(record.status.rawValue) " +
                "activeSessionID=\(record.activeSessionID?.uuidString ?? "nil") " +
                "currentSessionMatches=\(currentSessionMatches) " +
                "ownerUserMatches=\(ownerUserMatches) " +
                "ownerDeviceMatches=\(ownerDeviceMatches) " +
                "reason=returned_row_not_owner_occupied_match " +
                "statusReason=\(reason)"
            )
            print(
                "[PropertyStatusShadowWrite] property_status_occupied_cache_applied=false " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID.uuidString) " +
                "reason=\(reason)"
            )
            return false
        }

        var nextCache = propertyStatusByPropertyID
        nextCache[propertyID] = record
        propertyStatusByPropertyID = nextCache
        lastPropertyStatusRefreshAt = Date()
        print(
            "[PropertyStatusShadowWrite] property_status_local_cache_updated_after_claim " +
            "propertyID=\(propertyID.uuidString) " +
            "sessionID=\(sessionID.uuidString) " +
            "property_status_status=\(record.status.rawValue) " +
            "reason=\(reason)"
        )
        print(
            "[PropertyStatusShadowWrite] property_status_occupied_cache_applied=true " +
            "propertyID=\(propertyID.uuidString) " +
            "sessionID=\(sessionID.uuidString) " +
            "reason=\(reason)"
        )
        return true
    }

    @discardableResult
    private func updateLocalPropertyStatusCacheAfterRelease(
        _ record: PropertyStatusRecord,
        propertyID: UUID,
        deviceID: String,
        reason: String
    ) -> Bool {
        guard record.propertyID == propertyID,
              record.status == .idle || record.status == .exported else {
            print(
                "[PropertyStatusShadowWrite] property_status_zero_photo_release_applied=false " +
                "propertyID=\(propertyID.uuidString) " +
                "returnedPropertyID=\(record.propertyID.uuidString) " +
                "property_status_status=\(record.status.rawValue) " +
                "ownerDeviceID=\(deviceID) " +
                "reason=returned_row_not_released_state " +
                "statusReason=\(reason)"
            )
            return false
        }

        var nextCache = propertyStatusByPropertyID
        nextCache[propertyID] = record
        propertyStatusByPropertyID = nextCache
        lastPropertyStatusRefreshAt = Date()
        print(
            "[PropertyStatusShadowWrite] property_status_zero_photo_release_applied=true " +
            "propertyID=\(propertyID.uuidString) " +
            "property_status_status=\(record.status.rawValue) " +
            "ownerDeviceID=\(deviceID) " +
            "reason=\(reason)"
        )
        return true
    }

    private func updateLocalPropertyStatusCacheAfterExport(
        _ record: PropertyStatusRecord,
        propertyID: UUID,
        sessionID: UUID,
        reason: String
    ) {
        guard record.propertyID == propertyID,
              record.status == .exported,
              record.lastExportedSessionID == sessionID else {
            print(
                "[PropertyStatusShadowWrite] property_status_local_cache_updated_after_export=false " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID.uuidString) " +
                "returnedPropertyID=\(record.propertyID.uuidString) " +
                "property_status_status=\(record.status.rawValue) " +
                "lastExportedSessionID=\(record.lastExportedSessionID?.uuidString ?? "nil") " +
                "pending_export_cleared_after_export=false " +
                "reason=returned_row_not_exported_match " +
                "statusReason=\(reason)"
            )
            return
        }
        let hadPendingExport = propertyStatusByPropertyID[propertyID]?.status == .pendingExport
        var nextCache = propertyStatusByPropertyID
        nextCache[propertyID] = record
        propertyStatusByPropertyID = nextCache
        lastPropertyStatusRefreshAt = Date()
        print(
            "[PropertyStatusShadowWrite] property_status_local_cache_updated_after_export " +
            "propertyID=\(propertyID.uuidString) " +
            "sessionID=\(sessionID.uuidString) " +
            "property_status_status=\(record.status.rawValue) " +
            "pending_export_cleared_after_export=\(record.status == .exported && record.pendingExportSessionID == nil) " +
            "had_pending_export_before_update=\(hadPendingExport) " +
            "reason=\(reason)"
        )
    }

    func fetchPropertyStatusRecord(propertyID: UUID) async throws -> PropertyStatusRecord? {
        guard let activeOrganizationID else {
            return nil
        }
        return try await fetchPropertyStatusRecords(
            orgID: activeOrganizationID,
            propertyIDs: [propertyID]
        ).first
    }

    private func fetchPropertyStatusRecords(
        orgID: UUID,
        propertyIDs: [UUID]
    ) async throws -> [PropertyStatusRecord] {
        let uniquePropertyIDValues = Array(Set(propertyIDs))
            .map { $0.uuidString.lowercased() }
            .sorted()
        guard !uniquePropertyIDValues.isEmpty else { return [] }
        let uniquePropertyIDs = uniquePropertyIDValues.compactMap { UUID(uuidString: $0) }
#if DEBUG
        if let propertyStatusFetchOverride {
            return try await propertyStatusFetchOverride(orgID, uniquePropertyIDs)
        }
        if AppStateTestEnvironment.isRunningUnderXCTest {
            return uniquePropertyIDValues.compactMap { value in
                guard let propertyID = UUID(uuidString: value) else { return nil }
                return propertyStatusByPropertyID[propertyID]
            }
        }
#endif
        guard let client = supabaseClient else {
            throw RemotePropertyFetchError.missingClient
        }

        return try await client
            .from("property_status")
            .select(
                """
                property_id,
                org_id,
                status,
                active_session_id,
                draft_session_id,
                pending_export_session_id,
                last_exported_session_id,
                owner_user_id,
                owner_device_id,
                heartbeat_at,
                updated_at,
                updated_by,
                status_reason,
                revision
                """
            )
            .eq("org_id", value: orgID.uuidString.lowercased())
            .in("property_id", values: uniquePropertyIDValues)
            .execute()
            .value as [PropertyStatusRecord]
    }

    @MainActor
    private func queuePropertyStatusDiagnosticsRefresh(
        trigger: String,
        orgID: UUID?,
        propertyIDs: [UUID]
    ) {
        guard isRemotePropertyRefreshEnabled,
              let orgID,
              !propertyIDs.isEmpty else {
            return
        }
        let uniquePropertyIDs = Array(Set(propertyIDs)).sorted { $0.uuidString < $1.uuidString }
        let signature = propertyStatusDiagnosticsRequestSignature(
            orgID: orgID,
            propertyIDs: uniquePropertyIDs
        )
        let now = Date()
        if pendingPropertyStatusDiagnosticsSignature == signature {
            return
        }
        if lastPropertyStatusDiagnosticsSignature == signature,
           let completedAt = lastPropertyStatusDiagnosticsCompletedAt,
           now.timeIntervalSince(completedAt) < propertyStatusDiagnosticsDedupeInterval {
            return
        }
        pendingPropertyStatusDiagnosticsSignature = signature
        propertyStatusDiagnosticsRefreshTask?.cancel()
        let taskID = UUID()
        propertyStatusDiagnosticsRefreshTaskID = taskID
        propertyStatusDiagnosticsRefreshTask = Task { @MainActor [weak self] in
            do {
                try await Task.sleep(nanoseconds: 200_000_000)
            } catch {
                return
            }
            guard !Task.isCancelled else { return }
            await self?.refreshPropertyStatusDiagnostics(
                trigger: trigger,
                orgID: orgID,
                propertyIDs: uniquePropertyIDs,
                requestSignature: signature,
                taskID: taskID
            )
        }
    }

    private func propertyStatusDiagnosticsRequestSignature(
        orgID: UUID,
        propertyIDs: [UUID]
    ) -> String {
        let propertyPart = propertyIDs
            .map { $0.uuidString.lowercased() }
            .joined(separator: ",")
        let statusPart = propertyIDs
            .compactMap { propertyID -> String? in
                guard let record = propertyStatusByPropertyID[propertyID] else { return nil }
                return [
                    propertyID.uuidString.lowercased(),
                    record.status.rawValue,
                    String(record.revision),
                    record.activeSessionID?.uuidString.lowercased() ?? "nil",
                    record.draftSessionID?.uuidString.lowercased() ?? "nil",
                    record.pendingExportSessionID?.uuidString.lowercased() ?? "nil",
                    record.lastExportedSessionID?.uuidString.lowercased() ?? "nil"
                ].joined(separator: ":")
            }
            .joined(separator: "|")
        let derivedPart = propertyIDs
            .map { propertyStatusDerivedStateSignature(propertyID: $0) }
            .joined(separator: "|")
        return [
            orgID.uuidString.lowercased(),
            propertyPart,
            localStore.propertiesLedgerFingerprint(),
            statusPart,
            derivedPart
        ].joined(separator: "#")
    }

    private func propertyStatusDerivedStateSignature(propertyID: UUID) -> String {
        let occupancy = propertySessionOccupancyByPropertyID[propertyID]
        let draft = draftSession(for: propertyID)
        let pending = pendingExportSessionByProperty[propertyID] ?? sessions(for: propertyID).first {
            isPendingDelivery($0) && sessionHasCaptures($0)
        }
        let draftCoordination = draft.flatMap { sessionCoordinationStateBySessionID[$0.id] }
        return [
            propertyID.uuidString.lowercased(),
            draft?.id.uuidString.lowercased() ?? "nil",
            draft?.status.rawValue ?? "nil",
            draftCoordination?.lockedByUserID?.uuidString.lowercased() ?? "nil",
            normalizedSupabaseText(draftCoordination?.lockedByDeviceID) ?? "nil",
            occupancy?.occupiedByUserID?.uuidString.lowercased() ?? "nil",
            normalizedSupabaseText(occupancy?.occupiedByDeviceID) ?? "nil",
            pending?.id.uuidString.lowercased() ?? "nil",
            locallyLockedPropertyIDs.contains(propertyID) ? "locked" : "unlocked"
        ].joined(separator: ":")
    }

    @MainActor
    private func refreshPropertyStatusDiagnostics(
        trigger: String,
        orgID: UUID,
        propertyIDs: [UUID],
        requestSignature: String,
        taskID: UUID
    ) async {
        let requestedPropertyIDs = Array(Set(propertyIDs)).sorted { $0.uuidString < $1.uuidString }
        guard !requestedPropertyIDs.isEmpty else { return }
        let start = Date()
        defer {
            if pendingPropertyStatusDiagnosticsSignature == requestSignature {
                pendingPropertyStatusDiagnosticsSignature = nil
            }
            if propertyStatusDiagnosticsRefreshTaskID == taskID {
                propertyStatusDiagnosticsRefreshTask = nil
                propertyStatusDiagnosticsRefreshTaskID = nil
            }
        }

        do {
            let rows = try await fetchPropertyStatusRecords(
                orgID: orgID,
                propertyIDs: requestedPropertyIDs
            )
            let rowsByPropertyID = Dictionary(uniqueKeysWithValues: rows.map { ($0.propertyID, $0) })
            let completedAt = Date()
            let elapsedMs = Int(completedAt.timeIntervalSince(start) * 1000)

            var nextCache = propertyStatusByPropertyID
            for propertyID in requestedPropertyIDs {
                if let row = rowsByPropertyID[propertyID] {
                    nextCache[propertyID] = row
                } else {
                    nextCache.removeValue(forKey: propertyID)
                }
            }
            propertyStatusByPropertyID = nextCache
            lastPropertyStatusRefreshAt = completedAt

            var nextDiagnostics = propertyStatusDiagnostics
            for propertyID in requestedPropertyIDs {
                let derived = makePropertyStatusDerivedSummary(propertyID: propertyID)
                let comparison = Self.makePropertyStatusDiagnosticComparison(
                    propertyID: propertyID,
                    record: rowsByPropertyID[propertyID],
                    derivedSummary: derived,
                    currentUserID: authenticatedSupabaseUser?.id,
                    currentDeviceID: currentDeviceIdentifier(),
                    refreshElapsedMs: elapsedMs,
                    checkedAt: completedAt
                )
                nextDiagnostics[propertyID] = comparison
                logPropertyStatusDetailedDiagnosticsIfEnabled(comparison)
                logPropertyStatusCompareDetailIfEnabled(comparison)
            }
            propertyStatusDiagnostics = nextDiagnostics

            let missingCount = requestedPropertyIDs.count - rows.count
            let refreshedComparisons = requestedPropertyIDs.compactMap { nextDiagnostics[$0] }
            let mismatchCount = refreshedComparisons.filter { !$0.statusMatch }.count
            let compareSummary = Self.makePropertyStatusCompareSummary(
                comparisons: refreshedComparisons
            )
            lastPropertyStatusDiagnosticsSignature = requestSignature
            lastPropertyStatusDiagnosticsCompletedAt = completedAt
            if userDefaults.bool(forKey: "property_status_diagnostics_verbose_logging") {
                print(
                    "[PropertyStatusDiagnostics] badgeHydrationCompleted " +
                    "trigger=\(trigger) orgID=\(orgID.uuidString) " +
                    "requested=\(requestedPropertyIDs.count) rows=\(rows.count) " +
                    "missing=\(missingCount) mismatches=\(mismatchCount) " +
                    "draftCountHydrationSource=\(draftCountSource()) " +
                    "pendingExportHydrationSource=\(pendingExportCountSource()) " +
                    "propertyBadgeHydrationSource=\(badgeSourceSummary()) " +
                    "propertyStatusHydrationSource=property_status " +
                    "hydrationDuration=\(elapsedMs)"
                )
            }
            logPropertyStatusCompareSummary(
                trigger: trigger,
                orgID: orgID,
                summary: compareSummary,
                refreshElapsedMs: elapsedMs
            )
        } catch {
            let completedAt = Date()
            let elapsedMs = Int(completedAt.timeIntervalSince(start) * 1000)
            let category = Self.diagnosticErrorCategory(for: error)
            print(
                "[PropertyStatusDiagnostics] badgeHydrationCompleted " +
                "trigger=\(trigger) orgID=\(orgID.uuidString) " +
                "requested=\(requestedPropertyIDs.count) rows=0 " +
                "errorCategory=\(category.rawValue) " +
                "property_status_refresh_elapsed_ms=\(elapsedMs)"
            )
        }
    }

    private func makePropertyStatusDerivedSummary(propertyID: UUID) -> PropertyStatusDerivedSummary {
        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        if let propertyStatus = propertyStatusByPropertyID[propertyID] {
            let answer = Self.makePropertyStatusCompareAnswer(
                record: propertyStatus,
                currentUserID: currentUserID,
                currentDeviceID: currentDeviceID
            )
            let deleteEligibilityDecision = answer.deleteEligible
                ? "eligible_by_property_status"
                : "blocked_by_property_status_\(propertyStatus.status.rawValue)"
            return PropertyStatusDerivedSummary(
                draftBadgeDecision: answer.visibleBadgeState == .draft,
                pendingExportDecision: answer.visibleBadgeState == .pendingExport,
                lockedDecision: answer.visibleBadgeState == .locked,
                entryBlockingDecision: answer.entryBlocked ? "blocked_by_property_status" : "allowed_by_property_status",
                deleteEligibilityDecision: deleteEligibilityDecision,
                compareAnswer: answer
            )
        }
        let materialDraft = draftSession(for: propertyID)
        let draftLockState = materialDraft.flatMap { sessionCoordinationStateBySessionID[$0.id] }
        let draftOwnerUserID = draftLockState?.lockedByUserID
        let draftOwnerDeviceID = normalizedSupabaseText(draftLockState?.lockedByDeviceID)
        let occupancy = propertySessionOccupancyByPropertyID[propertyID]
        let occupancyOwnerUserID = occupancy?.occupiedByUserID
        let occupancyOwnerDeviceID = normalizedSupabaseText(occupancy?.occupiedByDeviceID)
        let occupancyHasOwner = occupancyOwnerUserID != nil || occupancyOwnerDeviceID != nil
        let occupancyActive = occupancyHasOwner && !isStaleCoordinationLock(lockedAt: occupancy?.occupiedAt)
        let occupancyOwnedByCurrentActor =
            (occupancyOwnerDeviceID != nil && occupancyOwnerDeviceID == currentDeviceID) ||
            (occupancyOwnerUserID != nil && occupancyOwnerUserID == currentUserID)
        let occupiedByOther = occupancyActive && !occupancyOwnedByCurrentActor
        let lockedDraftByOther = materialDraft.map { isSessionLockedByOther(sessionID: $0.id) } ?? false
        let locallyLocked = locallyLockedPropertyIDs.contains(propertyID)
        let showLock = occupiedByOther || lockedDraftByOther || locallyLocked
        let finalizedOrExported = isFinalSession(materialDraft)
        let draftOwnedByCurrentActor: Bool = {
            guard let materialDraft else { return false }
            if currentSession?.id == materialDraft.id { return true }
            if let draftOwnerDeviceID {
                return draftOwnerDeviceID == currentDeviceID
            }
            if let draftOwnerUserID {
                return draftOwnerUserID == currentUserID
            }
            return false
        }()
        let showDraft = materialDraft != nil &&
            !finalizedOrExported &&
            !showLock &&
            draftOwnedByCurrentActor
        let legacyPendingExportDecision = propertyStatusDerivedPendingExportCountIncluded(propertyID: propertyID)
        let entryBlockingDecision = showLock ? "blocked_by_existing_lock_state" : "allowed_by_existing_state"
        let deleteEligibilityDecision: String = {
            if showLock { return "blocked_by_lock_state" }
            if showDraft { return "blocked_by_draft_state" }
            if legacyPendingExportDecision { return "blocked_by_pending_export" }
            return "eligible_by_existing_state"
        }()
        let legacyVisibleBadgeState: PropertyStatusCompareBadgeState = {
            if showLock { return .locked }
            if showDraft { return .draft }
            if legacyPendingExportDecision { return .pendingExport }
            if propertyStatusDerivedExportedBadgeIncludedFromCache(propertyID: propertyID) { return .exported }
            return .idle
        }()
        let propertyStatusAnswer = propertyStatusByPropertyID[propertyID].map {
            Self.makePropertyStatusCompareAnswer(
                record: $0,
                currentUserID: currentUserID,
                currentDeviceID: currentDeviceID
            )
        }
        let visibleBadgeState = propertyStatusAnswer?.visibleBadgeState ?? legacyVisibleBadgeState
        let cutoverShowDraft = visibleBadgeState == .draft
        let cutoverShowLock = visibleBadgeState == .locked
        let cutoverPendingExportDecision = visibleBadgeState == .pendingExport
        let compareAnswer = PropertyStatusCompareAnswer(
            visibleBadgeState: visibleBadgeState,
            draftCountIncluded: propertyStatusAnswer?.draftCountIncluded ?? propertyStatusDerivedDraftCountIncluded(propertyID: propertyID),
            pendingExportCountIncluded: propertyStatusAnswer?.pendingExportCountIncluded ?? legacyPendingExportDecision,
            entryBlocked: showLock,
            deleteEligible: deleteEligibilityDecision == "eligible_by_existing_state"
        )
        return PropertyStatusDerivedSummary(
            draftBadgeDecision: cutoverShowDraft,
            pendingExportDecision: cutoverPendingExportDecision,
            lockedDecision: cutoverShowLock,
            entryBlockingDecision: entryBlockingDecision,
            deleteEligibilityDecision: deleteEligibilityDecision,
            compareAnswer: compareAnswer
        )
    }

    private func propertyStatusDerivedDraftCountIncluded(propertyID: UUID) -> Bool {
        if !draftSessionByProperty.isEmpty {
            return draftSessionByProperty[propertyID] != nil
        }
        return draftSession(for: propertyID) != nil
    }

    private func propertyStatusDerivedPendingExportCountIncluded(propertyID: UUID) -> Bool {
        if !pendingExportSessionByProperty.isEmpty {
            return pendingExportSessionByProperty[propertyID] != nil
        }
        return sessions(for: propertyID).contains { session in
            isPendingDelivery(session) && sessionHasCaptures(session)
        }
    }

    private func propertyStatusDerivedExportedBadgeIncludedFromCache(propertyID: UUID, now: Date = Date()) -> Bool {
        let currentDeviceID = currentDeviceIdentifier()
        return sessions(for: propertyID).contains { session in
            guard isReExportEligible(session, now: now) else { return false }
            let cacheKey = reExportAvailabilityCacheKey(session: session, currentDeviceID: currentDeviceID)
            let signature = reExportAvailabilitySignature(session: session, currentDeviceID: currentDeviceID)
            guard let cached = reExportAvailabilityCache[cacheKey],
                  cached.signature == signature,
                  now.timeIntervalSince(cached.checkedAt) < sessionArchiveAvailabilityCacheTTL else {
                return false
            }
            return cached.available
        }
    }

    private func logPropertyStatusCompareSummary(
        trigger: String,
        orgID: UUID,
        summary: PropertyStatusCompareSummary,
        refreshElapsedMs: Int
    ) {
        let propertyStatusLegacySkippedCount = properties.filter { propertyStatusByPropertyID[$0.id] != nil }.count
        let legacyFallbackCount = properties.count - propertyStatusLegacySkippedCount
        print(
            "[PropertyStatusCompare] summary " +
            "trigger=\(trigger) orgID=\(orgID.uuidString) " +
            "badge_source=\(badgeSourceSummary()) " +
            "draft_count_source=\(draftCountSource()) " +
            "pending_export_count_source=\(pendingExportCountSource()) " +
            "property_status_legacy_skipped_count=\(propertyStatusLegacySkippedCount) " +
            "legacy_fallback_count=\(legacyFallbackCount) " +
            "lock_badge_refresh_skipped_property_status_count=\(propertyStatusLegacySkippedCount) " +
            "compared_property_count=\(summary.comparedPropertyCount) " +
            "matched_count=\(summary.matchedCount) " +
            "mismatch_count=\(summary.mismatchCount) " +
            "missing_property_status_count=\(summary.missingPropertyStatusCount) " +
            "mismatch_categories=\(summary.mismatchCategorySummary) " +
            "property_status_refresh_elapsed_ms=\(refreshElapsedMs)"
        )
    }

    private func logPropertyStatusDetailedDiagnosticsIfEnabled(
        _ comparison: PropertyStatusDiagnosticComparison
    ) {
        guard userDefaults.bool(forKey: "property_status_diagnostics_verbose_logging") else {
            return
        }
        print(
            "[PropertyStatusDiagnostics:Detail] " +
            "property_status_row_found=\(comparison.rowFound) " +
            "propertyID=\(comparison.propertyID.uuidString) " +
            "property_status_status=\(comparison.status?.rawValue ?? "nil") " +
            "property_status_owner=\(comparison.ownerSummary) " +
            "property_status_session_ids=\(comparison.sessionIDSummary) " +
            "derived_status_summary=\(comparison.derivedStatusSummary) " +
            "status_match=\(comparison.statusMatch) " +
            "status_mismatch_reason=\(comparison.statusMismatchReason) " +
            "property_status_refresh_elapsed_ms=\(comparison.refreshElapsedMs)"
        )
    }

    private func logPropertyStatusCompareDetailIfEnabled(
        _ comparison: PropertyStatusDiagnosticComparison
    ) {
        guard userDefaults.bool(forKey: "property_status_compare_verbose"),
              !comparison.statusMatch else {
            return
        }
        print(
            "[PropertyStatusCompare:Detail] " +
            "propertyID=\(comparison.propertyID.uuidString) " +
            "property_status_row_found=\(comparison.rowFound) " +
            "property_status_status=\(comparison.status?.rawValue ?? "nil") " +
            "property_status_answer=\(comparison.propertyStatusAnswerSummary) " +
            "derived_answer=\(comparison.derivedAnswerSummary) " +
            "mismatch_categories=\(comparison.statusMismatchCategories.joined(separator: ",")) " +
            "status_mismatch_reason=\(comparison.statusMismatchReason)"
        )
    }

    static func makePropertyStatusDiagnosticComparison(
        propertyID: UUID,
        record: PropertyStatusRecord?,
        derivedSummary: PropertyStatusDerivedSummary,
        currentUserID: UUID?,
        currentDeviceID: String,
        refreshElapsedMs: Int,
        checkedAt: Date = Date()
    ) -> PropertyStatusDiagnosticComparison {
        guard let record else {
            return PropertyStatusDiagnosticComparison(
                propertyID: propertyID,
                rowFound: false,
                status: nil,
                ownerSummary: "user=nil,device=nil",
                sessionIDSummary: "active=nil,draft=nil,pending_export=nil,last_exported=nil",
                derivedStatusSummary: derivedSummary.diagnosticSummary,
                statusMatch: false,
                statusMismatchReason: "no_property_status_row",
                statusMismatchCategories: ["missing_property_status"],
                propertyStatusAnswerSummary: "missing",
                derivedAnswerSummary: derivedSummary.compareAnswer.diagnosticSummary,
                refreshElapsedMs: refreshElapsedMs,
                checkedAt: checkedAt
            )
        }

        let expectedAnswer = makePropertyStatusCompareAnswer(
            record: record,
            currentUserID: currentUserID,
            currentDeviceID: currentDeviceID
        )
        let derivedAnswer = derivedSummary.compareAnswer
        var mismatchReasons: [String] = []
        var mismatchCategories: [String] = []
        if derivedAnswer.visibleBadgeState != expectedAnswer.visibleBadgeState {
            mismatchCategories.append("badge_state")
            mismatchReasons.append(
                "badge_state expected=\(expectedAnswer.visibleBadgeState.rawValue) actual=\(derivedAnswer.visibleBadgeState.rawValue)"
            )
        }
        if derivedSummary.draftBadgeDecision != (expectedAnswer.visibleBadgeState == .draft) {
            mismatchCategories.append("draft_badge")
            mismatchReasons.append(
                "draft_badge expected=\(expectedAnswer.visibleBadgeState == .draft) actual=\(derivedSummary.draftBadgeDecision)"
            )
        }
        if derivedSummary.pendingExportDecision != (expectedAnswer.visibleBadgeState == .pendingExport) {
            mismatchCategories.append("pending_export_badge")
            mismatchReasons.append(
                "pending_export expected=\(expectedAnswer.visibleBadgeState == .pendingExport) actual=\(derivedSummary.pendingExportDecision)"
            )
        }
        if derivedSummary.lockedDecision != (expectedAnswer.visibleBadgeState == .locked) {
            mismatchCategories.append("locked_badge")
            mismatchReasons.append(
                "locked expected=\(expectedAnswer.visibleBadgeState == .locked) actual=\(derivedSummary.lockedDecision)"
            )
        }
        if derivedAnswer.draftCountIncluded != expectedAnswer.draftCountIncluded {
            mismatchCategories.append("draft_count")
            mismatchReasons.append(
                "draft_count expected=\(expectedAnswer.draftCountIncluded) actual=\(derivedAnswer.draftCountIncluded)"
            )
        }
        if derivedAnswer.pendingExportCountIncluded != expectedAnswer.pendingExportCountIncluded {
            mismatchCategories.append("pending_export_count")
            mismatchReasons.append(
                "pending_export_count expected=\(expectedAnswer.pendingExportCountIncluded) actual=\(derivedAnswer.pendingExportCountIncluded)"
            )
        }
        if derivedAnswer.entryBlocked != expectedAnswer.entryBlocked {
            mismatchCategories.append("entry_block")
            mismatchReasons.append(
                "entry_block expected=\(expectedAnswer.entryBlocked) actual=\(derivedAnswer.entryBlocked)"
            )
        }
        if derivedAnswer.deleteEligible != expectedAnswer.deleteEligible {
            mismatchCategories.append("delete_eligibility")
            mismatchReasons.append(
                "delete_eligibility expected=\(expectedAnswer.deleteEligible) actual=\(derivedAnswer.deleteEligible)"
            )
        }

        return PropertyStatusDiagnosticComparison(
            propertyID: propertyID,
            rowFound: true,
            status: record.status,
            ownerSummary: record.ownerDiagnosticSummary,
            sessionIDSummary: record.sessionIDDiagnosticSummary,
            derivedStatusSummary: derivedSummary.diagnosticSummary,
            statusMatch: mismatchReasons.isEmpty,
            statusMismatchReason: mismatchReasons.isEmpty ? "matched" : mismatchReasons.joined(separator: "; "),
            statusMismatchCategories: mismatchCategories,
            propertyStatusAnswerSummary: expectedAnswer.diagnosticSummary,
            derivedAnswerSummary: derivedAnswer.diagnosticSummary,
            refreshElapsedMs: refreshElapsedMs,
            checkedAt: checkedAt
        )
    }

    static func makePropertyStatusCompareAnswer(
        record: PropertyStatusRecord,
        currentUserID: UUID?,
        currentDeviceID: String
    ) -> PropertyStatusCompareAnswer {
        let ownedByCurrentActor = propertyStatusActorOwnedByCurrentActor(
            record: record,
            currentUserID: currentUserID,
            currentDeviceID: currentDeviceID
        )

        switch record.status {
        case .idle:
            return PropertyStatusCompareAnswer(
                visibleBadgeState: .idle,
                draftCountIncluded: false,
                pendingExportCountIncluded: false,
                entryBlocked: false,
                deleteEligible: true
            )
        case .exported:
            return PropertyStatusCompareAnswer(
                visibleBadgeState: .exported,
                draftCountIncluded: false,
                pendingExportCountIncluded: false,
                entryBlocked: false,
                deleteEligible: true
            )
        case .occupied:
            if propertyStatusOccupiedIsStale(record) {
                return PropertyStatusCompareAnswer(
                    visibleBadgeState: .idle,
                    draftCountIncluded: false,
                    pendingExportCountIncluded: false,
                    entryBlocked: false,
                    deleteEligible: true
                )
            }
            return PropertyStatusCompareAnswer(
                visibleBadgeState: ownedByCurrentActor ? .idle : .locked,
                draftCountIncluded: false,
                pendingExportCountIncluded: false,
                entryBlocked: !ownedByCurrentActor,
                deleteEligible: false
            )
        case .draft:
            return PropertyStatusCompareAnswer(
                visibleBadgeState: ownedByCurrentActor ? .draft : .locked,
                draftCountIncluded: ownedByCurrentActor,
                pendingExportCountIncluded: false,
                entryBlocked: !ownedByCurrentActor,
                deleteEligible: false
            )
        case .pendingExport:
            return PropertyStatusCompareAnswer(
                visibleBadgeState: .pendingExport,
                draftCountIncluded: false,
                pendingExportCountIncluded: true,
                entryBlocked: false,
                deleteEligible: false
            )
        }
    }

    static func makePropertyStatusCompareSummary(
        comparisons: [PropertyStatusDiagnosticComparison]
    ) -> PropertyStatusCompareSummary {
        var categories: [String: Int] = [:]
        for comparison in comparisons where !comparison.statusMatch {
            for category in comparison.statusMismatchCategories {
                categories[category, default: 0] += 1
            }
        }
        let missingCount = comparisons.filter { !$0.rowFound }.count
        let mismatchCount = comparisons.filter { !$0.statusMatch }.count
        return PropertyStatusCompareSummary(
            comparedPropertyCount: comparisons.count,
            matchedCount: comparisons.count - mismatchCount,
            mismatchCount: mismatchCount,
            missingPropertyStatusCount: missingCount,
            mismatchCategories: categories
        )
    }

    private static func propertyStatusActorOwnedByCurrentActor(
        record: PropertyStatusRecord,
        currentUserID: UUID?,
        currentDeviceID: String
    ) -> Bool {
        if let ownerDeviceID = record.ownerDeviceID?.trimmingCharacters(in: .whitespacesAndNewlines),
           !ownerDeviceID.isEmpty {
            return ownerDeviceID == currentDeviceID
        }
        if let ownerUserID = record.ownerUserID {
            return ownerUserID == currentUserID
        }
        return false
    }

    func draftBadgeSession(for propertyID: UUID) -> Session? {
        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()

        if let propertyStatus = propertyStatusByPropertyID[propertyID] {
            let propertyStatusAnswer = Self.makePropertyStatusCompareAnswer(
                record: propertyStatus,
                currentUserID: currentUserID,
                currentDeviceID: currentDeviceID
            )
            guard propertyStatusAnswer.visibleBadgeState == .draft else {
                if userDefaults.bool(forKey: "draft_badge_verbose_logging") {
                    print(
                        "[DraftBadge] propertyID=\(propertyID.uuidString) visible=false " +
                        "badge_source=property_status " +
                        "property_status_status=\(propertyStatus.status.rawValue) " +
                        "badge_visibility_reason=property_status_not_owner_draft"
                    )
                }
                return nil
            }
            let statusDraft = propertyStatus.draftSessionID.flatMap { draftSessionID in
                sessions(for: propertyID).first(where: { $0.id == draftSessionID })
            }
            guard let statusDraft else {
                if userDefaults.bool(forKey: "draft_badge_verbose_logging") {
                    print(
                        "[DraftBadge] propertyID=\(propertyID.uuidString) visible=true " +
                        "badge_source=property_status " +
                        "property_status_status=\(propertyStatus.status.rawValue) " +
                        "badge_visibility_reason=property_status_owner_draft_missing_local_session"
                    )
                }
                return nil
            }
            if userDefaults.bool(forKey: "draft_badge_verbose_logging") {
                print(
                    "[DraftBadge] propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(statusDraft.id.uuidString) " +
                    "visible=true " +
                    "badge_source=property_status " +
                    "draft_owner_user=\(propertyStatus.ownerUserID?.uuidString ?? "nil") " +
                    "draft_owner_device=\(normalizedSupabaseText(propertyStatus.ownerDeviceID) ?? "nil") " +
                    "current_user=\(currentUserID?.uuidString ?? "nil") " +
                    "current_device=\(currentDeviceID) " +
                    "badge_visibility_reason=property_status_owner_draft"
                )
            }
            return statusDraft
        }

        let materialDraft = draftSession(for: propertyID)
        let draftLockState = materialDraft.flatMap { sessionCoordinationStateBySessionID[$0.id] }
        let draftOwnerUserID = draftLockState?.lockedByUserID
        let draftOwnerDeviceID = normalizedSupabaseText(draftLockState?.lockedByDeviceID)
        let occupancy = propertySessionOccupancyByPropertyID[propertyID]
        let occupancyOwnerUserID = occupancy?.occupiedByUserID
        let occupancyOwnerDeviceID = normalizedSupabaseText(occupancy?.occupiedByDeviceID)
        let occupancyHasOwner = occupancyOwnerUserID != nil || occupancyOwnerDeviceID != nil
        let occupancyActive = occupancyHasOwner && !isStaleCoordinationLock(lockedAt: occupancy?.occupiedAt)
        let occupancyOwnedByCurrentActor =
            (occupancyOwnerDeviceID != nil && occupancyOwnerDeviceID == currentDeviceID) ||
            (occupancyOwnerUserID != nil && occupancyOwnerUserID == currentUserID)
        let occupiedByOther = occupancyActive && !occupancyOwnedByCurrentActor
        let lockedDraftByOther = materialDraft.map { isSessionLockedByOther(sessionID: $0.id) } ?? false
        let locallyLocked = locallyLockedPropertyIDs.contains(propertyID)
        let showLock = occupiedByOther || lockedDraftByOther || locallyLocked
        let finalizedOrExported = isFinalSession(materialDraft)
        let lockReason: String = {
            if occupiedByOther { return "active_occupancy_other_device" }
            if lockedDraftByOther { return "locked_by_other" }
            if locallyLocked { return "locally_locked" }
            if occupancyActive { return "active_occupancy_owned_by_current_device" }
            if occupancyHasOwner { return "stale_occupancy_ignored" }
            return "no_active_occupancy"
        }()
        let draftOwnedByCurrentActor: Bool = {
            guard let materialDraft else { return false }
            if currentSession?.id == materialDraft.id { return true }
            if let draftOwnerDeviceID {
                return draftOwnerDeviceID == currentDeviceID
            }
            if let draftOwnerUserID {
                return draftOwnerUserID == currentUserID
            }
            return false
        }()
        let showDraft = materialDraft != nil &&
            !finalizedOrExported &&
            !showLock &&
            draftOwnedByCurrentActor
        let draftReason: String = {
            guard materialDraft != nil else { return "no_material_draft" }
            if finalizedOrExported { return "finalized_or_exported" }
            if showLock { return "hidden_by_other_device_occupancy" }
            if draftOwnedByCurrentActor { return "visible_owned_by_current_device" }
            if draftOwnerDeviceID != nil || draftOwnerUserID != nil {
                return "hidden_non_owner"
            }
            return "hidden_unverified_local_owner"
        }()

        guard let draft = materialDraft else {
            if userDefaults.bool(forKey: "draft_badge_verbose_logging") {
                print(
                    "[DraftBadge] propertyID=\(propertyID.uuidString) visible=false " +
                    "badge_visibility_reason=\(draftReason)"
                )
            }
            return nil
        }
        if showDraft {
            if userDefaults.bool(forKey: "draft_badge_verbose_logging") {
                print(
                    "[DraftBadge] propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(draft.id.uuidString) " +
                    "visible=true " +
                    "draft_owner_user=\(draftOwnerUserID?.uuidString ?? "nil") " +
                    "draft_owner_device=\(draftOwnerDeviceID ?? "nil") " +
                    "current_user=\(currentUserID?.uuidString ?? "nil") " +
                    "current_device=\(currentDeviceID) " +
                    "badge_visibility_reason=\(draftReason) " +
                    "lock_visibility_reason=\(lockReason)"
                )
            }
            return draft
        } else {
            if userDefaults.bool(forKey: "draft_badge_verbose_logging") {
                print(
                    "[DraftBadge] propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(draft.id.uuidString) " +
                    "visible=false " +
                    "draft_owner_user=\(draftOwnerUserID?.uuidString ?? "nil") " +
                    "draft_owner_device=\(draftOwnerDeviceID ?? "nil") " +
                    "current_user=\(currentUserID?.uuidString ?? "nil") " +
                    "current_device=\(currentDeviceID) " +
                    "badge_visibility_reason=\(draftReason) " +
                    "lock_visibility_reason=\(lockReason)"
                )
            }
            return nil
        }
    }

    func debugPropertyOccupancyDescription(propertyID: UUID) -> String {
        guard let occupancy = propertySessionOccupancyByPropertyID[propertyID] else {
            return "nil"
        }
        return "occupiedByUserID=\(occupancy.occupiedByUserID?.uuidString ?? "nil"),occupiedByDeviceID=\(occupancy.occupiedByDeviceID ?? "nil"),occupiedAt=\(occupancy.occupiedAt?.ISO8601Format() ?? "nil")"
    }

    func debugSessionCoordinationDescription(sessionID: UUID?) -> String {
        guard let sessionID else { return "nil" }
        guard let state = sessionCoordinationStateBySessionID[sessionID] else {
            return "nil"
        }
        return "lockedByUserID=\(state.lockedByUserID?.uuidString ?? "nil"),lockedByDeviceID=\(state.lockedByDeviceID ?? "nil"),lockedAt=\(state.lockedAt?.ISO8601Format() ?? "nil")"
    }

    func sessionUIStateDiagnostics(propertyID: UUID, sessionID: UUID) -> SessionUIStateDiagnostics? {
        let localSession = sessions(for: propertyID).first(where: { $0.id == sessionID }) ??
            allSessionIndexByProperty[propertyID]?.first(where: { $0.id == sessionID }) ??
            (currentSession?.id == sessionID ? currentSession : nil)
        let remote = sessionCoordinationDebugRemoteRecords[sessionID]
        let state = sessionCoordinationStateBySessionID[sessionID]
        let remoteLockedAt = remote?.lockedAt.flatMap(parseSupabaseDateString)
        let effectiveLockedByUserID = remote?.lockedByUserID ?? state?.lockedByUserID
        let effectiveLockedByDeviceID = normalizedSupabaseText(remote?.lockedByDeviceID) ?? normalizedSupabaseText(state?.lockedByDeviceID)
        let effectiveLockedAt = remoteLockedAt ?? state?.lockedAt
        let remoteFinal = isFinalRemoteSessionState(
            status: remote?.status,
            completedAt: nil,
            exportedAt: remote?.exportedAt,
            isSealed: remote?.isSealed,
            firstDeliveredAt: remote?.firstDeliveredAt
        )
        let localFinal = isFinalSession(localSession)
        let showsDraft = localSession?.status == .draft && localSession?.isSealed == false && !remoteFinal
        let showsLock = hasActiveRemoteLock(
            session: localSession,
            lockedByUserID: effectiveLockedByUserID,
            lockedByDeviceID: effectiveLockedByDeviceID,
            lockedAt: effectiveLockedAt
        )
        let reason: String
        if localFinal || remoteFinal {
            reason = "final_session_suppresses_draft_and_lock"
        } else if showsLock {
            reason = "active_remote_lock"
        } else if isStaleCoordinationLock(lockedAt: effectiveLockedAt) {
            reason = "stale_zero_photo_occupancy_ignored"
        } else if showsDraft {
            reason = "local_active_draft"
        } else {
            reason = "free_inactive"
        }
        return SessionUIStateDiagnostics(
            sessionID: sessionID,
            propertyID: propertyID,
            localStatus: localSession?.status.rawValue,
            remoteStatus: remote?.status,
            localDraftFlag: localSession?.status == .draft,
            remoteDraftFlag: remote?.status.map { normalizedSupabaseText($0)?.lowercased() == Session.Status.draft.rawValue } ?? nil,
            localActiveSessionID: currentSession?.id,
            remoteActiveSessionID: showsLock ? sessionID : nil,
            localIsSealed: localSession?.isSealed ?? false,
            remoteIsSealed: remote?.isSealed,
            localExportedAt: localSession?.exportedAt,
            remoteExportedAt: remote?.exportedAt,
            lockOwnerUserID: effectiveLockedByUserID,
            lockOwnerDeviceID: effectiveLockedByDeviceID,
            lockAt: effectiveLockedAt,
            currentUserID: authenticatedSupabaseUser?.id,
            currentDeviceID: currentDeviceIdentifier(),
            computedShowsDraft: showsDraft,
            computedShowsLock: showsLock,
            computedCanOpen: !showsLock,
            reason: reason
        )
    }

    func sessionListContentDiagnostics(propertyID: UUID) -> SessionListContentDiagnostics {
        let localSessions = sessions(for: propertyID).sorted { $0.startedAt > $1.startedAt }
        let localLatest = localSessions.first
        let badgeModel = propertyCardBadgeModel(for: propertyID)
        let badgeSession = badgeModel.showDraft
            ? localSessions.first(where: { $0.id == badgeModel.materialDraftSessionID })
            : nil
        let capturedDraft = canonicalDraftSession(for: propertyID, requireCaptures: true)
        let selectedSession: Session? = {
            if let currentSession, currentSession.propertyID == propertyID {
                return currentSession
            }
            if let capturedDraft {
                return capturedDraft
            }
            return localLatest
        }()
        let selectedSource: String = {
            if selectedSession?.id == currentSession?.id {
                return "current_session"
            }
            if selectedSession?.id == capturedDraft?.id {
                return "captured_draft"
            }
            if selectedSession?.id == localLatest?.id {
                return "latest_local"
            }
            return "none"
        }()
        let activeLockSessionID = sessionCoordinationStateBySessionID.first { sessionID, state in
            guard localSessions.contains(where: { $0.id == sessionID }) else { return false }
            guard state.lockedByUserID != nil || normalizedSupabaseText(state.lockedByDeviceID) != nil else { return false }
            guard !isStaleCoordinationLock(lockedAt: state.lockedAt) else { return false }
            return true
        }?.key
#if DEBUG
        let remoteLatest = sessionCoordinationDebugRemoteRecords.values
            .filter { $0.propertyID == propertyID }
            .sorted { ($0.updatedAt ?? .distantPast) > ($1.updatedAt ?? .distantPast) }
            .first
        let remoteActiveLock = sessionCoordinationDebugRemoteRecords.values
            .filter { $0.propertyID == propertyID }
            .filter { remoteRecord in
                hasActiveRemoteLock(
                    session: localSessions.first(where: { session in session.id == remoteRecord.id }),
                    lockedByUserID: remoteRecord.lockedByUserID,
                    lockedByDeviceID: remoteRecord.lockedByDeviceID,
                    lockedAt: remoteRecord.lockedAt.flatMap(parseSupabaseDateString)
                )
            }
            .sorted { ($0.updatedAt ?? .distantPast) > ($1.updatedAt ?? .distantPast) }
            .first
#else
        let remoteLatest: RemoteSessionCoordinationRecord? = nil
        let remoteActiveLock: RemoteSessionCoordinationRecord? = nil
#endif
        let resolvedActiveLockSessionID = remoteActiveLock?.id ?? activeLockSessionID
        let resolvedLockState = resolvedActiveLockSessionID.flatMap { sessionCoordinationStateBySessionID[$0] }
        let remoteFinal = remoteLatest.map {
            isFinalRemoteSessionState(
                status: $0.status,
                completedAt: $0.completedAt,
                exportedAt: $0.exportedAt,
                isSealed: $0.isSealed,
                firstDeliveredAt: $0.firstDeliveredAt
            )
        } ?? false
        let localFinal = localLatest.map { isFinalSession($0) } ?? false
        let occupancy = propertySessionOccupancyByPropertyID[propertyID]
        let occupancyStartedAt = occupancy?.occupiedAt
        let occupancyActive = {
            guard let occupancy else { return false }
            guard occupancy.occupiedByUserID != nil ||
                normalizedSupabaseText(occupancy.occupiedByDeviceID) != nil ||
                occupancy.occupiedAt != nil else {
                return false
            }
            return !isStaleCoordinationLock(lockedAt: occupancy.occupiedAt)
        }()
        let materialContentCount = selectedSession.map { sessionMaterialContentCount($0) } ?? 0
        let badgeReason: String = {
            if badgeSession != nil { return "captured_draft_owned_by_current_device" }
            if capturedDraft != nil { return badgeModel.draftReason }
            return "no_captured_draft"
        }()
        let lockVisibilityReason: String = {
            if badgeModel.showLock {
                return "active_occupancy_visible"
            }
            guard resolvedActiveLockSessionID != nil else { return "no_active_lock" }
            if let state = resolvedLockState,
               normalizedSupabaseText(state.lockedByDeviceID) != nil ||
                state.lockedByUserID != nil {
                return "locked_by_other"
            }
            return "active_lock_visible"
        }()
        let computedOpenBehavior: String = {
            if resolvedActiveLockSessionID != nil {
                return "blocked_by_active_lock"
            }
            if occupancyActive {
                return "blocked_by_active_occupancy"
            }
            if capturedDraft != nil {
                return "open_existing_captured_draft"
            }
            return "open_new_draft"
        }()
        return SessionListContentDiagnostics(
            propertyID: propertyID,
            selectedSessionID: selectedSession?.id,
            selectedSessionSource: selectedSource,
            badgeSessionID: badgeSession?.id,
            badgeReason: badgeReason,
            photoSourceSessionID: selectedSession?.id,
            guidedCompletionSourceSessionID: selectedSession.flatMap { sessionHasCaptures($0) ? $0.id : nil },
            localLatestSessionID: localLatest?.id,
            remoteLatestSessionID: remoteLatest?.id,
            activeLockSessionID: resolvedActiveLockSessionID,
            occupancyActive: occupancyActive,
            occupancyStartedAt: occupancyStartedAt,
            occupancyReleasedAt: occupancyActive ? nil : occupancyStartedAt,
            materialContentCount: materialContentCount,
            badgeSourceSessionID: badgeSession?.id,
            lockSourceSessionID: resolvedActiveLockSessionID,
            finalizationSource: remoteFinal ? "remote" : (localFinal ? "local" : nil),
            staleStateReason: (remoteFinal && badgeSession != nil) ? "remote_final_overrides_local_draft" : nil,
            draftOwnerUserID: badgeModel.draftOwnerUserID ?? resolvedLockState?.lockedByUserID,
            draftOwnerDeviceID: badgeModel.draftOwnerDeviceID ?? normalizedSupabaseText(resolvedLockState?.lockedByDeviceID),
            currentUserID: badgeModel.currentUserID,
            currentDeviceID: badgeModel.currentDeviceID,
            lockVisibilityReason: lockVisibilityReason,
            computedOpenBehavior: computedOpenBehavior
        )
    }

    func setLiveSyncMonitoringActive(_ active: Bool) {
        if active {
            guard liveSyncTimer == nil else { return }
            liveSyncTimer = Timer.scheduledTimer(withTimeInterval: 2.0, repeats: true) { [weak self] _ in
                guard let self else { return }
                if self.isLoading { return }
                Task { @MainActor [weak self] in
                    await self?.refreshActiveOccupancyHeartbeatIfNeeded(reason: "live_sync_timer")
                }
                let now = Date()
                let isBurst = (self.liveSyncBurstUntil.map { $0 > now }) ?? false
                if !isBurst,
                   let lastRefresh = self.lastLiveSyncRefreshAt,
                   now.timeIntervalSince(lastRefresh) < 6.0 {
                    return
                }
                let fingerprint = self.localStore.propertiesLedgerFingerprint()
                if fingerprint != self.lastLiveSyncFingerprint {
                    self.lastLiveSyncRefreshAt = now
                    self.refreshPropertiesInBackground()
                }
            }
            liveSyncTimer?.tolerance = 1.0
        } else {
            liveSyncTimer?.invalidate()
            liveSyncTimer = nil
            liveSyncBurstUntil = nil
            lastLiveSyncRefreshAt = nil
        }
    }

    private struct PropertyRefreshPayload {
        let properties: [Property]
        let organizations: [Organization]
        let caches: HubCachePayload
        let fingerprint: String
    }

    private enum PropertyRefreshPriority: Int {
        case fallback = 0
        case background = 1
        case foreground = 2
    }

    private struct PropertyRefreshAuthority {
        let token: UInt64
        let orgID: UUID?
        let priority: PropertyRefreshPriority
        let userID: UUID?
        let contextGeneration: UInt64
        let source: String
    }

    private struct AppliedPropertyRefreshState {
        let token: UInt64
        let priority: PropertyRefreshPriority
        let fingerprint: String?
        let orgScopedCount: Int
    }

    private var isRemotePropertyRefreshEnabled: Bool {
        backendFeatureFlags.supabaseEnabled &&
        backendFeatureFlags.supabasePropertyReadEnabled &&
        supabaseClient != nil &&
        activeOrganizationID != nil &&
        isOrganizationContextReady
    }

    private var isSyncDeltaEnabled: Bool {
        backendFeatureFlags.supabaseEnabled &&
        backendFeatureFlags.syncDeltaEnabled &&
        supabaseClient != nil &&
        activeOrganizationID != nil
    }

    private func shouldReevaluateOrganizationAccess(for error: Error) -> Bool {
        if let remoteError = error as? RemotePropertyFetchError {
            switch remoteError {
            case .emptyResponseRejected:
                return true
            default:
                break
            }
        }

        let message = error.localizedDescription.lowercased()
        return message.contains("permission")
            || message.contains("row-level security")
            || message.contains("not found for the authenticated user")
            || message.contains("forbidden")
    }

    @MainActor
    private func resolveOrganizationAccessAfterRemotePropertyFailure(
        requestedOrganizationID: UUID,
        error: Error
    ) async -> Bool {
        guard shouldReevaluateOrganizationAccess(for: error),
              let userID = authenticatedSupabaseUser?.id else {
            return false
        }

        do {
            try await refreshOrganizationContext(for: userID)
        } catch {
            print("[OrgAccess] context_recheck_failed orgID=\(requestedOrganizationID.uuidString) error=\(error.localizedDescription)")
        }

        return activeOrganizationID != requestedOrganizationID
    }

    private func setLoadingState(_ loading: Bool) {
        guard isLoading != loading else { return }
        isLoading = loading
    }

    @MainActor
    private func performForegroundAccessRefreshSequence(
        contextRefreshOverride: ((UUID?) async throws -> Void)? = nil,
        propertyRefreshOverride: ((String?) async -> Bool)? = nil,
        convergenceOverride: ((String) async -> Void)? = nil
    ) async {
        if requiresAuthentication {
            guard isAuthenticationReady,
                  let userID = authenticatedSupabaseUser?.id else {
                return
            }

            do {
                if let contextRefreshOverride {
                    try await contextRefreshOverride(userID)
                } else {
                    try await refreshOrganizationContext(for: userID)
                }
            } catch {
                print("[OrgAccess] foreground_context_refresh_failed error=\(error.localizedDescription)")
                return
            }
        }

        guard isOrganizationContextReady,
              activeOrganizationID != nil else {
            return
        }

        let activeSessionCheckpointTrigger =
            currentSession?.status == .draft
            ? "foreground"
            : nil

        let propertyRefreshSucceeded: Bool
        if let propertyRefreshOverride {
            propertyRefreshSucceeded = await propertyRefreshOverride(activeSessionCheckpointTrigger)
        } else {
            propertyRefreshSucceeded = await performForegroundRemotePropertyRefresh(
                activeSessionCheckpointTrigger: activeSessionCheckpointTrigger
            )
        }

        guard propertyRefreshSucceeded,
              activeOrganizationID != nil else {
            return
        }

        if let convergenceOverride {
            await convergenceOverride("foreground")
        } else {
            await performRemoteConvergenceCycle(source: "foreground")
        }
    }

    @MainActor
    @discardableResult
    private func revalidateActiveSessionAccessIfNeeded(
        trigger: String,
        authorizedPropertyIDs: Set<UUID>,
        organizationID: UUID
    ) async -> Bool {
        guard let session = currentSession,
              session.status == .draft,
              session.propertyID == selectedPropertyID,
              activeOrganizationID == organizationID else {
            return false
        }

        guard !authorizedPropertyIDs.contains(session.propertyID) else {
            return false
        }

        print(
            "[ActiveSessionAccess] result=revoked " +
            "trigger=\(trigger) " +
            "propertyID=\(session.propertyID.uuidString) " +
            "sessionID=\(session.id.uuidString)"
        )

        let persistedDraft = saveDraftCurrentSession(scheduleShadowWrite: false)
        await releaseCurrentSessionCoordinationLockIfOwned()
        if let persistedDraft {
            scheduleSessionShadowWriteAfterCoordinationRelease(for: persistedDraft)
        }

        let message = "Access to this property was revoked."
        hubTransientStatusMessage = message
        activeSessionAccessRevocationRequest = ActiveSessionAccessRevocationRequest(
            id: UUID(),
            propertyID: session.propertyID,
            message: message
        )
        return true
    }

    @MainActor
    func finalizeActiveSessionAccessRevocationIfNeeded(
        requestID: UUID,
        propertyID: UUID
    ) {
        guard activeSessionAccessRevocationRequest?.id == requestID else { return }
        if currentSession?.propertyID == propertyID {
            clearCurrentSession()
        }
        if selectedPropertyID == propertyID {
            selectedPropertyID = nil
        }
        activeSessionAccessRevocationRequest = nil
    }

    @MainActor
    func clearHubTransientStatusMessageIfMatching(_ message: String) {
        guard hubTransientStatusMessage == message else { return }
        hubTransientStatusMessage = nil
    }

    private func beginPropertyListLoadingForOrgSwitch(organizationID: UUID) {
        pendingPropertyListLoadingOrganizationID = organizationID
        guard !isLoadingPropertiesForOrgSwitch else { return }
        isLoadingPropertiesForOrgSwitch = true
    }

    private func finishPropertyListLoadingForOrgSwitch(requestedOrganizationID: UUID? = nil) {
        if let requestedOrganizationID,
           pendingPropertyListLoadingOrganizationID != requestedOrganizationID {
            return
        }
        pendingPropertyListLoadingOrganizationID = nil
        guard isLoadingPropertiesForOrgSwitch else { return }
        isLoadingPropertiesForOrgSwitch = false
    }

    private func refreshPropertiesForOrganizationSwitch(requestedOrganizationID: UUID) async {
        let localAuthority = beginPropertyRefreshAuthority(
            orgID: requestedOrganizationID,
            priority: .fallback,
            source: "org_switch_local"
        )
        let firstPayload: PropertyRefreshPayload? = await withCheckedContinuation { continuation in
            DispatchQueue.global(qos: .userInitiated).async {
                let payload = (try? self.makeRefreshPayloadForHubIndexOnly())
                    ?? (try? self.makeRefreshPayload())
                continuation.resume(returning: payload)
            }
        }

        guard activeOrganizationID == requestedOrganizationID else {
            finishPropertyListLoadingForOrgSwitch(requestedOrganizationID: requestedOrganizationID)
            return
        }

        if let firstPayload {
            applyRefreshPayload(
                firstPayload,
                authority: localAuthority,
                replacingOrganizationID: requestedOrganizationID
            )
            scheduleOffloadEligibleSessionMedia(excludingSessionID: currentSession?.id)
        }

        await refreshPropertiesAwaitingForegroundRefresh()
        hubRowRefreshToken = UUID()
        finishPropertyListLoadingForOrgSwitch(requestedOrganizationID: requestedOrganizationID)
    }

    @MainActor
    private func performForegroundRemotePropertyRefresh(
        activeSessionCheckpointTrigger: String? = nil
    ) async -> Bool {
        guard let requestedOrganizationID = activeOrganizationID else {
            performLocalPropertyRefreshFallback(
                orgID: nil,
                source: "foreground_missing_org"
            )
            return false
        }
        let authority = beginPropertyRefreshAuthority(
            orgID: requestedOrganizationID,
            priority: .foreground,
            source: "foreground_remote"
        )
        let requestedUserID = authenticatedSupabaseUser?.id
        let requestedContextGeneration = authenticatedAccessContextGeneration

        logRemotePropertyFetchResult(
            outcome: "foreground_fetch_started",
            recordCount: backingPropertyCount(for: requestedOrganizationID),
            error: nil
        )

        do {
            let localBackingCount = backingPropertyCount(for: requestedOrganizationID)
            let records = try await fetchRemotePropertyList(activeOrganizationID: requestedOrganizationID)
            let validated = try validateRemotePropertyResponse(
                records: records,
                localCacheCount: localBackingCount,
                activeOrganizationID: requestedOrganizationID
            )
            guard isCurrentAuthenticatedAccessContext(
                userID: requestedUserID,
                organizationID: requestedOrganizationID,
                generation: requestedContextGeneration
            ) else {
                throw RemotePropertyFetchError.missingActiveOrganization
            }
            let payload = try makeRemotePropertyRefreshPayload(
                validatedRecords: validated,
                requestedOrganizationID: requestedOrganizationID
            )
            guard isCurrentAuthenticatedAccessContext(
                userID: requestedUserID,
                organizationID: requestedOrganizationID,
                generation: requestedContextGeneration
            ) else {
                print(
                    "[OrgAccess] discard_foreground_property_payload_for_stale_context " +
                    "requestedUserID=\(requestedUserID?.uuidString ?? "nil") " +
                    "currentUserID=\(authenticatedSupabaseUser?.id.uuidString ?? "nil") " +
                    "requestedOrgID=\(requestedOrganizationID.uuidString) " +
                    "currentOrgID=\(activeOrganizationID?.uuidString ?? "nil")"
                )
                return false
            }
            setAuthorizedPropertyIDs(
                Set(payload.properties.filter { $0.deletedAt == nil }.map(\.id)),
                for: requestedOrganizationID
            )
            if let activeSessionCheckpointTrigger {
                _ = await revalidateActiveSessionAccessIfNeeded(
                    trigger: activeSessionCheckpointTrigger,
                    authorizedPropertyIDs: Set(payload.properties.filter { $0.deletedAt == nil }.map(\.id)),
                    organizationID: requestedOrganizationID
                )
            }
            let mergedPayload = mergedBackingRefreshPayload(
                replacingOrganizationID: requestedOrganizationID,
                with: payload
            )
            do {
                try localStore.replacePropertyListCacheAtomically(
                    properties: mergedPayload.properties,
                    organizations: mergedPayload.organizations
                )
            } catch {
                print("[PropertiesRefresh] local cache replacement failed after remote authorization: \(error.localizedDescription)")
            }
            applyRefreshPayload(
                mergedPayload,
                authority: authority,
                replacingOrganizationID: requestedOrganizationID
            )
            let visiblePropertyIDs = mergedPayload.properties.filter { $0.deletedAt == nil }.map(\.id)
            queuePropertyStatusDiagnosticsRefresh(
                trigger: "foreground_refresh",
                orgID: requestedOrganizationID,
                propertyIDs: visiblePropertyIDs
            )
            await refreshVisibleLockBadgesFromEntrySources(
                orgID: requestedOrganizationID,
                propertyIDs: visiblePropertyIDs,
                reason: "foreground_refresh"
            )
            lastLiveSyncFingerprint = localStore.propertiesLedgerFingerprint()
            logRemotePropertyFetchResult(
                outcome: "foreground_success",
                recordCount: mergedPayload.properties.count,
                error: nil,
                fingerprint: mergedPayload.fingerprint
            )
            return true
        } catch {
            if await resolveOrganizationAccessAfterRemotePropertyFailure(
                requestedOrganizationID: requestedOrganizationID,
                error: error
            ) {
                return false
            }
            logRemotePropertyFetchResult(
                outcome: "foreground_fallback_local",
                recordCount: nil,
                error: error
            )
            performLocalPropertyRefreshFallback(
                orgID: requestedOrganizationID,
                source: "foreground_fallback_local"
            )
            return false
        }
    }

    @MainActor
    private func performBackgroundRemotePropertyRefresh() async {
        defer { isBackgroundRefreshInFlight = false }

        guard let requestedOrganizationID = activeOrganizationID else {
            logRemotePropertyFetchResult(
                outcome: "background_rejected",
                recordCount: nil,
                error: RemotePropertyFetchError.missingActiveOrganization
            )
            return
        }
        let authority = beginPropertyRefreshAuthority(
            orgID: requestedOrganizationID,
            priority: .background,
            source: "background_remote"
        )
        let requestedUserID = authenticatedSupabaseUser?.id
        let requestedContextGeneration = authenticatedAccessContextGeneration

        if let lastCompletedAt = lastBackgroundRemoteAttemptCompletedAt,
           Date().timeIntervalSince(lastCompletedAt) < 60 {
            return
        }

        logRemotePropertyFetchResult(
            outcome: "background_fetch_started",
            recordCount: backingPropertyCount(for: requestedOrganizationID),
            error: nil
        )

        do {
            let localBackingCount = backingPropertyCount(for: requestedOrganizationID)
            let records = try await fetchRemotePropertyList(activeOrganizationID: requestedOrganizationID)
            let validated = try validateRemotePropertyResponse(
                records: records,
                localCacheCount: localBackingCount,
                activeOrganizationID: requestedOrganizationID
            )
            guard isCurrentAuthenticatedAccessContext(
                userID: requestedUserID,
                organizationID: requestedOrganizationID,
                generation: requestedContextGeneration
            ) else {
                throw RemotePropertyFetchError.missingActiveOrganization
            }
            let payload = try makeRemotePropertyRefreshPayload(
                validatedRecords: validated,
                requestedOrganizationID: requestedOrganizationID
            )
            guard isCurrentAuthenticatedAccessContext(
                userID: requestedUserID,
                organizationID: requestedOrganizationID,
                generation: requestedContextGeneration
            ) else {
                print(
                    "[OrgAccess] discard_background_property_payload_for_stale_context " +
                    "requestedUserID=\(requestedUserID?.uuidString ?? "nil") " +
                    "currentUserID=\(authenticatedSupabaseUser?.id.uuidString ?? "nil") " +
                    "requestedOrgID=\(requestedOrganizationID.uuidString) " +
                    "currentOrgID=\(activeOrganizationID?.uuidString ?? "nil")"
                )
                return
            }
            setAuthorizedPropertyIDs(
                Set(payload.properties.filter { $0.deletedAt == nil }.map(\.id)),
                for: requestedOrganizationID
            )
            let mergedPayload = mergedBackingRefreshPayload(
                replacingOrganizationID: requestedOrganizationID,
                with: payload
            )
            let visiblePropertyIDs = mergedPayload.properties.filter { $0.deletedAt == nil }.map(\.id)
            if lastBackgroundRemoteFingerprint == mergedPayload.fingerprint {
                lastBackgroundRemoteAttemptCompletedAt = Date()
                return
            }
            guard wouldApplyRefreshPayloadChangeBackingState(mergedPayload) else {
                lastBackgroundRemoteFingerprint = mergedPayload.fingerprint
                lastBackgroundRemoteAttemptCompletedAt = Date()
                return
            }
            do {
                try localStore.replacePropertyListCacheAtomically(
                    properties: mergedPayload.properties,
                    organizations: mergedPayload.organizations
                )
            } catch {
                print("[PropertiesRefresh] local cache replacement failed after background remote authorization: \(error.localizedDescription)")
            }
            applyRefreshPayload(
                mergedPayload,
                authority: authority,
                replacingOrganizationID: requestedOrganizationID
            )
            queuePropertyStatusDiagnosticsRefresh(
                trigger: "background_refresh",
                orgID: requestedOrganizationID,
                propertyIDs: visiblePropertyIDs
            )
            lastBackgroundRemoteFingerprint = mergedPayload.fingerprint
            lastBackgroundRemoteAttemptCompletedAt = Date()
            lastLiveSyncFingerprint = localStore.propertiesLedgerFingerprint()
            scheduleOffloadEligibleSessionMedia(excludingSessionID: currentSession?.id)
            logRemotePropertyFetchResult(
                outcome: "background_success",
                recordCount: mergedPayload.properties.count,
                error: nil,
                fingerprint: mergedPayload.fingerprint
            )
        } catch {
            if await resolveOrganizationAccessAfterRemotePropertyFailure(
                requestedOrganizationID: requestedOrganizationID,
                error: error
            ) {
                return
            }
            logRemotePropertyFetchResult(
                outcome: "background_rejected",
                recordCount: nil,
                error: error
            )
        }
    }

    private func performLocalPropertyRefreshFallback(
        orgID: UUID? = nil,
        source: String = "local_fallback"
    ) {
        do {
            let payload = try makeRefreshPayload()
            let authority = beginPropertyRefreshAuthority(
                orgID: orgID ?? activeOrganizationID,
                priority: .fallback,
                source: source
            )
            applyRefreshPayload(
                payload,
                authority: authority,
                replacingOrganizationID: orgID ?? activeOrganizationID
            )
        } catch {
            // Preserve current in-memory view on transient iCloud read failures.
            print("[PropertiesRefresh] transient read failure: \(error.localizedDescription)")
        }
    }


    private func makeRefreshPayload() throws -> PropertyRefreshPayload {
        let start = Date()
        let fetchedProperties = try localStore.fetchProperties()
        let fetchedOrganizations = (try? localStore.fetchOrganizations()) ?? []
        let caches = makeHubCaches(for: fetchedProperties)
        let fingerprint = localStore.propertiesLedgerFingerprint()
        let elapsedMs = Int(Date().timeIntervalSince(start) * 1000)
        logHubFetch(
            phase: "background",
            source: "full-fallback",
            properties: fetchedProperties.count,
            orgs: fetchedOrganizations.count,
            elapsedMs: elapsedMs
        )
        return PropertyRefreshPayload(
            properties: fetchedProperties,
            organizations: fetchedOrganizations,
            caches: caches,
            fingerprint: fingerprint
        )
    }

    private func makeRefreshPayloadForHubIndexOnly() throws -> PropertyRefreshPayload {
        let start = Date()
        guard let state = try localStore.fetchPropertyAndOrganizationStateFromHubIndex(downloadTimeout: 2.0) else {
            let elapsedMs = Int(Date().timeIntervalSince(start) * 1000)
            logHubFetch(
                phase: "background",
                source: "none",
                properties: 0,
                orgs: 0,
                elapsedMs: elapsedMs
            )
            throw NSError(domain: "AppState.HubIndex", code: 1)
        }
        let elapsedMs = Int(Date().timeIntervalSince(start) * 1000)
        logHubFetch(
            phase: "background",
            source: state.source.rawValue,
            properties: state.properties.count,
            orgs: state.organizations.count,
            elapsedMs: elapsedMs
        )
        let caches = makeHubCaches(for: state.properties)
        let fingerprint = localStore.propertiesLedgerFingerprint()
        return PropertyRefreshPayload(
            properties: state.properties,
            organizations: state.organizations,
            caches: caches,
            fingerprint: fingerprint
        )
    }

    private func applyRefreshPayload(
        _ payload: PropertyRefreshPayload,
        authority: PropertyRefreshAuthority? = nil,
        replacingOrganizationID: UUID? = nil
    ) {
        guard shouldApplyRefreshPayload(
            payload,
            authority: authority,
            replacingOrganizationID: replacingOrganizationID
        ) else {
            return
        }
        applyHubCachePayload(
            properties: payload.properties,
            organizations: payload.organizations,
            caches: payload.caches
        )
        lastLiveSyncFingerprint = payload.fingerprint
    }

    private func wouldApplyRefreshPayloadChangeBackingState(_ payload: PropertyRefreshPayload) -> Bool {
        if !propertiesMatchForNoOpDecision(allProperties, payload.properties) {
            return true
        }
        if allOrganizations != payload.organizations {
            return true
        }
        if allSessionIndexByProperty != payload.caches.sessionIndex {
            return true
        }
        if allDraftSessionByProperty != payload.caches.drafts {
            return true
        }
        if allPendingExportSessionByProperty != payload.caches.pending {
            return true
        }
        if allHubMetaByProperty != payload.caches.meta {
            return true
        }
        return false
    }

    private func propertiesMatchForNoOpDecision(_ lhs: [Property], _ rhs: [Property]) -> Bool {
        guard lhs.count == rhs.count else { return false }
        for (left, right) in zip(lhs, rhs) {
            guard propertyMatchesForNoOpDecision(left, right) else {
                return false
            }
        }
        return true
    }

    private func propertyMatchesForNoOpDecision(_ lhs: Property, _ rhs: Property) -> Bool {
        lhs.id == rhs.id &&
        lhs.orgId == rhs.orgId &&
        lhs.name == rhs.name &&
        lhs.address == rhs.address &&
        lhs.street == rhs.street &&
        lhs.city == rhs.city &&
        lhs.state == rhs.state &&
        lhs.zip == rhs.zip &&
        lhs.clientName == rhs.clientName &&
        lhs.clientEmail == rhs.clientEmail &&
        lhs.clientPhone == rhs.clientPhone &&
        lhs.baselineSessionID == rhs.baselineSessionID &&
        lhs.isArchived == rhs.isArchived &&
        lhs.deletedAt == rhs.deletedAt
    }

    private static func propertyIsOrderedBefore(_ lhs: Property, _ rhs: Property) -> Bool {
        if lhs.createdAt != rhs.createdAt {
            return lhs.createdAt < rhs.createdAt
        }
        let nameOrder = lhs.name.localizedCaseInsensitiveCompare(rhs.name)
        if nameOrder != .orderedSame {
            return nameOrder == .orderedAscending
        }
        return lhs.id.uuidString.lowercased() < rhs.id.uuidString.lowercased()
    }

    private func mergedBackingRefreshPayload(
        replacingOrganizationID organizationID: UUID,
        with payload: PropertyRefreshPayload
    ) -> PropertyRefreshPayload {
        let mergedProperties = mergedBackingProperties(
            replacingOrganizationID: organizationID,
            with: payload.properties
        )
        let mergedOrganizations = mergedBackingOrganizations(
            replacingOrganizationID: organizationID,
            with: payload.organizations
        )
        let mergedCaches = mergedBackingCaches(
            replacingOrganizationID: organizationID,
            mergedProperties: mergedProperties,
            remoteCaches: payload.caches
        )
        return PropertyRefreshPayload(
            properties: mergedProperties,
            organizations: mergedOrganizations,
            caches: mergedCaches,
            fingerprint: payload.fingerprint
        )
    }

    private func mergedBackingProperties(
        replacingOrganizationID organizationID: UUID,
        with remoteProperties: [Property]
    ) -> [Property] {
        let remoteIDs = Set(remoteProperties.map(\.id))
        let preserved = allProperties.filter { property in
            property.orgId != organizationID ||
            (property.deletedAt != nil && !remoteIDs.contains(property.id))
        }
        return (preserved + remoteProperties).sorted(by: Self.propertyIsOrderedBefore)
    }

    private func mergedBackingOrganizations(
        replacingOrganizationID organizationID: UUID,
        with remoteOrganizations: [Organization]
    ) -> [Organization] {
        var merged = allOrganizations
        guard let replacement = remoteOrganizations.first(where: { $0.id == organizationID }) else {
            return merged
        }
        if let index = merged.firstIndex(where: { $0.id == organizationID }) {
            merged[index] = replacement
        } else {
            merged.append(replacement)
        }
        return merged
    }

    private func mergedBackingCaches(
        replacingOrganizationID organizationID: UUID,
        mergedProperties: [Property],
        remoteCaches: HubCachePayload
    ) -> HubCachePayload {
        let currentActivePropertyIDs = Set(
            allProperties
                .filter { $0.orgId == organizationID }
                .map(\.id)
        )
        let remoteActivePropertyIDs = Set(
            mergedProperties
                .filter { $0.orgId == organizationID }
                .map(\.id)
        )
        let replacedPropertyIDs = currentActivePropertyIDs.union(remoteActivePropertyIDs)

        let sessionIndex = allSessionIndexByProperty
            .filter { !replacedPropertyIDs.contains($0.key) }
            .merging(remoteCaches.sessionIndex) { _, new in new }
        let drafts = allDraftSessionByProperty
            .filter { !replacedPropertyIDs.contains($0.key) }
            .merging(remoteCaches.drafts) { _, new in new }
        let pending = allPendingExportSessionByProperty
            .filter { !replacedPropertyIDs.contains($0.key) }
            .merging(remoteCaches.pending) { _, new in new }
        let meta = allHubMetaByProperty
            .filter { !replacedPropertyIDs.contains($0.key) }
            .merging(remoteCaches.meta) { _, new in new }

        return HubCachePayload(
            sessionIndex: sessionIndex,
            drafts: drafts,
            pending: pending,
            meta: meta
        )
    }

    private func markLiveSyncBurstWindow(seconds: TimeInterval) {
        liveSyncBurstUntil = Date().addingTimeInterval(max(seconds, 1))
    }

    @discardableResult
    func createProperty(
        organizationID: UUID,
        clientName: String,
        propertyName: String,
        address: String,
        street: String = "",
        city: String = "",
        state: String = "",
        zip: String = "",
        clientPhone: String = "",
        clientEmail: String = ""
    ) throws -> Property {
        do {
            let property = try makePropertyForCreate(
                organizationID: organizationID,
                clientName: clientName,
                propertyName: propertyName,
                address: address,
                street: street,
                city: city,
                state: state,
                zip: zip,
                clientPhone: clientPhone,
                clientEmail: clientEmail
            )
            guard !requiresRemotePropertyCreate(for: organizationID) else {
                throw PropertyCreationError.remoteCreateUnavailable
            }
            let created = try persistCreatedPropertyLocally(property)
            schedulePhaseBPropertyShadowWrite(for: created)
            return created
        } catch {
            if let propertyCreationError = error as? PropertyCreationError {
                throw propertyCreationError
            }
            if case LocalStore.StoreError.noAvailableFolderID = error {
                throw PropertyCreationError.noAvailableFolderID
            }
            throw PropertyCreationError.persistenceFailed
        }
    }

    @discardableResult
    func createPropertyRemoteAware(
        organizationID: UUID,
        clientName: String,
        propertyName: String,
        address: String,
        street: String = "",
        city: String = "",
        state: String = "",
        zip: String = "",
        clientPhone: String = "",
        clientEmail: String = ""
    ) async throws -> Property {
        do {
            let property = try makePropertyForCreate(
                organizationID: organizationID,
                clientName: clientName,
                propertyName: propertyName,
                address: address,
                street: street,
                city: city,
                state: state,
                zip: zip,
                clientPhone: clientPhone,
                clientEmail: clientEmail
            )

            if requiresRemotePropertyCreate(for: organizationID) {
                guard remotePropertyCreatePathAvailable(for: organizationID) else {
                    throw PropertyCreationError.remoteCreateUnavailable
                }

                let payload = makeSupabasePropertyPayload(
                    propertyID: property.id,
                    orgID: organizationID,
                    property: property,
                    metadata: nil
                )
                print(
                    "[PropertyRemoteCreateDiag] event=remote_create_attempt " +
                    "propertyID=\(property.id.uuidString) " +
                    "selectedOrganizationID=\(organizationID.uuidString) " +
                    "payloadOrgID=\(payload.orgID.uuidString) " +
                    "payloadUpdatedBy=\(payload.updatedBy?.uuidString ?? "nil") " +
                    "appAuthUserID=\(authenticatedSupabaseUser?.id.uuidString ?? "nil") " +
                    "appAuthEmail=\(authenticatedSupabaseUser?.email ?? "nil") " +
                    "activeOrganizationID=\(activeOrganizationID?.uuidString ?? "nil") " +
                    "supabaseEnabled=\(backendFeatureFlags.supabaseEnabled) " +
                    "shadowWriteEnabled=\(backendFeatureFlags.shadowWriteEnabled) " +
                    "supabaseReadEnabled=\(backendFeatureFlags.supabaseReadEnabled) " +
                    "supabasePropertyReadEnabled=\(backendFeatureFlags.supabasePropertyReadEnabled) " +
                    "supabaseClientExists=\(supabaseClient != nil) " +
                    "organizationContextReady=\(isOrganizationContextReady) " +
                    "upsertConflictTarget=id"
                )

                do {
                    try await performRemotePropertyInsert(property: property, payload: payload)
                } catch {
                    throw PropertyCreationError.remoteCreateFailed(error.localizedDescription)
                }

                return try persistCreatedPropertyLocally(property)
            }

            let created = try persistCreatedPropertyLocally(property)
            schedulePhaseBPropertyShadowWrite(for: created)
            return created
        } catch {
            if let propertyCreationError = error as? PropertyCreationError {
                throw propertyCreationError
            }
            if case LocalStore.StoreError.noAvailableFolderID = error {
                throw PropertyCreationError.noAvailableFolderID
            }
            throw PropertyCreationError.persistenceFailed
        }
    }

    private func makePropertyForCreate(
        organizationID: UUID,
        clientName: String,
        propertyName: String,
        address: String,
        street: String,
        city: String,
        state: String,
        zip: String,
        clientPhone: String,
        clientEmail: String
    ) throws -> Property {
        let cleanedClientName = clientName.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedName = propertyName.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedAddress = address.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedStreet = street.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedCity = city.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedState = state.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedZip = zip.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedPhone = clientPhone.filter(\.isNumber)
        let cleanedEmail = clientEmail.trimmingCharacters(in: .whitespacesAndNewlines)

        guard !cleanedName.isEmpty else { throw PropertyCreationError.missingPropertyName }
        guard canAccessOrganization(organizationID) else { throw PropertyCreationError.missingOrganization }

        return Property(
            id: UUID(),
            orgId: organizationID,
            clientName: cleanedClientName.isEmpty ? nil : cleanedClientName,
            clientPhone: cleanedPhone.isEmpty ? nil : cleanedPhone,
            clientEmail: cleanedEmail.isEmpty ? nil : cleanedEmail,
            name: cleanedName,
            address: cleanedAddress.isEmpty ? nil : cleanedAddress,
            street: cleanedStreet.isEmpty ? nil : cleanedStreet,
            city: cleanedCity.isEmpty ? nil : cleanedCity,
            state: cleanedState.isEmpty ? nil : cleanedState,
            zip: cleanedZip.isEmpty ? nil : cleanedZip
        )
    }

    private func persistCreatedPropertyLocally(_ property: Property) throws -> Property {
        guard let orgID = property.orgId else { throw PropertyCreationError.missingOrganization }
        try ensureLocalOrganizationExists(for: orgID)
        let created = try localStore.createProperty(property)
        allProperties.append(created)
        allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
        allSessionIndexByProperty[created.id] = []
        allDraftSessionByProperty[created.id] = nil
        allPendingExportSessionByProperty[created.id] = nil
        allHubMetaByProperty[created.id] = makeHubMeta(for: created, organizations: allOrganizations)
        applyTenantScopedState()
        if selectedPropertyID == nil {
            selectedPropertyID = created.id
        }
        return created
    }

    @discardableResult
    func createOrganization(name: String) -> Organization? {
        guard !requiresAuthentication else { return nil }
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedName.isEmpty else { return nil }
        do {
            let created = try localStore.createOrganization(Organization(name: trimmedName))
            allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
            applyTenantScopedState()
            return created
        } catch {
            return allOrganizations.first(where: { $0.name.trimmingCharacters(in: .whitespacesAndNewlines).caseInsensitiveCompare(trimmedName) == .orderedSame })
        }
    }

    func organizationContacts(for organizationID: UUID?) -> [OrganizationContact] {
        guard canAccessOrganization(organizationID), let organizationID else { return [] }
        return organizations.first(where: { $0.id == organizationID })?.contacts ?? []
    }

    @discardableResult
    func updateOrganizationContact(organizationID: UUID, contact: OrganizationContact) -> Bool {
        guard canAccessOrganization(organizationID) else { return false }
        do {
            _ = try localStore.updateOrganizationContact(organizationID: organizationID, contact: contact)
            allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
            applyTenantScopedState()
            return true
        } catch {
            return false
        }
    }

    @discardableResult
    func deleteOrganizationContact(organizationID: UUID, contactID: UUID) -> Bool {
        guard canAccessOrganization(organizationID) else { return false }
        do {
            _ = try localStore.deleteOrganizationContact(organizationID: organizationID, contactID: contactID)
            allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
            applyTenantScopedState()
            return true
        } catch {
            return false
        }
    }

    func selectProperty(id: UUID) {
        selectedPropertyID = id
        markPropertyActivated(id: id)
    }

    func propertyOpenFreshness(for propertyID: UUID) -> PropertyOpenFreshnessSnapshot? {
        propertyOpenFreshnessByPropertyID[propertyID]
    }

    func beginPropertyOpenFreshnessCheck(propertyID: UUID) {
        guard let localProperty = properties.first(where: { $0.id == propertyID }) ??
                allProperties.first(where: { $0.id == propertyID }) else {
            propertyOpenFreshnessByPropertyID[propertyID] = PropertyOpenFreshnessSnapshot(
                propertyID: propertyID,
                status: .unknown,
                checkedAt: Date(),
                localUpdatedAt: nil,
                remoteUpdatedAt: nil,
                remoteRevision: nil,
                hasUnsyncedLocalPropertyWork: false,
                reason: "local_property_missing"
            )
            return
        }

        guard isRemotePropertyRefreshEnabled,
              let activeOrganizationID else {
            propertyOpenFreshnessByPropertyID[propertyID] = PropertyOpenFreshnessSnapshot(
                propertyID: propertyID,
                status: .usingLocalCache,
                checkedAt: Date(),
                localUpdatedAt: localProperty.updatedAt,
                remoteUpdatedAt: nil,
                remoteRevision: nil,
                hasUnsyncedLocalPropertyWork: false,
                reason: "remote_scope_unavailable"
            )
            print("[PropertyFreshness] propertyID=\(propertyID.uuidString) status=using_local_cache reason=remote_scope_unavailable")
            return
        }

        propertyOpenFreshnessByPropertyID[propertyID] = PropertyOpenFreshnessSnapshot(
            propertyID: propertyID,
            status: .checkingCloudStatus,
            checkedAt: Date(),
            localUpdatedAt: localProperty.updatedAt,
            remoteUpdatedAt: nil,
            remoteRevision: nil,
            hasUnsyncedLocalPropertyWork: false,
            reason: "checking"
        )

        Task { [weak self] in
            await self?.performPropertyOpenFreshnessCheck(
                propertyID: propertyID,
                activeOrganizationID: activeOrganizationID
            )
        }
    }

    private func performPropertyOpenFreshnessCheck(propertyID: UUID, activeOrganizationID: UUID) async {
        guard let localProperty = properties.first(where: { $0.id == propertyID }) ??
                allProperties.first(where: { $0.id == propertyID }) else {
            await MainActor.run {
                self.propertyOpenFreshnessByPropertyID[propertyID] = PropertyOpenFreshnessSnapshot(
                    propertyID: propertyID,
                    status: .unknown,
                    checkedAt: Date(),
                    localUpdatedAt: nil,
                    remoteUpdatedAt: nil,
                    remoteRevision: nil,
                    hasUnsyncedLocalPropertyWork: false,
                    reason: "local_property_missing"
                )
            }
            return
        }

        let hasUnsyncedLocalPropertyWork = Self.hasUnsyncedLocalPropertyWork(
            propertyID: propertyID,
            queuedMutations: (try? localStore.fetchQueuedMutations()) ?? []
        )

        do {
            let remote = try await fetchRemotePropertyFreshness(
                propertyID: propertyID,
                activeOrganizationID: activeOrganizationID
            )
            var evaluatedProperty = localProperty
            var evaluation = Self.evaluatePropertyOpenFreshness(
                localPropertyID: evaluatedProperty.id,
                localOrgID: evaluatedProperty.orgId,
                localUpdatedAt: evaluatedProperty.updatedAt,
                localIsArchived: evaluatedProperty.isArchived,
                activeOrganizationID: activeOrganizationID,
                remote: remote,
                hasUnsyncedLocalPropertyWork: hasUnsyncedLocalPropertyWork
            )
            if evaluation.status == .remoteUpdatesAvailable,
               !hasUnsyncedLocalPropertyWork,
               let remote,
               let refreshedProperty = await applyRemotePropertyFreshnessUpdateIfNeeded(
                propertyID: propertyID,
                activeOrganizationID: activeOrganizationID,
                remote: remote
               ) {
                evaluatedProperty = refreshedProperty
                let refreshedEvaluation = Self.evaluatePropertyOpenFreshness(
                    localPropertyID: evaluatedProperty.id,
                    localOrgID: evaluatedProperty.orgId,
                    localUpdatedAt: evaluatedProperty.updatedAt,
                    localIsArchived: evaluatedProperty.isArchived,
                    activeOrganizationID: activeOrganizationID,
                    remote: remote,
                    hasUnsyncedLocalPropertyWork: hasUnsyncedLocalPropertyWork
                )
                evaluation = refreshedEvaluation.status == .current
                    ? (.current, "remote_update_applied")
                    : refreshedEvaluation
            }
            if evaluation.status == .current,
               !hasUnsyncedLocalPropertyWork,
               let referenceFreshness = await reconcileLatestReferenceSessionFreshness(
                propertyID: propertyID,
                activeOrganizationID: activeOrganizationID
               ),
               referenceFreshness.hasPendingReferenceState {
                evaluation = (.remoteUpdatesAvailable, referenceFreshness.reason)
            }
            await MainActor.run {
                self.propertyOpenFreshnessByPropertyID[propertyID] = PropertyOpenFreshnessSnapshot(
                    propertyID: propertyID,
                    status: evaluation.status,
                    checkedAt: Date(),
                    localUpdatedAt: evaluatedProperty.updatedAt,
                    remoteUpdatedAt: remote?.updatedAt,
                    remoteRevision: remote?.revision,
                    hasUnsyncedLocalPropertyWork: hasUnsyncedLocalPropertyWork,
                    reason: evaluation.reason
                )
            }
            print(
                "[PropertyFreshness] propertyID=\(propertyID.uuidString) " +
                "status=\(evaluation.status.rawValue) reason=\(evaluation.reason) " +
                "localUpdatedAt=\(evaluatedProperty.updatedAt) " +
                "remoteUpdatedAt=\(remote?.updatedAt.description ?? "nil") " +
                "remoteRevision=\(remote?.revision.map(String.init) ?? "nil")"
            )
        } catch {
            let status = Self.propertyOpenFreshnessStatusForRemoteFailure(error)
            await MainActor.run {
                self.propertyOpenFreshnessByPropertyID[propertyID] = PropertyOpenFreshnessSnapshot(
                    propertyID: propertyID,
                    status: status,
                    checkedAt: Date(),
                    localUpdatedAt: localProperty.updatedAt,
                    remoteUpdatedAt: nil,
                    remoteRevision: nil,
                    hasUnsyncedLocalPropertyWork: hasUnsyncedLocalPropertyWork,
                    reason: Self.diagnosticErrorCategory(for: error).rawValue
                )
            }
            print(
                "[PropertyFreshness] propertyID=\(propertyID.uuidString) " +
                "status=\(status.rawValue) reason=remote_check_failed category=\(Self.diagnosticErrorCategory(for: error).rawValue)"
            )
        }
    }

    private func fetchRemotePropertyFreshness(
        propertyID: UUID,
        activeOrganizationID: UUID
    ) async throws -> PropertyOpenFreshnessRemoteSnapshot? {
        guard let client = supabaseClient else {
            throw RemotePropertyFetchError.missingClient
        }

        let records = try await withThrowingTaskGroup(of: [RemotePropertyFreshnessRecord].self) { group in
            group.addTask {
                try await client
                    .from("properties")
                    .select(
                        """
                        id,
                        org_id,
                        updated_at,
                        revision,
                        deleted_at,
                        is_archived,
                        capture_profile
                        """
                    )
                    .eq("id", value: propertyID.uuidString.lowercased())
                    .eq("org_id", value: activeOrganizationID.uuidString.lowercased())
                    .limit(1)
                    .execute()
                    .value as [RemotePropertyFreshnessRecord]
            }

            group.addTask {
                try await Task.sleep(nanoseconds: 3_000_000_000)
                throw RemotePropertyFetchError.timedOut
            }

            guard let firstResult = try await group.next() else {
                throw RemotePropertyFetchError.timedOut
            }
            group.cancelAll()
            return firstResult
        }

        guard let record = records.first else { return nil }
        return PropertyOpenFreshnessRemoteSnapshot(
            propertyID: record.id,
            orgID: record.orgID,
            updatedAt: record.updatedAt,
            revision: record.revision,
            deletedAt: record.deletedAt,
            isArchived: record.isArchived,
            captureProfile: record.captureProfile
        )
    }

    private func applyRemotePropertyFreshnessUpdateIfNeeded(
        propertyID: UUID,
        activeOrganizationID: UUID,
        remote: PropertyOpenFreshnessRemoteSnapshot
    ) async -> Property? {
        do {
            guard let record = try await fetchRemotePropertyDeltaRecord(
                propertyID: propertyID,
                activeOrganizationID: activeOrganizationID
            ) else {
                print(
                    "[PropertyFreshness] propertyID=\(propertyID.uuidString) " +
                    "action=apply_remote_update result=missing_remote_record"
                )
                return nil
            }
            let result = applySyncDeltaProperties(records: [record], orgID: activeOrganizationID)
            let refreshed = properties.first(where: { $0.id == propertyID }) ??
                allProperties.first(where: { $0.id == propertyID })
            print(
                "[PropertyFreshness] propertyID=\(propertyID.uuidString) " +
                "action=apply_remote_update applied=\(result.applied) skipped=\(result.skipped) " +
                "localUpdatedAt=\(refreshed?.updatedAt.description ?? "nil") " +
                "remoteUpdatedAt=\(remote.updatedAt) remoteRevision=\(remote.revision.map(String.init) ?? "nil")"
            )
            return refreshed
        } catch {
            print(
                "[PropertyFreshness] propertyID=\(propertyID.uuidString) " +
                "action=apply_remote_update result=failed category=\(Self.diagnosticErrorCategory(for: error).rawValue)"
            )
            return nil
        }
    }

    private func fetchRemotePropertyDeltaRecord(
        propertyID: UUID,
        activeOrganizationID: UUID
    ) async throws -> RemotePropertyDeltaRecord? {
        guard let client = supabaseClient else {
            throw RemotePropertyFetchError.missingClient
        }

        let records = try await withThrowingTaskGroup(of: [RemotePropertyDeltaRecord].self) { group in
            group.addTask {
                try await client
                    .from("properties")
                    .select("id, org_id, folder_id, capture_profile, client_name, client_email, client_phone, name, address_line1, city, state, postal_code, baseline_session_id, is_archived, created_at, updated_at, updated_by, revision, deleted_at")
                    .eq("id", value: propertyID.uuidString.lowercased())
                    .eq("org_id", value: activeOrganizationID.uuidString.lowercased())
                    .limit(1)
                    .execute()
                    .value as [RemotePropertyDeltaRecord]
            }

            group.addTask {
                try await Task.sleep(nanoseconds: 3_000_000_000)
                throw RemotePropertyFetchError.timedOut
            }

            guard let firstResult = try await group.next() else {
                throw RemotePropertyFetchError.timedOut
            }
            group.cancelAll()
            return firstResult
        }

        return records.first
    }

    private struct ReferenceFreshnessResult {
        let hasPendingReferenceState: Bool
        let reason: String
    }

    private func reconcileLatestReferenceSessionFreshness(
        propertyID: UUID,
        activeOrganizationID: UUID
    ) async -> ReferenceFreshnessResult? {
        let startedAt = Date()
        if let last = propertyReferenceMetadataRefreshAtByPropertyID[propertyID],
           startedAt.timeIntervalSince(last) < 5.0 {
            print(
                "[ReferenceFreshness] propertyID=\(propertyID.uuidString) " +
                "result=skipped reason=throttled elapsedMs=0"
            )
            return ReferenceFreshnessResult(hasPendingReferenceState: false, reason: "reference_refresh_throttled")
        }
        propertyReferenceMetadataRefreshAtByPropertyID[propertyID] = startedAt
        do {
            guard let latestSession = try await fetchLatestFinalizedReferenceSession(
                propertyID: propertyID,
                activeOrganizationID: activeOrganizationID
            ) else {
                print(
                    "[ReferenceFreshness] propertyID=\(propertyID.uuidString) " +
                    "latestFinalizedSessionID=NONE reason=no_finalized_remote_session"
                )
                return ReferenceFreshnessResult(hasPendingReferenceState: false, reason: "no_finalized_reference_session")
            }

            let sessionApply = applySyncDeltaSessions(records: [latestSession], orgID: activeOrganizationID)
            let remoteShots = try await fetchRemoteShotMetadataRows(
                propertyID: propertyID,
                sessionID: latestSession.id,
                activeOrganizationID: activeOrganizationID
            )
            applyRemoteShotMetadataRows(remoteShots, propertyID: propertyID, sessionID: latestSession.id)

            let localMetadata = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: latestSession.id)
            let expectedShotIDs = Set(remoteShots.map(\.id))
            let localShotIDs = Set((localMetadata?.shots ?? [])
                .filter { $0.sessionID == latestSession.id }
                .map(\.shotID))
            let missingMetadataCount = expectedShotIDs.subtracting(localShotIDs).count

            let missingMediaRequests = (localMetadata?.shots ?? [])
                .filter { shot in
                    guard expectedShotIDs.contains(shot.shotID), shot.sessionID == latestSession.id else { return false }
                    let relative = shot.originalRelativePath.trimmingCharacters(in: .whitespacesAndNewlines)
                    guard !relative.isEmpty else { return false }
                    return localStore.resolveSessionRelativeFileURL(
                        propertyID: propertyID,
                        sessionID: latestSession.id,
                        relativePath: relative
                    ) == nil
                }
                .map {
                    OperationalMediaHydrationRequest(
                        propertyID: propertyID,
                        sessionID: latestSession.id,
                        shotID: $0.shotID,
                        relativePathOverride: $0.originalRelativePath.trimmingCharacters(in: .whitespacesAndNewlines)
                    )
                }

            if !missingMediaRequests.isEmpty {
                _ = await ensureOperationalMediaAvailableForRequests(missingMediaRequests)
            }

            let refreshedMetadata = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: latestSession.id)
            let refreshedMissingMediaCount = (refreshedMetadata?.shots ?? [])
                .filter { shot in
                    guard expectedShotIDs.contains(shot.shotID), shot.sessionID == latestSession.id else { return false }
                    let relative = shot.originalRelativePath.trimmingCharacters(in: .whitespacesAndNewlines)
                    guard !relative.isEmpty else { return true }
                    return localStore.resolveSessionRelativeFileURL(
                        propertyID: propertyID,
                        sessionID: latestSession.id,
                        relativePath: relative
                    ) == nil
                }
                .count

            let guidedReferenceCount = remoteShots.filter { $0.isGuided == true }.count
            let flaggedReferenceCount = remoteShots.filter { $0.isFlagged == true }.count
            let hasPending = missingMetadataCount > 0 || refreshedMissingMediaCount > 0
            let reason: String
            if missingMetadataCount > 0 {
                reason = "reference_metadata_pending"
            } else if refreshedMissingMediaCount > 0 {
                reason = "reference_media_pending"
            } else {
                reason = "reference_metadata_current"
            }
            print(
                "[ReferenceFreshness] propertyID=\(propertyID.uuidString) " +
                "latestFinalizedSessionID=\(latestSession.id.uuidString) " +
                "sessionApply=\(sessionApply.applied)/\(sessionApply.skipped) " +
                "remoteShotCount=\(remoteShots.count) " +
                "localAppliedShotCount=\(localShotIDs.count) " +
                "guidedReferenceCount=\(guidedReferenceCount) " +
                "flaggedReferenceCount=\(flaggedReferenceCount) " +
                "missingMetadataCount=\(missingMetadataCount) " +
                "missingMediaCount=\(refreshedMissingMediaCount) " +
                "reason=\(reason) " +
                "elapsedMs=\(Int(Date().timeIntervalSince(startedAt) * 1000))"
            )
            return ReferenceFreshnessResult(hasPendingReferenceState: hasPending, reason: reason)
        } catch {
            print(
                "[ReferenceFreshness] propertyID=\(propertyID.uuidString) " +
                "result=failed category=\(Self.diagnosticErrorCategory(for: error).rawValue) " +
                "elapsedMs=\(Int(Date().timeIntervalSince(startedAt) * 1000))"
            )
            return ReferenceFreshnessResult(hasPendingReferenceState: true, reason: "reference_freshness_check_failed")
        }
    }

    private func fetchLatestFinalizedReferenceSession(
        propertyID: UUID,
        activeOrganizationID: UUID
    ) async throws -> RemoteSessionDeltaRecord? {
        guard let client = supabaseClient else {
            throw RemotePropertyFetchError.missingClient
        }
        let records = try await client
            .from("sessions")
            .select("id, org_id, property_id, title, status, started_at, completed_at, exported_at, is_sealed, first_delivered_at, re_export_expires_at, capture_profile, updated_at, updated_by, revision, deleted_at")
            .eq("org_id", value: activeOrganizationID.uuidString.lowercased())
            .eq("property_id", value: propertyID.uuidString.lowercased())
            .eq("status", value: "completed")
            .is("deleted_at", value: nil)
            .order("updated_at", ascending: false)
            .limit(5)
            .execute()
            .value as [RemoteSessionDeltaRecord]

        return records
            .filter {
                isFinalRemoteSessionState(
                    status: $0.status,
                    completedAt: $0.completedAt.flatMap(parseSupabaseDateString),
                    exportedAt: $0.exportedAt,
                    isSealed: $0.isSealed,
                    firstDeliveredAt: $0.firstDeliveredAt
                )
            }
            .sorted {
                let lhsDate = $0.firstDeliveredAt ?? $0.exportedAt ?? $0.completedAt.flatMap(parseSupabaseDateString) ?? $0.updatedAt
                let rhsDate = $1.firstDeliveredAt ?? $1.exportedAt ?? $1.completedAt.flatMap(parseSupabaseDateString) ?? $1.updatedAt
                return lhsDate > rhsDate
            }
            .first
    }

    private func fetchRemoteShotMetadataRows(
        propertyID: UUID,
        sessionID: UUID,
        activeOrganizationID: UUID
    ) async throws -> [RemoteShotMetadataRecord] {
        guard let client = supabaseClient else {
            throw RemotePropertyFetchError.missingClient
        }
        return try await client
            .from("shots")
            .select("id, org_id, property_id, session_id, created_at, updated_at, updated_by, revision, deleted_at, building, elevation, detail_type, angle_index, shot_key, logical_shot_identity, capture_kind, first_capture_kind, is_guided, is_flagged, issue_id, issue_status, trade, reason, priority, capture_mode, lens, latitude, longitude, accuracy_meters, image_width, image_height, lifecycle_state, retired_at, retired_reason, retired_by, superseded_by_shot_id, supersedes_shot_id, replacement_reason, hidden_from_reports, hidden_from_gallery, lifecycle_updated_at, storage_bucket, storage_path, checksum_sha256, byte_size, upload_state, upload_attempts, last_upload_error")
            .eq("org_id", value: activeOrganizationID.uuidString.lowercased())
            .eq("property_id", value: propertyID.uuidString.lowercased())
            .eq("session_id", value: sessionID.uuidString.lowercased())
            .is("deleted_at", value: nil)
            .execute()
            .value as [RemoteShotMetadataRecord]
    }

    nonisolated static func evaluatePropertyOpenFreshness(
        localPropertyID: UUID,
        localOrgID: UUID?,
        localUpdatedAt: Date?,
        localIsArchived: Bool,
        activeOrganizationID: UUID?,
        remote: PropertyOpenFreshnessRemoteSnapshot?,
        hasUnsyncedLocalPropertyWork: Bool
    ) -> (status: PropertyOpenFreshnessStatus, reason: String) {
        guard let remote else {
            return (.needsReview, "remote_property_missing")
        }
        guard remote.propertyID == localPropertyID else {
            return (.needsReview, "remote_property_id_mismatch")
        }
        if let activeOrganizationID, remote.orgID != activeOrganizationID {
            return (.needsReview, "remote_org_mismatch")
        }
        if let localOrgID, remote.orgID != localOrgID {
            return (.needsReview, "local_org_mismatch")
        }
        if remote.deletedAt != nil {
            return (.needsReview, "remote_deleted")
        }
        if remote.isArchived != localIsArchived {
            return (.needsReview, "remote_archived_conflict")
        }
        guard let localUpdatedAt else {
            return hasUnsyncedLocalPropertyWork
                ? (.needsReview, "local_updated_at_missing_with_unsynced_work")
                : (.remoteUpdatesAvailable, "local_updated_at_missing")
        }

        if remote.updatedAt.timeIntervalSince(localUpdatedAt) > 0.001 {
            if hasUnsyncedLocalPropertyWork {
                return (.needsReview, "remote_newer_with_unsynced_local_property_work")
            }
            return (.remoteUpdatesAvailable, "remote_updated_at_newer")
        }

        return (.current, "remote_not_newer")
    }

    nonisolated static func hasUnsyncedLocalPropertyWork(
        propertyID: UUID,
        queuedMutations: [LocalStore.QueuedMutation]
    ) -> Bool {
        queuedMutations.contains { item in
            guard item.acknowledgedAt == nil else { return false }
            guard item.status == .pending || item.status == .failed || item.status == .inFlight else { return false }
            let entityType = item.entityType.lowercased()
            let operation = item.operation.lowercased()
            guard entityType == "property" || operation.contains("property") else { return false }
            return item.entityID == propertyID || item.propertyID == propertyID
        }
    }

    nonisolated static func propertyOpenFreshnessStatusForRemoteFailure(_ error: Error) -> PropertyOpenFreshnessStatus {
        diagnosticErrorCategory(for: error) == .network ? .offline : .usingLocalCache
    }

    nonisolated static func propertyOpenFreshnessDisplayLabel(for status: PropertyOpenFreshnessStatus) -> String {
        switch status {
        case .checkingCloudStatus:
            return "Checking cloud status"
        case .current:
            return "Current"
        case .usingLocalCache:
            return "Using local cache"
        case .remoteUpdatesAvailable:
            return "Remote updates available"
        case .needsReview:
            return "Needs review"
        case .offline:
            return "Offline"
        case .unknown:
            return "Unknown"
        }
    }

    nonisolated static func propertyOpenFreshnessSymbolName(for status: PropertyOpenFreshnessStatus) -> String {
        switch status {
        case .checkingCloudStatus:
            return "icloud"
        case .current:
            return "checkmark.icloud"
        case .usingLocalCache:
            return "internaldrive"
        case .remoteUpdatesAvailable:
            return "arrow.down.icloud"
        case .needsReview:
            return "exclamationmark.icloud"
        case .offline:
            return "wifi.slash"
        case .unknown:
            return "questionmark.circle"
        }
    }

    @discardableResult
    func setPropertyCaptureProfileDefault(propertyID: UUID, profile: CaptureProfile) -> Bool {
        guard canAccessProperty(propertyID) || selectedPropertyID == propertyID else { return false }
        guard let source = properties.first(where: { $0.id == propertyID }) ??
                allProperties.first(where: { $0.id == propertyID }) else { return false }
        var updated = source
        let resolvedOrgID = resolveCaptureProfileOrgID(property: updated, propertyID: propertyID)
        let selectedContext = selectedPropertyID == propertyID
        let currentSessionContext = currentSession?.propertyID == propertyID
        print(
            "[CaptureProfileSync] event=property_local_update_prepare " +
            "propertyID=\(propertyID.uuidString) " +
            "oldOrgID=\(updated.orgId?.uuidString ?? "nil") " +
            "resolvedOrgID=\(resolvedOrgID?.uuidString ?? "nil") " +
            "activeOrganizationID=\(activeOrganizationID?.uuidString ?? "nil") " +
            "selectedPropertyMatch=\(selectedContext) " +
            "currentSessionPropertyMatch=\(currentSessionContext) " +
            "oldCaptureProfile=\(updated.captureProfile?.rawValue ?? "nil") " +
            "newCaptureProfile=\(profile.rawValue)"
        )
        if let resolvedOrgID {
            do {
                try ensureLocalOrganizationExists(for: resolvedOrgID)
            } catch {
                print(
                    "[CaptureProfileSync] event=property_local_org_ensure_failed " +
                    "propertyID=\(propertyID.uuidString) " +
                    "resolvedOrgID=\(resolvedOrgID.uuidString) " +
                    "error=\(error.localizedDescription)"
                )
            }
            ensureCaptureProfilePropertyVisibility(propertyID: propertyID, orgID: resolvedOrgID)
        }
        if updated.orgId != resolvedOrgID {
            updated.orgId = resolvedOrgID
        }
        updated.captureProfile = profile

        do {
            let persisted = try localStore.updateProperty(updated)
            if let rawIndex = allProperties.firstIndex(where: { $0.id == propertyID }) {
                allProperties[rawIndex] = persisted
            }
            let caches = makeHubCaches(for: allProperties)
            applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
            let remainsVisible = properties.contains(where: { $0.id == propertyID })
            let passesActiveOrgFilter = activeOrganizationID.map { persisted.orgId == $0 } ?? !requiresAuthentication
            print(
                "[CaptureProfileSync] event=property_local_update " +
                "propertyID=\(propertyID.uuidString) " +
                "orgID=\(persisted.orgId?.uuidString ?? "nil") " +
                "activeOrganizationID=\(activeOrganizationID?.uuidString ?? "nil") " +
                "captureProfile=\(profile.rawValue) " +
                "remainsVisible=\(remainsVisible) " +
                "passesActiveOrgFilter=\(passesActiveOrgFilter) " +
                "deletedAt=\(persisted.deletedAt.map { supabaseTimestampString($0) } ?? "nil") " +
                "isArchived=\(persisted.isArchived)"
            )
            scheduleCaptureProfilePropertyRemoteWrite(property: persisted, profile: profile)
            return true
        } catch {
            print(
                "[CaptureProfileSync] event=property_local_update_failed " +
                "propertyID=\(propertyID.uuidString) " +
                "captureProfile=\(profile.rawValue) " +
                "error=\(error.localizedDescription)"
            )
            return false
        }
    }

    @discardableResult
    func setSessionCaptureProfileSnapshot(
        propertyID: UUID,
        sessionID: UUID,
        profile: CaptureProfile
    ) -> Bool {
        guard canAccessProperty(propertyID) else { return false }

        do {
            var metadata = try localStore.loadSessionMetadata(propertyID: propertyID, sessionID: sessionID)
            let previousMetadataProfile = metadata.captureProfile
            metadata.captureProfile = profile.rawValue
            try localStore.saveSessionMetadataAtomically(
                propertyID: propertyID,
                sessionID: sessionID,
                metadata: metadata
            )

            let localSessions = (try? localStore.fetchSessionsForCacheBuild(propertyID: propertyID)) ?? []
            let baseSession = localSessions.first(where: { $0.id == sessionID }) ??
                (currentSession?.id == sessionID ? currentSession : nil)
            if var session = baseSession {
                session.captureProfile = profile
                let persisted = (try? localStore.upsertSession(session)) ?? session
                if currentSession?.id == sessionID {
                    currentSession = persisted
                }
                reloadSessionCache(for: propertyID)
                scheduleCaptureProfileSessionRemoteWrite(
                    propertyID: propertyID,
                    session: persisted,
                    profile: profile
                )
            }

            if previousMetadataProfile != profile.rawValue {
                print(
                    "[CaptureProfileSync] event=session_local_update " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(sessionID.uuidString) " +
                    "activeOrganizationID=\(activeOrganizationID?.uuidString ?? "nil") " +
                    "captureProfile=\(profile.rawValue)"
                )
            }
            return true
        } catch {
            print(
                "[CaptureProfileSync] event=session_local_update_failed " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID.uuidString) " +
                "captureProfile=\(profile.rawValue) " +
                "error=\(error.localizedDescription)"
            )
            return false
        }
    }

    @discardableResult
    func backfillCaptureProfilesIfMissing(
        propertyID: UUID,
        sessionID: UUID?,
        propertyProfile: CaptureProfile?,
        sessionProfile: CaptureProfile?
    ) async -> Bool {
        if propertyProfile == nil && sessionProfile == nil {
            logCaptureProfileBackfillOnce(
                key: "unknown|\(propertyID.uuidString)|\(sessionID?.uuidString ?? "nil")",
                message:
                    "[CaptureProfileSync] event=backfill_skipped reason=local_value_unknown " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(sessionID?.uuidString ?? "nil")"
            )
            return false
        }
        guard canAccessProperty(propertyID) || selectedPropertyID == propertyID else {
            return false
        }
        guard let property = allProperties.first(where: { $0.id == propertyID }) ??
                properties.first(where: { $0.id == propertyID }),
              let orgID = resolveCaptureProfileOrgID(property: property, propertyID: propertyID) else {
            return false
        }

        let canAttemptRemote = captureProfileBackfillFetchOverride != nil ||
            remoteMutationPathAvailable(for: orgID)
        guard canAttemptRemote else { return false }

        do {
            let remoteState: CaptureProfileBackfillRemoteState
            if let captureProfileBackfillFetchOverride {
                remoteState = try await captureProfileBackfillFetchOverride(orgID, propertyID, sessionID)
            } else {
                remoteState = try await fetchCaptureProfileBackfillRemoteState(
                    orgID: orgID,
                    propertyID: propertyID,
                    sessionID: sessionID
                )
            }

            let propertyProfileToWrite: CaptureProfile?
            if let propertyProfile {
                if !remoteState.propertyRowExists {
                    logCaptureProfileBackfillOnce(
                        key: "property-missing|\(propertyID.uuidString)",
                        message:
                            "[CaptureProfileSync] event=backfill_property_profile_skipped reason=remote_row_missing " +
                            "propertyID=\(propertyID.uuidString) " +
                            "orgID=\(orgID.uuidString) " +
                            "captureProfile=\(propertyProfile.rawValue)"
                    )
                    propertyProfileToWrite = nil
                } else if let remoteProfile = remoteState.propertyCaptureProfile {
                    logCaptureProfileBackfillOnce(
                        key: "property-nonnull|\(propertyID.uuidString)|\(remoteProfile.rawValue)",
                        message:
                            "[CaptureProfileSync] event=backfill_property_profile_skipped reason=remote_already_non_null " +
                            "propertyID=\(propertyID.uuidString) " +
                            "orgID=\(orgID.uuidString) " +
                            "remoteCaptureProfile=\(remoteProfile.rawValue) " +
                            "localCaptureProfile=\(propertyProfile.rawValue)"
                    )
                    propertyProfileToWrite = nil
                } else {
                    propertyProfileToWrite = propertyProfile
                }
            } else {
                logCaptureProfileBackfillOnce(
                    key: "property-unknown|\(propertyID.uuidString)",
                    message:
                        "[CaptureProfileSync] event=backfill_property_profile_skipped reason=local_value_unknown " +
                        "propertyID=\(propertyID.uuidString) " +
                        "orgID=\(orgID.uuidString)"
                )
                propertyProfileToWrite = nil
            }

            let sessionProfileToWrite: CaptureProfile?
            var sessionEnsureProfile: CaptureProfile?
            if let sessionID {
                if let sessionProfile {
                    if !remoteState.sessionRowExists {
                        sessionEnsureProfile = sessionProfile
                        sessionProfileToWrite = sessionProfile
                    } else if let remoteProfile = remoteState.sessionCaptureProfile {
                        logCaptureProfileBackfillOnce(
                            key: "session-nonnull|\(sessionID.uuidString)|\(remoteProfile.rawValue)",
                            message:
                                "[CaptureProfileSync] event=backfill_session_profile_skipped reason=remote_already_non_null " +
                                "propertyID=\(propertyID.uuidString) " +
                                "sessionID=\(sessionID.uuidString) " +
                                "orgID=\(orgID.uuidString) " +
                                "remoteCaptureProfile=\(remoteProfile.rawValue) " +
                                "localCaptureProfile=\(sessionProfile.rawValue)"
                        )
                        sessionProfileToWrite = nil
                    } else {
                        sessionProfileToWrite = sessionProfile
                    }
                } else {
                    logCaptureProfileBackfillOnce(
                        key: "session-unknown|\(sessionID.uuidString)",
                        message:
                            "[CaptureProfileSync] event=backfill_session_profile_skipped reason=local_value_unknown " +
                            "propertyID=\(propertyID.uuidString) " +
                            "sessionID=\(sessionID.uuidString) " +
                            "orgID=\(orgID.uuidString)"
                    )
                    sessionProfileToWrite = nil
                }
            } else {
                sessionProfileToWrite = nil
            }

            guard propertyProfileToWrite != nil || sessionProfileToWrite != nil else {
                return false
            }

            if let propertyProfileToWrite {
                print(
                    "[CaptureProfileSync] event=backfill_property_profile_attempt " +
                    "propertyID=\(propertyID.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(propertyProfileToWrite.rawValue)"
                )
            }
            if let sessionID, let sessionProfileToWrite {
                print(
                    "[CaptureProfileSync] event=backfill_session_profile_attempt " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(sessionID.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(sessionProfileToWrite.rawValue)"
                )
            }

            if let sessionID, let sessionEnsureProfile {
                do {
                    print(
                        "[CaptureProfileSync] event=backfill_session_profile_ensure_attempt " +
                        "propertyID=\(propertyID.uuidString) " +
                        "sessionID=\(sessionID.uuidString) " +
                        "orgID=\(orgID.uuidString) " +
                        "captureProfile=\(sessionEnsureProfile.rawValue)"
                    )
                    if let captureProfileBackfillEnsureOverride {
                        try await captureProfileBackfillEnsureOverride(
                            orgID,
                            propertyID,
                            sessionID,
                            sessionEnsureProfile
                        )
                    } else {
                        let metadata = try localStore.loadSessionMetadata(
                            propertyID: propertyID,
                            sessionID: sessionID
                        )
                        let localSessions = (try? localStore.fetchSessionsForCacheBuild(propertyID: propertyID)) ?? []
                        let baseSession = localSessions.first(where: { $0.id == sessionID }) ??
                            (currentSession?.id == sessionID ? currentSession : nil)
                        guard let baseSession else {
                            throw NSError(domain: "ScoutCapture.CaptureProfileSync", code: 6, userInfo: [
                                NSLocalizedDescriptionKey: "Missing local session for capture_profile backfill ensure."
                            ])
                        }
                        let ensureMetadata = sessionEnsureMetadataForCaptureProfileSync(
                            metadata: metadata,
                            session: baseSession,
                            profile: sessionEnsureProfile
                        )
                        try await ensureSupabaseSessionPrerequisites(
                            propertyID: propertyID,
                            sessionID: sessionID,
                            metadata: ensureMetadata,
                            orgID: orgID
                        )
                    }
                    print(
                        "[CaptureProfileSync] event=backfill_session_profile_ensure_success " +
                        "propertyID=\(propertyID.uuidString) " +
                        "sessionID=\(sessionID.uuidString) " +
                        "orgID=\(orgID.uuidString) " +
                        "captureProfile=\(sessionEnsureProfile.rawValue)"
                    )
                } catch {
                    print(
                        "[CaptureProfileSync] event=backfill_session_profile_failed " +
                        "propertyID=\(propertyID.uuidString) " +
                        "sessionID=\(sessionID.uuidString) " +
                        "orgID=\(orgID.uuidString) " +
                        "captureProfile=\(sessionEnsureProfile.rawValue) " +
                        "error=\(error.localizedDescription)"
                    )
                    throw error
                }
            }

            if let captureProfileBackfillWriteOverride {
                try await captureProfileBackfillWriteOverride(
                    orgID,
                    propertyID,
                    sessionID,
                    propertyProfileToWrite,
                    sessionProfileToWrite
                )
            } else {
                if let propertyProfileToWrite {
                    do {
                        _ = try await backfillPropertyCaptureProfileInSupabase(
                            propertyID: propertyID,
                            orgID: orgID,
                            profile: propertyProfileToWrite
                        )
                    } catch {
                        print(
                            "[CaptureProfileSync] event=backfill_property_profile_failed " +
                            "propertyID=\(propertyID.uuidString) " +
                            "orgID=\(orgID.uuidString) " +
                            "captureProfile=\(propertyProfileToWrite.rawValue) " +
                            "error=\(error.localizedDescription)"
                        )
                        throw error
                    }
                }
                if let sessionID, let sessionProfileToWrite {
                    do {
                        _ = try await updateSessionCaptureProfileInSupabase(
                            sessionID: sessionID,
                            propertyID: propertyID,
                            orgID: orgID,
                            profile: sessionProfileToWrite
                        )
                    } catch {
                        print(
                            "[CaptureProfileSync] event=backfill_session_profile_failed " +
                            "propertyID=\(propertyID.uuidString) " +
                            "sessionID=\(sessionID.uuidString) " +
                            "orgID=\(orgID.uuidString) " +
                            "captureProfile=\(sessionProfileToWrite.rawValue) " +
                            "error=\(error.localizedDescription)"
                        )
                        throw error
                    }
                }
            }

            if let propertyProfileToWrite {
                logCaptureProfileBackfillOnce(
                    key: "property-success|\(propertyID.uuidString)|\(propertyProfileToWrite.rawValue)",
                    message:
                    "[CaptureProfileSync] event=backfill_property_profile_success " +
                    "propertyID=\(propertyID.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(propertyProfileToWrite.rawValue) " +
                    "verifiedCaptureProfile=\(propertyProfileToWrite.rawValue) " +
                    "affectedRows=1"
                )
            }
            if let sessionID, let sessionProfileToWrite {
                logCaptureProfileBackfillOnce(
                    key: "session-success|\(sessionID.uuidString)|\(sessionProfileToWrite.rawValue)",
                    message:
                    "[CaptureProfileSync] event=backfill_session_profile_success " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(sessionID.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(sessionProfileToWrite.rawValue) " +
                    "verifiedCaptureProfile=\(sessionProfileToWrite.rawValue) " +
                    "affectedRows=1"
                )
            }
            return true
        } catch {
            print(
                "[CaptureProfileSync] event=backfill_failed " +
                "propertyID=\(propertyID.uuidString) " +
                "sessionID=\(sessionID?.uuidString ?? "nil") " +
                "orgID=\(orgID.uuidString) " +
                "error=\(error.localizedDescription)"
            )
            return false
        }
    }

    func runCaptureProfileMaintenanceBackfill() async -> CaptureProfileMaintenanceBackfillResult {
        var result = CaptureProfileMaintenanceBackfillResult()
        defer { recordCaptureProfileMaintenanceDiagnostics(result) }
        guard canRecoverDeletedPropertiesInActiveOrganization,
              let activeOrganizationID else {
            print(
                "[CaptureProfileSync] event=maintenance_backfill_scan " +
                "reason=active_org_missing_or_not_authorized " +
                "localPropertiesFound=0 propertiesScanned=0 sessionsScanned=0 " +
                "remotePropertiesChecked=0 remoteSessionsChecked=0"
            )
            print("[CaptureProfileSync] event=maintenance_backfill_complete reason=not_authorized")
            result.failed += 1
            return result
        }
        let canAttemptRemote = captureProfileBackfillFetchOverride != nil ||
            remoteMutationPathAvailable(for: activeOrganizationID)
        guard canAttemptRemote else {
            print(
                "[CaptureProfileSync] event=maintenance_backfill_scan " +
                "reason=remote_unavailable " +
                "orgID=\(activeOrganizationID.uuidString) " +
                "localPropertiesFound=0 propertiesScanned=0 sessionsScanned=0 " +
                "remotePropertiesChecked=0 remoteSessionsChecked=0"
            )
            print(
                "[CaptureProfileSync] event=maintenance_backfill_complete reason=remote_unavailable " +
                "orgID=\(activeOrganizationID.uuidString)"
            )
            result.failed += 1
            return result
        }

        print(
            "[CaptureProfileSync] event=maintenance_backfill_start " +
            "orgID=\(activeOrganizationID.uuidString)"
        )

        let remoteActivePropertyIDs: Set<UUID>
        do {
            remoteActivePropertyIDs = try await fetchActiveRemotePropertyIDsForCaptureProfileMaintenance(
                orgID: activeOrganizationID
            )
            result.remoteActivePropertyCount = remoteActivePropertyIDs.count
        } catch {
            recordDiagnosticsError(error)
            print(
                "[CaptureProfileSync] event=maintenance_backfill_scan " +
                "reason=remote_active_properties_fetch_failed " +
                "orgID=\(activeOrganizationID.uuidString) " +
                "localPropertiesFound=0 propertiesScanned=0 sessionsScanned=0 " +
                "remotePropertiesChecked=0 remoteSessionsChecked=0 " +
                "remoteActivePropertyCount=0 " +
                "error=\(error.localizedDescription)"
            )
            result.failed += 1
            return result
        }

        let localProperties: [Property]
        do {
            localProperties = try localStore.fetchProperties()
            result.localPropertiesFound = localProperties.count
        } catch {
            recordDiagnosticsError(error)
            print(
                "[CaptureProfileSync] event=maintenance_backfill_complete " +
                "orgID=\(activeOrganizationID.uuidString) " +
                "localPropertiesFound=0 propertiesScanned=0 sessionsScanned=0 " +
                "remotePropertiesChecked=0 remoteSessionsChecked=0 " +
                "remoteActivePropertyCount=\(result.remoteActivePropertyCount) " +
                "propertyProfilesFilled=0 sessionProfilesFilled=0 sessionsEnsured=0 skipped=0 failed=1 " +
                "error=\(error.localizedDescription)"
            )
            result.failed += 1
            return result
        }

        let candidateProperties = localProperties.compactMap { property -> Property? in
            if property.deletedAt != nil {
                result.propertiesFilteredDeleted += 1
                return nil
            }
            if property.isArchived {
                result.propertiesFilteredArchived += 1
                return nil
            }
            let resolvedOrgID = maintenanceBackfillResolvedOrgID(
                for: property,
                activeOrganizationID: activeOrganizationID,
                remoteActivePropertyIDs: remoteActivePropertyIDs
            )
            guard resolvedOrgID == activeOrganizationID else {
                result.propertiesFilteredOrgMismatch += 1
                result.trueOrgMismatchCount += 1
                return nil
            }
            if property.orgId != activeOrganizationID {
                result.staleOrgReconciledCount += 1
            }
            guard canAccessProperty(property.id) ||
                    isCaptureProfileActivePropertyContext(propertyID: property.id) ||
                    remoteActivePropertyIDs.contains(property.id) else {
                result.propertiesFilteredInaccessible += 1
                return nil
            }
            return property
        }

        for property in candidateProperties {
            result.propertiesScanned += 1
            let propertyProfile = knownLocalPropertyCaptureProfile(for: property)
            if let propertyProfile {
                do {
                    result.remotePropertiesChecked += 1
                    let remoteState = try await fetchCaptureProfileBackfillStateForMaintenance(
                        orgID: activeOrganizationID,
                        propertyID: property.id,
                        sessionID: nil
                    )
                    if remoteState.propertyRowExists,
                       remoteState.propertyCaptureProfile == nil {
                        do {
                            print(
                                "[CaptureProfileSync] event=backfill_property_profile_attempt " +
                                "propertyID=\(property.id.uuidString) " +
                                "orgID=\(activeOrganizationID.uuidString) " +
                                "captureProfile=\(propertyProfile.rawValue)"
                            )
                            if let captureProfileBackfillWriteOverride {
                                try await captureProfileBackfillWriteOverride(
                                    activeOrganizationID,
                                    property.id,
                                    nil,
                                    propertyProfile,
                                    nil
                                )
                            } else {
                                _ = try await backfillPropertyCaptureProfileInSupabase(
                                    propertyID: property.id,
                                    orgID: activeOrganizationID,
                                    profile: propertyProfile
                                )
                            }
                            result.propertyProfilesFilled += 1
                            recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: true)
                            logCaptureProfileBackfillOnce(
                                key: "maintenance-property-success|\(property.id.uuidString)|\(propertyProfile.rawValue)",
                                message:
                                "[CaptureProfileSync] event=backfill_property_profile_success " +
                                "propertyID=\(property.id.uuidString) " +
                                "orgID=\(activeOrganizationID.uuidString) " +
                                "captureProfile=\(propertyProfile.rawValue) " +
                                "verifiedCaptureProfile=\(propertyProfile.rawValue) " +
                                "affectedRows=1"
                            )
                        } catch {
                            result.failed += 1
                            recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: false, error: error)
                            print(
                                "[CaptureProfileSync] event=maintenance_backfill_property_failed " +
                                "propertyID=\(property.id.uuidString) " +
                                "orgID=\(activeOrganizationID.uuidString) " +
                                "captureProfile=\(propertyProfile.rawValue) " +
                                "error=\(error.localizedDescription)"
                            )
                        }
                    } else {
                        result.skipped += 1
                    }
                } catch {
                    result.failed += 1
                    recordDiagnosticsError(error)
                    print(
                        "[CaptureProfileSync] event=maintenance_backfill_property_failed " +
                        "propertyID=\(property.id.uuidString) " +
                        "orgID=\(activeOrganizationID.uuidString) " +
                        "error=\(error.localizedDescription)"
                    )
                }
            } else {
                result.skipped += 1
            }

            let localSessions = (try? localStore.fetchSessionsForCacheBuild(propertyID: property.id)) ?? []
            for session in localSessions where session.deletedAt == nil {
                result.sessionsScanned += 1
                let sessionProfileState = localSessionCaptureProfileScanState(
                    propertyID: property.id,
                    session: session
                )
                let sessionProfile: CaptureProfile
                switch sessionProfileState {
                case .known(let profile):
                    sessionProfile = profile
                case .missingMetadata:
                    result.sessionMetadataMissing += 1
                    result.skipped += 1
                    continue
                case .unknownProfile:
                    result.sessionProfileUnknown += 1
                    result.skipped += 1
                    continue
                }

                do {
                    result.remoteSessionsChecked += 1
                    let remoteState = try await fetchCaptureProfileBackfillStateForMaintenance(
                        orgID: activeOrganizationID,
                        propertyID: property.id,
                        sessionID: session.id
                    )
                    if remoteState.sessionRowExists,
                       remoteState.sessionCaptureProfile != nil {
                        result.skipped += 1
                        continue
                    }

                    do {
                        if !remoteState.sessionRowExists {
                            print(
                                "[CaptureProfileSync] event=backfill_session_profile_ensure_attempt " +
                                "propertyID=\(property.id.uuidString) " +
                                "sessionID=\(session.id.uuidString) " +
                                "orgID=\(activeOrganizationID.uuidString) " +
                                "captureProfile=\(sessionProfile.rawValue)"
                            )
                            if let captureProfileBackfillEnsureOverride {
                                try await captureProfileBackfillEnsureOverride(
                                    activeOrganizationID,
                                    property.id,
                                    session.id,
                                    sessionProfile
                                )
                            } else {
                                let metadata = try localStore.loadSessionMetadata(
                                    propertyID: property.id,
                                    sessionID: session.id
                                )
                                let ensureMetadata = sessionEnsureMetadataForCaptureProfileSync(
                                    metadata: metadata,
                                    session: session,
                                    profile: sessionProfile
                                )
                                try await ensureSupabaseSessionPrerequisites(
                                    propertyID: property.id,
                                    sessionID: session.id,
                                    metadata: ensureMetadata,
                                    orgID: activeOrganizationID
                                )
                            }
                            print(
                                "[CaptureProfileSync] event=backfill_session_profile_ensure_success " +
                                "propertyID=\(property.id.uuidString) " +
                                "sessionID=\(session.id.uuidString) " +
                                "orgID=\(activeOrganizationID.uuidString) " +
                                "captureProfile=\(sessionProfile.rawValue)"
                            )
                        }
                        print(
                            "[CaptureProfileSync] event=backfill_session_profile_attempt " +
                            "propertyID=\(property.id.uuidString) " +
                            "sessionID=\(session.id.uuidString) " +
                            "orgID=\(activeOrganizationID.uuidString) " +
                            "captureProfile=\(sessionProfile.rawValue)"
                        )
                        if let captureProfileBackfillWriteOverride {
                            try await captureProfileBackfillWriteOverride(
                                activeOrganizationID,
                                property.id,
                                session.id,
                                nil,
                                sessionProfile
                            )
                        } else {
                            _ = try await updateSessionCaptureProfileInSupabase(
                                sessionID: session.id,
                                propertyID: property.id,
                                orgID: activeOrganizationID,
                                profile: sessionProfile
                            )
                        }
                        result.sessionProfilesFilled += 1
                        recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: true)
                        if !remoteState.sessionRowExists {
                            result.sessionsEnsured += 1
                        }
                        logCaptureProfileBackfillOnce(
                            key: "maintenance-session-success|\(session.id.uuidString)|\(sessionProfile.rawValue)",
                            message:
                            "[CaptureProfileSync] event=backfill_session_profile_success " +
                            "propertyID=\(property.id.uuidString) " +
                            "sessionID=\(session.id.uuidString) " +
                            "orgID=\(activeOrganizationID.uuidString) " +
                            "captureProfile=\(sessionProfile.rawValue) " +
                            "verifiedCaptureProfile=\(sessionProfile.rawValue) " +
                            "affectedRows=1"
                        )
                    } catch {
                        result.failed += 1
                        recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: false, error: error)
                        print(
                            "[CaptureProfileSync] event=maintenance_backfill_session_failed " +
                            "propertyID=\(property.id.uuidString) " +
                            "sessionID=\(session.id.uuidString) " +
                            "orgID=\(activeOrganizationID.uuidString) " +
                            "captureProfile=\(sessionProfile.rawValue) " +
                            "error=\(error.localizedDescription)"
                        )
                    }
                } catch {
                    result.failed += 1
                    recordDiagnosticsError(error)
                    print(
                        "[CaptureProfileSync] event=maintenance_backfill_session_failed " +
                        "propertyID=\(property.id.uuidString) " +
                        "sessionID=\(session.id.uuidString) " +
                        "orgID=\(activeOrganizationID.uuidString) " +
                        "error=\(error.localizedDescription)"
                    )
                }
            }
        }

        let scanReason: String
        if result.localPropertiesFound == 0 {
            scanReason = "local_property_list_empty"
        } else if result.propertiesScanned == 0 {
            scanReason = "all_properties_filtered"
        } else if result.sessionsScanned == 0 {
            scanReason = "no_local_sessions_found"
        } else {
            scanReason = "complete"
        }
        print(
            "[CaptureProfileSync] event=maintenance_backfill_scan " +
            "reason=\(scanReason) " +
            "orgID=\(activeOrganizationID.uuidString) " +
            "localPropertiesFound=\(result.localPropertiesFound) " +
            "propertiesScanned=\(result.propertiesScanned) " +
            "sessionsScanned=\(result.sessionsScanned) " +
            "remotePropertiesChecked=\(result.remotePropertiesChecked) " +
            "remoteSessionsChecked=\(result.remoteSessionsChecked) " +
            "remoteActivePropertyCount=\(result.remoteActivePropertyCount) " +
            "staleOrgReconciledCount=\(result.staleOrgReconciledCount) " +
            "trueOrgMismatchCount=\(result.trueOrgMismatchCount) " +
            "filteredDeleted=\(result.propertiesFilteredDeleted) " +
            "filteredArchived=\(result.propertiesFilteredArchived) " +
            "filteredOrgMismatch=\(result.propertiesFilteredOrgMismatch) " +
            "filteredInaccessible=\(result.propertiesFilteredInaccessible) " +
            "sessionMetadataMissing=\(result.sessionMetadataMissing) " +
            "sessionProfileUnknown=\(result.sessionProfileUnknown)"
        )
        print(
            "[CaptureProfileSync] event=maintenance_backfill_complete " +
            "orgID=\(activeOrganizationID.uuidString) " +
            "localPropertiesFound=\(result.localPropertiesFound) " +
            "propertiesScanned=\(result.propertiesScanned) " +
            "sessionsScanned=\(result.sessionsScanned) " +
            "remotePropertiesChecked=\(result.remotePropertiesChecked) " +
            "remoteSessionsChecked=\(result.remoteSessionsChecked) " +
            "remoteActivePropertyCount=\(result.remoteActivePropertyCount) " +
            "staleOrgReconciledCount=\(result.staleOrgReconciledCount) " +
            "trueOrgMismatchCount=\(result.trueOrgMismatchCount) " +
            "propertyProfilesFilled=\(result.propertyProfilesFilled) " +
            "sessionProfilesFilled=\(result.sessionProfilesFilled) " +
            "sessionsEnsured=\(result.sessionsEnsured) " +
            "skipped=\(result.skipped) " +
            "failed=\(result.failed)"
        )
        return result
    }

    private func knownLocalPropertyCaptureProfile(for property: Property) -> CaptureProfile? {
        if let captureProfile = property.captureProfile {
            return captureProfile
        }
        return CaptureProfile(
            storedValue: userDefaults.string(
                forKey: "scout.captureProfile.property.\(property.id.uuidString)"
            )
        )
    }

    private func knownLocalSessionCaptureProfile(propertyID: UUID, session: Session) -> CaptureProfile? {
        if let captureProfile = session.captureProfile {
            return captureProfile
        }
        guard let metadata = try? localStore.loadSessionMetadata(
            propertyID: propertyID,
            sessionID: session.id
        ) else {
            return nil
        }
        return CaptureProfile(storedValue: metadata.captureProfile)
    }

    private func localSessionCaptureProfileScanState(
        propertyID: UUID,
        session: Session
    ) -> CaptureProfileSessionProfileScanState {
        if let captureProfile = session.captureProfile {
            return .known(captureProfile)
        }
        guard let metadata = try? localStore.loadSessionMetadata(
            propertyID: propertyID,
            sessionID: session.id
        ) else {
            return .missingMetadata
        }
        if let profile = CaptureProfile(storedValue: metadata.captureProfile) {
            return .known(profile)
        }
        return .unknownProfile
    }

    private func maintenanceBackfillResolvedOrgID(
        for property: Property,
        activeOrganizationID: UUID,
        remoteActivePropertyIDs: Set<UUID>
    ) -> UUID? {
        if property.orgId == activeOrganizationID {
            return activeOrganizationID
        }
        if remoteActivePropertyIDs.contains(property.id) {
            print(
                "[CaptureProfileSync] event=maintenance_backfill_remote_org_reconcile " +
                "propertyID=\(property.id.uuidString) " +
                "staleOrgID=\(property.orgId?.uuidString ?? "nil") " +
                "resolvedOrgID=\(activeOrganizationID.uuidString) " +
                "activeOrganizationID=\(activeOrganizationID.uuidString)"
            )
            return activeOrganizationID
        }
        if isCaptureProfileActivePropertyContext(propertyID: property.id) {
            print(
                "[CaptureProfileSync] event=maintenance_backfill_stale_org_override " +
                "propertyID=\(property.id.uuidString) " +
                "staleOrgID=\(property.orgId?.uuidString ?? "nil") " +
                "resolvedOrgID=\(activeOrganizationID.uuidString) " +
                "activeOrganizationID=\(activeOrganizationID.uuidString)"
            )
            return activeOrganizationID
        }
        return property.orgId
    }

    private func fetchActiveRemotePropertyIDsForCaptureProfileMaintenance(orgID: UUID) async throws -> Set<UUID> {
        if let captureProfileRemotePropertyIDsFetchOverride {
            return try await captureProfileRemotePropertyIDsFetchOverride(orgID)
        }
        guard let client = supabaseClient else {
            throw NSError(domain: "ScoutCapture.CaptureProfileSync", code: 7, userInfo: [
                NSLocalizedDescriptionKey: "Missing Supabase client for capture_profile maintenance remote property scan."
            ])
        }
        let rows = try await client
            .from("properties")
            .select("id")
            .eq("org_id", value: orgID.uuidString.lowercased())
            .execute()
            .value as [SessionIDOnlyRecord]
        return Set(rows.map(\.id))
    }

    private func fetchCaptureProfileBackfillStateForMaintenance(
        orgID: UUID,
        propertyID: UUID,
        sessionID: UUID?
    ) async throws -> CaptureProfileBackfillRemoteState {
        if let captureProfileBackfillFetchOverride {
            return try await captureProfileBackfillFetchOverride(orgID, propertyID, sessionID)
        }
        return try await fetchCaptureProfileBackfillRemoteState(
            orgID: orgID,
            propertyID: propertyID,
            sessionID: sessionID
        )
    }

    private func logCaptureProfileBackfillOnce(key: String, message: String) {
        guard captureProfileBackfillLoggedKeys.insert(key).inserted else { return }
        print(message)
    }

    private func fetchCaptureProfileBackfillRemoteState(
        orgID: UUID,
        propertyID: UUID,
        sessionID: UUID?
    ) async throws -> CaptureProfileBackfillRemoteState {
        guard let client = supabaseClient else {
            throw NSError(domain: "ScoutCapture.CaptureProfileSync", code: 5, userInfo: [
                NSLocalizedDescriptionKey: "Missing Supabase client for capture_profile backfill."
            ])
        }

        let propertyRows = try await client
            .from("properties")
            .select("id, org_id, capture_profile")
            .eq("id", value: propertyID.uuidString.lowercased())
            .eq("org_id", value: orgID.uuidString.lowercased())
            .limit(1)
            .execute()
            .value as [SupabaseCaptureProfileUpdateResult]

        var sessionRows: [SupabaseCaptureProfileUpdateResult] = []
        if let sessionID {
            sessionRows = try await client
                .from("sessions")
                .select("id, org_id, property_id, capture_profile")
                .eq("id", value: sessionID.uuidString.lowercased())
                .eq("property_id", value: propertyID.uuidString.lowercased())
                .eq("org_id", value: orgID.uuidString.lowercased())
                .limit(1)
                .execute()
                .value as [SupabaseCaptureProfileUpdateResult]
        }

        return CaptureProfileBackfillRemoteState(
            propertyRowExists: !propertyRows.isEmpty,
            propertyCaptureProfile: CaptureProfile(storedValue: propertyRows.first?.captureProfile),
            sessionRowExists: !sessionRows.isEmpty,
            sessionCaptureProfile: CaptureProfile(storedValue: sessionRows.first?.captureProfile)
        )
    }

    private func isCaptureProfileActivePropertyContext(propertyID: UUID) -> Bool {
        if currentSession?.propertyID == propertyID {
            return true
        }
        if selectedPropertyID == propertyID {
            return true
        }
        return false
    }

    private func ensureCaptureProfilePropertyVisibility(propertyID: UUID, orgID: UUID) {
        guard isCaptureProfileActivePropertyContext(propertyID: propertyID),
              isPropertyScopedOrganization(orgID) else { return }
        var authorizedIDs = authorizedPropertyIDsByOrganization[orgID] ?? []
        guard authorizedIDs.insert(propertyID).inserted else { return }
        authorizedPropertyIDsByOrganization[orgID] = authorizedIDs
    }

    private func resolveCaptureProfileOrgID(property: Property, propertyID: UUID) -> UUID? {
        if isCaptureProfileActivePropertyContext(propertyID: propertyID),
           let activeOrganizationID {
            if property.orgId != activeOrganizationID {
                print(
                    "[CaptureProfileSync] event=stale_org_override " +
                    "propertyID=\(propertyID.uuidString) " +
                    "staleOrgID=\(property.orgId?.uuidString ?? "nil") " +
                    "resolvedOrgID=\(activeOrganizationID.uuidString) " +
                    "activeOrganizationID=\(activeOrganizationID.uuidString)"
                )
            }
            return activeOrganizationID
        }
        if canAccessOrganization(property.orgId) {
            return property.orgId
        }
        return property.orgId
    }

    private func scheduleCaptureProfilePropertyRemoteWrite(property: Property, profile: CaptureProfile) {
        guard let orgID = resolveCaptureProfileOrgID(property: property, propertyID: property.id) else {
            print("[CaptureProfileSync] event=property_remote_write_skipped reason=missing_org propertyID=\(property.id.uuidString)")
            return
        }
        let canAttempt = remoteMutationPathAvailable(for: orgID)
        print(
            "[CaptureProfileSync] event=property_remote_write_attempt " +
            "propertyID=\(property.id.uuidString) " +
            "orgID=\(orgID.uuidString) " +
            "activeOrganizationID=\(activeOrganizationID?.uuidString ?? "nil") " +
            "captureProfile=\(profile.rawValue) " +
            "updatedBy=\(authenticatedSupabaseUser?.id.uuidString ?? "nil") " +
            "supabaseClientExists=\(supabaseClient != nil) " +
            "gateAllowed=\(canAttempt)"
        )
        guard canAttempt else { return }

        Task(priority: .utility) { [weak self] in
            do {
                try await self?.updatePropertyCaptureProfileInSupabase(
                    propertyID: property.id,
                    orgID: orgID,
                    profile: profile
                )
                print(
                    "[CaptureProfileSync] event=property_remote_write_success " +
                    "propertyID=\(property.id.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(profile.rawValue)"
                )
                self?.recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: true)
            } catch {
                print(
                    "[CaptureProfileSync] event=property_remote_write_failed " +
                    "propertyID=\(property.id.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(profile.rawValue) " +
                    "error=\(error.localizedDescription)"
                )
                self?.recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: false, error: error)
            }
        }
    }

    private func scheduleCaptureProfileSessionRemoteWrite(
        propertyID: UUID,
        session: Session,
        profile: CaptureProfile
    ) {
        guard let property = allProperties.first(where: { $0.id == propertyID }) ??
                properties.first(where: { $0.id == propertyID }),
              let orgID = resolveCaptureProfileOrgID(property: property, propertyID: propertyID) else {
            print("[CaptureProfileSync] event=session_remote_write_skipped reason=missing_property_or_org propertyID=\(propertyID.uuidString) sessionID=\(session.id.uuidString)")
            return
        }
        let canAttempt = remoteMutationPathAvailable(for: orgID)
        print(
            "[CaptureProfileSync] event=session_remote_write_attempt " +
            "propertyID=\(propertyID.uuidString) " +
            "sessionID=\(session.id.uuidString) " +
            "orgID=\(orgID.uuidString) " +
            "activeOrganizationID=\(activeOrganizationID?.uuidString ?? "nil") " +
            "captureProfile=\(profile.rawValue) " +
            "updatedBy=\(authenticatedSupabaseUser?.id.uuidString ?? "nil") " +
            "supabaseClientExists=\(supabaseClient != nil) " +
            "gateAllowed=\(canAttempt)"
        )
        guard canAttempt else { return }

        Task(priority: .utility) { [weak self] in
            do {
                guard let self else { return }
                let loadedMetadata = try self.localStore.loadSessionMetadata(
                    propertyID: propertyID,
                    sessionID: session.id
                )
                let ensureMetadata = self.sessionEnsureMetadataForCaptureProfileSync(
                    metadata: loadedMetadata,
                    session: session,
                    profile: profile
                )
                print(
                    "[CaptureProfileSync] event=session_remote_ensure_attempt " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(session.id.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "targetProfile=\(profile.rawValue) " +
                    "localSessionStatus=\(session.status.rawValue) " +
                    "metadataStatus=\(loadedMetadata.status.rawValue) " +
                    "ensureStatus=\(ensureMetadata.status.rawValue)"
                )
                try await self.ensureSupabaseSessionPrerequisites(
                    propertyID: propertyID,
                    sessionID: session.id,
                    metadata: ensureMetadata,
                    orgID: orgID
                )
                print(
                    "[CaptureProfileSync] event=session_remote_ensure_success " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(session.id.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "targetProfile=\(profile.rawValue)"
                )
                let result = try await self.updateSessionCaptureProfileInSupabase(
                    sessionID: session.id,
                    propertyID: propertyID,
                    orgID: orgID,
                    profile: profile
                )
                print(
                    "[CaptureProfileSync] event=session_remote_write_success " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(session.id.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(profile.rawValue) " +
                    "verifiedCaptureProfile=\(result.captureProfile ?? "nil") " +
                    "affectedRows=1"
                )
                self.recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: true)
            } catch {
                print(
                    "[CaptureProfileSync] event=session_remote_write_failed " +
                    "propertyID=\(propertyID.uuidString) " +
                    "sessionID=\(session.id.uuidString) " +
                    "orgID=\(orgID.uuidString) " +
                    "captureProfile=\(profile.rawValue) " +
                    "error=\(error.localizedDescription)"
                )
                self?.recordShadowWriteDiagnostics(entity: .captureProfile, succeeded: false, error: error)
            }
        }
    }

    func propertyHasBaseline(_ propertyID: UUID) -> Bool {
        guard canAccessProperty(propertyID) else { return false }
        return properties.first(where: { $0.id == propertyID })?.baselineSessionID != nil
    }

    @discardableResult
    func setPropertyBaselineSession(propertyID: UUID, sessionID: UUID) -> Bool {
        guard canAccessProperty(propertyID) else { return false }
        guard let index = properties.firstIndex(where: { $0.id == propertyID }) else { return false }
        var updated = properties[index]
        updated.baselineSessionID = sessionID
        do {
            let persisted = try localStore.updateProperty(updated)
            if let rawIndex = allProperties.firstIndex(where: { $0.id == propertyID }) {
                allProperties[rawIndex] = persisted
            }
            let caches = makeHubCaches(for: allProperties)
            applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
            schedulePhaseBPropertyShadowWrite(for: persisted)
            return true
        } catch {
            return false
        }
    }

    @discardableResult
    func setPropertyArchived(id: UUID, archived: Bool) -> Bool {
        guard canAccessProperty(id) else { return false }
        guard let property = properties.first(where: { $0.id == id }) else { return false }
        var updated = property
        updated.isArchived = archived
        do {
            let persisted = try localStore.updateProperty(updated)
            if let idx = allProperties.firstIndex(where: { $0.id == id }) {
                allProperties[idx] = persisted
            }
            if archived, selectedPropertyID == id {
                clearCurrentSession()
                selectedPropertyID = nil
            }
            let caches = makeHubCaches(for: allProperties)
            applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
            schedulePhaseBPropertyShadowWrite(for: persisted)
            return true
        } catch {
            return false
        }
    }

    @discardableResult
    func updatePropertyContact(
        id: UUID,
        organizationID: UUID?,
        propertyName: String?,
        clientName: String?,
        address: String?,
        street: String?,
        city: String?,
        state: String?,
        zip: String?,
        clientPhone: String?,
        clientEmail: String?
    ) -> Bool {
        guard canAccessProperty(id) else { return false }
        guard let index = properties.firstIndex(where: { $0.id == id }) else { return false }
        var updated = properties[index]
        let cleanedName = propertyName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedClient = clientName?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedAddress = address?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedStreet = street?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedCity = city?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedState = state?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedZip = zip?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let digitsOnlyPhone = (clientPhone ?? "").filter(\.isNumber)
        let cleanedEmail = clientEmail?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        if let organizationID, canAccessOrganization(organizationID) {
            updated.orgId = organizationID
        }
        if !cleanedName.isEmpty {
            updated.name = cleanedName
        }
        updated.clientName = cleanedClient.isEmpty ? nil : cleanedClient
        updated.address = cleanedAddress.isEmpty ? nil : cleanedAddress
        updated.street = cleanedStreet.isEmpty ? nil : cleanedStreet
        updated.city = cleanedCity.isEmpty ? nil : cleanedCity
        updated.state = cleanedState.isEmpty ? nil : cleanedState
        updated.zip = cleanedZip.isEmpty ? nil : cleanedZip
        updated.clientPhone = digitsOnlyPhone.isEmpty ? nil : digitsOnlyPhone
        updated.clientEmail = cleanedEmail.isEmpty ? nil : cleanedEmail

        do {
            let persisted = try localStore.updateProperty(updated)
            if let rawIndex = allProperties.firstIndex(where: { $0.id == id }) {
                allProperties[rawIndex] = persisted
            }
            allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
            let caches = makeHubCaches(for: allProperties)
            applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
            schedulePhaseBPropertyShadowWrite(for: persisted)
            return true
        } catch {
            return false
        }
    }

    func propertyDataCounts(for propertyID: UUID) -> PropertyDataCounts {
        guard canAccessProperty(propertyID) else {
            return PropertyDataCounts(sessions: 0, guided: 0, observations: 0)
        }
        let sessions = (try? localStore.fetchSessions(propertyID: propertyID).count) ?? 0
        let guided = (try? localStore.fetchGuidedShots(propertyID: propertyID).count) ?? 0
        let observations = (try? localStore.fetchObservations(propertyID: propertyID).count) ?? 0
        return PropertyDataCounts(sessions: sessions, guided: guided, observations: observations)
    }

    func recentlyDeletedProperties() -> [Property] {
        scopedRecentlyDeletedProperties(from: allProperties)
            .sorted(by: Self.propertyIsOrderedBefore)
    }

    func activeProperties() -> [Property] {
        properties.filter { $0.deletedAt == nil && !$0.isArchived }
    }

    func archivedProperties() -> [Property] {
        properties.filter { $0.deletedAt == nil && $0.isArchived }
    }

    @discardableResult
    func remoteSoftDeleteProperty(id: UUID) async -> Bool {
        do {
            try await performRemoteSoftDeleteProperty(id: id)
            return true
        } catch {
            let message = softDeleteErrorMessage(for: error)
            hubTransientStatusMessage = message
            print("[PropertySoftDelete] result=failed propertyID=\(id.uuidString) error=\(message)")
            return false
        }
    }

    private func performRemoteSoftDeleteProperty(id: UUID) async throws {
        guard currentSession?.propertyID != id else {
            throw PropertySoftDeleteError.activeSession
        }
        guard canAccessProperty(id),
              let existing = allProperties.first(where: { $0.id == id }) ?? properties.first(where: { $0.id == id }) else {
            throw PropertySoftDeleteError.propertyNotFound
        }
        guard supabaseClient != nil,
              let orgID = activeOrganizationID,
              authenticatedSupabaseUser != nil,
              isOrganizationContextReady else {
            throw PropertySoftDeleteError.missingAuthenticatedContext
        }

        let preflight = try await forceRefreshRemotePropertyDeletePreflightState(
            propertyID: id,
            orgID: orgID
        )
        print(
            "[PropertySoftDelete] preflight propertyID=\(id.uuidString) " +
            "occupancyCount=\(preflight.occupancyCount) " +
            "lockCount=\(preflight.lockCount) " +
            "decision=\(preflight.isBlocked ? "blocked" : "allowed") " +
            "reason=\(preflight.blockedReason ?? "none")"
        )
        guard !preflight.isBlocked else {
            throw PropertySoftDeleteError.remoteOccupancy
        }

        try await callSoftDeletePropertyRPC(propertyID: id)
        applyRemoteSoftDeletedPropertyLocally(existing, deletedAt: Date())

#if DEBUG
        if let propertySoftDeleteRefreshOverride {
            _ = await propertySoftDeleteRefreshOverride()
            return
        }
#endif
        _ = await performForegroundRemotePropertyRefresh()
    }

    private func forceRefreshRemotePropertyDeletePreflightState(
        propertyID: UUID,
        orgID: UUID
    ) async throws -> PropertyDeletePreflightSnapshot {
#if DEBUG
        if let propertyDeletePreflightRefreshOverride {
            return try await propertyDeletePreflightRefreshOverride(orgID, propertyID)
        }
#endif
        let occupancy = try await fetchRemotePropertySessionOccupancyRecordDirect(
            orgID: orgID,
            propertyID: propertyID
        )
        setPropertySessionOccupancyState(
            propertyID: propertyID,
            occupiedByUserID: occupancy?.occupiedByUserID,
            occupiedByDeviceID: normalizedSupabaseText(occupancy?.occupiedByDeviceID),
            occupiedAt: occupancy?.occupiedAt.flatMap(parseSupabaseDateString)
        )
        if propertySessionOccupancyIsActive(occupancy) {
            return PropertyDeletePreflightSnapshot(
                occupancyCount: 1,
                lockCount: 0,
                isBlocked: true,
                blockedReason: "occupancy"
            )
        } else if occupancy != nil {
            setPropertySessionOccupancyState(
                propertyID: propertyID,
                occupiedByUserID: nil,
                occupiedByDeviceID: nil,
                occupiedAt: nil
            )
        }

        let lockRecords = try await fetchRemotePropertySessionLockRecordsDirect(
            orgID: orgID,
            propertyID: propertyID
        )
        let activeLockRecords = lockRecords.filter { record in
            hasActiveRemoteLock(record: record)
        }
        guard activeLockRecords.isEmpty else {
            return PropertyDeletePreflightSnapshot(
                occupancyCount: 0,
                lockCount: activeLockRecords.count,
                isBlocked: true,
                blockedReason: "session_lock"
            )
        }
        return PropertyDeletePreflightSnapshot.clear
    }

    private func callSoftDeletePropertyRPC(propertyID: UUID) async throws {
#if DEBUG
        if let propertySoftDeleteRPCOverride {
            try await propertySoftDeleteRPCOverride(propertyID)
            return
        }
#endif
        guard let client = supabaseClient else {
            throw PropertySoftDeleteError.missingAuthenticatedContext
        }
        let params = SoftDeletePropertyRPCPayload(targetPropertyID: propertyID)
        do {
            _ = try await (try client.rpc("soft_delete_property", params: params)).execute()
        } catch {
            throw normalizedSoftDeleteRPCError(error)
        }
    }

    private func normalizedSoftDeleteRPCError(_ error: Error) -> Error {
        let message = error.localizedDescription
        let lowered = message.lowercased()
        if lowered.contains("occupancy") ||
            lowered.contains("currently in use") ||
            lowered.contains("active property") {
            return PropertySoftDeleteError.remoteOccupancy
        }
        return PropertySoftDeleteError.remoteFailed(message)
    }

    private func softDeleteErrorMessage(for error: Error) -> String {
        if let propertyError = error as? PropertySoftDeleteError,
           let description = propertyError.errorDescription {
            return description
        }
        let normalized = normalizedSoftDeleteRPCError(error)
        if let propertyError = normalized as? PropertySoftDeleteError,
           let description = propertyError.errorDescription {
            return description
        }
        return "The property could not be deleted. \(error.localizedDescription)"
    }

    private func applyRemoteSoftDeletedPropertyLocally(_ property: Property, deletedAt: Date) {
        var updated = property
        updated.deletedAt = property.deletedAt ?? deletedAt
        updated.updatedAt = max(property.updatedAt, deletedAt)

        if let index = allProperties.firstIndex(where: { $0.id == updated.id }) {
            allProperties[index] = updated
        } else {
            allProperties.append(updated)
        }
        allProperties.sort(by: Self.propertyIsOrderedBefore)

        let caches = makeHubCaches(for: allProperties)
        do {
            try localStore.replacePropertyListCacheAtomically(
                properties: allProperties,
                organizations: allOrganizations
            )
        } catch {
            print("[PropertySoftDelete] local cache update failed after remote success: \(error.localizedDescription)")
        }
        applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)

        if selectedPropertyID == updated.id {
            selectedPropertyID = nil
        }
    }

    @discardableResult
    func remoteSoftDeleteSession(propertyID: UUID, sessionID: UUID) async -> Bool {
        do {
            try await performRemoteSoftDeleteSession(propertyID: propertyID, sessionID: sessionID)
            lastSessionDeleteErrorMessage = nil
            return true
        } catch {
            let message = softDeleteSessionErrorMessage(for: error)
            lastSessionDeleteErrorMessage = message
            hubTransientStatusMessage = message
            print("[SessionSoftDelete] result=failed sessionID=\(sessionID.uuidString) error=\(message)")
            return false
        }
    }

    private func performRemoteSoftDeleteSession(propertyID: UUID, sessionID: UUID) async throws {
        guard currentSession?.id != sessionID else {
            throw SessionSoftDeleteError.activeSession
        }
        guard canAccessProperty(propertyID),
              let existing = ((try? localStore.fetchSessionsForCacheBuild(propertyID: propertyID)) ?? [])
                .first(where: { $0.id == sessionID }) else {
            throw SessionSoftDeleteError.sessionNotFound
        }
        guard supabaseClient != nil,
              let orgID = activeOrganizationID,
              authenticatedSupabaseUser != nil,
              isOrganizationContextReady else {
            throw SessionSoftDeleteError.missingAuthenticatedContext
        }

        let preflight: SessionDeletePreflightSnapshot
        do {
            preflight = try await forceRefreshRemoteSessionDeletePreflightState(
                orgID: orgID,
                propertyID: propertyID,
                sessionID: sessionID
            )
        } catch {
            if let sessionError = error as? SessionSoftDeleteError {
                throw sessionError
            }
            throw SessionSoftDeleteError.preflightFailed(error.localizedDescription)
        }

        print(
            "[SessionSoftDelete] preflight sessionID=\(sessionID.uuidString) " +
            "propertyID=\(propertyID.uuidString) " +
            "deletedAt=\(preflight.deletedAt.map { supabaseTimestampString($0) } ?? "nil") " +
            "occupancyCount=\(preflight.occupancyCount) " +
            "lockCount=\(preflight.lockCount) " +
            "decision=\(preflight.isBlocked ? "blocked" : "allowed") " +
            "reason=\(preflight.blockedReason ?? "none")"
        )
        guard !preflight.isBlocked else {
            throw SessionSoftDeleteError.remoteInUse
        }

        try await callSoftDeleteSessionRPC(sessionID: sessionID)
        applyRemoteSoftDeletedSessionLocally(existing, deletedAt: preflight.deletedAt ?? Date())

#if DEBUG
        if let sessionSoftDeleteRefreshOverride {
            _ = await sessionSoftDeleteRefreshOverride()
            return
        }
#endif
        _ = await performForegroundRemotePropertyRefresh()
    }

    private func forceRefreshRemoteSessionDeletePreflightState(
        orgID: UUID,
        propertyID: UUID,
        sessionID: UUID
    ) async throws -> SessionDeletePreflightSnapshot {
#if DEBUG
        if let sessionDeletePreflightRefreshOverride {
            return try await sessionDeletePreflightRefreshOverride(orgID, propertyID, sessionID)
        }
#endif
        guard let sessionRecord = try await fetchRemoteSessionDeletePreflightRecordDirect(
            orgID: orgID,
            propertyID: propertyID,
            sessionID: sessionID
        ) else {
            throw SessionSoftDeleteError.sessionNotFound
        }

        let occupancy = try await fetchRemotePropertySessionOccupancyRecordDirect(
            orgID: orgID,
            propertyID: propertyID
        )
        setPropertySessionOccupancyState(
            propertyID: propertyID,
            occupiedByUserID: occupancy?.occupiedByUserID,
            occupiedByDeviceID: normalizedSupabaseText(occupancy?.occupiedByDeviceID),
            occupiedAt: occupancy?.occupiedAt.flatMap(parseSupabaseDateString)
        )
        if propertySessionOccupancyIsActive(occupancy) {
            return SessionDeletePreflightSnapshot(
                deletedAt: sessionRecord.deletedAt,
                occupancyCount: 1,
                lockCount: sessionDeletePreflightLockFieldsPresent(sessionRecord) ? 1 : 0,
                isBlocked: true,
                blockedReason: "property_occupancy"
            )
        } else if occupancy != nil {
            setPropertySessionOccupancyState(
                propertyID: propertyID,
                occupiedByUserID: nil,
                occupiedByDeviceID: nil,
                occupiedAt: nil
            )
        }

        if sessionDeletePreflightLockFieldsPresent(sessionRecord) {
            let isStaleOwnLock = sessionDeletePreflightLockIsOwnedByCurrentDevice(sessionRecord) &&
                sessionDeletePreflightLockIsStale(sessionRecord) &&
                currentSession?.id != sessionID

            if isStaleOwnLock {
                let didClear = await clearStaleSessionCoordinationLockForDeletePreflight(
                    sessionRecord: sessionRecord,
                    propertyID: propertyID,
                    sessionID: sessionID
                )
                if didClear {
                    return SessionDeletePreflightSnapshot(
                        deletedAt: sessionRecord.deletedAt,
                        occupancyCount: 0,
                        lockCount: 0,
                        isBlocked: false,
                        blockedReason: nil
                    )
                }
            }

            return SessionDeletePreflightSnapshot(
                deletedAt: sessionRecord.deletedAt,
                occupancyCount: 0,
                lockCount: 1,
                isBlocked: true,
                blockedReason: isStaleOwnLock ? "stale_session_lock_clear_failed" : "session_lock"
            )
        }

        return SessionDeletePreflightSnapshot(
            deletedAt: sessionRecord.deletedAt,
            occupancyCount: 0,
            lockCount: 0,
            isBlocked: false,
            blockedReason: nil
        )
    }

    private func clearStaleSessionCoordinationLockForDeletePreflight(
        sessionRecord: RemoteSessionDeletePreflightRecord,
        propertyID: UUID,
        sessionID: UUID
    ) async -> Bool {
        guard sessionDeletePreflightLockIsOwnedByCurrentDevice(sessionRecord),
              sessionDeletePreflightLockIsStale(sessionRecord),
              currentSession?.id != sessionID,
              let property = properties.first(where: { $0.id == propertyID }) ?? allProperties.first(where: { $0.id == propertyID }),
              let session = ((try? localStore.fetchSessionsForCacheBuild(propertyID: propertyID)) ?? []).first(where: { $0.id == sessionID }),
              let metadata = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: sessionID) else {
            return false
        }

        print(
            "[SessionSoftDelete] event=stale_lock_clear_attempt " +
            "sessionID=\(sessionID.uuidString) " +
            "propertyID=\(propertyID.uuidString) " +
            "lockedByUserID=\(sessionRecord.lockedByUserID?.uuidString ?? "nil") " +
            "lockedByDeviceID=\(sessionRecord.lockedByDeviceID ?? "nil") " +
            "lockedAt=\(sessionRecord.lockedAt ?? "nil") " +
            "ttlSeconds=\(Int(sessionCoordinationStaleLockThreshold))"
        )

        let clearedState = SessionCoordinationState(
            lockedByUserID: nil,
            lockedByDeviceID: nil,
            lockedAt: nil
        )
        setSessionCoordinationState(
            sessionID: sessionID,
            lockedByUserID: nil,
            lockedByDeviceID: nil,
            lockedAt: nil
        )
#if DEBUG
        if AppStateTestEnvironment.isRunningUnderXCTest {
            sessionCoordinationDebugRemoteRecords[sessionID] = RemoteSessionCoordinationRecord(
                id: sessionID,
                orgID: sessionRecord.orgID,
                propertyID: propertyID,
                status: nil,
                completedAt: nil,
                exportedAt: nil,
                isSealed: nil,
                firstDeliveredAt: nil,
                reExportExpiresAt: nil,
                lockedByUserID: nil,
                lockedByDeviceID: nil,
                lockedAt: nil,
                coordinationTier1Snapshot: sessionCoordinationTier1SnapshotString(metadata: metadata),
                updatedAt: Date()
            )
            print(
                "[SessionSoftDelete] event=stale_lock_clear_success " +
                "sessionID=\(sessionID.uuidString) source=test"
            )
            return true
        }
#endif

        let didClear = await persistSessionCoordinationMutation(
            property: property,
            session: session,
            metadata: metadata,
            desiredState: clearedState
        )
        print(
            "[SessionSoftDelete] event=\(didClear ? "stale_lock_clear_success" : "stale_lock_clear_failed") " +
            "sessionID=\(sessionID.uuidString)"
        )
        return didClear
    }

    private func callSoftDeleteSessionRPC(sessionID: UUID) async throws {
#if DEBUG
        if let sessionSoftDeleteRPCOverride {
            try await sessionSoftDeleteRPCOverride(sessionID)
            return
        }
#endif
        guard let client = supabaseClient else {
            throw SessionSoftDeleteError.missingAuthenticatedContext
        }
        let params = SoftDeleteSessionRPCPayload(targetSessionID: sessionID)
        do {
            _ = try await (try client.rpc("soft_delete_session", params: params)).execute()
        } catch {
            throw normalizedSoftDeleteSessionRPCError(error)
        }
    }

    private func normalizedSoftDeleteSessionRPCError(_ error: Error) -> Error {
        let message = error.localizedDescription
        let lowered = message.lowercased()
        if lowered.contains("currently in use") ||
            lowered.contains("occupancy") ||
            lowered.contains("lock") {
            return SessionSoftDeleteError.remoteInUse
        }
        return SessionSoftDeleteError.remoteFailed(message)
    }

    private func softDeleteSessionErrorMessage(for error: Error) -> String {
        if let sessionError = error as? SessionSoftDeleteError,
           let description = sessionError.errorDescription {
            return description
        }
        let normalized = normalizedSoftDeleteSessionRPCError(error)
        if let sessionError = normalized as? SessionSoftDeleteError,
           let description = sessionError.errorDescription {
            return description
        }
        return "The session could not be deleted. \(error.localizedDescription)"
    }

    private func applyRemoteSoftDeletedSessionLocally(_ session: Session, deletedAt: Date) {
        var updated = session
        updated.deletedAt = session.deletedAt ?? deletedAt
        do {
            _ = try localStore.upsertSession(updated)
            reloadSessionCache(for: updated.propertyID)
        } catch {
            print("[SessionSoftDelete] local cache update failed after remote success: \(error.localizedDescription)")
        }
    }

