    @discardableResult
    func deletePropertyIfEmpty(id: UUID) -> Bool {
        guard canAccessProperty(id) else { return false }
        let counts = propertyDataCounts(for: id)
        guard counts.isEmpty else { return false }
        do {
            try localStore.deleteProperty(id: id)
            allProperties.removeAll { $0.id == id }
            let caches = makeHubCaches(for: allProperties)
            applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
            if selectedPropertyID == id {
                selectedPropertyID = nil
                clearCurrentSession()
            }
            cloudBackupManager?.markDataChanged(scheduleBackupAfter: 0)
            return true
        } catch {
            if handleDeletePropertyNotFound(id: id, error: error) {
                return true
            }
            return false
        }
    }

    @discardableResult
    func deleteProperty(id: UUID) -> Bool {
        guard canAccessProperty(id) else { return false }
        refreshProperties()
        do {
            try localStore.deleteProperty(id: id)
            allProperties.removeAll { $0.id == id }
            let caches = makeHubCaches(for: allProperties)
            applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
            if selectedPropertyID == id {
                selectedPropertyID = nil
                clearCurrentSession()
            }
            cloudBackupManager?.markDataChanged(scheduleBackupAfter: 0)
            return true
        } catch {
            if handleDeletePropertyNotFound(id: id, error: error) {
                return true
            }
            return false
        }
    }

    private func handleDeletePropertyNotFound(id: UUID, error: Error) -> Bool {
        guard case LocalStore.StoreError.propertyNotFound = error else {
            return false
        }

        // Cross-device iCloud updates can remove a property on disk before this device's in-memory list refreshes.
        refreshProperties()
        allProperties.removeAll { $0.id == id }
        let caches = makeHubCaches(for: allProperties)
        applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
        if selectedPropertyID == id {
            selectedPropertyID = nil
            clearCurrentSession()
        }
        return true
    }

    @discardableResult
    func startSession(skipPropertyStatusPreflight: Bool = false) -> Session? {
        guard let selectedPropertyID else { return nil }
        if !skipPropertyStatusPreflight {
            let propertyStatusEntryPreflight = evaluatePropertyStatusEntryPreflight(
                propertyID: selectedPropertyID,
                context: "start_session"
            )
            if let propertyStatusEntryPreflight,
               propertyStatusEntryPreflight.isBlocked {
                recordDraftSessionReuseDecision(
                    propertyID: selectedPropertyID,
                    session: nil,
                    decision: "blocked_property_status_entry_preflight",
                    candidateCount: 0,
                    blockedReason: propertyStatusEntryPreflight.reason,
                    foregroundRefreshReconciliation: "property_status_entry_preflight_blocked_before_session_selection"
                )
                print(
                    "[StartSession] propertyID=\(selectedPropertyID.uuidString) " +
                    "blockedReason=property_status_entry_preflight:\(propertyStatusEntryPreflight.reason) " +
                    "pendingDeliveryExists=not_evaluated reExportEligibleExists=not_evaluated"
                )
                return nil
            }
        }
        ensureCanonicalOrgPersistenceForSelectedPropertyIfKnown(reason: "start_session")
        let sessionsForProperty = sessions(for: selectedPropertyID)
        let reusableDrafts = sessionsForProperty
            .filter { $0.deletedAt == nil && $0.status == .draft && !$0.isSealed && sessionHasCaptures($0) }
            .sorted { $0.startedAt > $1.startedAt }
        let pendingDeliveryExists = sessionsForProperty.contains(where: { isPendingDelivery($0) })
        let reExportEligibleExists = sessionsForProperty.contains(where: { isReExportEligible($0) })
        if let currentSession, currentSession.status == .draft, currentSession.propertyID == selectedPropertyID {
            let persistedCurrent = persistReusableDraftSessionIfNeeded(currentSession)
            recordDraftSessionReuseDecision(
                propertyID: selectedPropertyID,
                session: persistedCurrent,
                decision: "reuse_current_draft",
                candidateCount: reusableDrafts.count,
                blockedReason: nil,
                foregroundRefreshReconciliation: "current_session_retained"
            )
            print("[StartSession] propertyID=\(selectedPropertyID.uuidString) blockedReason=none pendingDeliveryExists=\(pendingDeliveryExists) reExportEligibleExists=\(reExportEligibleExists)")
            logActiveSession(persistedCurrent)
            cloudBackupManager?.setCaptureModeActive(true)
            return persistedCurrent
        }

        if let draft = reusableDrafts.first {
            currentSession = draft
            recordDraftSessionReuseDecision(
                propertyID: selectedPropertyID,
                session: draft,
                decision: "reuse_persisted_draft",
                candidateCount: reusableDrafts.count,
                blockedReason: nil,
                foregroundRefreshReconciliation: reusableDrafts.count > 1 ? "duplicate_drafts_detected_latest_reused" : "persisted_draft_reattached"
            )
            print("[StartSession] propertyID=\(selectedPropertyID.uuidString) blockedReason=none pendingDeliveryExists=\(pendingDeliveryExists) reExportEligibleExists=\(reExportEligibleExists)")
            cloudBackupManager?.setCaptureModeActive(true)
            return draft
        }

        let blockedReason = sessionsForProperty.contains { $0.deletedAt == nil && $0.status != .draft }
            ? "no_reusable_active_draft_completed_or_sealed_sessions_only"
            : "no_reusable_active_draft_found"
        let inheritedCaptureProfile = properties.first(where: { $0.id == selectedPropertyID })?.captureProfile ??
            allProperties.first(where: { $0.id == selectedPropertyID })?.captureProfile
        let session = Session(
            propertyID: selectedPropertyID,
            startedAt: Date(),
            status: .draft,
            endedAt: nil,
            exportedAt: nil,
            captureProfile: inheritedCaptureProfile
        )
        currentSession = session
        recordDraftSessionReuseDecision(
            propertyID: selectedPropertyID,
            session: session,
            decision: "created_new_draft",
            candidateCount: reusableDrafts.count,
            blockedReason: blockedReason,
            foregroundRefreshReconciliation: "new_occupancy_shell_created_not_persisted_until_capture"
        )
        if let property = properties.first(where: { $0.id == session.propertyID }) ?? allProperties.first(where: { $0.id == session.propertyID }),
           let orgID = property.orgId {
            Task {
                await emitAuditEvent(
                    orgID: orgID,
                    eventType: "session.started",
                    sessionID: session.id,
                    propertyID: session.propertyID,
                    payload: [:]
                )
            }
        }
        print("[StartSession] propertyID=\(selectedPropertyID.uuidString) blockedReason=none pendingDeliveryExists=\(pendingDeliveryExists) reExportEligibleExists=\(reExportEligibleExists)")
        cloudBackupManager?.setCaptureModeActive(true)
        return session
    }

    private func persistReusableDraftSessionIfNeeded(_ session: Session) -> Session {
        let alreadyPersisted = sessions(for: session.propertyID).contains { $0.id == session.id }
        guard !alreadyPersisted else {
            currentSession = session
            return session
        }
        guard sessionHasCaptures(session) || isFinalSession(session) else {
            currentSession = session
            print(
                "[StartSession] propertyID=\(session.propertyID.uuidString) " +
                "sessionID=\(session.id.uuidString) persist=skipped reason=transient_zero_photo_occupancy_shell"
            )
            return session
        }

        let persisted = (try? localStore.upsertSession(session)) ?? session
        currentSession = persisted
        reloadSessionCache(for: session.propertyID)
        return persisted
    }

    private func recordDraftSessionReuseDecision(
        propertyID: UUID,
        session: Session?,
        decision: String,
        candidateCount: Int,
        blockedReason: String?,
        foregroundRefreshReconciliation: String
    ) {
        mutateLocalDiagnostics { diagnostics in
            diagnostics.sessionSnapshotUpload.lastDraftReuseDecisionAt = Date()
            diagnostics.sessionSnapshotUpload.lastDraftReusePropertyID = propertyID
            diagnostics.sessionSnapshotUpload.lastDraftReuseSessionID = session?.id
            diagnostics.sessionSnapshotUpload.lastDraftReuseDecision = decision
            diagnostics.sessionSnapshotUpload.lastDraftReuseCandidateCount = candidateCount
            diagnostics.sessionSnapshotUpload.lastDraftReuseBlockedReason = blockedReason
            diagnostics.sessionSnapshotUpload.lastDraftDuplicateDetected = candidateCount > 1
            diagnostics.sessionSnapshotUpload.lastDraftForegroundRefreshReconciliation = foregroundRefreshReconciliation
        }
    }

    private func ensureCanonicalOrgPersistenceForSelectedPropertyIfKnown(reason: String) {
        guard let propertyID = selectedPropertyID,
              isAuthenticationReady,
              authenticatedSupabaseUser != nil,
              let canonicalOrgID = activeOrganizationID else {
            return
        }

        let runtimeProperty = properties.first(where: { $0.id == propertyID }) ??
            allProperties.first(where: { $0.id == propertyID })
        let persistedProperty = (try? localStore.fetchProperties().first { $0.id == propertyID }) ?? runtimeProperty
        let persistedOrgID = persistedProperty?.orgId
        let runtimeOrgID = runtimeProperty?.orgId
        guard persistedOrgID != canonicalOrgID || runtimeOrgID != canonicalOrgID else {
            recordCanonicalOrgPersistence(
                propertyID: propertyID,
                persistedOrgID: persistedOrgID,
                runtimeOrgID: runtimeOrgID,
                canonicalOrgID: canonicalOrgID,
                result: "already_matched_\(reason)"
            )
            return
        }

        do {
            let organizationName = organizationSelectionOptions.first(where: { $0.id == canonicalOrgID })?.name
                ?? allOrganizations.first(where: { $0.id == canonicalOrgID })?.name
                ?? activeOrganization?.name
                ?? "Remote Organization"
            let repaired = try localStore.repairPropertyOrgIDForSessionSnapshotValidation(
                propertyID: propertyID,
                canonicalOrgID: canonicalOrgID,
                organizationName: organizationName
            )
            allOrganizations = (try? localStore.fetchOrganizations()) ?? allOrganizations
            if let index = allProperties.firstIndex(where: { $0.id == repaired.id }) {
                allProperties[index] = repaired
            } else {
                allProperties.append(repaired)
            }
            let caches = makeHubCaches(for: allProperties)
            applyHubCachePayload(properties: allProperties, organizations: allOrganizations, caches: caches)
            recordCanonicalOrgPersistence(
                propertyID: propertyID,
                persistedOrgID: repaired.orgId,
                runtimeOrgID: repaired.orgId,
                canonicalOrgID: canonicalOrgID,
                result: "repaired_\(reason)"
            )
        } catch {
            recordCanonicalOrgPersistence(
                propertyID: propertyID,
                persistedOrgID: persistedOrgID,
                runtimeOrgID: runtimeOrgID,
                canonicalOrgID: canonicalOrgID,
                result: "blocked_\(reason): \(Self.diagnosticsPreviewText(error.localizedDescription, maxLength: 90) ?? "unknown_error")"
            )
        }
    }

    private func recordCanonicalOrgPersistence(
        propertyID: UUID,
        persistedOrgID: UUID?,
        runtimeOrgID: UUID?,
        canonicalOrgID: UUID,
        result: String
    ) {
        mutateLocalDiagnostics { diagnostics in
            diagnostics.sessionSnapshotUpload.lastOrgPersistenceRepairAt = Date()
            diagnostics.sessionSnapshotUpload.lastOrgPersistencePropertyID = propertyID
            diagnostics.sessionSnapshotUpload.lastOrgPersistencePersistedOrgID = persistedOrgID
            diagnostics.sessionSnapshotUpload.lastOrgPersistenceRuntimeOrgID = runtimeOrgID
            diagnostics.sessionSnapshotUpload.lastOrgPersistenceCanonicalSupabaseOrgID = canonicalOrgID
            diagnostics.sessionSnapshotUpload.lastOrgPersistenceMatch = persistedOrgID == canonicalOrgID && runtimeOrgID == canonicalOrgID
            diagnostics.sessionSnapshotUpload.lastOrgPersistenceRepairResult = result
        }
    }

    @discardableResult
    func ensureCurrentSessionPersisted() -> Session? {
        guard let session = currentSession else { return nil }
        let alreadyPersisted = sessions(for: session.propertyID).contains { $0.id == session.id }
        guard !alreadyPersisted else { return session }

        let persisted = (try? localStore.upsertSession(session)) ?? session
        currentSession = persisted
        reloadSessionCache(for: session.propertyID)
        return persisted
    }

    @discardableResult
    func saveDraftCurrentSession(scheduleShadowWrite: Bool = true) -> Session? {
        guard var session = currentSession else { return nil }
        session.status = .draft
        session.endedAt = nil
        session.exportedAt = nil
        if session.firstDeliveredAt == nil {
            session.isSealed = false
        }
        currentSession = session
        let persisted = (try? localStore.upsertSession(session)) ?? session
        currentSession = persisted
        reloadSessionCache(for: session.propertyID)
        if scheduleShadowWrite {
            schedulePhaseBSessionShadowWrite(for: persisted)
        }
        if sessionHasCaptures(persisted) {
            schedulePropertyStatusShadowWrite(
                transition: .promoteDraft,
                propertyID: persisted.propertyID,
                sessionID: persisted.id,
                reason: "save_draft_with_captures"
            )
        }
        return persisted
    }

    func scheduleSessionShadowWriteAfterCoordinationRelease(for session: Session) {
        schedulePhaseBSessionShadowWrite(for: session)
    }

    func promoteCurrentSessionToActiveCaptureLockIfNeeded(reason: String) {
        Task {
            await promoteCurrentSessionToActiveCaptureLock(reason: reason)
        }
    }

    private func promoteCurrentSessionToActiveCaptureLock(reason: String) async {
        guard backendFeatureFlags.sessionCoordinationEnabled,
              backendFeatureFlags.supabaseEnabled,
              backendFeatureFlags.shadowWriteEnabled,
              let session = currentSession,
              session.status == .draft,
              !isFinalSession(session),
              sessionHasCaptures(session),
              let property = properties.first(where: { $0.id == session.propertyID }) ??
                allProperties.first(where: { $0.id == session.propertyID }),
              let orgID = property.orgId,
              let metadata = try? localStore.loadSessionMetadata(propertyID: session.propertyID, sessionID: session.id) else {
            return
        }

        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        let renewedOccupancy = PropertySessionOccupancyState(
            occupiedByUserID: currentUserID,
            occupiedByDeviceID: currentDeviceID,
            occupiedAt: Date()
        )
        _ = await persistPropertySessionOccupancyMutation(
            propertyID: session.propertyID,
            orgID: orgID,
            desiredState: renewedOccupancy
        )

        let existing = sessionCoordinationStateBySessionID[session.id]
        if existing?.lockedByUserID == currentUserID,
           normalizedSupabaseText(existing?.lockedByDeviceID) == currentDeviceID,
           existing?.lockedAt != nil {
            return
        }

        let desiredState = SessionCoordinationState(
            lockedByUserID: currentUserID,
            lockedByDeviceID: currentDeviceID,
            lockedAt: Date()
        )
        let didPersist = await persistSessionCoordinationMutation(
            property: property,
            session: session,
            metadata: metadata,
            desiredState: desiredState
        )
        if didPersist {
            occupancyOnlyClaimedSessionIDs.remove(session.id)
            print(
                "[SessionCoordinationEval] event=promote_active_capture_lock " +
                "reason=\(reason) " +
                "propertyID=\(session.propertyID.uuidString) " +
                "sessionID=\(session.id.uuidString)"
            )
            schedulePropertyStatusShadowWrite(
                transition: .promoteDraft,
                propertyID: session.propertyID,
                sessionID: session.id,
                reason: "first_capture_\(reason)"
            )
            await emitAuditEvent(
                orgID: orgID,
                eventType: "session.locked",
                sessionID: session.id,
                propertyID: session.propertyID,
                payload: [:]
            )
        }
    }

    func completeCurrentSession(markExported: Bool) {
        guard var session = currentSession else { return }
        let wasAlreadyCompleted = session.status == .completed
        session.status = .completed
        if session.endedAt == nil {
            session.endedAt = Date()
        }
        session.isSealed = true
        if markExported {
            let now = Date()
            applyDeliverySuccess(to: &session, deliveredAt: now)
        } else {
            if session.exportedAt != nil {
                session.exportedAt = nil
            }
        }
        currentSession = session
        let persistedSession = try? localStore.upsertSession(session)
        let persisted = persistedSession ?? session
        currentSession = persisted
        reloadSessionCache(for: persisted.propertyID)
        schedulePhaseBSessionShadowWrite(for: persisted)
        schedulePropertyStatusShadowWrite(
            transition: markExported ? .exported : .pendingExport,
            propertyID: persisted.propertyID,
            sessionID: persisted.id,
            reason: markExported ? "complete_current_session_exported" : "complete_current_session_pending_export"
        )
        scheduleOffloadEligibleSessionMedia(excludingSessionID: currentSession?.id)
        cloudBackupManager?.setCaptureModeActive(false)
        triggerBackupForLifecycleEvent()
        emitSessionCompletedAuditEventIfNeeded(for: persistedSession, wasAlreadyCompleted: wasAlreadyCompleted)
    }
    
    func clearCurrentSession() {
        scheduleOffloadEligibleSessionMedia(excludingSessionID: currentSession?.id)
        if let session = currentSession {
            let ownershipState = sessionCoordinationStateBySessionID[session.id]
            let hasSessionCoordinationLock =
                ownershipState?.lockedByUserID != nil ||
                normalizedSupabaseText(ownershipState?.lockedByDeviceID) != nil ||
                ownershipState?.lockedAt != nil
            let hasOccupancyOnlyClaim = occupancyOnlyClaimedSessionIDs.contains(session.id)
            if hasSessionCoordinationLock || hasOccupancyOnlyClaim {
                Task {
                    if hasOccupancyOnlyClaim {
                        await self.releasePropertySessionOccupancyIfOwned(
                            propertyID: session.propertyID,
                            sessionID: session.id,
                            emitReleasedEvent: true
                        )
                    }
                    if hasSessionCoordinationLock {
                        await self.releaseSessionCoordinationLockIfOwnedUsingState(
                            propertyID: session.propertyID,
                            sessionID: session.id,
                            emitReleasedEvent: !hasOccupancyOnlyClaim,
                            ownershipState: ownershipState
                        )
                    }
                }
            }
        }
        if let sessionID = currentSession?.id {
            sessionCoordinationStateBySessionID.removeValue(forKey: sessionID)
            sessionCoordinationEntrySnapshotBySessionID.removeValue(forKey: sessionID)
        }
        currentSession = nil
        cloudBackupManager?.setCaptureModeActive(false)
    }
    
    func draftSession(for propertyID: UUID) -> Session? {
        guard canAccessProperty(propertyID) else { return nil }
        return canonicalDraftSession(for: propertyID, requireCaptures: true)
    }
    
    func sessions(for propertyID: UUID) -> [Session] {
        guard canAccessProperty(propertyID) else { return [] }
        if let cached = sessionIndexByProperty[propertyID] {
            return cached.filter { $0.deletedAt == nil }
        }
        let fetched = (try? localStore.fetchSessions(propertyID: propertyID)) ?? []
        var uniqueByID: [UUID: Session] = [:]
        for session in fetched {
            uniqueByID[session.id] = session
        }
        return uniqueByID.values
            .filter { $0.deletedAt == nil }
            .sorted { $0.startedAt < $1.startedAt }
    }

    func recentlyDeletedSessions() -> [Session] {
        properties
            .flatMap { property -> [Session] in
                if let cached = allSessionIndexByProperty[property.id] {
                    return cached
                }
                return loadAndNormalizeSessions(propertyID: property.id)
            }
            .filter { $0.deletedAt != nil }
            .sorted {
                ($0.deletedAt ?? .distantPast, $0.startedAt) >
                ($1.deletedAt ?? .distantPast, $1.startedAt)
            }
    }

    func latestPendingExportSession(for propertyID: UUID) -> Session? {
        guard canAccessProperty(propertyID) else { return nil }
        if let cached = pendingExportSessionByProperty[propertyID] {
            return cached
        }
        return sessions(for: propertyID)
            .filter { isPendingDelivery($0) && sessionHasCaptures($0) }
            .sorted { $0.startedAt > $1.startedAt }
            .first
    }

    func reconcileRemoteSessionContentForPropertyOpen(propertyID: UUID) async {
        let startedAt = Date()
        if let last = propertyReferenceReconcileAtByPropertyID[propertyID],
           startedAt.timeIntervalSince(last) < 5.0 {
            print(
                "[ReferenceMetadataRefresh] propertyID=\(propertyID.uuidString) " +
                "result=skipped reason=throttled elapsedMs=0"
            )
            return
        }
        propertyReferenceReconcileAtByPropertyID[propertyID] = startedAt
        guard backendFeatureFlags.supabaseEnabled,
              backendFeatureFlags.mediaSupabaseUploadEnabled,
              canAccessProperty(propertyID),
              let property = properties.first(where: { $0.id == propertyID }) ??
                allProperties.first(where: { $0.id == propertyID }),
              let orgID = property.orgId,
              canAccessOrganization(orgID),
              let client = supabaseClient else {
            print(
                "[ReferenceMetadataRefresh] propertyID=\(propertyID.uuidString) " +
                "result=skipped reason=prereq_failed elapsedMs=\(Int(Date().timeIntervalSince(startedAt) * 1000))"
            )
            return
        }

        let targetSessions = sessions(for: propertyID)
            .filter { $0.deletedAt == nil && isFinalSession($0) }
            .sorted {
                ($0.endedAt ?? $0.exportedAt ?? $0.startedAt) >
                ($1.endedAt ?? $1.exportedAt ?? $1.startedAt)
            }
            .prefix(2)

        for session in targetSessions {
            do {
                let rows = try await client
                    .from("shots")
                    .select("id, org_id, property_id, session_id, created_at, updated_at, updated_by, revision, deleted_at, building, elevation, detail_type, angle_index, shot_key, logical_shot_identity, capture_kind, first_capture_kind, is_guided, is_flagged, issue_id, issue_status, trade, reason, priority, capture_mode, lens, latitude, longitude, accuracy_meters, image_width, image_height, lifecycle_state, retired_at, retired_reason, retired_by, superseded_by_shot_id, supersedes_shot_id, replacement_reason, hidden_from_reports, hidden_from_gallery, lifecycle_updated_at, storage_bucket, storage_path, checksum_sha256, byte_size, upload_state, upload_attempts, last_upload_error")
                    .eq("org_id", value: orgID.uuidString.lowercased())
                    .eq("property_id", value: propertyID.uuidString.lowercased())
                    .eq("session_id", value: session.id.uuidString.lowercased())
                    .is("deleted_at", value: nil)
                    .execute()
                    .value as [RemoteShotMetadataRecord]
                applyRemoteShotMetadataRows(rows, propertyID: propertyID, sessionID: session.id)
            } catch {
                recordDiagnosticsError(error)
            }
        }
        print(
            "[ReferenceMetadataRefresh] propertyID=\(propertyID.uuidString) " +
            "sessionCount=\(targetSessions.count) elapsedMs=\(Int(Date().timeIntervalSince(startedAt) * 1000))"
        )
    }

    private func applyRemoteShotMetadataRows(
        _ rows: [RemoteShotMetadataRecord],
        propertyID: UUID,
        sessionID: UUID
    ) {
        guard !rows.isEmpty else { return }
        var metadata = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: sessionID)
        let existingShots = Dictionary(uniqueKeysWithValues: (metadata?.shots ?? []).map { ($0.shotID, $0) })
        var issueByID = Dictionary(uniqueKeysWithValues: (metadata?.issues ?? []).map { ($0.issueID, $0) })
        var appliedFlaggedCount = 0
        for row in rows where row.deletedAt == nil {
            if let rowPropertyID = row.propertyID, rowPropertyID != propertyID {
                continue
            }
            if let rowSessionID = row.sessionID, rowSessionID != sessionID {
                continue
            }
            let existing = existingShots[row.id]
            let local = existing ?? makeLocalShotMetadataShell(from: row, propertyID: propertyID, sessionID: sessionID)
            let merged = row.merged(withLocal: local)
            try? localStore.upsertShot(propertyID: propertyID, sessionID: sessionID, shot: merged, matchMode: .append)
            guard merged.isFlagged, let issueID = merged.issueID else { continue }
            var issue = issueByID[issueID] ?? IssueMetadata(
                issueID: issueID,
                issueStatus: merged.issueStatus ?? "active",
                currentReason: merged.noteText,
                firstSeenAt: merged.createdAt,
                lastSeenAt: merged.updatedAt,
                lastCaptureSessionId: sessionID,
                detailNote: merged.noteText,
                shotKey: merged.shotKey
            )
            issue.issueStatus = merged.issueStatus ?? issue.issueStatus
            issue.currentReason = normalizedSupabaseText(merged.noteText) ?? issue.currentReason
            issue.lastSeenAt = max(issue.lastSeenAt ?? merged.updatedAt, merged.updatedAt)
            issue.lastCaptureSessionId = sessionID
            issue.detailNote = normalizedSupabaseText(merged.noteText) ?? issue.detailNote
            issue.shotKey = normalizedSupabaseText(merged.shotKey) ?? issue.shotKey
            issueByID[issueID] = issue
            appliedFlaggedCount += 1
        }
        if appliedFlaggedCount > 0,
           var refreshed = try? localStore.loadSessionMetadata(propertyID: propertyID, sessionID: sessionID) {
            refreshed.issues = Array(issueByID.values).sorted { lhs, rhs in
                if (lhs.firstSeenAt ?? .distantPast) != (rhs.firstSeenAt ?? .distantPast) {
                    return (lhs.firstSeenAt ?? .distantPast) < (rhs.firstSeenAt ?? .distantPast)
                }
                return lhs.issueID.uuidString < rhs.issueID.uuidString
            }
            try? localStore.saveSessionMetadataAtomically(propertyID: propertyID, sessionID: sessionID, metadata: refreshed)
            try? localStore.mergeRemoteFlaggedReferenceObservations(
                propertyID: propertyID,
                sessionID: sessionID,
                metadata: refreshed
            )
            let localFlaggedCount = (try? localStore.fetchObservations(propertyID: propertyID)
                .filter { $0.sessionID == sessionID || $0.updatedInSessionID == sessionID }
                .count) ?? 0
            print(
                "[FlaggedReferenceSync] latestFinalizedSessionID=\(sessionID.uuidString) " +
                "remoteFlaggedShotCount=\(appliedFlaggedCount) " +
                "localFlaggedRefCount=\(localFlaggedCount) " +
                "flaggedMetadataPendingReason=none flaggedMediaPendingReason=checked_by_reference_freshness"
            )
        }
    }

    private func makeLocalShotMetadataShell(
        from row: RemoteShotMetadataRecord,
        propertyID: UUID,
        sessionID: UUID
    ) -> ShotMetadata {
        let storageLeaf = row.storagePath
            .flatMap { normalizedSupabaseText($0) }
            .map { URL(fileURLWithPath: $0).lastPathComponent }
        let filename = storageLeaf?.isEmpty == false ? storageLeaf! : "\(row.id.uuidString).heic"
        let relativePath = "Originals/\(filename)"
        return ShotMetadata(
            shotID: row.id,
            propertyID: row.propertyID ?? propertyID,
            sessionID: row.sessionID ?? sessionID,
            createdAt: row.createdAt ?? Date.distantPast,
            updatedAt: row.updatedAt ?? row.createdAt ?? Date.distantPast,
            building: row.building ?? "",
            elevation: row.elevation ?? "",
            detailType: row.detailType ?? "",
            angleIndex: max(0, row.angleIndex ?? 0),
            trade: row.trade,
            priority: row.priority,
            shotKey: row.shotKey ?? ShotMetadata.makeShotKey(building: row.building ?? "", elevation: row.elevation ?? "", detailType: row.detailType ?? "", angleIndex: max(1, row.angleIndex ?? 1)),
            isGuided: row.isGuided ?? false,
            isFlagged: row.isFlagged ?? false,
            issueID: row.issueID,
            issueStatus: row.issueStatus,
            captureKind: row.captureKind,
            firstCaptureKind: row.firstCaptureKind,
            noteText: row.reason,
            noteCategory: nil,
            originalFilename: filename,
            originalRelativePath: relativePath,
            originalByteSize: row.byteSize,
            storageBucket: row.storageBucket,
            storagePath: row.storagePath,
            checksumSHA256: row.checksumSHA256,
            byteSize: row.byteSize,
            uploadState: row.uploadState ?? "uploaded",
            uploadAttempts: row.uploadAttempts ?? 0,
            lastUploadError: row.lastUploadError,
            stampedFilename: nil,
            stampedRelativePath: nil,
            captureMode: row.captureMode,
            lens: row.lens,
            exifOrientation: nil,
            orientation: nil,
            latitude: row.latitude,
            longitude: row.longitude,
            accuracyMeters: row.accuracyMeters,
            imageWidth: row.imageWidth,
            imageHeight: row.imageHeight,
            lifecycleState: row.lifecycleState,
            retiredAt: row.retiredAt,
            retiredReason: row.retiredReason,
            retiredByUserID: row.retiredByUserID,
            supersededByShotID: row.supersededByShotID,
            supersedesShotID: row.supersedesShotID,
            replacementReason: row.replacementReason,
            hiddenFromReports: row.hiddenFromReports,
            hiddenFromGallery: row.hiddenFromGallery,
            lifecycleUpdatedAt: row.lifecycleUpdatedAt
        )
    }
    
    func pendingExportCountAcrossProperties() -> Int {
        guard !propertyStatusByPropertyID.isEmpty else {
            return legacyPendingExportCountAcrossProperties()
        }
        var pendingCount = 0
        var legacyPendingSessionIDs = Set<UUID>()
        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        for property in properties {
            if let record = propertyStatusByPropertyID[property.id] {
                let answer = Self.makePropertyStatusCompareAnswer(
                    record: record,
                    currentUserID: currentUserID,
                    currentDeviceID: currentDeviceID
                )
                if answer.pendingExportCountIncluded {
                    pendingCount += 1
                }
            } else {
                for session in sessions(for: property.id) where isPendingDelivery(session) && sessionHasCaptures(session) {
                    legacyPendingSessionIDs.insert(session.id)
                }
            }
        }
        return pendingCount + legacyPendingSessionIDs.count
    }

    private func legacyPendingExportCountAcrossProperties() -> Int {
        if !pendingExportSessionByProperty.isEmpty {
            return Set(pendingExportSessionByProperty.values.map(\.id)).count
        }
        var pendingSessionIDs = Set<UUID>()
        for property in properties {
            for session in sessions(for: property.id) where isPendingDelivery(session) && sessionHasCaptures(session) {
                pendingSessionIDs.insert(session.id)
            }
        }
        return pendingSessionIDs.count
    }
    
    func draftPropertyCount() -> Int {
        guard !propertyStatusByPropertyID.isEmpty else {
            return legacyDraftPropertyCount()
        }
        let currentUserID = authenticatedSupabaseUser?.id
        let currentDeviceID = currentDeviceIdentifier()
        return properties.reduce(0) { count, property in
            if let record = propertyStatusByPropertyID[property.id] {
                let answer = Self.makePropertyStatusCompareAnswer(
                    record: record,
                    currentUserID: currentUserID,
                    currentDeviceID: currentDeviceID
                )
                return count + (answer.draftCountIncluded ? 1 : 0)
            }
            return count + (legacyDraftCountIncluded(propertyID: property.id) ? 1 : 0)
        }
    }

    private func legacyDraftPropertyCount() -> Int {
        if !draftSessionByProperty.isEmpty {
            return draftSessionByProperty.count
        }
        return properties.filter { draftSession(for: $0.id) != nil }.count
    }

    private func legacyDraftCountIncluded(propertyID: UUID) -> Bool {
        if !draftSessionByProperty.isEmpty {
            return draftSessionByProperty[propertyID] != nil
        }
        return draftSession(for: propertyID) != nil
    }

